/// A yard's number key, as the switcher's rows show it: ⌘1 opens the
/// first yard on macOS, ctrl+1 elsewhere. Only the first nine yards have
/// number bindings.
pub(crate) fn number_key(place: usize) -> Option<String> {
    (place < 9).then(|| {
        if cfg!(target_os = "macos") {
            format!("⌘{}", place + 1)
        } else {
            format!("ctrl+{}", place + 1)
        }
    })
}

/// The keys of the window, as `yardr chat` has them, with the card's:
/// a number key or the arrows choose an option, Enter sends the pick with
/// the line's words, `x` puts aside, `d` declines, `a` asks about this,
/// `e` expands.
pub fn bind_keys(cx: &mut App) {
    for context in [CONTEXT, NO_LINE_CONTEXT] {
        cx.bind_keys([
            KeyBinding::new("tab", Next, Some(context)),
            KeyBinding::new("shift-tab", Previous, Some(context)),
            // The line's own binding is the deeper one: with the focus in
            // the line it copies the line's selection, as before.
            KeyBinding::new("secondary-c", input::Copy, Some(context)),
            // The arrows choose even while words are typed: the line keeps
            // left and right for its cursor, and up and down while its
            // words have a row to go to.
            KeyBinding::new("up", ChoiceUp, Some(context)),
            KeyBinding::new("down", ChoiceDown, Some(context)),
            KeyBinding::new("escape", Leave, Some(context)),
            // The jump control's key works while words are typed: the
            // line has no binding for it.
            KeyBinding::new("secondary-end", JumpNewest, Some(context)),
            // Home and End with the modifier are the oldest loaded and
            // the newest: plain they are the line's caret keys, for the
            // row's ends.
            KeyBinding::new("secondary-home", JumpOldest, Some(context)),
            // A page up or down scrolls what is shown, with the focus
            // anywhere: the line has no binding for these keys.
            KeyBinding::new("pageup", PageUp, Some(context)),
            KeyBinding::new("pagedown", PageDown, Some(context)),
        ]);
    }
    // Where no line is typed in: one key marks one notice read and with
    // shift every one, and on a card the same keys pick, put aside, decline
    // and expand. With the line focused those keys are the line's text.
    cx.bind_keys([
        KeyBinding::new("x", Dismiss, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("shift-x", DismissAll, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("1", Pick1, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("2", Pick2, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("3", Pick3, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("4", Pick4, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("5", Pick5, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("6", Pick6, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("7", Pick7, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("8", Pick8, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("9", Pick9, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("enter", Decide, Some(NO_LINE_CONTEXT)),
        // A run ask is approved with a key no other card answers with, and
        // never with Enter alone: the habit of answering picks must not
        // run a command.
        KeyBinding::new("secondary-enter", Approve, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("secondary-enter", Approve, Some(SETUP_SECRET_CONTEXT)),
        KeyBinding::new("d", Decline, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("a", AskAbout, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("e", Expand, Some(NO_LINE_CONTEXT)),
        KeyBinding::new("i", FocusWords, Some(NO_LINE_CONTEXT)),
        // The history's filter, from anywhere its keys are the window's:
        // with the focus in a line the key is the line's text.
        KeyBinding::new("/", FocusFilter, Some(NO_LINE_CONTEXT)),
        // The cheatsheet of the open view's keys, from anywhere its
        // keys are the window's: with the focus in a line a `?` is
        // the line's text, and the "? all keys" hints open it with a
        // click instead.
        KeyBinding::new("?", ShowKeys, Some(NO_LINE_CONTEXT)),
    ]);
    cx.bind_keys([
        KeyBinding::new("up", ChoiceUp, Some(SWITCH_CONTEXT)),
        KeyBinding::new("down", ChoiceDown, Some(SWITCH_CONTEXT)),
        KeyBinding::new("enter", Decide, Some(SWITCH_CONTEXT)),
        KeyBinding::new("escape", Leave, Some(SWITCH_CONTEXT)),
        // `+` adds a yard from the list; `=` is the key it is on, which
        // some platforms report instead, as with Larger.
        KeyBinding::new("+", AddYard, Some(SWITCH_CONTEXT)),
        KeyBinding::new("=", AddYard, Some(SWITCH_CONTEXT)),
        KeyBinding::new("?", ShowKeys, Some(SWITCH_CONTEXT)),
    ]);
    // The away screen's details open on Enter from anywhere, as on a
    // click. The binding has no context, as the switcher's keys do, so it
    // answers while the yard is away and the line is not drawn. It answers
    // everywhere else too, before the fields and the line take Enter for
    // themselves; the handler takes it only where no yard was made and no
    // way's fields are open, and never stops it.
    cx.bind_keys([KeyBinding::new("enter", AwayDetails, None)]);
    // The modes step with the brackets from anywhere, as the yards do
    // with digits: with the modifier, and with no context, so they
    // answer with the focus in the line too.
    cx.bind_keys([
        KeyBinding::new("secondary-[", PreviousMode, None),
        KeyBinding::new("secondary-]", NextMode, None),
    ]);
    // The switcher and a yard by its place in the list, from anywhere:
    // with the modifier, since a plain digit is a card's pick.
    cx.bind_keys([
        KeyBinding::new("secondary-y", SwitchYards, None),
        KeyBinding::new("secondary-1", Yard1, None),
        KeyBinding::new("secondary-2", Yard2, None),
        KeyBinding::new("secondary-3", Yard3, None),
        KeyBinding::new("secondary-4", Yard4, None),
        KeyBinding::new("secondary-5", Yard5, None),
        KeyBinding::new("secondary-6", Yard6, None),
        KeyBinding::new("secondary-7", Yard7, None),
        KeyBinding::new("secondary-8", Yard8, None),
        KeyBinding::new("secondary-9", Yard9, None),
    ]);
    // The settings and their own keys, wherever the focus is, the yard
    // there or away. Larger is on `=`, the key `+` is on, with shift or
    // without.
    cx.bind_keys([
        KeyBinding::new("secondary-,", OpenSettings, None),
        KeyBinding::new("secondary-=", Larger, None),
        KeyBinding::new("secondary-+", Larger, None),
        KeyBinding::new("secondary--", Smaller, None),
        KeyBinding::new("secondary-0", UsualSize, None),
        KeyBinding::new("secondary-shift-l", NextLook, None),
    ]);
}

pub struct Footplate {
    /// The yard's client, or none while the yard that was chosen cannot be
    /// opened: `down` says why.
    client: Option<Client>,
    /// The name the window runs as, for this machine's yard.
    name: String,
    /// What the environment says of the yard, which wins over the settings.
    env: Env,
    /// The yard that is open, by the name the settings list it under, or
    /// by its address where the environment names it: whose the drafts,
    /// the ask words and the counts are.
    yard: String,
    /// Which opening of a yard this is, counted from the window's start.
    /// The answer to a call made in an earlier one is another yard's, or
    /// this one's before it was left, and changes nothing of what is
    /// typed or shown beside the model.
    opening: u64,
    /// Which following the open yard's is, of all the window started
    /// ([`Held::session`]), and how many it started.
    session: u64,
    sessions: u64,
    /// How each follower watches a stream that says nothing.
    watch: session::Watch,
    /// How long until a follower tries the yard again.
    retry: Duration,
    /// The yard of the settings the open one was opened as, or none of
    /// the one yard the environment names.
    entry: Option<settings::Yard>,
    /// The other yards of the settings, by name: each followed as the
    /// open one is, by a client and a follower of its own, so that what
    /// waits in it is known and told of, and a switch shows it as it
    /// stands. Nothing of one is shown or sent while it is here.
    held: HashMap<String, Held>,
    /// Hands on what the follower of the open yard learns.
    following: Option<Task<()>>,
    /// Stops that follower when the yard is opened anew or is no longer
    /// listed, even while its event stream has no new words to deliver.
    following_stop: Option<session::FollowControl>,
    /// What the yard has, once it was read. It is kept while the yard is
    /// away, for the conversation that was open.
    model: Option<Model>,
    /// Why the yard is not there, while it is not.
    down: Option<String>,
    away: Away,
    /// The away screen's details are open: the socket, the error and the
    /// hint at yardr status, where no yard was ever made. Closed at first.
    away_details: bool,
    /// The yard answered while a way's fields stood open on the away
    /// screen: the screen and the fields stand until the person leaves
    /// them, though the yard may be away again since. While it answers
    /// under them, the screen says so, and leaving them opens it.
    answered_while_adding: bool,
    /// Of a yard at an address: who it says this device is.
    said: Option<api::Me>,
    line: Entity<Line>,
    conversation: ScrollHandle,
    /// How many mails arrived in the open conversation below its view
    /// while it stood scrolled up: what the jump control carries.
    new_below: usize,
    /// The conversation was told to its newest and the layout has not
    /// put it there yet: the jump control stays out of the frame before
    /// it, whose scroll offset is the old view's.
    bottom_pending: bool,
    /// Older mail was put in above the view: the mail to keep where it
    /// stood, and whether the layout has put it at the top of the view
    /// yet. See [`Footplate::keep_place`].
    anchor: Option<(Anchor, bool)>,
    /// The conversation's viewport size and whether it stood at its
    /// newest when last laid out: a resize that finds it there puts it
    /// at its newest again, since its offset is counted from the top.
    stood: Option<(Size<Pixels>, bool)>,
    /// Where the open conversation stood when its older mail was last
    /// asked for: the conversation, its oldest mail and the scroll offset.
    /// Standing there still asks for nothing again, so a page the yard
    /// did not answer is not asked for with every frame.
    older_at: Option<(String, u64, Pixels)>,
    /// The conversation's position when it was left for a decision, so
    /// dealing with that decision can return to the same place.
    back_position: Option<(String, gpui::Point<gpui::Pixels>)>,
    /// The open card's own scroll: mail and notices arriving never move it.
    decision: ScrollHandle,
    /// The bead the drawer at the window's right shows, if one is open
    /// there: a bead link's bead, beside what was being read.
    drawer: Option<String>,
    /// The drawer's own scroll: the reading pane's never moves it.
    drawer_scroll: ScrollHandle,
    /// The left list's own scroll: the window never moves it, but the
    /// arrivals shots stand at its end, where the arrivals row is.
    rows: ScrollHandle,
    /// What is selected of the open conversation's messages.
    selection: Entity<Selection>,
    /// The images of the conversations and cards that were open, by hash:
    /// an image never changes under its hash, so each is asked for once.
    images: HashMap<String, Picture>,
    /// The image shown full size over the window, while one is: a click
    /// on a thumbnail opens it, and Esc, a click outside or its × shuts
    /// it again.
    image_open: Option<ImageOpen>,
    /// The menu a right press on a picture opened, while one stands: it
    /// offers to save the picture, and Esc, a press outside it or its one
    /// item shuts it.
    picture_menu: Option<PictureMenu>,
    /// The session's screen shown over the window, while one is: a
    /// Screen control opens it, and Esc, a click outside or its × shuts
    /// it again.
    screen_open: Option<ScreenOpen>,
    /// The newest read of a session's screen, so a slower earlier answer
    /// cannot replace a refresh.
    screen_read: u64,
    /// The open screen's own scroll: each answer stands it at the pane's
    /// bottom, where the input line is.
    screen_scroll: ScrollHandle,
    /// Whether the web view answers at the setting's address: what a
    /// note's page is drawn with.
    view_up: ViewUp,
    run_up: ViewUp,
    /// Whether a file's or page's row was drawn in the latest frame: a
    /// "no" from the view or the sandbox origin is asked again only
    /// while one is. Set from the rows, which draw from a shared
    /// reference, and cleared when the frame starts.
    rows_shown: Cell<bool>,
    /// What is attached and not sent, for each conversation of each yard,
    /// and the text typed in those that are not open; the open one's is in
    /// the line. They speak of the open yard alone.
    drafts: Drafts,
    /// The words typed for each ask of the open yard that is not the open
    /// one, by bead and ask; the open one's are in the line.
    ask_words: HashMap<(String, u64), String>,
    /// The same of the yards that are not open, by yard: they are the
    /// open yard's again when theirs is opened, and no call of another
    /// yard can name them.
    kept_words: HashMap<String, HashMap<(String, u64), String>>,
    /// The files attached to each ask's note of the open yard, by bead
    /// and ask, in the order they came: what a drop on the open card
    /// leaves for Enter to send with the words.
    note_files: HashMap<(String, u64), Vec<Attachment>>,
    /// The same of the yards that are not open, by yard.
    kept_note_files: HashMap<String, HashMap<(String, u64), Vec<Attachment>>>,
    /// Why each yard that is not reached is not, in a word or two, by
    /// yard: what its row in the switcher says, of the open one and of
    /// every other. A yard that answers is in it no longer.
    unreached: HashMap<String, &'static str>,
    /// Where each yard stood when it was last left, by yard.
    places: HashMap<String, Place>,
    /// The row the open yard is to be put back to and its scroll, which
    /// it is not yet: the yard has not answered for what the row shows,
    /// or the layout has not had it. Whether it was laid out as long as
    /// it now is. See [`Footplate::come_back`].
    returning: Option<((Selected, Pixels), bool)>,
    /// What there was to say while a yard was being opened and nothing
    /// showed to say it in: it is said when the yard shows.
    late: Option<String>,
    /// The switcher's list is shown as a popover at the rail's head: the
    /// row of it the keys are on.
    switching: Option<usize>,
    /// The cheatsheet of the open view's keys stands over the window.
    show_keys: bool,
    /// The About card stands over the window, with what the yardr on this
    /// machine says of itself.
    about: Option<About>,
    /// The Feedback form stands over the window, with what is typed in it.
    feedback: Option<Feedback>,
    /// The rail's mode icon the pointer stands on, if any: its glyph
    /// brightens, as quiet text does.
    rail_hover: Option<Mode>,
    /// The mail the pointer stands on, by seq, and the piece of it, if
    /// any: its bar of reactions to tap floats over it.
    react_hover: Option<(u64, Piece)>,
    /// The bar's emoji the pointer stands on, by mail and emoji, if any:
    /// it draws larger in its square. A piece left clears only its own
    /// mark, as a letter's does.
    emoji_hover: Option<(u64, String)>,
    /// The ask decline was pressed on with an empty line: the next Enter
    /// sends the typed words as the decline, and esc leaves it.
    declining: Option<(String, u64)>,
    /// The field of a secret ask's card, which shows marks unless its
    /// toggle is pressed. It is another than the line: what is typed here
    /// is in no draft and with no ask's words, and it is gone when the
    /// card is left.
    secret: Entity<Line>,
    /// The history's filter field. The model holds what is typed, as it is
    /// typed; the field is the editor alone.
    filter: Entity<Line>,
    /// The values typed so far for an ask of several names, in the order
    /// of its names: they go together, with the last.
    secret_typed: Vec<String>,
    /// The ask the field and those values are for.
    secret_for: Option<(String, u64)>,
    /// The field draws the secret as typed, for a look: its toggle's
    /// state, for the ask the field is for, and kept for no other.
    secret_shown: bool,
    /// The field of a weighty card's typed-back number, where no unlock
    /// is offered: the ask's number, drawn as typed. It is another than
    /// the secret field: a secret ask's value and its number are typed
    /// apart, and the number never carries the value.
    typeback: Entity<Line>,
    /// The session and ask the number field is for: bead IDs and ask
    /// numbers can be the same in different yards.
    typeback_for: Option<(u64, String, u64)>,
    /// The run ask whose approval is with the yard and not answered yet:
    /// no second one goes after it.
    approving: Option<(String, u64)>,
    /// A pairing approval's sitting: the transient on its decided card
    /// until the screen is left or the code runs out, then its ended
    /// state. Screen memory alone, never logged or filed.
    approval_pairing: Option<ApprovalPairing>,
    /// The teammates whose removals are with the yard and not answered
    /// yet, by following session and user: no second filing goes after
    /// one.
    removing: HashSet<(u64, String)>,
    /// The parked beads whose moves are with the yard and not answered
    /// yet, by following session and bead: no second move goes after one.
    moving: HashSet<(u64, String)>,
    /// The Pair a phone pane's device field: the name the pairing is
    /// opened for. It is another than the line: what is typed here is in
    /// no draft and with no ask's words, and it is gone when a pairing
    /// opens.
    device_name: Entity<Line>,
    /// A pairing's opening is with the yard and not answered yet: no
    /// second one goes after it, and no ending either.
    pairing_opening: bool,
    /// A pairing's ending is with the yard and not answered yet: no
    /// second one goes after it, and no opening either.
    pairing_ending: bool,
    /// What the Mac's unlock says where a test fixed it instead of the
    /// system: whether the gate is offered, and what it answers. Tests
    /// start with no gate, so a weighty card never prompts the person
    /// running them; the window reads the system's where this is none.
    test_unlock: Option<(bool, bool)>,
    /// The run asks this yard took no approval of from this window, having
    /// no such call for it: their cards say where to approve instead.
    approve_elsewhere: HashSet<(String, u64)>,
    /// Why the yard did not take an ask's answer, by ask, as its card
    /// says it in place. A new answer for the ask clears it.
    refused: HashMap<(String, u64), String>,
    /// The attachments that are images, by id, as they are drawn.
    thumbs: HashMap<u64, Arc<Image>>,
    focus: FocusHandle,
    /// The board's waits banner's focus: a click takes it, and Enter
    /// with it opens the decisions mode.
    waits_focus: FocusHandle,
    /// The window this is drawn in: a change that comes with no key or
    /// click of its own, as the yard's answer does, moves the focus by it.
    handle: AnyWindowHandle,
    icon: Arc<Image>,
    /// Which read of the queue a put-aside return waits for: an older
    /// timer does nothing when the queue was read since.
    ask_generation: u64,
    /// The moment up to which the queue was read for put-aside returns: a
    /// return at or before it does not read the queue again.
    returns_read: Option<chrono::DateTime<chrono::Utc>>,
    /// The text size and the look, as they are drawn.
    settings: Settings,
    /// The file they are kept in, or none: then they last as long as the
    /// window.
    kept: Option<PathBuf>,
    /// Why the last change was not kept, if it was not.
    unkept: Option<String>,
    /// The settings are shown where the conversation is.
    settings_open: bool,
    /// A yard in the settings, to add, to sign in or to pair again: its
    /// name, its socket or its address, which of the account's yards at
    /// the edge, a pairing's code and a sign-in's email and password as
    /// they are typed, which of them show, whether a code or a sign-in is
    /// on its way to the yard, and what came of the last.
    yard_name: Entity<Line>,
    socket: Entity<Line>,
    address: Entity<Line>,
    edge_yard: Entity<Line>,
    code: Entity<Line>,
    email: Entity<Line>,
    password: Entity<Line>,
    adding: Option<Adding>,
    pairing: bool,
    signing_in: bool,
    yard_said: Option<String>,
    /// The web view's base address as it is typed: what opens a note's
    /// pages in the browser, and what a typed one that is none says.
    view: Entity<Line>,
    view_said: Option<String>,
    run: Entity<Line>,
    run_said: Option<String>,
    /// The voice key as it is typed: what talking with the yard by voice
    /// is spoken to OpenAI with, and what a typed one that is none says.
    /// A masked line, as a secret ask's field is: what is typed is in no
    /// draft, and Enter keeps it beside the settings and clears the field.
    voice_key: Entity<Line>,
    voice_said: Option<String>,
    /// Whether the list of voices stands open under its field in the
    /// settings, as the yard's ⋯ menu stands open on its card: shut by a
    /// pick, by esc, and by leaving the section.
    voice_menu: bool,
    /// The microphones the machine lists, as the Voice settings last read
    /// them (`read_inputs`): none until they have been. A microphone that
    /// is plugged in later is there when the list is opened again.
    voice_inputs: Option<Vec<Input>>,
    /// Whether the list of microphones stands open under its field, shut as
    /// the list of voices is.
    voice_input_menu: bool,
    /// The voice session of the open conversation, while one stands or is
    /// being made. Never held with a yard: leaving the conversation, the
    /// yard or the window ends it.
    voice: Option<Talk>,
    /// Why the last session could not be made, or ended: the words of
    /// whoever refused it, shown in the conversation's head and never parsed.
    /// A new tap, or another conversation, clears them.
    voice_refusal: Option<String>,
    /// How many voice sessions the window started, which tells their words
    /// apart.
    voices: u64,
    /// "Set up a yard here", while it is underway: it stands where the
    /// yard that is not there would, and where its conversation will.
    first_run: Option<Entity<FirstRun>>,
    /// What the first run reaches outside the window with. The switch
    /// reaches out with the same, and so does the top strip.
    means: Means,
    /// A left press on the window's top strip, waiting to be a drag.
    title_press: titlebar::Press,
    /// The status row at the list's head: the yardr it runs, ensured
    /// once, and the PATH widened by doctor, once, which only grows.
    switch_program: Option<PathBuf>,
    switch_path: Option<std::ffi::OsString>,
    /// What `status` last said of the open yard, or that its home holds
    /// no yard. Neither is a reading that failed, or none yet.
    switch_status: Option<setup::Status>,
    switch_noyard: bool,
    /// A reading is underway: another is not started meanwhile, and its
    /// answer is fresh enough for both.
    switch_reading: bool,
    /// What the switch is doing, if anything.
    switch_busy: Option<SwitchBusy>,
    /// What the last start could not start, in yardr's words, while the
    /// yard is down still: what the status row says the yard lacks.
    switch_troubles: Vec<String>,
    /// One faint line under the switch: why yardr is not there to run,
    /// or what there is to know of the one there is. A reading that went
    /// through clears it.
    switch_note: Option<String>,
    /// The question before stopping: what down would stop, which nothing
    /// has agreed to yet. It stands where the conversation is.
    switch_question: Option<setup::Down>,
    /// "Agents and you" in the settings: the near yard's operator
    /// settings. The chosen style, the line about the operator as it is
    /// typed, what of the two is underway, whether the yard's own stand
    /// in them, and what came of the last read or save.
    agents_style: usize,
    agents_about: Entity<Line>,
    agents_busy: Option<AgentsBusy>,
    agents_read: bool,
    agents_said: Option<String>,
    /// Telemetry in the settings: the switch's change underway, if one
    /// is, what came of the last press, and the install id as last
    /// copied, if it still stands. The preview itself is the model's,
    /// read with the yard.
    telemetry_busy: Option<bool>,
    telemetry_said: Option<String>,
    telemetry_copied: Option<String>,
    /// The yard whose ⋯ menu stands open on its card, if one does:
    /// pair again, rename and remove, and the sign-in again of a hosted
    /// yard.
    yard_menu: Option<String>,
    /// The row to open once the yard has it: the yardmaster's, after the
    /// first run, whose yard may not have answered yet.
    wanted_row: Option<Selected>,
    /// The system's notifications, and what it answered when it was asked
    /// whether footplate may notify: it is asked when the settings switch
    /// them on, and at the start when they are on.
    system: Box<dyn notify::System>,
    permission: Option<Permission>,
    /// Hands on the rows of the notifications a person activates, for as
    /// long as it is held here.
    _heeding: Task<()>,
    /// What arrived, in whichever yard, and is told of when the burst it
    /// came in is over.
    burst: Burst,
    /// A settings change invalidates timers for any batch already waiting.
    burst_generation: u64,
    /// Whether the window is the one in front.
    front: bool,
    /// How many things the dock's icon says wait ([`waiting`]).
    waiting: usize,
    /// The item in the Mac's menu bar or a Linux desktop's tray (tray.rs).
    #[cfg(any(target_os = "macos", target_os = "linux", test))]
    tray: crate::tray::Tray,
    /// Hands on what a person chooses in the item's menu, for as long as
    /// it is held here.
    #[cfg(any(target_os = "macos", target_os = "linux", test))]
    _tray_heeding: Task<()>,
}

impl Footplate {
    /// The window on the yard behind `client`, for the user the yard knows
    /// `name` as. It follows the yard from here on.
    #[cfg(test)]
    pub fn new(client: Client, name: String, window: &mut Window, cx: &mut Context<Self>) -> Self {
        let mut this = Self::bare(Env::default(), name, window, cx);
        this.follow(settings::HERE.to_string(), Ok(client), cx);
        this
    }

    /// The window on the yard the environment names, else the one the
    /// settings kept in `file` had open last: one of this machine, for the
    /// user the yard knows `name` as, or one at an address, for the user
    /// its token is of. A yard that cannot be opened is said why, and the settings
    /// are there to choose again.
    pub fn opened(
        env: Env,
        name: String,
        file: Option<PathBuf>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> Self {
        Self::watching(env, name, file, session::WATCH, session::RETRY, window, cx)
    }

    /// The window before it has a yard.
    fn bare(env: Env, name: String, window: &mut Window, cx: &mut Context<Self>) -> Self {
        // The title in the window's options reaches a macOS and an X11
        // window; a Wayland one has only what is set on it.
        window.set_window_title(crate::NAME);
        let line = cx.new(Line::new);
        cx.subscribe(&line, |this, _, _: &Submitted, cx| this.send(cx))
            .detach();
        cx.subscribe(&line, |this, _, pasted: &Pasted, cx| {
            this.paste(&pasted.0, cx)
        })
        .detach();
        cx.subscribe(&line, |this, _, _: &Emptied, cx| this.remove_last(cx))
            .detach();
        let secret = cx.new(Line::masked);
        cx.subscribe(&secret, |this, _, _: &Submitted, cx| this.give(cx))
            .detach();
        // A weighty card's typed-back number, where no unlock is offered:
        // drawn as typed, as a terminal echoes it. Enter in it submits
        // nothing: the approval or the give reads it, and Enter alone
        // approves nothing still.
        let typeback = cx.new(Line::new);
        // The card's Give and Send buttons are disabled while their field
        // is empty: the window is drawn again with what is typed.
        cx.observe(&line, |_, _, cx| cx.notify()).detach();
        cx.observe(&secret, |this, secret, cx| {
            // A filled secret field types another: whatever candidate the
            // setup card took is taken back as the field fills.
            if !secret.read(cx).text().is_empty()
                && let Some((bead, ask)) = this.open_ask()
                && let Some(model) = this.model.as_mut()
            {
                model.clear_account(&bead, ask);
            }
            cx.notify();
        })
        .detach();
        // The history's filter: what is typed is the model's, as it is
        // typed, and the window draws the rows again only when it changed.
        let filter = cx.new(|cx| {
            let mut filter = Line::new(cx);
            filter.set_placeholder("Filter decided ( / )", cx);
            filter
        });
        cx.observe(&filter, |this, filter, cx| {
            let typed = filter.read(cx).text().to_string();
            let changed = this
                .model
                .as_mut()
                .is_some_and(|m| m.set_decided_filter(&typed));
            if changed {
                cx.notify();
            }
        })
        .detach();
        // The Pair a phone pane's device field: Enter in it opens the
        // pairing for the name typed. The Open button is dimmed while it
        // is empty: the window is drawn again with what is typed.
        let device_name = cx.new(|cx| {
            let mut field = Line::new(cx);
            field.set_placeholder("iphone", cx);
            field
        });
        cx.subscribe(&device_name, |this, _, _: &Submitted, cx| {
            this.open_phone_pairing(cx)
        })
        .detach();
        cx.observe(&device_name, |_, _, cx| cx.notify()).detach();
        // Enter in a field of a yard adds it, or sends the pairing's code.
        let field = |hint: &'static str, cx: &mut Context<Self>| {
            let field = cx.new(|cx| {
                let mut field = Line::new(cx);
                field.set_placeholder(hint, cx);
                field
            });
            cx.subscribe(&field, |this, _, _: &Submitted, cx| this.submit_yard(cx))
                .detach();
            field
        };
        let yard_name = field("plantime", cx);
        let socket = field("/Users/plantime/.yardr/yard.sock", cx);
        let address = field("https://mac.example.net", cx);
        let edge_yard = field("airy", cx);
        let code = field("K7QM-2XPD", cx);
        let email = field("jo@example.net", cx);
        // The password shows marks, as a secret ask's field does: what is
        // typed is in no draft and with no ask's words.
        let password = cx.new(Line::masked);
        cx.subscribe(&password, |this, _, _: &Submitted, cx| this.submit_yard(cx))
            .detach();
        // Enter in the web view's address keeps it: a note's pages open
        // through it.
        let view = cx.new(|cx| {
            let mut field = Line::new(cx);
            field.set_placeholder(settings::WEB_VIEW, cx);
            field
        });
        cx.subscribe(&view, |this, _, _: &Submitted, cx| this.submit_view(cx))
            .detach();
        // Enter in the run base keeps it: a note's pages run through
        // it. Empty is the view's host on the sandbox port.
        let run = cx.new(|cx| {
            let mut field = Line::new(cx);
            field.set_placeholder("http://127.0.0.1:8789/", cx);
            field
        });
        cx.subscribe(&run, |this, _, _: &Submitted, cx| this.submit_run(cx))
            .detach();
        // Enter in the voice key keeps it beside the settings and clears
        // the field. The key shows marks, as the Kratos password does:
        // what is typed is in no draft.
        let voice_key = cx.new(Line::masked);
        cx.subscribe(&voice_key, |this, _, _: &Submitted, cx| {
            this.submit_voice_key(cx)
        })
        .detach();
        // Enter in the line about the operator saves it with the chosen
        // style: the next session picks both up.
        let agents_about = cx.new(|cx| {
            let mut field = Line::new(cx);
            field.set_placeholder("I teach history and do not read code", cx);
            field
        });
        cx.subscribe(&agents_about, |this, _, _: &Submitted, cx| {
            this.save_agents(cx)
        })
        .detach();
        let selection = cx.new(|_| Selection::default());
        cx.observe(&selection, |_, _, cx| cx.notify()).detach();
        // Auto is the desktop's look: when that changes, the window is
        // drawn again.
        cx.observe_window_appearance(window, |_, _, cx| cx.notify())
            .detach();
        // The settings' keys are the application's, as quit is. An action
        // of the window goes by way of what has the focus, and while the
        // yard is away that is a line that is not drawn: it would go
        // nowhere.
        Self::on_app_action::<OpenSettings>(window, cx, Self::toggle_settings);
        // The application menu's About, which no key opens.
        Self::on_app_action::<OpenAbout>(window, cx, Self::show_about);
        Self::on_app_action::<Larger>(window, cx, |this, _, cx| this.resize(1, cx));
        Self::on_app_action::<Smaller>(window, cx, |this, _, cx| this.resize(-1, cx));
        Self::on_app_action::<UsualSize>(window, cx, |this, _, cx| this.usual_size(cx));
        Self::on_app_action::<NextLook>(window, cx, |this, _, cx| {
            this.look(this.settings.look.next(), cx)
        });
        // So are the switcher's: another yard is opened from wherever the
        // focus is, and from a yard that is away.
        Self::on_app_action::<SwitchYards>(window, cx, Self::toggle_switcher);
        // Enter for the away screen's details likewise answers from
        // wherever the focus is, but unlike those it never stops the key:
        // the fields and the line take Enter beside it, after it.
        {
            let (this, handle) = (cx.weak_entity(), window.window_handle());
            let app: &mut App = cx;
            app.on_action(move |_: &AwayDetails, cx| {
                cx.propagate();
                let this = this.clone();
                cx.defer(move |cx| {
                    let _ = handle.update(cx, |_, _, cx| {
                        this.update(cx, |this, cx| this.away_details_key(cx))
                    });
                });
            });
        }
        Self::on_app_action::<Yard1>(window, cx, |this, w, cx| this.switch_nth(0, w, cx));
        Self::on_app_action::<Yard2>(window, cx, |this, w, cx| this.switch_nth(1, w, cx));
        Self::on_app_action::<Yard3>(window, cx, |this, w, cx| this.switch_nth(2, w, cx));
        Self::on_app_action::<Yard4>(window, cx, |this, w, cx| this.switch_nth(3, w, cx));
        Self::on_app_action::<Yard5>(window, cx, |this, w, cx| this.switch_nth(4, w, cx));
        Self::on_app_action::<Yard6>(window, cx, |this, w, cx| this.switch_nth(5, w, cx));
        Self::on_app_action::<Yard7>(window, cx, |this, w, cx| this.switch_nth(6, w, cx));
        Self::on_app_action::<Yard8>(window, cx, |this, w, cx| this.switch_nth(7, w, cx));
        Self::on_app_action::<Yard9>(window, cx, |this, w, cx| this.switch_nth(8, w, cx));
        // What arrives on the open row of a window in front is read there,
        // and the system tells of the rest.
        cx.observe_window_activation(window, |this, window, _| {
            this.front = window.is_window_active()
        })
        .detach();
        // The window's close button asks here first. Where closing hides,
        // the window is kept and the application hidden with it, so this
        // view, its followers, its models and its drafts go on; else the
        // window closes, and the application quits with its one window.
        // Quitting does not ask here.
        let this = cx.weak_entity();
        window.on_window_should_close(cx, move |_, cx| {
            // Shut or hidden, the window shows nothing from here on: a voice
            // session does not go on under it (design 3.2).
            let _ = this.update(cx, |this, cx| this.end_voice(cx));
            let hides = this.read_with(cx, |this, _| this.closing_hides());
            if !hides.unwrap_or(false) {
                return true;
            }
            // A test hides nothing: gpui's test platform has no hide.
            #[cfg(not(test))]
            cx.hide();
            false
        });
        // Whatever changes what waits in a yard has the window drawn
        // again: the dock's icon is told there, of every yard at once and
        // with the window behind another, where nothing is drawn. The
        // item in the menu bar is told after it, and says its number.
        cx.observe_self(|this, cx| {
            // And the row that is waited for is opened once it is there.
            this.seek_wanted(cx);
            this.badge();
            #[cfg(any(target_os = "macos", target_os = "linux", test))]
            this.tray();
        })
        .detach();
        let system = notify::system();
        let heeding = Self::heed(system.as_ref(), cx);
        #[cfg(any(target_os = "macos", target_os = "linux", test))]
        let tray = crate::tray::Tray::default();
        #[cfg(any(target_os = "macos", target_os = "linux", test))]
        let tray_heeding = Self::heed_tray(tray.chosen(), cx);

        Footplate {
            client: None,
            name,
            env,
            yard: String::new(),
            opening: 0,
            session: 0,
            sessions: 0,
            watch: session::WATCH,
            retry: session::RETRY,
            entry: None,
            held: HashMap::new(),
            following: None,
            following_stop: None,
            model: None,
            down: None,
            away: Away::Stopped,
            away_details: false,
            answered_while_adding: false,
            said: None,
            line,
            conversation: ScrollHandle::new(),
            new_below: 0,
            bottom_pending: false,
            anchor: None,
            stood: None,
            older_at: None,
            back_position: None,
            decision: ScrollHandle::new(),
            drawer: None,
            drawer_scroll: ScrollHandle::new(),
            rows: ScrollHandle::new(),
            selection,
            images: HashMap::new(),
            image_open: None,
            picture_menu: None,
            screen_open: None,
            screen_read: 0,
            screen_scroll: ScrollHandle::new(),
            view_up: ViewUp::Unknown,
            run_up: ViewUp::Unknown,
            rows_shown: Cell::new(false),
            drafts: Drafts::default(),
            ask_words: HashMap::new(),
            kept_words: HashMap::new(),
            note_files: HashMap::new(),
            kept_note_files: HashMap::new(),
            unreached: HashMap::new(),
            places: HashMap::new(),
            returning: None,
            late: None,
            switching: None,
            show_keys: false,
            about: None,
            feedback: None,
            rail_hover: None,
            react_hover: None,
            emoji_hover: None,
            declining: None,
            secret,
            filter,
            secret_typed: Vec::new(),
            secret_for: None,
            secret_shown: false,
            typeback,
            typeback_for: None,
            approving: None,
            approval_pairing: None,
            removing: HashSet::new(),
            moving: HashSet::new(),
            device_name,
            pairing_opening: false,
            pairing_ending: false,
            test_unlock: match cfg!(test) {
                true => Some((false, false)),
                false => None,
            },
            approve_elsewhere: HashSet::new(),
            refused: HashMap::new(),
            thumbs: HashMap::new(),
            focus: cx.focus_handle(),
            waits_focus: cx.focus_handle(),
            handle: window.window_handle(),
            icon: Arc::new(Image::from_bytes(ImageFormat::Png, ICON.to_vec())),
            ask_generation: 0,
            returns_read: None,
            settings: Settings::default(),
            kept: None,
            unkept: None,
            settings_open: false,
            yard_name,
            socket,
            address,
            edge_yard,
            code,
            email,
            password,
            adding: None,
            pairing: false,
            signing_in: false,
            yard_said: None,
            view,
            view_said: None,
            run,
            run_said: None,
            voice_key,
            voice_said: None,
            voice_menu: false,
            voice_inputs: None,
            voice_input_menu: false,
            voice: None,
            voice_refusal: None,
            voices: 0,
            first_run: None,
            means: Means::real(),
            title_press: titlebar::Press::default(),
            switch_program: None,
            switch_path: None,
            switch_status: None,
            switch_noyard: false,
            switch_reading: false,
            switch_busy: None,
            switch_troubles: Vec::new(),
            switch_note: None,
            switch_question: None,
            agents_style: 0,
            agents_about,
            agents_busy: None,
            agents_read: false,
            agents_said: None,
            telemetry_busy: None,
            telemetry_said: None,
            telemetry_copied: None,
            yard_menu: None,
            wanted_row: None,
            system,
            permission: None,
            _heeding: heeding,
            burst: Burst::default(),
            burst_generation: 0,
            front: window.is_window_active(),
            waiting: 0,
            #[cfg(any(target_os = "macos", target_os = "linux", test))]
            tray,
            #[cfg(any(target_os = "macos", target_os = "linux", test))]
            _tray_heeding: tray_heeding,
        }
    }

    /// The window with what `file` keeps of the text size, the look and the
    /// yards, which is where a change of them is kept from here on. The
    /// yard that is open stays open: [`Footplate::opened`] opens the kept
    /// one.
    pub fn kept_in(mut self, file: Option<PathBuf>, cx: &mut Context<Self>) -> Self {
        if let Some(file) = &file {
            self.settings = Settings::read(file);
        }
        // The addresses' fields hold the shown yard's, or the one the
        // settings open where the window shows none yet.
        let shown = self.yard.clone();
        let entry = self
            .settings
            .yard(&shown)
            .unwrap_or_else(|| self.settings.opened())
            .clone();
        self.view
            .update(cx, |line, cx| line.set_text(&entry.web_view, cx));
        self.run
            .update(cx, |line, cx| line.set_text(&entry.run_base, cx));
        let usual = entry.view(&self.env.socket).unwrap_or("").to_string();
        self.view
            .update(cx, |line, cx| line.set_placeholder(&usual, cx));
        let run_usual = entry
            .view(&self.env.socket)
            .and_then(|view| Address::parse_view(view).ok())
            .map(|view| view.run_base().to_string())
            .unwrap_or_default();
        self.run
            .update(cx, |line, cx| line.set_placeholder(&run_usual, cx));
        cx.set_global(self.settings.look);
        self.kept = file;
        if self.settings.notifications.on {
            self.ask_permission(cx);
        }
        self
    }

    pub fn line(&self) -> &Entity<Line> {
        &self.line
    }
}

/// What an expanded card shows of its bead: the body, the notes with
/// their pictures, the about-beads and the design doc.
pub(crate) struct Expanded<'a> {
    body: &'a str,
    notes: &'a [model::CardNote],
    about: &'a [crate::api::AboutBead],
    doc: &'a str,
}

impl Drop for Footplate {
    fn drop(&mut self) {
        if let Some(stop) = self.following_stop.take() {
            stop.stop();
        }
    }
}

impl Focusable for Footplate {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus.clone()
    }
}

impl Render for Footplate {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        // A file's or page's row sets it where one is drawn: a "no" from
        // the view or the sandbox origin is asked again only while one is.
        self.rows_shown.set(false);
        self.reconcile_scroll(window, cx);
        // The one place the text size is set: every size that goes with the
        // text is in rems, and the text itself is seven eighths of one.
        window.set_rem_size(self.settings.rem());
        let palette = Palette::now(window, cx);
        // On a card the window holds the keys to pick with, and the line to
        // type words in: with the focus in the line those keys are text.
        let context = match self.model.as_ref().and_then(|m| m.selected().cloned()) {
            // The switcher's list has the keys while it is open.
            _ if self.switching.is_some() => SWITCH_CONTEXT,
            // The settings stand where the card or the notices do: the keys
            // that pick and mark read are not for what is not in view.
            _ if self.settings_open => CONTEXT,
            // Nor are they for the window with an image over it: the
            // window holds the keys until it shuts.
            _ if self.image_open.is_some() => CONTEXT,
            // Nor with a session's screen over it, as above.
            _ if self.screen_open.is_some() => CONTEXT,
            // Nor with the Feedback form over it, whose fields take any
            // letter a card's keys are.
            _ if self.feedback.is_some() => CONTEXT,
            // Nor are they for the first run, whose fields take names.
            _ if self.first_run.is_some() => CONTEXT,
            // Nor for the question before stopping, which stands where
            // the card is: it is answered with a click, or left with esc.
            _ if self.switch_question.is_some() => CONTEXT,
            // A yard that is away has no card in view either, and what is
            // typed there is a yard's name or a code: `e` and `d` are
            // letters of it, and Enter is the field's. One that is
            // reconnecting keeps its card, and its keys.
            _ if self.down.is_some() && !self.reconnecting() => CONTEXT,
            Some(Selected::Conversation(_)) => CONTEXT,
            // With the focus in the history's filter its keys are text,
            // whatever is open: a `d` or `/` typed there is no card's.
            _ if self.filter.focus_handle(cx).is_focused(window) => CONTEXT,
            // With the focus in the Pair a phone pane's field its keys
            // are text, whatever is open: an `i` or `e` typed there is
            // no card's.
            _ if self.device_name.focus_handle(cx).is_focused(window) => CONTEXT,
            Some(Selected::Decision(_))
            | Some(Selected::Waiting(_))
            | Some(Selected::Decided(_, _))
                if self.line.focus_handle(cx).is_focused(window)
                    || self.secret.focus_handle(cx).is_focused(window)
                    || self.typeback.focus_handle(cx).is_focused(window) =>
            {
                CONTEXT
            }
            // The Lines details of a parked bead end with the card's line,
            // where it is drawn: no other bead's details have a line to
            // type in, and their keys are not the line's text.
            Some(Selected::Bead(_))
                if self.waiting_card().is_some()
                    && self.line.focus_handle(cx).is_focused(window) =>
            {
                CONTEXT
            }
            _ => NO_LINE_CONTEXT,
        };
        let root = div()
            .key_context(context)
            .track_focus(&self.focus)
            .on_action(cx.listener(|this, _: &Next, window, cx| this.step(1, window, cx)))
            .on_action(cx.listener(|this, _: &Previous, window, cx| this.step(-1, window, cx)))
            .on_action(cx.listener(|this, _: &NextMode, window, cx| this.step_mode(1, window, cx)))
            .on_action(
                cx.listener(|this, _: &PreviousMode, window, cx| this.step_mode(-1, window, cx)),
            )
            .on_action(cx.listener(Self::copy))
            .on_action(cx.listener(Self::dismiss))
            .on_action(cx.listener(|this, _: &DismissAll, _, cx| this.dismiss_all(cx)))
            .on_action(cx.listener(|this, _: &Pick1, _, cx| this.pick(1, cx)))
            .on_action(cx.listener(|this, _: &Pick2, _, cx| this.pick(2, cx)))
            .on_action(cx.listener(|this, _: &Pick3, _, cx| this.pick(3, cx)))
            .on_action(cx.listener(|this, _: &Pick4, _, cx| this.pick(4, cx)))
            .on_action(cx.listener(|this, _: &Pick5, _, cx| this.pick(5, cx)))
            .on_action(cx.listener(|this, _: &Pick6, _, cx| this.pick(6, cx)))
            .on_action(cx.listener(|this, _: &Pick7, _, cx| this.pick(7, cx)))
            .on_action(cx.listener(|this, _: &Pick8, _, cx| this.pick(8, cx)))
            .on_action(cx.listener(|this, _: &Pick9, _, cx| this.pick(9, cx)))
            .on_action(cx.listener(|this, _: &ChoiceUp, _, cx| this.choice(-1, cx)))
            .on_action(cx.listener(|this, _: &ChoiceDown, _, cx| this.choice(1, cx)))
            .on_action(
                cx.listener(|this, _: &Decide, window, cx| match this.switching {
                    Some(at) => this.switch_nth(at, window, cx),
                    // The board's waits banner owns Enter with the focus
                    // on it: no card is open there, and the link opens
                    // the decisions mode, as a click does.
                    None if this.card().is_none() && this.waits_focus.is_focused(window) => {
                        this.set_mode(Mode::Decisions, window, cx)
                    }
                    None => this.decide(cx),
                }),
            )
            .on_action(
                cx.listener(|this, _: &AddYard, window, cx| {
                    this.add_yard_from_switcher(window, cx)
                }),
            )
            .on_action(cx.listener(|this, _: &Approve, _, cx| this.approve(cx)))
            .on_action(cx.listener(Self::decline))
            .on_action(cx.listener(Self::ask_about))
            .on_action(cx.listener(Self::expand))
            .on_action(cx.listener(Self::focus_words))
            .on_action(cx.listener(Self::focus_filter))
            .on_action(cx.listener(Self::leave))
            .on_action(cx.listener(|this, _: &ShowKeys, _, cx| this.toggle_keys(cx)))
            .on_action(cx.listener(Self::jump_newest))
            .on_action(cx.listener(Self::jump_oldest))
            .on_action(cx.listener(|this, _: &PageUp, window, cx| this.page(false, window, cx)))
            .on_action(cx.listener(|this, _: &PageDown, window, cx| this.page(true, window, cx)))
            // Files dropped anywhere on the window are for the note of
            // the open card, where one is, else for the draft of the open
            // conversation.
            .on_drop(
                cx.listener(|this, files: &ExternalPaths, _, cx| this.dropped(files.paths(), cx)),
            )
            .size_full()
            .flex()
            .bg(palette.ground)
            .text_color(palette.text)
            .text_size(rems(select::ROOT_TEXT_REM));
        // Where the content reaches up into the title bar, a drag on the
        // window's top moves it, and the band across the rail and the list
        // leaves that strip to the traffic lights.
        let root = self.title_strip(root, window, cx);
        let top = titlebar::inset(self.means.titlebar.is_some(), window.is_fullscreen());
        // The rail stands on the window's far left whatever shows: the
        // modes answer where a yard's rows are there, and the foot's
        // switcher and settings stay alive while the yard is away.
        let root = root.child(self.rail(palette, top, cx));
        // A yard that is away keeps the status row beside the screen,
        // with none of its rows: what they open is not there. Only a
        // yard of this machine has one; one at an address, the one yard
        // the environment names, and one being set up here have none.
        // One that is reconnecting keeps its rows with it, below.
        let beside = match (&self.down, &self.model) {
            (Some(_), _) if self.reconnecting() => None,
            (Some(_), _)
                if !matches!(self.switch_for(), SwitchFor::Far) && self.first_run.is_none() =>
            {
                Some(self.column(div().flex_1(), palette, top, cx))
            }
            _ => None,
        };
        let root = root.children(beside);
        let shown = match (&self.down, &self.model) {
            (Some(_), _) if self.settings_open && !self.reconnecting() => {
                root.child(self.talk_settings(palette, top, cx))
            }
            // A yard that answered in this run and is away now stays as
            // last seen: its rows, and its open row with its sends held.
            // The settings stand over that as their sheet, with no rows
            // beside them.
            (Some(_), Some(_)) if self.reconnecting() && self.settings_open => {
                root.child(self.talk_settings(palette, top, cx))
            }
            (Some(_), Some(model)) if self.reconnecting() && self.first_run.is_some() => root
                .child(self.list(model, palette, top, cx))
                .children(self.first_run.clone()),
            (Some(_), Some(model)) if self.reconnecting() => root
                .child(self.list(model, palette, top, cx))
                .child(self.talk(model, palette, cx))
                .children(self.talk_drawer(model, palette, cx)),
            (Some(why), _) => match &self.first_run {
                Some(first_run) => root.child(first_run.clone()),
                None => root.child(self.away(why, palette, cx)),
            },
            // The question before stopping stands where the conversation
            // is, and what was there is back once it is answered.
            (None, Some(model)) if self.switch_question.is_some() => {
                root.child(self.list(model, palette, top, cx)).child(
                    self.stop_question(
                        self.switch_question
                            .as_ref()
                            .expect("the question is asked"),
                        palette,
                        cx,
                    ),
                )
            }
            // The settings stand as their sheet, with their own
            // sections, over whatever stood open: no rows beside them.
            (None, Some(_)) if self.settings_open => {
                root.child(self.talk_settings(palette, top, cx))
            }
            // The yard answers before its first run is over: its rows are
            // there, and the first run where a conversation will be.
            (None, Some(model)) if self.first_run.is_some() => root
                .child(self.list(model, palette, top, cx))
                .children(self.first_run.clone()),
            (None, Some(model)) => root
                .child(self.list(model, palette, top, cx))
                .child(self.talk(model, palette, cx))
                .children(self.talk_drawer(model, palette, cx)),
            (None, None) => root,
        };
        // The switcher's list stands over whatever shows, to the right
        // of the rail's head; the image open over the window, where one
        // is, over that: over whatever shows, the settings and the first
        // run with it.
        let shown = shown.children(
            self.switching
                .map(|at| self.switcher(at, palette, window, cx)),
        );
        let shown = match &self.image_open {
            Some(open) => shown.child(self.image_layer(open, window, cx)),
            None => shown,
        };
        // The menu of a picture, in the thread or full size, over that:
        // Esc shuts it before the image.
        let shown = match &self.picture_menu {
            Some(menu) => shown.child(self.picture_menu_layer(menu, palette, cx)),
            None => shown,
        };
        // A session's screen over the image, where one is: Esc shuts
        // the top one first.
        let shown = match &self.screen_open {
            Some(open) => shown.child(self.screen_layer(open, window, cx)),
            None => shown,
        };
        // The Feedback form over that, the About card over it, which the
        // application menu opens from anywhere, and the cheatsheet over
        // everything else, as esc shuts it first.
        let shown = match &self.feedback {
            Some(form) => shown.child(self.feedback_layer(form, top, palette, cx)),
            None => shown,
        };
        let shown = match &self.about {
            Some(about) => shown.child(self.about_layer(about, top, palette, cx)),
            None => shown,
        };
        let keys = self.show_keys.then(|| self.keys_view());
        shown
            .children(keys.map(|view| self.keys_layer(view, palette, cx)))
            .into_any_element()
    }
}

fn expanded_text_key(card_key: u64, section: &str, index: usize, text: &str) -> u64 {
    select::key((card_key, section, index, text))
}

