    /// The recommendation stands under its own option with its why, and the
    /// ask's age beside its question; the head names the yard, the bead and
    /// the topic once; the line beside the disclosure names the bead and the
    /// ask's number, as `yardr bead answer` takes them.
    #[test]
    fn the_card_names_the_recommendation_its_age_and_its_head_once() {
        assert_eq!(
            recommended_line("the test passed"),
            "recommended: the test passed"
        );
        assert_eq!(recommended_line(""), "recommended");
        assert_eq!(asked_age("now"), "asked now");
        assert_eq!(asked_age("2h"), "asked 2h");
        assert_eq!(asked_age(""), "");
        assert_eq!(
            decision_head("plantime", "yd-ymkt", "Writing"),
            "plantime · bead yd-ymkt · Writing"
        );
        assert_eq!(ask_line("bead-a", 3), "bead-a · ask 3");
        // The number comes from the one counter of every note in the yard,
        // and a bead of another yard keeps its `@peer`.
        assert_eq!(
            ask_line("footplate-e09j", 14603),
            "footplate-e09j · ask 14603"
        );
        assert_eq!(ask_line("yd-ymkt@north", 7), "yd-ymkt@north · ask 7");
        assert_eq!(
            DECLINE_IS_NO_PICK,
            "Say no to all options. The asker finds another way."
        );
    }

    #[test]
    fn a_writable_secret_card_lists_ask_about_this_in_its_footer() {
        let ordinary = "i types it · enter sends it to the yard · esc leaves, and nothing is sent · or in a terminal: yardr bead answer bead-s 7 --secret";
        assert_eq!(
            secret_keys("bead-s", 7, Approval::Direct, true),
            format!("{ordinary} · a ask about this")
        );
        assert_eq!(secret_keys("bead-s", 7, Approval::Direct, false), ordinary);
        // Where the Mac's unlock stands in front, Enter opens it first;
        // where no unlock is offered, `i` types the number before the value.
        assert_eq!(
            secret_keys("bead-s", 7, Approval::Unlock, true),
            "i types it · enter sends it to the yard after unlocking · esc leaves, and nothing is sent · or in a terminal: yardr bead answer bead-s 7 --secret · a ask about this"
        );
        assert_eq!(
            secret_keys("bead-s", 7, Approval::TypeBack, true),
            "i types the number, then it · enter sends it to the yard with its number · esc leaves, and nothing is sent · or in a terminal: yardr bead answer bead-s 7 --secret · a ask about this"
        );
        assert_eq!(
            secret_keys("bead-s", 7, Approval::Nowhere, true),
            "in a terminal: yardr bead answer bead-s 7 --secret · a ask about this"
        );
        assert_eq!(approval(false, true, false), Approval::Direct);
        assert_eq!(approval(false, false, false), Approval::Direct);
        assert_eq!(approval(true, true, false), Approval::Unlock);
        assert_eq!(approval(true, false, false), Approval::TypeBack);
        assert_eq!(approval(false, true, true), Approval::Nowhere);
        assert_eq!(approval(true, true, true), Approval::Nowhere);
        assert_eq!(approval(true, false, true), Approval::Nowhere);
        assert_eq!(
            approve_unlock_label("plantime"),
            "Approve in plantime after unlocking"
        );
        assert_eq!(
            typeback_line(7, "approve"),
            "type the ask's number, 7, to approve this weighty card"
        );
        assert_eq!(
            typeback_line(7, "give"),
            "type the ask's number, 7, to give this weighty card"
        );
        assert_eq!(
            typeback_line(7, "pick"),
            "type the ask's number, 7, to pick this weighty card"
        );
        assert_eq!(
            typeback_mismatch(7),
            "ask 7's number was not typed back, so nothing was done"
        );
        assert_eq!(
            run_keys(Approval::Direct, true),
            format!("{APPROVE_KEY} approves · enter alone approves nothing · a ask about this")
        );
        assert_eq!(
            run_keys(Approval::Unlock, false),
            format!("{APPROVE_KEY} approves after unlocking · enter alone approves nothing")
        );
        assert_eq!(
            run_keys(Approval::TypeBack, false),
            format!(
                "{APPROVE_KEY} approves after its number is typed · enter alone approves nothing · i types the number"
            )
        );
        assert_eq!(run_keys(Approval::Nowhere, false), "");
        assert_eq!(run_keys(Approval::Nowhere, true), "a ask about this");
        let setup = api::Setup::default();
        let terminal = "or in a terminal: yardr bead answer bead-s 7 <n> --secret";
        assert_eq!(
            setup_keys("bead-s", 7, &setup, Approval::Direct, false),
            format!(
                "{APPROVE_KEY} approves · enter alone approves nothing · i types the account · {terminal}"
            )
        );
        assert_eq!(
            setup_keys("bead-s", 7, &setup, Approval::Unlock, false),
            format!(
                "{APPROVE_KEY} approves after unlocking · enter alone approves nothing · i types the account · {terminal}"
            )
        );
        assert_eq!(
            setup_keys("bead-s", 7, &setup, Approval::TypeBack, false),
            format!(
                "{APPROVE_KEY} approves after its number is typed · enter alone approves nothing · i types the number, then the account · {terminal}"
            )
        );
        assert_eq!(
            setup_keys("bead-s", 7, &setup, Approval::Nowhere, false),
            ""
        );
    }

