    /// A port whose listener answers the web view's front page to every
    /// connection: the view, up. Its base address.
    fn view_up() -> String {
        use std::io::{Read as _, Write as _};
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let base = format!("http://{}", listener.local_addr().unwrap());
        std::thread::spawn(move || {
            for mut conn in listener.incoming().flatten() {
                let mut asked = [0u8; 1024];
                let _ = conn.read(&mut asked);
                let _ = conn.write_all(
                    b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                );
            }
        });
        base
    }

    /// A view that `view_down` has stood up, until `view_serve` has it
    /// answer.
    #[derive(Default)]
    struct Standing {
        serving: AtomicBool,
        hits: Arc<AtomicUsize>,
    }

    /// The views `view_down` has stood up, by the base address it gave.
    fn standing() -> &'static Mutex<HashMap<String, Arc<Standing>>> {
        static STANDING: std::sync::OnceLock<Mutex<HashMap<String, Arc<Standing>>>> =
            std::sync::OnceLock::new();
        STANDING.get_or_init(Mutex::default)
    }

    /// A base address nothing answers at: the view, down. Its port is held
    /// from here on, so that nothing else is handed the number before
    /// `view_serve` starts the view there: a port let go is free to any
    /// other test or process that asks for one, and the suite asks all the
    /// time. The listener takes each connection and lets it go with no
    /// answer, which a probe reads as down. It listens, and is not left
    /// bound alone, since macOS drops the first packet to a port that is
    /// bound and does not listen: a probe at it would wait out its whole
    /// connect timeout, where a port let go refuses at once.
    fn view_down() -> String {
        use std::io::{Read as _, Write as _};
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let base = format!("http://{}", listener.local_addr().unwrap());
        let view = Arc::new(Standing::default());
        standing()
            .lock()
            .unwrap()
            .insert(base.clone(), view.clone());
        std::thread::spawn(move || {
            for mut conn in listener.incoming().flatten() {
                if !view.serving.load(Ordering::SeqCst) {
                    continue;
                }
                view.hits.fetch_add(1, Ordering::SeqCst);
                let mut asked = [0u8; 1024];
                let _ = conn.read(&mut asked);
                let _ = conn.write_all(
                    b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n",
                );
            }
        });
        base
    }

    /// The view started after the first probe at the down address `base`:
    /// now answering its front page there, on the port `view_down` held.
    /// Counts the connections it answers.
    fn view_serve(base: &str) -> Arc<AtomicUsize> {
        let view = standing().lock().unwrap().remove(base);
        let view = view
            .unwrap_or_else(|| panic!("{base} is no address view_down gave, or is served already"));
        view.serving.store(true, Ordering::SeqCst);
        view.hits.clone()
    }

    /// Whether the window has the web view up, down, or not asked yet.
    fn view_answered(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<bool> {
        view.read_with(cx, |v, _| v.view_up_now())
    }

    /// Whether the window has the sandbox origin up, down, or not asked yet.
    fn run_answered(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<bool> {
        view.read_with(cx, |v, _| v.run_up_now())
    }

    /// The pages the window opens in the browser from here on: in place
    /// of the browser.
    fn opened_pages(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Rc<RefCell<Vec<String>>> {
        let opened: Rc<RefCell<Vec<String>>> = Rc::default();
        let pages = opened.clone();
        view.update(cx, |v, _| {
            v.means.open = Rc::new(move |url, _| pages.borrow_mut().push(url.to_string()));
        });
        opened
    }

    fn chosen_of(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        bead: &str,
        ask: u64,
    ) -> u64 {
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            let now = chrono::Utc::now();
            model
                .decision_detail(bead, &now)
                .unwrap()
                .asks
                .into_iter()
                .find(|a| a.ask == ask)
                .unwrap()
                .chosen
        })
    }

    fn has_bead(view: &Entity<Footplate>, cx: &mut VisualTestContext, bead: &str) -> bool {
        view.read_with(cx, |v, _| v.model.as_ref().unwrap().has_bead(bead))
    }

    fn expanded_of(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        bead: &str,
        ask: u64,
    ) -> bool {
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            let now = chrono::Utc::now();
            model
                .decision_detail(bead, &now)
                .unwrap()
                .asks
                .into_iter()
                .find(|a| a.ask == ask)
                .unwrap()
                .expanded
        })
    }

    fn current_ask_of(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> u64 {
        view.read_with(cx, |v, _| {
            v.model.as_ref().unwrap().current_ask().unwrap().1
        })
    }

    #[gpui::test]
    fn the_card_picks_with_words_puts_aside_declines_and_expands(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_three());
        yard.answer("Bead", &bead_three());
        yard.answer("AnswerAsk", "{}");
        yard.answer("DeferAsk", "{}");
        yard.answer("DeclineAsk", "{}");
        yard.answer("AddNote", "{}");
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        // The bead opens on its oldest ask, and the bead is read.
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-a".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-a"));
        assert_eq!(current_ask_of(&view, cx), 3);
        cx.run_until_parked();

        // A number key chooses; Enter sends the pick. The line starts
        // focused, so esc holds the window's keys first.
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("2");
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), 2);
        cx.simulate_keystrokes("enter");
        wait(cx, "the pick", |_| {
            yard.asked("AnswerAsk")
                == [json!({"bead": "bead-a", "ask": 3, "option": 2, "actor": "jo"})]
        });
        // The ask moves to Decided at once in the model; the queue's next
        // read is the yard's stale answer in this test, which brings it
        // back. What matters here is the write.
        cx.run_until_parked();

        // A pick with words on the next ask: choose, type them in, Enter
        // sends the one answer.
        view.update(cx, |v, cx| v.select_ask("bead-a".into(), 4, cx));
        assert_eq!(current_ask_of(&view, cx), 4);
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("1");
        assert_eq!(chosen_of(&view, cx, "bead-a", 4), 1);
        cx.simulate_keystrokes("i");
        cx.simulate_input("send them tonight");
        assert_eq!(typed(&view, cx), "send them tonight");
        cx.simulate_keystrokes("enter");
        wait(cx, "the pick with words", |_| {
            yard.asked("AnswerAsk").last()
                == Some(&json!({"bead": "bead-a", "ask": 4, "option": 1,
                                "words": "send them tonight", "actor": "jo"}))
        });
        assert_eq!(typed(&view, cx), "");
        cx.run_until_parked();

        // Words with no option chosen and no recommendation go as a plain
        // note; the ask stays open.
        view.update(cx, |v, cx| v.select_ask("bead-a".into(), 5, cx));
        assert_eq!(current_ask_of(&view, cx), 5);
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("i");
        cx.simulate_input("what about the docs links?");
        cx.simulate_keystrokes("enter");
        wait(cx, "the note", |_| {
            yard.asked("AddNote")
                == [json!({"bead": "bead-a", "text": "what about the docs links?", "actor": "jo"})]
        });
        assert_eq!(current_ask_of(&view, cx), 5);
        assert_eq!(typed(&view, cx), "");

        // `x` puts it aside.
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("x");
        wait(cx, "put aside", |_| {
            yard.asked("DeferAsk") == [json!({"bead": "bead-a", "ask": 5, "actor": "jo"})]
        });
        cx.run_until_parked();

        // Decline with words already typed goes at once.
        view.update(cx, |v, cx| v.select_ask("bead-a".into(), 3, cx));
        cx.simulate_keystrokes("i");
        cx.simulate_input("not mine to take");
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("d");
        wait(cx, "declined", |_| {
            yard.asked("DeclineAsk")
                == [json!({"bead": "bead-a", "ask": 3, "words": "not mine to take", "actor": "jo"})]
        });
        cx.run_until_parked();

        // Decline with an empty line asks for words: the next Enter sends
        // them.
        view.update(cx, |v, cx| v.select_ask("bead-a".into(), 4, cx));
        cx.simulate_keystrokes("escape");
        assert_eq!(typed(&view, cx), "");
        cx.simulate_keystrokes("d");
        cx.simulate_input("the greeting can wait");
        cx.simulate_keystrokes("enter");
        wait(cx, "declined after asking", |_| {
            yard.asked("DeclineAsk").last()
                == Some(
                    &json!({"bead": "bead-a", "ask": 4, "words": "the greeting can wait", "actor": "jo"}),
                )
        });
        cx.run_until_parked();

        // One key expands the card to the bead whole, and folds it again.
        view.update(cx, |v, cx| v.select_ask("bead-a".into(), 3, cx));
        cx.simulate_keystrokes("escape");
        assert!(!expanded_of(&view, cx, "bead-a", 3));
        cx.simulate_keystrokes("e");
        assert!(expanded_of(&view, cx, "bead-a", 3));
        // The window draws the expanded card and stays.
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        cx.simulate_keystrokes("e");
        assert!(!expanded_of(&view, cx, "bead-a", 3));

        // The arrows choose around the ends, even while words are typed.
        cx.simulate_keystrokes("i");
        cx.simulate_input("tonight?");
        cx.simulate_keystrokes("down");
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), 1);
        cx.simulate_keystrokes("up");
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), 3);
        assert_eq!(typed(&view, cx), "tonight?");
    }

    #[gpui::test]
    fn an_expanded_card_shows_its_notes_pictures(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_three());
        // The note names two images, and the yard holds one.
        let held = "ab".repeat(32);
        let gone = "cd".repeat(32);
        yard.blob(&held, &png());
        yard.answer("Bead", &bead_note_pictures(&held, &gone));
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-a".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-a"));
        // Folded, the card asks for none of the note's images.
        cx.run_until_parked();
        assert_eq!(yard.blobs_asked(), Vec::<String>::new());
        // One key expands it: the image the yard holds is drawn, and the
        // one it holds no longer is a line that says so.
        view.update(cx, |v, cx| v.select_ask("bead-a".into(), 3, cx));
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("e");
        assert!(expanded_of(&view, cx, "bead-a", 3));
        wait(cx, "the note's image", |cx| {
            picture(&view, cx, &held) == "here"
        });
        wait(cx, "that the other image is gone", |cx| {
            picture(&view, cx, &gone) == "image cdcdcdcd: the yard no longer has it"
        });
        // The window draws the expanded card and stays.
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        assert_eq!(yard.blobs_asked().len(), 2);
    }

    /// The window on `yard`, whose bead-a asks three, its note naming
    /// the page `page`: the decision open, the bead read.
    fn note_page_view<'a>(
        yard: &Yard,
        page: &str,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        yard.answer("UserAsks", &asks_three());
        yard.answer("Bead", &bead_note_page(page));
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-a".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-a"));
        (view, cx)
    }

