    /// A drop on an ask taken back attaches nothing: its card takes no
    /// note. Words with a file on a decided ask go nowhere: the ask takes
    /// no note either, and the file stays until it is removed.
    #[gpui::test]
    fn a_drop_on_a_taken_back_ask_attaches_nothing_and_a_decided_one_takes_no_note(
        cx: &mut TestAppContext,
    ) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let mut asks: Value =
            serde_json::from_str(&asks_decided(1, "Switch to attention")).unwrap();
        asks["result"]["decided"][0]["state"] = json!("taken back");
        yard.answer("UserAsks", &asks.to_string());
        yard.answer("Bead", &bead_decided());
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decided", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.decided_count() == 6)
            })
        });

        let dir = tempfile::tempdir().unwrap();
        let mockup = dir.path().join("mockup.html");
        std::fs::write(&mockup, PAGE).unwrap();
        open_decided(&view, cx, "bead-d", 11);
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-d"));
        view.update(cx, |v, cx| v.dropped(std::slice::from_ref(&mockup), cx));
        cx.run_until_parked();
        assert_eq!(
            notice(&view, cx),
            "an ask taken back takes no note: the file was not attached"
        );
        assert_eq!(card_attached(&view, cx, "bead-d", 11), []);

        // Ask 12 was answered and keeps its line: a page attaches, but
        // with words Enter sends neither note nor answer.
        open_decided(&view, cx, "bead-d", 12);
        view.update(cx, |v, cx| v.dropped(&[mockup], cx));
        wait(cx, "the page", |cx| {
            card_attached(&view, cx, "bead-d", 12).len() == 1
        });
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("i");
        cx.simulate_input("still true?");
        cx.simulate_keystrokes("enter");
        wait(cx, "why the words went nowhere", |cx| {
            notice(&view, cx) == "words alone go nowhere on this ask: remove the file, then send"
        });
        assert_eq!(yard.asked("AddNote").len(), 0);
        assert_eq!(yard.asked("AnswerAsk").len(), 0);
        assert_eq!(typed(&view, cx), "still true?");
        assert_eq!(card_attached(&view, cx, "bead-d", 12).len(), 1);
    }

    #[test]
    fn the_run_base_is_set_or_the_view_s_host_on_the_sandbox_port() {
        // Set, it is read as an address.
        assert_eq!(
            run_address_of("https://pages.example.net/", "http://127.0.0.1:8791/")
                .unwrap()
                .to_string(),
            "https://pages.example.net"
        );
        // Empty, it is derived from the view's.
        assert_eq!(
            run_address_of("", "http://127.0.0.1:9000/")
                .unwrap()
                .to_string(),
            "http://127.0.0.1:8789"
        );
        // Neither reading is none.
        assert_eq!(run_address_of("", "plantime"), None);
        assert_eq!(run_address_of("plantime", "http://127.0.0.1:8791/"), None);
    }

    #[gpui::test]
    fn a_note_s_page_carries_run_beside_open(cx: &mut TestAppContext) {
        let yard = Yard::start();
        let page = "ab".repeat(32);
        let (view, cx) = note_page_view(&yard, &page, cx);
        // The view and the run base answer: the row carries Open and
        // run, and the yard is asked for none of the page's bytes.
        let base = view_up();
        let run = view_up();
        set_view(&view, cx, &base);
        set_run(&view, cx, &run);
        wait(cx, "the web view", |cx| {
            view_answered(&view, cx) == Some(true)
        });
        wait(cx, "the run base", |cx| {
            run_answered(&view, cx) == Some(true)
        });
        view.update(cx, |v, cx| v.select_ask("bead-a".into(), 3, cx));
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("e");
        assert!(expanded_of(&view, cx, "bead-a", 3));
        assert!(drawn(cx, &format!("page row {page}")));
        assert!(drawn(cx, &format!("page open {page}")));
        assert!(drawn(cx, &format!("page run {page}")));
        assert_eq!(yard.blobs_asked(), Vec::<String>::new());
        assert_eq!(picture(&view, cx, &page), "");
        // Run hands the sandbox origin's page to the browser.
        let opened = opened_pages(&view, cx);
        click_on(cx, &format!("page run {page}"));
        cx.run_until_parked();
        assert_eq!(opened.borrow().as_slice(), [format!("{run}/blobs/{page}")]);
    }

