    /// The words of a card are typed in the same line as a mail: shift
    /// and Enter break the line, the words go with their line break, and
    /// the arrows are the words' while they have a row to go to.
    #[gpui::test]
    fn the_words_of_a_card_take_line_breaks_and_the_arrows_choose_at_their_ends(
        cx: &mut TestAppContext,
    ) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_three());
        yard.answer("Bead", &bead_three());
        yard.answer("AnswerAsk", "{}");
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-a".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-a"));
        assert_eq!(current_ask_of(&view, cx), 3);
        cx.run_until_parked();

        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("2");
        cx.simulate_keystrokes("i");
        cx.simulate_input("after Friday,");
        cx.simulate_keystrokes("shift-enter");
        cx.simulate_input("the freeze is over then");
        assert_eq!(typed(&view, cx), "after Friday,\nthe freeze is over then");
        // The words are two rows, and the field as high.
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        assert_eq!(view.read_with(cx, |v, cx| v.line.read(cx).rows()), (2, 2));

        // Up is the words' from the second row: the option stays. From the
        // first row it chooses, and down from the last.
        cx.simulate_keystrokes("up");
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), 2);
        cx.simulate_keystrokes("up");
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), 1);
        cx.simulate_keystrokes("down");
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), 1);
        cx.simulate_keystrokes("down");
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), 2);

        // Enter sends the pick with the words as typed.
        cx.simulate_keystrokes("enter");
        wait(cx, "the pick with words of two lines", |_| {
            yard.asked("AnswerAsk")
                == [json!({"bead": "bead-a", "ask": 3, "option": 2,
                           "words": "after Friday,\nthe freeze is over then", "actor": "jo"})]
        });
        assert_eq!(typed(&view, cx), "");
    }

    /// Moves the pointer where `selector` is drawn.
    fn hover_on(cx: &mut VisualTestContext, selector: &str) {
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        let at: &'static str = Box::leak(selector.to_string().into_boxed_str());
        let bounds = cx
            .debug_bounds(at)
            .unwrap_or_else(|| panic!("nothing is drawn for {selector}"));
        cx.simulate_mouse_move(bounds.center(), None, gpui::Modifiers::default());
    }

    /// Clicks where `selector` is drawn.
    fn click_on(cx: &mut VisualTestContext, selector: &str) {
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        let at: &'static str = Box::leak(selector.to_string().into_boxed_str());
        let bounds = cx
            .debug_bounds(at)
            .unwrap_or_else(|| panic!("nothing is drawn for {selector}"));
        cx.simulate_click(bounds.center(), gpui::Modifiers::default());
    }

    /// Presses the right button where `selector` is drawn, and lets it go.
    fn right_click_on(cx: &mut VisualTestContext, selector: &str) {
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        let at: &'static str = Box::leak(selector.to_string().into_boxed_str());
        let bounds = cx
            .debug_bounds(at)
            .unwrap_or_else(|| panic!("nothing is drawn for {selector}"));
        let none = gpui::Modifiers::default();
        cx.simulate_mouse_down(bounds.center(), MouseButton::Right, none);
        cx.simulate_mouse_up(bounds.center(), MouseButton::Right, none);
    }

    /// Whether `selector` is drawn.
    fn drawn(cx: &mut VisualTestContext, selector: &str) -> bool {
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        let at: &'static str = Box::leak(selector.to_string().into_boxed_str());
        cx.debug_bounds(at).is_some()
    }

    fn bounds_of(cx: &mut VisualTestContext, selector: &str) -> Bounds<Pixels> {
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        let at: &'static str = Box::leak(selector.to_string().into_boxed_str());
        cx.debug_bounds(at)
            .unwrap_or_else(|| panic!("nothing is drawn for {selector}"))
    }

    /// Where `selector` stands in the frame last drawn, with no redraw:
    /// for a test that reads many bounds of one frame, where `bounds_of`
    /// would draw the whole window again for each.
    fn bounds_now(cx: &mut VisualTestContext, selector: &str) -> Bounds<Pixels> {
        let at: &'static str = Box::leak(selector.to_string().into_boxed_str());
        cx.debug_bounds(at)
            .unwrap_or_else(|| panic!("nothing is drawn for {selector}"))
    }

    /// Opens one dealt with: "Decided" unfolded, its row selected.
    fn open_decided(view: &Entity<Footplate>, cx: &mut VisualTestContext, bead: &str, ask: u64) {
        view.update(cx, |v, cx| {
            v.change(cx, |m| {
                if !m.decided_expanded() {
                    m.toggle_decided();
                }
                m.select(Selected::Decided(bead.into(), ask))
            })
        });
        cx.run_until_parked();
    }

    fn decided_detail_of(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        bead: &str,
        ask: u64,
    ) -> DecidedDetail {
        view.read_with(cx, |v, _| {
            v.model
                .as_ref()
                .unwrap()
                .decided_detail(bead, ask, &chrono::Utc)
                .unwrap()
        })
    }

    /// Noon of the 12th of October 2026, UTC: the history's day groups and
    /// times stand still under it.
    fn history_noon() -> chrono::DateTime<chrono::Utc> {
        chrono::DateTime::parse_from_rfc3339("2026-10-12T12:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc)
    }

    /// Every decided row of every day under the fixed noon, folds'
    /// members with them: what the history holds, without its shape.
    fn decided_all(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Vec<DecidedRow> {
        let now = history_noon();
        view.read_with(cx, |v, _| {
            v.model
                .as_ref()
                .unwrap()
                .decided_groups(&now)
                .into_iter()
                .flat_map(|group| group.rows)
                .flat_map(|entry| match entry {
                    DecidedEntry::One(row) => vec![row],
                    DecidedEntry::Fold(fold) => fold.rows,
                })
                .collect()
        })
    }

    /// Six dealt with on one bead, asked by mayor at 11:07: answered,
    /// answered with words, put aside, declined, left to the asker, and a
    /// words answer. Ask 11's pick is `pick` with `label`. The one put aside
    /// returns in a year no run of the tests reaches: the window compares
    /// that time with the clock.
    fn asks_decided(pick: u64, label: &str) -> String {
        json!({"result": {"open": [], "decided": [
            {"bead": "bead-d", "bead_title": "Switch the inbox", "topic": "topic:linear-out",
             "ask": 11, "question": "Switch my inbox to the 'attention' set of events?", "asker": "mayor",
             "since": "2026-10-12T11:07:00Z", "state": "answered", "option": pick, "option_label": label},
            {"bead": "bead-d", "bead_title": "Switch the inbox", "topic": "topic:linear-out",
             "ask": 12, "question": "Switch the inbox now or after Friday?", "asker": "mayor",
             "since": "2026-10-12T11:07:00Z", "state": "answered",
             "option": 2, "option_label": "Add only the three", "words": "go slow"},
            {"bead": "bead-d", "bead_title": "Switch the inbox", "topic": "topic:linear-out",
             "ask": 13, "question": "Rebuild the index tonight?", "asker": "mayor",
             "since": "2026-10-12T11:07:00Z", "state": "put aside",
             "return_at": "2099-10-13T09:30:00Z"},
            {"bead": "bead-d", "bead_title": "Switch the inbox", "topic": "topic:linear-out",
             "ask": 14, "question": "Take the release train?", "asker": "mayor",
             "since": "2026-10-12T11:07:00Z", "state": "declined", "words": "not mine"},
            {"bead": "bead-d", "bead_title": "Switch the inbox", "topic": "topic:linear-out",
             "ask": 15, "question": "Name the release?", "asker": "mayor",
             "since": "2026-10-12T11:07:00Z", "state": "answered",
             "option": 4, "option_label": "You decide"},
            {"bead": "bead-d", "bead_title": "Switch the inbox", "topic": "topic:linear-out",
             "ask": 16, "question": "Who greets the newcomer?", "asker": "mayor",
             "since": "2026-10-12T11:07:00Z", "state": "answered", "words": "warmly"}
        ]}})
        .to_string()
    }

    fn attention_options() -> serde_json::Value {
        json!([
            {"label": "Switch to attention", "consequence": "I run 'yardr crew set mayor --on attention' now; takes effect at once"},
            {"label": "Add only the three", "consequence": "keep my hand list and append the missing kinds"},
            {"label": "Leave it", "consequence": "no change; doctor keeps flagging it"},
            {"label": "You decide", "consequence": "leave it to mayor"}
        ])
    }

    fn decided_bead_ask(ask: u64, question: &str, state: &str, options: bool) -> serde_json::Value {
        let mut a = json!({
            "ask": ask, "to": "jo", "asker": "mayor",
            "since": "2026-10-12T11:07:00Z",
            "question": question,
            "context": ["My inbox listens to a hand-written list of event kinds."],
            "state": state,
        });
        if options {
            a["options"] = attention_options();
            a["recommend"] = json!(1);
            a["why"] = json!("it follows new kinds without hand edits");
        } else {
            a["options"] = json!([]);
        }
        a
    }

    fn bead_decided() -> String {
        json!({"result": {
            "id": "bead-d", "title": "Switch the inbox",
            "body": "The body of bead-d.",
            "stage": "new", "labels": ["topic:linear-out"],
            "notes": [],
            "asks": [
                decided_bead_ask(11, "Switch my inbox to the 'attention' set of events?", "answered", true),
                decided_bead_ask(12, "Switch the inbox now or after Friday?", "answered", true),
                decided_bead_ask(13, "Rebuild the index tonight?", "put aside", true),
                decided_bead_ask(14, "Take the release train?", "declined", true),
                decided_bead_ask(15, "Name the release?", "answered", true),
                decided_bead_ask(16, "Who greets the newcomer?", "answered", false),
            ]
        }})
        .to_string()
    }

    /// A put-aside ask whose return is past while the yard still lists it as
    /// put aside: the queue is read once more for it and no more, and the
    /// parked beads with it, since an ask that is back takes its bead out of
    /// them and tells no event. Read again for every answer that still lists
    /// it, the window asked without end.
    #[gpui::test]
    fn a_return_that_is_past_reads_the_queue_once(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [
                {"bead": "bead-d", "bead_title": "Switch the inbox", "topic": "topic:linear-out",
                 "ask": 13, "question": "Rebuild the index tonight?", "asker": "mayor",
                 "since": "2000-01-01T11:07:00Z", "state": "put aside",
                 "return_at": "2000-01-02T09:30:00Z"}
            ]}})
            .to_string(),
        );
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the yardmaster's conversation", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        // Once as the yard is opened, and once for the return that is past.
        wait(cx, "the queue read for the return", |_| {
            yard.asked("UserAsks").len() == 2 && yard.asked("Waiting").len() == 2
        });
        for _ in 0..20 {
            cx.run_until_parked();
            thread::sleep(Duration::from_millis(5));
        }
        assert_eq!(yard.asked("UserAsks").len(), 2);
        assert_eq!(yard.asked("Waiting").len(), 2);
        view.read_with(cx, |v, _| {
            assert_eq!(v.model.as_ref().unwrap().decided_count(), 1);
        });
    }

    #[gpui::test]
    fn a_decided_card_shows_what_was_decided_and_a_new_pick_replaces_it(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_decided(1, "Switch to attention"));
        yard.answer("Bead", &bead_decided());
        yard.answer("AnswerAsk", "{}");
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        // Nothing open: the yardmaster's conversation is, with the decided
        // folded under the decisions.
        wait(cx, "the yardmaster's conversation", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.decided_count(), 6);
            assert!(!model.decided_expanded());
        });

        open_decided(&view, cx, "bead-d", 11);
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-d"));

        // The decided card's header names the yard, with its dot.
        assert!(drawn(cx, "in this machine bead-d 11"));
        assert!(drawn(cx, "in this machine bead-d 11 dot"));

        // Each state in plain words with who and when, and the pick.
        let d = decided_detail_of(&view, cx, "bead-d", 11);
        assert_eq!(d.picked, 1);
        assert_eq!(d.words, "");
        assert_eq!(d.state_line, "you picked 1 · Switch to attention");
        assert_eq!(d.chosen, 0);
        assert_eq!(decided_keys(&d), "1-4 change your pick");

        let d = decided_detail_of(&view, cx, "bead-d", 12);
        assert_eq!(d.picked, 2);
        assert_eq!(d.words, "go slow");
        assert_eq!(d.state_line, "you picked 2 · Add only the three");

        let d = decided_detail_of(&view, cx, "bead-d", 13);
        assert_eq!(d.picked, 0);
        assert_eq!(d.state_line, "put aside, back 10-13 09:30");

        let d = decided_detail_of(&view, cx, "bead-d", 14);
        assert_eq!(d.state_line, "you declined: not mine");

        let d = decided_detail_of(&view, cx, "bead-d", 15);
        assert_eq!(d.picked, 4);
        assert_eq!(d.state_line, "left to mayor");

        // An ask with no options: the answer's words are the state line.
        let d = decided_detail_of(&view, cx, "bead-d", 16);
        assert_eq!(d.picked, 0);
        assert_eq!(d.state_line, "you answered: warmly");
        assert_eq!(decided_keys(&d), "i words · enter sends");

        // The Decided rows lead with the outcome's icon, then whose and
        // when; the picks stay on the cards.
        let rows: Vec<(String, String)> = decided_all(&view, cx)
            .into_iter()
            .map(|r| (r.outcome, r.detail))
            .collect();
        assert_eq!(
            rows,
            [
                ("✓approved".to_string(), "mayor · 11:07".to_string()),
                ("✓approved".to_string(), "mayor · 11:07".to_string()),
                ("‖put aside".to_string(), "mayor · 11:07".to_string()),
                (
                    "✕declined: not mine".to_string(),
                    "mayor · 11:07".to_string()
                ),
                ("✓left to mayor".to_string(), "11:07".to_string()),
                ("✎warmly".to_string(), "mayor · 11:07".to_string()),
            ]
        );

        // The window draws every variant and stays.
        for ask in [11, 12, 13, 14, 15, 16] {
            open_decided(&view, cx, "bead-d", ask);
        }
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();

        // On a decided ask nothing is chosen by default and Enter alone
        // sends nothing: not the recommendation, and no note.
        open_decided(&view, cx, "bead-d", 11);
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("AnswerAsk"), Vec::<serde_json::Value>::new());
        assert_eq!(yard.asked("AddNote"), Vec::<serde_json::Value>::new());
        cx.simulate_keystrokes("i");
        cx.simulate_input("second thoughts");
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("AnswerAsk"), Vec::<serde_json::Value>::new());
        assert_eq!(yard.asked("AddNote"), Vec::<serde_json::Value>::new());
        // Esc leaves the words.
        cx.simulate_keystrokes("escape");
        assert_eq!(typed(&view, cx), "");

        // A number then Enter replaces the pick, as before.
        yard.answer("UserAsks", &asks_decided(2, "Add only the three"));
        cx.simulate_keystrokes("2");
        assert_eq!(decided_detail_of(&view, cx, "bead-d", 11).chosen, 2);
        cx.simulate_keystrokes("enter");
        wait(cx, "the changed pick", |_| {
            yard.asked("AnswerAsk")
                == [json!({"bead": "bead-d", "ask": 11, "option": 2, "actor": "jo"})]
        });
        wait(cx, "the new pick shown", |cx| {
            decided_detail_of(&view, cx, "bead-d", 11).picked == 2
        });
        assert_eq!(
            decided_detail_of(&view, cx, "bead-d", 11).state_line,
            "you picked 2 · Add only the three"
        );
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
    }

    /// The window on `yard`, with six decided on bead-d, once they show.
    fn history_view<'a>(
        yard: &Yard,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        yard.answer("UserAsks", &asks_decided(1, "Switch to attention"));
        yard.answer("Bead", &bead_decided());
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decided", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.decided_count() == 6)
            })
        });
        (view, cx)
    }

    /// `/` opens the folded history with its filter typed in: what is typed
    /// narrows its rows, and esc leaves the filter with what is typed
    /// standing.
    #[gpui::test]
    fn slash_types_in_the_history_s_filter_and_narrows_its_rows(cx: &mut TestAppContext) {
        let yard = Yard::start();
        let (view, cx) = history_view(&yard, cx);
        to_decisions(&view, cx);
        open_decided(&view, cx, "bead-d", 11);
        // Folded again, the card still open; esc leaves the line for the
        // window's keys.
        view.update(cx, |v, cx| {
            v.change(cx, |m| {
                m.toggle_decided();
                Vec::new()
            })
        });
        cx.run_until_parked();
        view.read_with(cx, |v, _| {
            assert!(!v.model.as_ref().unwrap().decided_expanded())
        });
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
        // `/` opens the history with its filter and chips.
        cx.simulate_keystrokes("/");
        cx.run_until_parked();
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().decided_expanded())
        });
        assert!(drawn(cx, "decided filter"));
        assert!(drawn(cx, "decided chip all"));
        assert!(drawn(cx, "decided chip words"));
        // Typed: only the ask naming the attention set stands.
        cx.simulate_input("attention");
        cx.run_until_parked();
        let rows: Vec<u64> = decided_all(&view, cx).into_iter().map(|r| r.ask).collect();
        assert_eq!(rows, [11]);
        // Esc leaves the filter; what is typed stays typed.
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
        let rows: Vec<u64> = decided_all(&view, cx).into_iter().map(|r| r.ask).collect();
        assert_eq!(rows, [11]);
    }

    /// There is no filter to focus before the yard has decided any asks:
    /// it is not drawn until the history has a row.
    #[gpui::test]
    fn slash_does_not_open_an_empty_history_filter(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": []}}).to_string(),
        );
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the empty decisions", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|model| model.decided_count() == 0)
            })
        });
        to_decisions(&view, cx);

        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("/");
        cx.run_until_parked();

        assert!(!drawn(cx, "decided filter"));
        view.read_with(cx, |v, _| {
            assert!(!v.model.as_ref().unwrap().decided_expanded());
        });
    }

    /// A history longer than a page draws its newest fifty when it is
    /// opened, and under them one quiet row with how many are left: a press
    /// on it draws the next page. The filter searches the whole history, so
    /// it finds an ask past the page. Closing and opening starts at the
    /// first page again, and a mail's chip for an ask past the page draws
    /// down to it. The test's frame keeps the bounds of what it drew once,
    /// so each row is looked for before it has been drawn, and what is gone
    /// is read from the model.
    #[gpui::test]
    fn the_opened_history_draws_a_page_and_its_more_row_draws_the_next(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let decided: Vec<Value> = (1..=120u64)
            .rev()
            .map(|n| {
                json!({"bead": "bead-l", "bead_title": "Deploys", "topic": "", "ask": n,
                       "question": format!("Approve deploy-{n:03}?"),
                       "asker": if n % 2 == 0 { "mayor" } else { "assembly" },
                       "since": "2026-10-12T11:07:00Z", "state": "answered",
                       "option": 1, "option_label": "Approve it"})
            })
            .collect();
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": decided}}).to_string(),
        );
        yard.answer("Bead", &bead_decided());
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the history", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.decided_count() == 120)
            })
        });
        // Tall enough that every row of the longest page is on the screen to
        // press the more row under.
        cx.simulate_resize(gpui::size(px(1280.), px(8000.)));
        to_decisions(&view, cx);
        let head = |n: u64| format!("decided head bead-l {n}");
        let left = |view: &Entity<Footplate>, cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| v.model.as_ref().unwrap().decided_left())
        };

        // Folded, the history draws no row and no more row.
        assert!(!drawn(cx, &head(120)) && !drawn(cx, "decided more"));
        click_on(cx, "decided toggle");
        // The newest fifty, then the row for the other seventy, standing
        // right under the last of them with its count in words at its right.
        assert!(drawn(cx, &head(120)) && drawn(cx, &head(71)));
        assert!(!drawn(cx, &head(70)) && !drawn(cx, &head(3)));
        assert_eq!(left(&view, cx), 70);
        let (last, more) = (bounds_of(cx, &head(71)), bounds_of(cx, "decided more"));
        let first = bounds_of(cx, &head(120));
        let step = bounds_of(cx, &head(119)).top() - first.top();
        assert!(last.bottom() <= more.top() && more.top() - last.top() < step * 2.);
        let count = bounds_of(cx, "decided more count");
        assert!(more.left() < count.left() && count.right() <= more.right());
        assert_eq!(words::left_words(70), "70 left");
        assert_eq!(words::left_words(1), "1 left");

        // The filter finds ask 3, which stands past the page, with none left
        // to draw; clearing it stands the first page again.
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("/");
        cx.simulate_input("deploy-003");
        cx.run_until_parked();
        assert!(drawn(cx, &head(3)));
        assert_eq!(left(&view, cx), 0);
        cx.simulate_keystrokes(
            "backspace backspace backspace backspace backspace backspace backspace backspace backspace backspace",
        );
        cx.run_until_parked();
        assert_eq!(left(&view, cx), 70);

        // A press draws the next page; another the last, and none is left.
        click_on(cx, "decided more");
        assert!(drawn(cx, &head(21)) && !drawn(cx, &head(20)));
        assert_eq!(left(&view, cx), 20);
        click_on(cx, "decided more");
        assert!(drawn(cx, &head(1)));
        assert_eq!(left(&view, cx), 0);

        // Closed and opened again, it starts at the first page.
        click_on(cx, "decided toggle");
        click_on(cx, "decided toggle");
        assert_eq!(left(&view, cx), 70);

        // A mail's chip for ask 3, which stands past that page: the history
        // draws down to it, and its row is the open one.
        view.update_in(cx, |v, window, cx| {
            v.open_reference(
                select::RefTarget::Ask {
                    bead: "bead-l".into(),
                    ask: 3,
                    open: false,
                },
                window,
                cx,
            )
        });
        cx.run_until_parked();
        assert_eq!(left(&view, cx), 0);
        assert_eq!(
            open_row(&view, cx),
            Some(Selected::Decided("bead-l".into(), 3))
        );
    }

