    /// The grants view lists every source × holder × call, by source, for
    /// the operator's window alone: each call's own time and approver,
    /// the weighty words for update and `--as` rows, and each row's
    /// revoke line. Anywhere else the row stands nowhere.
    #[gpui::test]
    fn the_grants_view_lists_every_call_with_its_revoke_for_the_operator_alone(
        cx: &mut TestAppContext,
    ) {
        let grants = || {
            json!({"result": [
                {"source": "google-mail", "crew": "yardmaster",
                 "calls": ["read"],
                 "at": "2026-10-17T19:02:00Z", "by": "mckean",
                 "given": {"read": {
                    "at": "2026-10-17T19:02:00Z", "by": "mckean",
                    "bead": "yd-c546", "ask": 409, "asker": "yardmaster"}}},
                {"source": "google-mail", "crew": "yardmaster", "as": "ada",
                 "calls": ["send"],
                 "at": "2026-10-17T19:04:00Z", "by": "mckean",
                 "given": {"send": {
                    "at": "2026-10-17T19:04:00Z", "by": "mckean",
                    "bead": "yd-c546", "ask": 412, "asker": "yardmaster"}}},
                {"source": "telegram", "group": "builders",
                 "calls": ["read"],
                 "at": "2026-10-12T10:15:00Z", "by": "mckean"},
                {"source": "crm", "crew": "yardmaster",
                 "calls": ["customer", "note"],
                 "at": "2026-10-17T19:06:00Z", "by": "mckean",
                 "given": {
                    "customer": {"at": "2026-10-17T19:06:00Z", "by": "mckean"},
                    "note": {"at": "2026-10-17T19:06:00Z", "by": "mckean"}},
                 "kinds": {"customer": "read", "note": "update"}},
            ]})
            .to_string()
        };
        // The same grants from a yard before it served kinds.
        let older = || {
            let mut all: serde_json::Value = serde_json::from_str(&grants()).unwrap();
            for grant in all["result"].as_array_mut().unwrap() {
                grant.as_object_mut().unwrap().remove("kinds");
            }
            all.to_string()
        };
        let asks = || {
            json!({"result": {"open": [
                {"bead": "bead-a", "bead_title": "Move the links", "topic": "",
                 "ask": 3, "question": "Move them now?", "asker": "yardmaster",
                 "since": "2026-10-10T10:00:00Z"}
            ], "decided": []}})
            .to_string()
        };
        // The operator's: the row stands last of decisions, and opens the
        // grants by source.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks());
        yard.answer("Bead", &bead_three());
        yard.answer("SourceGrants", &grants());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "decision row bead-a"));
        assert!(drawn(cx, "row grants"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.is_operator());
            assert_eq!(model.grant_records().len(), 4);
        });
        click_on(cx, "row grants");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Grants));
        assert_eq!(view.read_with(cx, |v, _| v.keys_view()), KeysView::Grants);
        assert!(drawn(cx, "grants head"));
        assert!(drawn(cx, "grants summary"));
        assert!(drawn(cx, "grants source google-mail"));
        assert!(drawn(cx, "grants source telegram"));
        assert!(drawn(cx, "grants row google-mail read"));
        assert!(drawn(cx, "grants row google-mail send"));
        assert!(drawn(cx, "grants row telegram read"));
        assert!(drawn(cx, "grants source crm"));
        assert!(drawn(cx, "grants row crm customer"));
        assert!(drawn(cx, "grants row crm note"));
        // A plain read carries no weight, nor does a named one by the kind
        // the yard served; an update as a user carries both lines, and a
        // named update the one; the unkept record says when it last
        // changed.
        assert!(!drawn(cx, "grants weight google-mail read 0"));
        assert!(!drawn(cx, "grants weight crm customer 0"));
        assert!(drawn(cx, "grants weight crm note 0"));
        assert!(!drawn(cx, "grants weight crm note 1"));
        assert!(drawn(cx, "grants weight google-mail send 0"));
        assert!(drawn(cx, "grants weight google-mail send 1"));
        assert!(drawn(cx, "grants unkept"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            let records = model.grant_records();
            assert_eq!(
                crate::model::grant_summary(records),
                "5 calls granted of 3 sources to 2 holders: 2 may change something outside the yard, 1 call as a user."
            );
            assert_eq!(
                crate::model::grant_revoke("google-mail", "send", &records[1]),
                "yardr source revoke google-mail send --crew yardmaster --as ada"
            );
        });
        // A grant given reads the grants again, here from a yard before it
        // served kinds: the named read is weighty as it was, and the
        // summary counts it.
        yard.answer("SourceGrants", &older());
        yard.emit(r#"{"seq": 21, "kind": "source_granted", "actor": "mckean", "data": {}}"#);
        wait(cx, "the grants read again, without kinds", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| {
                    m.grant_records().len() == 4
                        && m.grant_records().iter().all(|g| g.kinds.is_empty())
                })
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "grants weight crm customer 0"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                crate::model::grant_summary(v.model.as_ref().unwrap().grant_records()),
                "5 calls granted of 3 sources to 2 holders: 3 may change something outside the yard, 1 call as a user."
            );
        });
        yard.answer("SourceGrants", &json!({"result": []}).to_string());
        yard.emit(r#"{"seq": 22, "kind": "source_granted", "actor": "mckean", "data": {}}"#);
        wait(cx, "the grants read again", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.grant_records().is_empty())
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "grants empty"));
        // Anywhere else: no row. The yard's operator is mckean, and the
        // window runs as jo.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Settings", r#"{"result": {"operator": "mckean"}}"#);
        yard.answer("UserAsks", &asks());
        yard.answer("Bead", &bead_three());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "decision row bead-a"));
        assert!(!drawn(cx, "row grants"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(!model.is_operator());
            assert!(model.grant_records().is_empty());
        });
        assert!(yard.asked("SourceGrants").is_empty());
    }

    /// A yard from before the grants view has no SourceGrants call: no
    /// notice is raised in any mode, and the grants pane says the yard is
    /// too old instead, and nowhere else.
    #[gpui::test]
    fn an_old_yard_says_so_in_the_grants_pane_and_nowhere_else(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "SourceGrants",
            r#"{"error": {"code": "error", "message": "no such method SourceGrants"}}"#,
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().grants_too_old());
        });
        assert_eq!(notice(&view, cx), "");
        assert!(!drawn(cx, "grants too old"));
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row grants"));
        click_on(cx, "row grants");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Grants));
        assert!(drawn(cx, "grants too old"));
        assert_eq!(yard.asked("SourceGrants").len(), 1);
        assert_eq!(notice(&view, cx), "");
        // Back in chat: no notice, and the words stand in the grants pane
        // alone. (What was drawn stays drawn to the tests, so the words
        // gone from the pane are not said here.)
        to_chat(&view, cx);
        cx.run_until_parked();
        assert_eq!(notice(&view, cx), "");
    }

    /// A yard that refuses the grants as a request come down the link from
    /// its edge serves them on its machine alone: the row and the pane say
    /// where they are read, with no notice, and the refusal is not asked
    /// again, by opening the row or by the window's second try of a failed
    /// read. The window is not the operator's at first, and the operator
    /// named afterwards is: the read that makes is the one refused.
    #[gpui::test]
    fn a_yard_that_refuses_the_grants_down_the_link_says_where_they_are_read(
        cx: &mut TestAppContext,
    ) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Settings", r#"{"result": {"operator": "mckean"}}"#);
        yard.answer(
            "SourceGrants",
            &json!({"error": {"code": "error", "message": "the operator's grant list is not read over the link: this request came down the link from the edge. Read it on the yard's machine (`yardr source grants`). The edge saw the device's token with it: remove the device and add it again (yardr user device rm)."}}).to_string(),
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(!drawn(cx, "row grants"));
        assert!(yard.asked("SourceGrants").is_empty());

        yard.emit(r#"{"seq": 21, "kind": "setting_changed", "actor": "mckean", "data": {"key": "operator", "value": "jo"}}"#);
        wait(cx, "the grants refused down the link", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.is_operator() && m.grants_on_the_yard())
            })
        });
        assert_eq!(yard.asked("SourceGrants").len(), 1);
        assert_eq!(notice(&view, cx), "");
        assert!(drawn(cx, "row grants"));
        click_on(cx, "row grants");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Grants));
        assert!(drawn(cx, "grants on the yard"));
        assert!(!drawn(cx, "grants too old"));
        assert!(!drawn(cx, "grants empty"));
        // A failed read is made again once, after a while: not this one,
        // which no try will change.
        cx.executor().advance_clock(session::RETRY + session::RETRY);
        cx.run_until_parked();
        assert_eq!(yard.asked("SourceGrants").len(), 1);
        assert_eq!(notice(&view, cx), "");
    }

    /// A hosted yard is not asked for its grants, which it serves down no
    /// link from its edge: not at the start, and not by opening the row.
    /// No notice is raised, and the row and the pane say the grants are
    /// read on the yard's machine. It serves a session's screen down that
    /// link to the operator's paired device, so the conversation's header
    /// carries the Screen and the yard is asked for it through the edge. One
    /// from before that refuses the read so: the card then says where the
    /// screen is read, the refresh asks no more, and the Screen goes from
    /// the header.
    #[gpui::test]
    fn a_hosted_yard_is_asked_for_a_screen_and_not_its_grants_and_a_refusal_says_where_the_screen_is_read(
        cx: &mut TestAppContext,
    ) {
        use crate::fake::{Router, SESSION, TOKEN};

        let far = Yard::start_tcp();
        a_yard_of_jo(&far);
        far.answer(
            "SessionScreen",
            &json!({"result": {"screen": "\u{1b}[1myardmaster\u{1b}[0m\n❯ "}}).to_string(),
        );
        let edge = Router::start(&far, SESSION);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(edge.client_with(TOKEN, SESSION), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the hosted yard's conversation", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.is_operator());
            assert!(model.grants_on_the_yard());
            assert!(model.grant_records().is_empty());
            assert!(!model.screen_on_the_yard());
            assert_eq!(
                model.screen_for_crew("yardmaster"),
                Some("yardmaster".to_string())
            );
        });
        assert_eq!(notice(&view, cx), "");

        // The operator's conversation with the yardmaster is drawn with
        // its state beside the name and the Screen at the header's edge, as
        // on the yard's own machine, and the Screen asks the yard through
        // the edge.
        assert!(drawn(cx, "conversation state"));
        assert!(drawn(cx, "talk screen yardmaster"));
        click_on(cx, "talk screen yardmaster");
        wait(cx, "the hosted yard's screen", |cx| {
            screen_of(&view, cx) == "2 lines"
        });
        assert_eq!(
            far.asked("SessionScreen"),
            [json!({"session": "yardmaster"})]
        );
        // A hosted yard from before the screen came down the link refuses
        // the read so: the card says where the screen is read, in no red,
        // and the refresh asks no more.
        far.answer(
            "SessionScreen",
            &json!({"error": {"code": "error", "message": "a session's screen is not read over the link: this request came down the link from the edge. Read it on the yard's machine. The edge saw the device's token with it: remove the device and add it again (yardr user device rm)."}}).to_string(),
        );
        click_on(cx, "screen refresh");
        wait(cx, "the screen read on the yard's machine", |cx| {
            screen_of(&view, cx) == model::SCREEN_ON_THE_YARD
        });
        assert!(drawn(cx, "screen on the yard"));
        assert_eq!(notice(&view, cx), "");
        assert_eq!(far.asked("SessionScreen").len(), 2);
        click_on(cx, "screen refresh");
        cx.run_until_parked();
        assert_eq!(screen_of(&view, cx), model::SCREEN_ON_THE_YARD);
        assert_eq!(far.asked("SessionScreen").len(), 2);
        // The Screen goes from the window. (What was drawn stays drawn to
        // the tests, so the model says it, not the frame.)
        click_on(cx, "screen close");
        cx.run_until_parked();
        assert_eq!(overlay_screen(&view, cx), None);
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.screen_on_the_yard());
            assert_eq!(model.screen_for_crew("yardmaster"), None);
        });

        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row grants"));
        click_on(cx, "row grants");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Grants));
        assert!(drawn(cx, "grants on the yard"));
        assert!(!drawn(cx, "grants too old"));
        assert!(!drawn(cx, "grants empty"));
        assert_eq!(notice(&view, cx), "");
        assert!(far.asked("SourceGrants").is_empty());
    }

    /// The teammates view lists every teammate with their yard name,
    /// email, role and paired-or-waiting state, for the operator's
    /// window alone: a waiting row and a paired row with each device's
    /// last use. Anywhere else the row stands nowhere, and the call is
    /// never made. A teammate's event reads the list again, and an empty
    /// yard says none is invited.
    #[gpui::test]
    fn the_teammates_view_lists_each_teammate_with_their_state_for_the_operator_alone(
        cx: &mut TestAppContext,
    ) {
        let teammates = || {
            json!({"result": [
                {"name": "hal", "role": "member", "email": "hal@example.net",
                 "invited_by": "jo", "invited_at": "2026-10-08T09:30:00Z",
                 "devices": []},
                {"name": "sam", "role": "member", "email": "sam@example.net",
                 "invited_by": "jo", "invited_at": "2026-10-08T09:30:00Z",
                 "devices": [
                    {"name": "tablet", "last_used": "2026-10-08T09:30:00Z"},
                    {"name": "spare"}]},
            ]})
            .to_string()
        };
        let asks = || {
            json!({"result": {"open": [
                {"bead": "bead-a", "bead_title": "Move the links", "topic": "",
                 "ask": 3, "question": "Move them now?", "asker": "yardmaster",
                 "since": "2026-10-10T10:00:00Z"}
            ], "decided": []}})
            .to_string()
        };
        // The operator's: the row stands last of decisions, beside the
        // grants', and opens the teammates.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks());
        yard.answer("Bead", &bead_three());
        yard.answer("Teammates", &teammates());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "decision row bead-a"));
        assert!(drawn(cx, "row grants"));
        assert!(drawn(cx, "row teammates"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.is_operator());
            assert_eq!(model.teammate_records().len(), 2);
        });
        click_on(cx, "row teammates");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Teammates));
        assert_eq!(
            view.read_with(cx, |v, _| v.keys_view()),
            KeysView::Teammates
        );
        assert!(drawn(cx, "teammates head"));
        assert!(drawn(cx, "teammates summary"));
        assert!(drawn(cx, "teammates row hal"));
        assert!(drawn(cx, "teammates name hal"));
        assert!(drawn(cx, "teammates email hal"));
        assert!(drawn(cx, "teammates role hal"));
        assert!(drawn(cx, "teammates invited hal"));
        assert!(drawn(cx, "teammates state hal"));
        assert!(drawn(cx, "teammates row sam"));
        assert!(drawn(cx, "teammates state sam"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(
                crate::model::teammates_summary(model.teammate_records()),
                "2 teammates: 1 paired, 1 waiting."
            );
            assert_eq!(
                crate::model::teammate_state(&model.teammate_records()[0]),
                "waiting"
            );
            assert!(
                crate::model::teammate_state(&model.teammate_records()[1])
                    .starts_with("paired: tablet, last used ")
            );
        });
        // A device paired reads the teammates again: hal is paired now.
        yard.answer(
            "Teammates",
            &json!({"result": [
                {"name": "hal", "role": "member", "email": "hal@example.net",
                 "invited_by": "jo", "invited_at": "2026-10-08T09:30:00Z",
                 "devices": [{"name": "phone"}]},
                {"name": "sam", "role": "member", "email": "sam@example.net",
                 "invited_by": "jo", "invited_at": "2026-10-08T09:30:00Z",
                 "devices": [
                    {"name": "tablet", "last_used": "2026-10-08T09:30:00Z"},
                    {"name": "spare"}]},
            ]})
            .to_string(),
        );
        yard.emit(r#"{"seq": 21, "kind": "device_added", "actor": "jo", "data": {"user": "hal", "device": "phone"}}"#);
        wait(cx, "the teammates read again, hal paired", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| {
                    m.teammate_records().len() == 2 && !m.teammate_records()[0].devices.is_empty()
                })
            })
        });
        cx.run_until_parked();
        view.read_with(cx, |v, _| {
            assert_eq!(
                crate::model::teammates_summary(v.model.as_ref().unwrap().teammate_records()),
                "2 teammates: 2 paired, 0 waiting."
            );
        });
        // A removal reads them again too: nobody is left, and the pane
        // says none is invited.
        yard.answer("Teammates", &json!({"result": []}).to_string());
        yard.emit(r#"{"seq": 22, "kind": "user_removed", "actor": "jo", "data": {"user": "sam"}}"#);
        wait(cx, "the teammates read again", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.teammate_records().is_empty())
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "teammates empty"));
        // Anywhere else: no row, and no call. The yard's operator is
        // mckean, and the window runs as jo.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Settings", r#"{"result": {"operator": "mckean"}}"#);
        yard.answer("UserAsks", &asks());
        yard.answer("Bead", &bead_three());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "decision row bead-a"));
        assert!(!drawn(cx, "row teammates"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(!model.is_operator());
            assert!(model.teammate_records().is_empty());
        });
        assert!(yard.asked("Teammates").is_empty());
    }

    /// The operator's window of a hosted yard reads the teammates down
    /// the link from its edge, as an approval: the row stands, the call
    /// is made, and the pane lists them.
    #[gpui::test]
    fn a_hosted_yard_is_asked_for_its_teammates_down_the_link(cx: &mut TestAppContext) {
        use crate::fake::{Router, SESSION, TOKEN};

        let far = Yard::start_tcp();
        a_yard_of_jo(&far);
        far.answer(
            "Teammates",
            r#"{"result": [{"name": "sam", "role": "member", "email": "sam@example.net",
                 "invited_by": "jo", "invited_at": "2026-10-08T09:30:00Z",
                 "devices": [{"name": "tablet"}]}]}"#,
        );
        let edge = Router::start(&far, SESSION);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(edge.client_with(TOKEN, SESSION), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the hosted yard's conversation", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.is_operator());
            assert_eq!(model.teammate_records().len(), 1);
        });
        assert_eq!(far.asked("Teammates"), vec![json!({})]);
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row teammates"));
        click_on(cx, "row teammates");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Teammates));
        assert!(drawn(cx, "teammates row sam"));
        assert!(drawn(cx, "teammates state sam"));
        assert_eq!(notice(&view, cx), "");
    }

    /// A yard from before the teammates view has no Teammates call: no
    /// notice is raised in any mode, and the teammates pane says the yard
    /// is too old instead, and nowhere else.
    #[gpui::test]
    fn an_old_yard_says_so_in_the_teammates_pane_and_nowhere_else(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "Teammates",
            r#"{"error": {"code": "error", "message": "no such method Teammates"}}"#,
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().teammates_too_old());
        });
        assert_eq!(notice(&view, cx), "");
        assert!(!drawn(cx, "teammates too old"));
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row teammates"));
        click_on(cx, "row teammates");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Teammates));
        assert!(drawn(cx, "teammates too old"));
        assert_eq!(yard.asked("Teammates").len(), 1);
        assert_eq!(notice(&view, cx), "");
        // Back in chat: no notice, and the words stand in the teammates
        // pane alone. (What was drawn stays drawn to the tests, so the
        // words gone from the pane are not said here.)
        to_chat(&view, cx);
        cx.run_until_parked();
        assert_eq!(notice(&view, cx), "");
    }

    /// Remove files the teammate's removal with that user, and the filed
    /// bead and ask are said on the pane's line. The operator's own row
    /// has no Remove. Nothing underway is filed twice. A refusal is shown
    /// as the refusal line, filing nothing, and a call that ends without
    /// an answer reads the queue again, never filed or not.
    #[gpui::test]
    fn remove_files_the_uninvite_and_says_the_filed_bead_and_ask(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "Teammates",
            &json!({"result": [
                {"name": "jo", "role": "operator", "email": "jo@example.net",
                 "invited_by": "jo", "invited_at": "2026-10-08T09:30:00Z",
                 "devices": [{"name": "laptop"}]},
                {"name": "sam", "role": "member", "email": "sam@example.net",
                 "invited_by": "jo", "invited_at": "2026-10-08T09:30:00Z",
                 "devices": []},
                {"name": "hal", "role": "member", "email": "hal@example.net",
                 "invited_by": "jo", "invited_at": "2026-10-08T09:30:00Z",
                 "devices": []},
            ]})
            .to_string(),
        );
        yard.answer(
            "UninviteTeammate",
            r#"{"result": {"bead": "yd-uninvite", "ask": 83}}"#,
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_decisions(&view, cx);
        cx.run_until_parked();
        click_on(cx, "row teammates");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Teammates));
        // Sam's row has its Remove; jo's own row has none.
        assert!(drawn(cx, "teammates row jo"));
        assert!(!drawn(cx, "teammates remove jo"));
        assert!(drawn(cx, "teammates remove sam"));
        // A removal underway says so in the button's place.
        view.update_in(cx, |v, _, cx| {
            v.removing.insert((v.session, "sam".into()));
            cx.notify();
        });
        cx.run_until_parked();
        assert!(drawn(cx, "teammates removing sam"));
        view.update_in(cx, |v, _, cx| {
            v.removing.remove(&(v.session, "sam".into()));
            cx.notify();
        });
        // The press files the removal with sam, and the filed bead and
        // ask are said.
        click_on(cx, "teammates remove sam");
        wait(cx, "the removal filed", |cx| {
            notice(&view, cx) == "removal of sam filed on yd-uninvite ask 83"
        });
        assert_eq!(
            yard.asked("UninviteTeammate"),
            [json!({"user": "sam", "actor": "jo"})]
        );
        assert!(view.read_with(cx, |v, _| v.removing.is_empty()));
        // Two removals can be pending for different teammates. A second
        // press for the same teammate is still ignored, and each row
        // keeps its own busy marker while the yard answers them in turn.
        yard.answer(
            "UninviteTeammate",
            r#"{"result": {"bead": "yd-uninvite-2", "ask": 84}}"#,
        );
        yard.hold_calls("UninviteTeammate");
        view.update_in(cx, |v, _, cx| v.remove_teammate("sam".into(), cx));
        assert_eq!(view.read_with(cx, |v, _| v.removing.len()), 1);
        view.update_in(cx, |v, _, cx| v.remove_teammate("hal".into(), cx));
        view.update_in(cx, |v, _, cx| v.remove_teammate("sam".into(), cx));
        assert_eq!(view.read_with(cx, |v, _| v.removing.len()), 2);
        yard.release_calls("UninviteTeammate");
        wait(cx, "both removals answered", |cx| {
            yard.calls_held("UninviteTeammate") == 0
                && view.read_with(cx, |v, _| v.removing.is_empty())
        });
        assert_eq!(yard.asked("UninviteTeammate").len(), 3);
        // A refusal is shown as the refusal line, filing nothing.
        yard.answer(
            "UninviteTeammate",
            r#"{"error": {"code": "error", "message": "user hal: not found"}}"#,
        );
        click_on(cx, "teammates remove sam");
        wait(cx, "the refusal", |cx| {
            notice(&view, cx) == "not filed: user hal: not found"
        });
        assert_eq!(yard.asked("UninviteTeammate").len(), 4);
        // A call that ends without an answer reads the queue again, and
        // is never said to be filed or not.
        yard.answer_nothing("UninviteTeammate");
        let asks = yard.asked("UserAsks").len();
        click_on(cx, "teammates remove sam");
        wait(cx, "the queue read again", |cx| {
            notice(&view, cx) == "the yard did not answer; read the queue again"
                && yard.asked("UserAsks").len() == asks + 1
        });
    }

    /// Pair a phone opens a pairing for the name typed, and the pane
    /// shows its QR, code and minutes left; End ends it through the yard,
    /// and the pane offers Open again. Nothing opens with no name typed;
    /// Enter in the field opens as the button does.
    // The pane is the socket's: a yard at its listener stands no row.
    #[cfg(unix)]
    #[gpui::test]
    fn pair_a_phone_opens_shows_and_ends_a_pairing(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let ends =
            (chrono::Utc::now() + chrono::TimeDelta::minutes(9) + chrono::TimeDelta::seconds(30))
                .to_rfc3339();
        let open = json!({"result": {"user": "jo", "device": "iphone", "state": "open",
            "expires": ends, "code": "K7QM-2XPD",
            "qr": "https://edge.example.com#K7QM-2XPD#jo/edgeyard"}})
        .to_string();
        let none =
            r#"{"error": {"code": "not-found", "message": "an open device pairing: not found"}}"#;
        yard.answer(
            "DevicePairOpen",
            &json!({"result": {"user": "jo", "device": "iphone", "state": "open",
                "expires": ends, "code": "K7QM-2XPD"}})
            .to_string(),
        );
        // The state read with the rest already holds the pairing the
        // yard has open.
        yard.answer("DevicePairState", &open);
        yard.answer(
            "DevicePairClose",
            &json!({"result": {"user": "jo", "device": "iphone", "state": "ended",
                "expires": ends}})
            .to_string(),
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.pair_offered());
            assert_eq!(model.pairing().unwrap().device.as_str(), "iphone");
        });
        // For the opening below the yard starts with none open.
        yard.answer("DevicePairState", none);
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row teammates"));
        assert!(drawn(cx, "row pairing"));
        assert_eq!(view.read_with(cx, |v, _| v.keys_view()), KeysView::Card);
        click_on(cx, "row pairing");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Pairing));
        assert_eq!(view.read_with(cx, |v, _| v.keys_view()), KeysView::Pairing);
        // Opening the pane reads the pairing again: none is open, and
        // the form stands.
        wait(cx, "the pairing read again, none open", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.pairing().is_none())
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "pairing head"));
        assert!(drawn(cx, "pairing summary"));
        assert!(drawn(cx, "pairing name"));
        assert!(drawn(cx, "pairing help"));
        assert!(drawn(cx, "pairing open"));
        // Nothing opens with no name typed.
        click_on(cx, "pairing open");
        cx.run_until_parked();
        assert!(yard.asked("DevicePairOpen").is_empty());
        // The name typed, Open sends the opening with it, for the
        // window's own user. The opening stands, so the state read for
        // its QR string answers it.
        yard.answer("DevicePairState", &open);
        click_on(cx, "pairing name");
        cx.simulate_input("iphone");
        view.read_with(cx, |v, cx| {
            assert_eq!(
                v.device_name.read(cx).text().to_string(),
                "iphone",
                "typed text lands in the device field"
            );
        });
        click_on(cx, "pairing open");
        wait(cx, "the opening sent", |_| {
            yard.asked("DevicePairOpen") == [json!({"user": "jo", "name": "iphone", "actor": "jo"})]
        });
        // The pane shows the QR, the code and the minutes left, with End.
        wait(cx, "the pairing read with its QR string", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.pairing().is_some_and(|p| p.qr.is_some()))
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "pairing qr"));
        assert!(drawn(cx, "pairing code"));
        assert!(drawn(cx, "pairing left"));
        assert!(drawn(cx, "pairing end"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            let pairing = model.pairing().unwrap();
            assert_eq!(pairing.code.as_str(), "K7QM-2XPD");
            assert_eq!(
                pairing.qr.as_deref(),
                Some("https://edge.example.com#K7QM-2XPD#jo/edgeyard")
            );
            assert_eq!(
                crate::model::pairing_left(&pairing.expires, &chrono::Utc::now()),
                "9 minutes left"
            );
            assert!(model.pairing_line().is_empty());
        });
        // End ends it through the yard, and the pane offers Open again.
        click_on(cx, "pairing end");
        wait(cx, "the ending sent", |_| {
            yard.asked("DevicePairClose") == [json!({"actor": "jo"})]
        });
        wait(cx, "the pairing ended", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.pairing().is_none())
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "pairing name"));
        assert!(drawn(cx, "pairing open"));
        assert_eq!(notice(&view, cx), "");
        // Enter in the field opens as the button does.
        yard.answer(
            "DevicePairOpen",
            &json!({"result": {"user": "jo", "device": "tablet", "state": "open",
                "expires": ends, "code": "ABCD-EFGH"}})
            .to_string(),
        );
        click_on(cx, "pairing name");
        cx.simulate_input("tablet");
        cx.simulate_keystrokes("enter");
        wait(cx, "the opening sent by Enter", |_| {
            yard.asked("DevicePairOpen").len() == 2
        });
        assert_eq!(
            yard.asked("DevicePairOpen")[1],
            json!({"user": "jo", "name": "tablet", "actor": "jo"})
        );
    }

    /// Reopening the pane while a pairing lives shows it again from the
    /// state, with the same code. A pairing opened or ended elsewhere
    /// arrives as a device event, which reads it again too: the phone
    /// paired ends it, and the pane offers Open again.
    // The pane is the socket's: a yard at its listener stands no row.
    #[cfg(unix)]
    #[gpui::test]
    fn reopening_the_pane_shows_the_living_pairing_again(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let ends = (chrono::Utc::now() + chrono::TimeDelta::minutes(10)).to_rfc3339();
        let open = json!({"result": {"user": "jo", "device": "iphone", "state": "open",
            "expires": ends, "code": "K7QM-2XPD",
            "qr": "https://edge.example.com#K7QM-2XPD#jo/edgeyard"}})
        .to_string();
        let none =
            r#"{"error": {"code": "not-found", "message": "an open device pairing: not found"}}"#;
        // A pairing the operator opened at a terminal: the state read
        // with the rest holds it already.
        yard.answer("DevicePairState", &open);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row pairing"));
        click_on(cx, "row pairing");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Pairing));
        assert!(drawn(cx, "pairing qr"));
        assert!(drawn(cx, "pairing code"));
        let reads = yard.asked("DevicePairState").len();
        assert!(reads >= 2);
        // Away and back: the pairing is read again, with the same code.
        click_on(cx, "row teammates");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Teammates));
        click_on(cx, "row pairing");
        wait(cx, "the pairing read again", |_| {
            yard.asked("DevicePairState").len() == reads + 1
        });
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Pairing));
        assert!(drawn(cx, "pairing qr"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().pairing().unwrap().code.as_str(),
                "K7QM-2XPD"
            );
        });
        // The phone pairs: the pairing ends, and the pane offers Open
        // again.
        yard.answer("DevicePairState", none);
        yard.emit(r#"{"seq": 21, "kind": "device_added", "actor": "jo", "data": {"user": "jo", "device": "iphone"}}"#);
        wait(cx, "the pairing ended by the phone", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.pairing().is_none())
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "pairing name"));
        assert!(drawn(cx, "pairing open"));
        assert_eq!(notice(&view, cx), "");
        // Another opened at a terminal shows on its event, unopened.
        yard.answer("DevicePairState", &open);
        yard.emit(r#"{"seq": 22, "kind": "device_pair_opened", "actor": "jo", "data": {"user": "jo", "device": "iphone"}}"#);
        wait(cx, "the pairing opened elsewhere", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.pairing().is_some_and(|p| p.code.as_str() == "K7QM-2XPD"))
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "pairing qr"));
        assert!(drawn(cx, "pairing code"));
    }

    /// A second opening while one lives, and a name the yard will not
    /// pair, stand as the pane's refusal line, opening nothing.
    // The pane is the socket's: a yard at its listener stands no row.
    #[cfg(unix)]
    #[gpui::test]
    fn a_refused_opening_stands_as_the_pane_s_line(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_decisions(&view, cx);
        cx.run_until_parked();
        click_on(cx, "row pairing");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Pairing));
        // A name the yard will not pair.
        let bad = "device \"!\": use letters, digits, '.', '_', '-' or '/' (starting with a letter or digit)";
        yard.answer(
            "DevicePairOpen",
            &json!({"error": {"code": "error", "message": bad}}).to_string(),
        );
        click_on(cx, "pairing name");
        cx.simulate_input("!");
        click_on(cx, "pairing open");
        wait(cx, "the refusal", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.pairing_line() == format!("not opened: {bad}"))
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "pairing line"));
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().pairing().is_none());
        });
        assert_eq!(notice(&view, cx), "");
        // A second opening while one lives: the terminal opened one
        // meanwhile.
        let busy = "a pairing is open already, for the device tablet of jo until 12:30:00: a yard has one at a time";
        yard.answer(
            "DevicePairOpen",
            &json!({"error": {"code": "error", "message": busy}}).to_string(),
        );
        click_on(cx, "pairing name");
        cx.simulate_keystrokes("backspace");
        cx.simulate_input("iphone");
        click_on(cx, "pairing open");
        wait(cx, "the refusal", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.pairing_line() == format!("not opened: {busy}"))
            })
        });
        cx.run_until_parked();
        assert!(drawn(cx, "pairing line"));
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().pairing().is_none());
        });
        assert_eq!(notice(&view, cx), "");
        assert_eq!(yard.asked("DevicePairOpen").len(), 2);
    }

    /// A yard from before the pairing calls has none to serve: no notice
    /// is raised in any mode, and the pane says the yard is too old
    /// instead, and nowhere else.
    // The pane is the socket's: a yard at its listener stands no row.
    #[cfg(unix)]
    #[gpui::test]
    fn an_old_yard_says_so_in_the_pairing_pane_and_nowhere_else(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "DevicePairState",
            r#"{"error": {"code": "error", "message": "no such method DevicePairState"}}"#,
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().pairing_too_old());
        });
        assert_eq!(notice(&view, cx), "");
        assert!(!drawn(cx, "pairing too old"));
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row pairing"));
        click_on(cx, "row pairing");
        cx.run_until_parked();
        assert_eq!(open_row(&view, cx), Some(Selected::Pairing));
        assert!(drawn(cx, "pairing too old"));
        assert_eq!(yard.asked("DevicePairState").len(), 1);
        assert_eq!(notice(&view, cx), "");
        to_chat(&view, cx);
        cx.run_until_parked();
        assert_eq!(notice(&view, cx), "");
    }

    /// On a yard at an address, over the edge or paired direct, the
    /// action is absent and no pairing call is sent: the pane is the
    /// socket's, and a device token never opens a pairing.
    #[gpui::test]
    fn a_yard_at_an_address_shows_no_pairing_action_and_sends_no_pairing_call(
        cx: &mut TestAppContext,
    ) {
        use crate::fake::{Router, SESSION, TOKEN};

        // Over the edge: the operator's window of a hosted yard.
        let far = Yard::start_tcp();
        a_yard_of_jo(&far);
        let edge = Router::start(&far, SESSION);
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(edge.client_with(TOKEN, SESSION), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the hosted yard's conversation", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row teammates"));
        assert!(!drawn(cx, "row pairing"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.is_operator());
            assert!(!model.pair_offered());
            assert!(model.pairing().is_none());
        });
        assert!(far.asked("DevicePairState").is_empty());
        assert!(far.asked("DevicePairOpen").is_empty());
        assert!(far.asked("DevicePairClose").is_empty());
        // A pairing's event reads the teammates, as ever, and no pairing.
        let reads = far.asked("Teammates").len();
        far.emit(r#"{"seq": 21, "kind": "device_added", "actor": "jo", "data": {"user": "jo", "device": "iphone"}}"#);
        wait(cx, "the teammates read again", |_| {
            far.asked("Teammates").len() == reads + 1
        });
        cx.run_until_parked();
        assert!(far.asked("DevicePairState").is_empty());
        assert_eq!(notice(&view, cx), "");

        // Paired direct: the operator's window as the yard's device.
        let dir = tempfile::tempdir().unwrap();
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        far.answer("Settings", r#"{"result": {"operator": "jo"}}"#);
        let file = dir.path().join("footplate/settings.json");
        Settings {
            yards: vec![settings::Yard::far("far", far.address(), "yard-far.token")],
            open: "far".to_string(),
            ..Settings::default()
        }
        .write(&file)
        .unwrap();
        yard::keep_token(
            &dir.path().join("footplate/yard-far.token"),
            crate::fake::TOKEN,
        )
        .unwrap();
        let env = Env {
            socket: dir.path().join("yard.sock"),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "the far yard's conversation", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert!(!drawn(cx, "row pairing"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.is_operator());
            assert!(!model.pair_offered());
        });
        assert!(far.asked("DevicePairState").is_empty());
        assert!(far.asked("DevicePairOpen").is_empty());
        assert!(far.asked("DevicePairClose").is_empty());
        assert_eq!(notice(&view, cx), "");
    }

    /// The pairing's QR string draws as a square PNG of dark modules on
    /// a light ground: the same string draws the same bytes, and another
    /// string another's.
    #[test]
    fn qr_png_draws_the_string_as_a_square_png() {
        use super::asks::qr_png;
        let qr = "https://edge.example.com#K7QM-2XPD#jo/edgeyard";
        let png = qr_png(qr).unwrap();
        let image = image::load_from_memory(&png).unwrap();
        assert_eq!(image.width(), image.height());
        assert!(image.width() > 0);
        assert!(image.width() <= 240);
        // The same string draws the same bytes; another draws another's.
        assert_eq!(png, qr_png(qr).unwrap());
        assert_ne!(
            png,
            qr_png("https://edge.example.com#AAAA-0000#jo/edgeyard").unwrap()
        );
        // Light ground at the corners, and dark modules within.
        let gray = image.to_luma8();
        assert_eq!(gray.get_pixel(0, 0).0, [255]);
        assert_eq!(gray.get_pixel(image.width() - 1, 0).0, [255]);
        assert!(gray.pixels().any(|pixel| pixel.0 == [0]));
    }

    /// The settings offer Telemetry to the operator on a yard that serves
    /// the calls: on, the state, the consent words, the install id with a
    /// copy of it, the next request and payload, and Turn off. Turn off
    /// sends the off call only on the press, and reads the preview again;
    /// off, Turn on sends the on call the same way. The switch's move
    /// reads the preview again too. The window of another user is
    /// offered no section, and asks nothing.
    #[gpui::test]
    fn telemetry_stands_in_the_settings_for_the_operator_with_the_switch(cx: &mut TestAppContext) {
        let on = || {
            json!({"result": {
                "install_id": "3f6d1c2e-9a4b-4e7a-b5c1-2d8f0a6e4b90",
                "telemetry": "on", "since": "2026-10-26",
                "sending_day": "2026-10-28", "source_days": ["2026-10-27"],
                "hosted": false,
                "request": {"api_key": "phc_test", "batch": [{"event": "yardr_daily"}]},
            }})
            .to_string()
        };
        let off = || {
            json!({"result": {
                "telemetry": "off", "sending_day": "2026-10-28",
                "hosted": false, "request": null, "no_batch": "off",
            }})
            .to_string()
        };
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("TelemetryShow", &on());
        yard.answer(
            "TelemetrySet",
            r#"{"result": {"telemetry": "off", "changed": true}}"#,
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        // The preview is read with the yard; the change waits for the
        // press.
        assert_eq!(yard.asked("TelemetryShow"), vec![json!({})]);
        assert!(yard.asked("TelemetrySet").is_empty());
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(drawn(cx, "settings section telemetry"));
        click_on(cx, "settings section telemetry");
        // On: the state, the consent words, the id with its copy, the
        // next request and payload as the yard returns them, and Turn
        // off.
        assert!(drawn(cx, "telemetry state"));
        assert!(drawn(cx, "telemetry consent"));
        assert!(drawn(cx, "telemetry id"));
        assert!(drawn(cx, "telemetry copy"));
        assert!(drawn(cx, "telemetry next"));
        assert!(drawn(cx, "telemetry payload"));
        assert!(!drawn(cx, "telemetry no batch"));
        assert!(drawn(cx, "telemetry deletion"));
        assert!(drawn(cx, "telemetry off"));
        assert!(!drawn(cx, "telemetry on"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.telemetry_offered());
            assert!(!model.telemetry_read_only());
            let preview = model.telemetry_preview().unwrap();
            assert_eq!(preview.install_id, "3f6d1c2e-9a4b-4e7a-b5c1-2d8f0a6e4b90");
            assert_eq!(
                preview.request.as_ref().unwrap()["batch"][0]["event"],
                json!("yardr_daily")
            );
        });
        assert_eq!(notice(&view, cx), "");
        // Copy puts the install id on the clipboard.
        cx.write_to_clipboard(ClipboardItem::new_string("before".into()));
        click_on(cx, "telemetry copy");
        cx.run_until_parked();
        assert_eq!(
            clipboard(cx).as_deref(),
            Some("3f6d1c2e-9a4b-4e7a-b5c1-2d8f0a6e4b90")
        );
        // Turn off sends the off call with the operator, and reads the
        // preview again: off, with the switch off.
        yard.answer("TelemetryShow", &off());
        click_on(cx, "telemetry off");
        wait(cx, "the switch turned off", |cx| drawn(cx, "telemetry on"));
        assert_eq!(
            yard.asked("TelemetrySet"),
            vec![json!({"on": false, "actor": "jo"})]
        );
        assert_eq!(yard.asked("TelemetryShow").len(), 2);
        view.read_with(cx, |v, _| {
            let preview = v.model.as_ref().unwrap().telemetry_preview().unwrap();
            assert_eq!(preview.telemetry, "off");
        });
        // Turn on sends the on call only on the press, and reads again.
        assert_eq!(yard.asked("TelemetrySet").len(), 1);
        yard.answer("TelemetryShow", &on());
        yard.answer(
            "TelemetrySet",
            r#"{"result": {"telemetry": "on", "changed": true}}"#,
        );
        click_on(cx, "telemetry on");
        wait(cx, "the switch turned on", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.telemetry_preview().is_some_and(|p| p.telemetry == "on"))
            })
        });
        assert_eq!(
            yard.asked("TelemetrySet").last(),
            Some(&json!({"on": true, "actor": "jo"}))
        );
        assert_eq!(yard.asked("TelemetryShow").len(), 3);
        assert_eq!(notice(&view, cx), "");
        // The switch's move reads the preview again.
        yard.answer("TelemetryShow", &off());
        yard.emit(r#"{"seq": 21, "kind": "setting_changed", "actor": "jo", "data": {"key": "telemetry"}}"#);
        wait(cx, "the preview read again", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.telemetry_preview().is_some_and(|p| p.telemetry == "off"))
            })
        });
        assert_eq!(yard.asked("TelemetryShow").len(), 4);
        // Off from the start: the consent words and Turn on, with no id,
        // no payload and no Turn off.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("TelemetryShow", &off());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(drawn(cx, "settings section telemetry"));
        click_on(cx, "settings section telemetry");
        assert!(drawn(cx, "telemetry state"));
        assert!(drawn(cx, "telemetry consent"));
        assert!(drawn(cx, "telemetry on"));
        assert!(!drawn(cx, "telemetry id"));
        assert!(!drawn(cx, "telemetry next"));
        assert!(!drawn(cx, "telemetry payload"));
        assert!(!drawn(cx, "telemetry off"));
        assert_eq!(notice(&view, cx), "");
        // Another user's window: no section, and no call.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Settings", r#"{"result": {"operator": "mckean"}}"#);
        yard.answer("TelemetryShow", &on());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(!drawn(cx, "settings section telemetry"));
        view.read_with(cx, |v, _| {
            assert!(!v.model.as_ref().unwrap().telemetry_offered());
        });
        assert!(yard.asked("TelemetryShow").is_empty());
        assert_eq!(notice(&view, cx), "");
    }

    /// A yard from before the telemetry calls, and one that refuses the
    /// preview as a request come down the link from its edge, offer no
    /// Telemetry section: with no notice, and the refusal is not asked
    /// again, by the window's second try of a failed read or by the
    /// switch's move. A hosted yard is not asked at all. Telemetry kept
    /// open past the yard that offered it shows the first section's. A
    /// preview that could not be read is offered still, with why and try
    /// again.
    #[gpui::test]
    fn telemetry_hides_where_the_yard_serves_no_calls(cx: &mut TestAppContext) {
        // A yard from before the calls: asked once, with no section and
        // no notice, and not asked again.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "TelemetryShow",
            r#"{"error": {"code": "error", "message": "no such method TelemetryShow"}}"#,
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        assert_eq!(yard.asked("TelemetryShow").len(), 1);
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(!drawn(cx, "settings section telemetry"));
        view.read_with(cx, |v, _| {
            assert!(!v.model.as_ref().unwrap().telemetry_offered());
        });
        assert_eq!(notice(&view, cx), "");
        cx.executor().advance_clock(session::RETRY + session::RETRY);
        cx.run_until_parked();
        assert_eq!(yard.asked("TelemetryShow").len(), 1);
        yard.emit(r#"{"seq": 21, "kind": "setting_changed", "actor": "jo", "data": {"key": "telemetry"}}"#);
        cx.run_until_parked();
        assert_eq!(yard.asked("TelemetryShow").len(), 1);
        assert_eq!(notice(&view, cx), "");
        // The link's refusal hides it too, in no notice.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "TelemetryShow",
            &json!({"error": {"code": "error", "message": "the telemetry switch is not read over the link: this request came down the link from the edge. Read it on the yard's machine (`yardr telemetry show`). The edge saw the device's token with it: remove the device and add it again (yardr user device rm)."}}).to_string(),
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        assert_eq!(yard.asked("TelemetryShow").len(), 1);
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(!drawn(cx, "settings section telemetry"));
        assert_eq!(notice(&view, cx), "");
        // A hosted yard is not asked at all.
        use crate::fake::{Router, SESSION, TOKEN};
        let far = Yard::start_tcp();
        a_yard_of_jo(&far);
        let edge = Router::start(&far, SESSION);
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(edge.client_with(TOKEN, SESSION), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the hosted yard's conversation", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.is_operator());
            assert!(!model.telemetry_offered());
        });
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(!drawn(cx, "settings section telemetry"));
        assert!(far.asked("TelemetryShow").is_empty());
        assert_eq!(notice(&view, cx), "");
        // Telemetry kept open past the yard that offered it shows the
        // first section's.
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        Settings {
            section: Section::Telemetry,
            ..Settings::default()
        }
        .write(&file)
        .unwrap();
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened_kept(&yard, &file, cx);
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(!drawn(cx, "settings section telemetry"));
        assert!(drawn(cx, "text size"));
        // A preview that could not be read is offered still, with why
        // and try again; the retry reads it.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("TelemetryShow", r#"{"result": {"telemetry": 7}}"#);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        assert!(drawn(cx, "settings section telemetry"));
        click_on(cx, "settings section telemetry");
        assert!(drawn(cx, "telemetry notice"));
        assert!(drawn(cx, "telemetry again"));
        assert!(!drawn(cx, "telemetry state"));
        yard.answer(
            "TelemetryShow",
            r#"{"result": {"telemetry": "off", "sending_day": "2026-10-28", "hosted": false, "request": null, "no_batch": "off"}}"#,
        );
        click_on(cx, "telemetry again");
        wait(cx, "the preview read again", |cx| {
            drawn(cx, "telemetry state")
        });
        assert!(drawn(cx, "telemetry on"));
        assert_eq!(notice(&view, cx), "");
    }

    /// A yard that reads the preview but refuses the switch's change
    /// stands the section read-only: the state, the id and the payload
    /// with no buttons, and the sentence that the switch is changed in
    /// the yard's web view, with Open where the view answers and none
    /// where it does not. The refused change is made once, and never
    /// again by another path. Any other refusal is said of the press,
    /// with the buttons to try again.
    #[gpui::test]
    fn a_refused_change_stands_read_only_with_the_web_view(cx: &mut TestAppContext) {
        let on = || {
            json!({"result": {
                "install_id": "3f6d1c2e-9a4b-4e7a-b5c1-2d8f0a6e4b90",
                "telemetry": "on", "since": "2026-10-26",
                "sending_day": "2026-10-28", "source_days": ["2026-10-27"],
                "hosted": false,
                "request": {"api_key": "phc_test", "batch": [{"event": "yardr_daily"}]},
            }})
            .to_string()
        };
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("TelemetryShow", &on());
        yard.answer(
            "TelemetrySet",
            &json!({"error": {"code": "error", "message": "the telemetry switch is taken over https only, or from the yard's own machine: this request reached the yard's listener in plain HTTP from another machine. Put the proxy or tunnel that ends TLS on the yard's machine, or Change it on the yard's machine (`yardr telemetry on` or `yardr telemetry off`). The device's token was sent with it and may have crossed a network in the clear: if it did, remove the device and add it again (yardr user device rm)."}}).to_string(),
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        // The press's refusal stands the section read-only: made once.
        view.update_in(cx, |v, _, cx| v.telemetry_turn(false, cx));
        wait(cx, "the change refused", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.telemetry_read_only())
            })
        });
        assert_eq!(
            yard.asked("TelemetrySet"),
            vec![json!({"on": false, "actor": "jo"})]
        );
        // Where the view does not answer: the sentence with no Open.
        let down = view_down();
        set_view(&view, cx, &down);
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        click_on(cx, "settings section telemetry");
        wait(cx, "the web view down", |cx| {
            view_answered(&view, cx) == Some(false)
        });
        assert!(drawn(cx, "telemetry state"));
        assert!(drawn(cx, "telemetry id"));
        assert!(drawn(cx, "telemetry payload"));
        assert!(drawn(cx, "telemetry read only"));
        assert!(!drawn(cx, "telemetry open"));
        assert!(!drawn(cx, "telemetry on"));
        assert!(!drawn(cx, "telemetry off"));
        assert_eq!(notice(&view, cx), "");
        // Where the view answers: Open takes the telemetry page to the
        // browser. The refused change is made no second time.
        let base = view_up();
        set_view(&view, cx, &base);
        let pages = opened_pages(&view, cx);
        click_on(cx, "settings section telemetry");
        wait(cx, "the web view", |cx| {
            view_answered(&view, cx) == Some(true)
        });
        assert!(drawn(cx, "telemetry open"));
        click_on(cx, "telemetry open");
        cx.run_until_parked();
        assert_eq!(pages.borrow().as_slice(), [format!("{base}/telemetry")]);
        cx.run_until_parked();
        assert_eq!(yard.asked("TelemetrySet").len(), 1);
        assert_eq!(notice(&view, cx), "");
        // Any other refusal is said of the press, with the buttons to
        // try again.
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("TelemetryShow", &on());
        yard.answer(
            "TelemetrySet",
            r#"{"error": {"code": "error", "message": "the switch is stuck"}}"#,
        );
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        cx.simulate_keystrokes("secondary-,");
        click_on(cx, "settings section telemetry");
        click_on(cx, "telemetry off");
        wait(cx, "the refusal said", |cx| drawn(cx, "telemetry said"));
        assert!(drawn(cx, "telemetry off"));
        assert!(!drawn(cx, "telemetry read only"));
        assert_eq!(yard.asked("TelemetrySet").len(), 1);
        assert_eq!(notice(&view, cx), "");
    }

    /// Chat's groups hold their rows in order, each under its head: the
    /// crew with their states as dots beside their names, the linked
    /// yards' people with their peer suffixes drawn apart, this yard's
    /// people, and the yard row. Only the crew carries dots. The yard's
    /// count is a badge; the rows' counts stay quiet words.
    #[gpui::test]
    fn the_chat_groups_hold_their_rows_with_dots_and_peers(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserNotifications", &notices_many(2));
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        wait(cx, "the notices", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| m.yard_unread() == 2)
            })
        });
        // Each head over its rows, in order down the list.
        let crew = bounds_of(cx, "group This yard's crew");
        let assembly = bounds_of(cx, "row name assembly");
        let master = bounds_of(cx, "row name yardmaster");
        let linked = bounds_of(cx, "group Linked yards");
        let clerk = bounds_of(cx, "row name clerk@north");
        let people = bounds_of(cx, "group People");
        let jo = bounds_of(cx, "row name jo");
        let head = bounds_of(cx, "group Yard");
        let yard_row = bounds_of(cx, "row yard");
        let mut last = crew.top();
        for (what, at) in [
            ("crew head", &crew),
            ("assembly", &assembly),
            ("yardmaster", &master),
            ("linked head", &linked),
            ("clerk", &clerk),
            ("people head", &people),
            ("jo", &jo),
            ("yard head", &head),
            ("yard row", &yard_row),
        ] {
            assert!(
                last <= at.top(),
                "{what} stands out of order: {at:?} after {last:?}"
            );
            last = at.bottom();
        }
        // The dots stand beside the crew's names, on their lines, and
        // nowhere else.
        for name in ["assembly", "yardmaster"] {
            let dot = bounds_of(cx, &format!("row dot {name}"));
            let row = bounds_of(cx, &format!("row name {name}"));
            assert!(
                dot.right() <= row.left() + px(1.)
                    && dot.top() >= row.top()
                    && dot.bottom() <= row.bottom() + px(1.),
                "{name}'s dot stands off its name: {dot:?} {row:?}"
            );
        }
        assert!(!drawn(cx, "row dot clerk@north"));
        assert!(!drawn(cx, "row dot jo"));
        assert!(!drawn(cx, "row dot yard"));
        // The peer suffix stands apart at its name's end.
        let peer = bounds_of(cx, "row peer clerk@north");
        assert!(
            peer.right() <= clerk.right() + px(1.) && peer.left() >= clerk.left(),
            "the peer stands off its name: {peer:?} {clerk:?}"
        );
        // The yard's count is a badge sixteen high, not words.
        let badge = bounds_of(cx, "row unread yard");
        assert!(
            (badge.size.height - px(16.)).abs() < px(1.),
            "the notices count is no badge: {badge:?}"
        );
    }

    /// The timetable's list holds the arrivals row, counting what is in
    /// transit. A click on it opens the panel; Departures keeps the board:
    /// the served rows flat in the served arrival order under their
    /// column head, each with its cells in the board's order and
    /// remarked as served.
    #[gpui::test]
    fn departures_stands_flat_in_the_served_arrival_order(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_board());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        // The crew stands in chat, and the arrivals row in timetable.
        assert!(drawn(cx, "row name yardmaster"));
        assert!(!drawn(cx, "row arrivals"));
        assert!(!drawn(cx, "arrival yd-zulu"));
        to_timetable(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row arrivals"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().arrivals_row().line,
                "3 in transit"
            );
        });
        // The board on a click: the rows flat in the served order, no
        // grouping by platform.
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::Arrivals)
            );
        });
        assert!(drawn(cx, "arrivals head"));
        assert!(drawn(cx, "departures head"));
        for bead in ["yd-zulu", "yd-alpha", "footplate-p512"] {
            assert!(drawn(cx, &format!("arrival {bead}")), "{bead}");
            assert!(drawn(cx, &format!("arrival expected {bead}")), "{bead}");
            assert!(drawn(cx, &format!("arrival bead {bead}")), "{bead}");
            assert!(drawn(cx, &format!("arrival title {bead}")), "{bead}");
            assert!(drawn(cx, &format!("arrival platform {bead}")), "{bead}");
            assert!(drawn(cx, &format!("arrival line {bead}")), "{bead}");
        }
        let zulu = bounds_of(cx, "arrival yd-zulu").top();
        let alpha = bounds_of(cx, "arrival yd-alpha").top();
        let p512 = bounds_of(cx, "arrival footplate-p512").top();
        assert!(
            zulu < alpha && alpha < p512,
            "the rows stand out of the served order: {zulu:?} {alpha:?} {p512:?}"
        );
        // The cells in the board's order: Expected first, the remark
        // last.
        for bead in ["yd-zulu", "yd-alpha", "footplate-p512"] {
            let expected = bounds_of(cx, &format!("arrival expected {bead}")).left();
            let title = bounds_of(cx, &format!("arrival title {bead}")).left();
            let platform = bounds_of(cx, &format!("arrival platform {bead}")).left();
            let line = bounds_of(cx, &format!("arrival line {bead}")).left();
            assert!(
                expected < title && title < platform && platform < line,
                "the cells stand out of the board's order: {bead}"
            );
        }
        // The rows as served: the late mark and the hold as words in
        // the remark, nothing where none is.
        assert!(drawn(cx, "arrival remark yd-zulu"));
        assert!(!drawn(cx, "arrival remark yd-alpha"));
        assert!(drawn(cx, "arrival remark footplate-p512"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(
                model
                    .arrival_rows()
                    .iter()
                    .map(|row| (
                        row.bead.as_str(),
                        row.platform.as_str(),
                        row.remark.as_str(),
                        row.tone.as_str()
                    ))
                    .collect::<Vec<_>>(),
                [
                    ("yd-zulu", "draft", "late", "amber"),
                    ("yd-alpha", "review", "", "none"),
                    ("footplate-p512", "draft", "held", "red"),
                ]
            );
        });
        // Three travel and three show: no capped line stands.
        assert!(!drawn(cx, "arrivals capped"));
    }

    /// A yard from before the Lines view serves no Arrivals or Flows:
    /// no notice is raised in any mode, and the Lines pane says the yard
    /// is too old instead, on the panel and under Departures alike, and
    /// nowhere else.
    #[gpui::test]
    fn an_old_yard_says_so_in_the_lines_pane_and_nowhere_else(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let old = |method: &str| {
            format!(r#"{{"error": {{"code": "error", "message": "no such method {method}"}}}}"#)
        };
        yard.answer("Arrivals", &old("Arrivals"));
        yard.answer("Flows", &old("Flows"));
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.arrivals_too_old());
            assert!(model.flows_too_old());
        });
        assert_eq!(notice(&view, cx), "");
        assert!(!drawn(cx, "lines too old"));
        // The panel says the yard is too old, and so does the board
        // under the toggle, with still no notice anywhere.
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        cx.run_until_parked();
        assert!(drawn(cx, "lines too old"));
        assert_eq!(notice(&view, cx), "");
        to_departures(cx);
        assert!(drawn(cx, "lines too old"));
        assert_eq!(notice(&view, cx), "");
        // Back in chat and in decisions: no notice, and the words stand
        // in the Lines pane alone. (What was drawn stays drawn to the
        // tests, so the words gone from the pane are not said here.)
        to_chat(&view, cx);
        cx.run_until_parked();
        assert_eq!(notice(&view, cx), "");
        to_decisions(&view, cx);
        cx.run_until_parked();
        assert_eq!(notice(&view, cx), "");
    }

    /// A Lines call read again past an old yard says the yard is too
    /// old, with no notice; any other failure of the re-read is a
    /// notice, as ever.
    #[gpui::test]
    fn a_lines_call_read_again_says_an_old_yard_and_notices_the_rest(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_board());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        wait(cx, "the arrivals and flows", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.arrival_rows().len() == 3 && m.travelling() == 3)
            })
        });
        // The board read again past an answer the yard has no call for:
        // its old rows go with it, and no notice is raised.
        yard.answer_once_status(
            "Arrivals",
            200,
            r#"{"error": {"code": "error", "message": "no such method Arrivals"}}"#,
        );
        yard.emit(r#"{"seq": 21, "kind": "noted", "actor": "yardmaster", "bead": "bead-a", "data": {"note": 1}}"#);
        wait(cx, "the yard too old for arrivals", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.arrivals_too_old() && m.arrival_rows().is_empty())
            })
        });
        cx.run_until_parked();
        assert_eq!(notice(&view, cx), "");
        view.read_with(cx, |v, _| {
            assert!(!v.model.as_ref().unwrap().flows_too_old());
        });
        // The panel's call can become unavailable on a later read too:
        // its old rows go, and the same quiet words stand in their place.
        yard.answer_once_status(
            "Flows",
            200,
            r#"{"error": {"code": "error", "message": "no such method Flows"}}"#,
        );
        yard.emit(r#"{"seq": 22, "kind": "noted", "actor": "yardmaster", "bead": "bead-a", "data": {"note": 2}}"#);
        wait(cx, "the yard too old for flows", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().is_some_and(|m| {
                    m.flows_too_old() && m.travelling() == 0 && m.depots().is_empty()
                })
            })
        });
        assert_eq!(notice(&view, cx), "");
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        cx.run_until_parked();
        assert!(drawn(cx, "lines too old"));
        to_departures(cx);
        assert!(drawn(cx, "lines too old"));
        assert_eq!(notice(&view, cx), "");
        // A re-read the yard serves unreadably is a notice, as ever.
        yard.answer_once_status("Flows", 200, r#"{"result": {"travelling": [7]}}"#);
        yard.emit(r#"{"seq": 23, "kind": "noted", "actor": "yardmaster", "bead": "bead-a", "data": {"note": 3}}"#);
        wait(cx, "why the flows could not be read", |cx| {
            !notice(&view, cx).is_empty()
        });
        assert!(
            notice(&view, cx).starts_with("the flows could not be read: "),
            "{}",
            notice(&view, cx)
        );
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().flows_too_old());
        });
    }

