    /// The board banners how many beads wait on the person reading:
    /// the head alone above the table, no row per bead, and a click
    /// opens the decisions mode, as Enter does with the focus on it. The
    /// wait for several counts with an open ask on that bead.
    #[gpui::test]
    fn the_board_banners_how_many_wait_on_you(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_waits());
        yard.answer("Flows", &flows_board());
        yard.answer("UserAsks", &asks_about("yd-zulu", "yardmaster", "Land it?"));
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model
                    .as_ref()
                    .unwrap()
                    .waiting_on_you()
                    .iter()
                    .map(|(bead, _)| *bead)
                    .collect::<Vec<_>>(),
                ["yd-zulu"]
            );
        });
        assert!(drawn(cx, "waits banner"));
        assert!(!drawn(cx, "waits yd-zulu"));
        assert!(!drawn(cx, "waits title yd-zulu"));
        assert!(!drawn(cx, "waits open yd-zulu"));
        let banner = bounds_of(cx, "waits banner").bottom();
        let head = bounds_of(cx, "departures head").top();
        assert!(
            banner <= head,
            "the banner stands below the table: {banner:?} {head:?}"
        );
        click_on(cx, "waits banner");
        wait(cx, "the decisions mode", |cx| {
            rail_mode(&view, cx) == Mode::Decisions
        });
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        wait(cx, "the arrivals board again", |cx| {
            drawn(cx, "arrival yd-zulu")
        });
        cx.update(|window, cx| window.focus(&view.read(cx).waits_focus.clone()));
        cx.simulate_keystrokes("enter");
        wait(cx, "the decisions mode by key", |cx| {
            rail_mode(&view, cx) == Mode::Decisions
        });
    }

    /// A wait for several without an open ask banners nothing: the row
    /// stands as the yard printed it, and counts toward no "waiting on
    /// you". That is all a yard from before `Waiting` can say. One that
    /// serves it says whose move it is: with the same bead parked for the
    /// person among several, it counts and the banner stands once the
    /// bead's next event has the queue read, and the click opens the
    /// decisions mode.
    #[gpui::test]
    fn a_wait_for_several_without_an_open_ask_banners_nothing(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_waits());
        yard.answer("Flows", &flows_board());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert!(model.waiting_too_old());
            assert!(model.waiting_on_you().is_empty());
        });
        assert!(!drawn(cx, "waits banner"));

        // The yard now serves the queue, and parks the bead for jo.
        yard.answer("Waiting", &waiting_of(&["yd-zulu"]));
        yard.emit(r#"{"seq": 21, "kind": "advanced", "actor": "yardmaster", "bead": "yd-zulu", "data": {}}"#);
        wait(cx, "the parked bead counted", |cx| {
            view.read_with(cx, |v, _| {
                let model = v.model.as_ref().unwrap();
                !model.waiting_too_old()
                    && model
                        .waiting_on_you()
                        .iter()
                        .map(|(bead, _)| *bead)
                        .eq(["yd-zulu"])
            })
        });
        wait(cx, "the banner", |cx| drawn(cx, "waits banner"));
        click_on(cx, "waits banner");
        wait(cx, "the decisions mode", |cx| {
            rail_mode(&view, cx) == Mode::Decisions
        });
    }

    /// The banner holds fifty-five waits on its one line: the head
    /// alone above the table, no row per bead, and a click opens the
    /// decisions mode. The arrivals row's wait for several counts with
    /// its open ask; the fifty-four flows rows name jo alone.
    #[gpui::test]
    fn the_banner_holds_fifty_five_waits_on_one_line(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_waits());
        yard.answer("UserAsks", &asks_about("yd-zulu", "yardmaster", "Land it?"));
        let mut flows: Value = serde_json::from_str(&flows_board()).unwrap();
        let beads = flows["result"]["depots"][0]["flows"][0]["stages"][0]["beads"]
            .as_array_mut()
            .unwrap();
        for n in 0..54 {
            beads.push(json!({
                "bead": format!("yd-w{n:02}"), "title": format!("Wait number {n}"),
                "expected": "1h–2h", "remark": "waits for jo", "tone": "amber",
                "working": false,
            }));
        }
        yard.answer("Flows", &flows.to_string());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        view.read_with(cx, |v, _| {
            assert_eq!(v.model.as_ref().unwrap().waiting_on_you().len(), 55);
        });
        assert!(drawn(cx, "waits banner"));
        assert!(!drawn(cx, "waits yd-zulu"));
        assert!(!drawn(cx, "waits yd-w00"));
        assert!(!drawn(cx, "waits yd-w53"));
        assert!(!drawn(cx, "waits open yd-zulu"));
        let banner = bounds_of(cx, "waits banner").bottom();
        let head = bounds_of(cx, "departures head").top();
        assert!(
            banner <= head,
            "the banner stands below the table: {banner:?} {head:?}"
        );
        click_on(cx, "waits banner");
        wait(cx, "the decisions mode", |cx| {
            rail_mode(&view, cx) == Mode::Decisions
        });
    }

    /// The banner counts what waits: one waits, two wait. Quiet
    /// says folded or open with how many lines stand under it.
    #[test]
    fn the_banner_counts_what_waits_on_you() {
        assert_eq!(waits_head(1), "1 waits on you");
        assert_eq!(waits_head(2), "2 wait on you");
        assert_eq!(waits_head(55), "55 wait on you");
        assert_eq!(quiet_head(false, 1), "▸ Quiet · 1");
        assert_eq!(quiet_head(true, 5), "▾ Quiet · 5");
    }

    /// A remark reads waiting only where it waits on the reader: a
    /// stalled bead reads red, a held bead only where they hold it, a
    /// wait naming them reads waiting, and a hold by anyone else or
    /// no one known, late, blocked, a wait for anyone else and
    /// nothing read dim.
    #[test]
    fn remarks_read_waiting_only_where_they_wait_on_the_reader() {
        let palette = Palette::of(Look::Dark, WindowAppearance::Dark);
        assert_eq!(
            remark_color("held by jo", "red", "jo", "jo", palette),
            palette.warn
        );
        assert_eq!(
            remark_color("held by jo", "none", "jo", "jo", palette),
            palette.warn
        );
        assert_eq!(
            remark_color("stalled · session failed", "red", "", "jo", palette),
            palette.warn
        );
        assert_eq!(
            remark_color("held by ada", "red", "ada", "jo", palette),
            palette.faint
        );
        assert_eq!(
            remark_color("held", "red", "", "jo", palette),
            palette.faint
        );
        assert_eq!(
            remark_color("waits for jo", "amber", "", "jo", palette),
            palette.text_accent
        );
        assert_eq!(
            remark_color("waits for jo, ada", "amber", "", "ada", palette),
            palette.text_accent
        );
        assert_eq!(
            remark_color("late", "amber", "", "jo", palette),
            palette.faint
        );
        assert_eq!(
            remark_color("late by 40m", "amber", "", "jo", palette),
            palette.faint
        );
        assert_eq!(
            remark_color("blocked by yd-x", "amber", "", "jo", palette),
            palette.faint
        );
        assert_eq!(
            remark_color("waits for jo", "amber", "", "ada", palette),
            palette.faint
        );
        assert_eq!(remark_color("", "none", "", "jo", palette), palette.faint);
    }

    /// A stage column's head says whose group works there: its name,
    /// that it waits on a person where the group is manual, and its
    /// seats where the yard serves them. No route and paused say why.
    #[test]
    fn a_stage_column_s_head_says_whose_group_works_there() {
        let stage =
            |group: &str, human: bool, limit: Option<usize>, taken: Option<usize>| FlowStage {
                group: group.to_string(),
                human,
                limit,
                taken,
                ..FlowStage::default()
            };
        assert_eq!(
            stage_group_words(&stage("muse-builders", false, Some(3), Some(2))),
            "muse-builders · 2 of 3 seats"
        );
        assert_eq!(
            stage_group_words(&stage("mckean", true, Some(1), Some(1))),
            "mckean · waiting on a person · 1 of 1 seats"
        );
        assert_eq!(
            stage_group_words(&stage("muse-builders", false, None, None)),
            "muse-builders"
        );
        assert_eq!(
            stage_group_words(&stage("muse-builders", false, Some(0), Some(0))),
            "muse-builders · paused"
        );
        assert_eq!(
            stage_group_words(&stage("", false, None, None)),
            "no route matches"
        );
    }

    /// Who works a bead, for its hover and its details line: the
    /// session without its herdr runner word, then the group, kind
    /// and model where served. Any other worker stays whole, a claim
    /// with no kind shows its group alone, a yard serving none of
    /// the three shows the session's name alone, and no worker says
    /// nothing.
    #[test]
    fn a_worked_bead_s_hover_and_details_name_who_works_it() {
        let bead = |worker: &str, group: &str, kind: &str, model: &str| FlowBead {
            worker: worker.to_string(),
            group: group.to_string(),
            kind: kind.to_string(),
            model: model.to_string(),
            ..FlowBead::default()
        };
        assert_eq!(
            worker_words(&bead(
                "herdr footplate-pnpx-draft",
                "opus-builders",
                "claude",
                "claude-opus-5-5"
            )),
            Some((
                "footplate-pnpx-draft\nopus-builders · claude · claude-opus-5-5".to_string(),
                "worked by footplate-pnpx-draft · opus-builders · claude · claude-opus-5-5"
                    .to_string(),
            ))
        );
        assert_eq!(
            worker_words(&bead("exec pid 4127", "footplate-assembly", "", "")),
            Some((
                "exec pid 4127\nfootplate-assembly".to_string(),
                "worked by exec pid 4127 · footplate-assembly".to_string(),
            ))
        );
        assert_eq!(
            worker_words(&bead(
                "herdr yd-zulu-new",
                "muse-builders",
                "",
                "muse-spark-1.3-contributor"
            )),
            Some((
                "yd-zulu-new\nmuse-builders · muse-spark-1.3-contributor".to_string(),
                "worked by yd-zulu-new · muse-builders · muse-spark-1.3-contributor".to_string(),
            ))
        );
        assert_eq!(
            worker_words(&bead("herdr yd-zulu-new", "muse-builders", "muse", "")),
            Some((
                "yd-zulu-new\nmuse-builders · muse".to_string(),
                "worked by yd-zulu-new · muse-builders · muse".to_string(),
            ))
        );
        assert_eq!(
            worker_words(&bead("herdr yd-zulu-new", "", "", "")),
            Some((
                "yd-zulu-new".to_string(),
                "worked by yd-zulu-new".to_string(),
            ))
        );
        assert_eq!(worker_words(&bead("", "", "", "")), None);
        assert_eq!(
            worker_words(&bead(
                "",
                "muse-builders",
                "muse",
                "muse-spark-1.3-contributor"
            )),
            None
        );
    }

    /// The panel's head splits "N working" by served kind where two or
    /// more kinds work; one kind alone drops the split, as do beads
    /// with no kind. Its tooltip lists each working group with its
    /// seats, one per line: the name alone where no current stage
    /// names the group, paused where it is paused, and none at all
    /// where no worked bead names a group.
    #[test]
    fn the_panel_s_working_head_splits_by_kind_with_groups_on_hover() {
        let kinds = |kinds: &[(&str, usize)]| {
            kinds
                .iter()
                .map(|(k, n)| (k.to_string(), *n))
                .collect::<Vec<_>>()
        };
        assert_eq!(
            working_words(5, &kinds(&[("muse", 3), ("claude", 2)])),
            "5 working: 3 muse, 2 claude"
        );
        assert_eq!(working_words(2, &kinds(&[("muse", 2)])), "2 working");
        assert_eq!(working_words(1, &kinds(&[])), "1 working");
        let group = |name: &str, limit: Option<usize>, taken: Option<usize>| WorkingGroup {
            name: name.to_string(),
            limit,
            taken,
        };
        assert_eq!(
            working_tip(&[
                group("muse-builders", Some(5), Some(3)),
                group("opus-builders", Some(2), Some(2)),
                group("footplate-assembly", Some(1), Some(1)),
                group("old-builders", None, None),
            ]),
            Some(
                "muse-builders · 3 of 5 seats\nopus-builders · 2 of 2 seats\nfootplate-assembly · 1 of 1 seat\nold-builders"
                    .to_string()
            )
        );
        assert_eq!(working_tip(&[]), None);
        assert_eq!(
            working_group_words(&group("muse-builders", Some(0), Some(1))),
            "muse-builders · paused"
        );
        assert_eq!(
            working_group_words(&group("muse-builders", Some(5), None)),
            "muse-builders"
        );
    }

    /// A bead waits for a seat where it is unclaimed, its remark names
    /// no held, blocked or waiting state, and its group's seats are all
    /// taken. A late mark waits too; only a routed group with seats
    /// can be full.
    #[test]
    fn a_bead_waits_for_a_seat_where_its_group_is_full() {
        let stage = |limit: Option<usize>, taken: Option<usize>| FlowStage {
            limit,
            taken,
            ..FlowStage::default()
        };
        let bead = |remark: &str, tone: &str, working: bool| FlowBead {
            remark: remark.to_string(),
            tone: tone.to_string(),
            working,
            ..FlowBead::default()
        };
        let full = stage(Some(2), Some(2));
        assert!(waits_for_seat(&bead("", "none", false), &full));
        assert!(waits_for_seat(&bead("late by 40m", "amber", false), &full));
        assert!(!waits_for_seat(&bead("", "none", true), &full));
        assert!(!waits_for_seat(&bead("held", "red", false), &full));
        assert!(!waits_for_seat(
            &bead("held by yardmaster", "red", false),
            &full
        ));
        assert!(!waits_for_seat(
            &bead("blocked by yd-x", "amber", false),
            &full
        ));
        assert!(!waits_for_seat(
            &bead("waits for jo", "amber", false),
            &full
        ));
        assert!(!waits_for_seat(
            &bead("", "none", false),
            &stage(Some(3), Some(2))
        ));
        assert!(!waits_for_seat(
            &bead("", "none", false),
            &stage(Some(0), Some(0))
        ));
        assert!(!waits_for_seat(
            &bead("", "none", false),
            &stage(None, None)
        ));
    }

    /// A stage's lamp burns only where a bead stands on it: the served
    /// fault or turn, and nothing on an empty stage whatever it serves.
    /// The panel's cell adds the running green where a bead is worked and
    /// no fault or turn burns, as the phones' strips mark a stage moving;
    /// the line view's columns draw the served lamp alone.
    #[test]
    fn a_stage_s_lamp_burns_only_where_a_bead_stands_on_it() {
        let stage = |lamp: &str, beads: usize| FlowStage {
            lamp: lamp.to_string(),
            beads: vec![FlowBead::default(); beads],
            ..FlowStage::default()
        };
        assert_eq!(stage_lamp(&stage("fault", 1)), "fault");
        assert_eq!(stage_lamp(&stage("turn", 2)), "turn");
        assert_eq!(stage_lamp(&stage("none", 1)), "none");
        assert_eq!(stage_lamp(&stage("fault", 0)), "none");
        assert_eq!(stage_lamp(&stage("turn", 0)), "none");
        let worked = |lamp: &str| {
            let mut stage = stage(lamp, 2);
            stage.beads[1].working = true;
            stage
        };
        assert_eq!(stage_state(&worked("none")), "moving");
        assert_eq!(stage_state(&worked("fault")), "fault");
        assert_eq!(stage_state(&worked("turn")), "turn");
        assert_eq!(stage_state(&stage("none", 2)), "none");
        assert_eq!(stage_state(&stage("none", 0)), "none");
        // The line view's columns keep to the served lamp.
        assert_eq!(stage_lamp(&worked("none")), "none");
    }

    /// A cell draws its worked beads first, each group in the served
    /// order, and never reorders what no bead is worked in.
    #[test]
    fn a_cell_draws_its_worked_beads_before_the_waiting_ones() {
        let bead = |id: &str, working: bool| FlowBead {
            bead: id.to_string(),
            working,
            ..FlowBead::default()
        };
        let order = |beads: &[FlowBead]| {
            worked_first(beads)
                .iter()
                .map(|bead| bead.bead.clone())
                .collect::<Vec<_>>()
        };
        let served = [
            bead("a", false),
            bead("b", true),
            bead("c", false),
            bead("d", true),
        ];
        assert_eq!(order(&served), ["b", "d", "a", "c"]);
        // The worked bead listed last comes first.
        assert_eq!(order(&[bead("a", false), bead("b", true)]), ["b", "a"]);
        assert_eq!(order(&[bead("a", false), bead("c", false)]), ["a", "c"]);
        assert_eq!(order(&[bead("b", true), bead("d", true)]), ["b", "d"]);
        assert!(order(&[]).is_empty());
    }

    /// A cell's "+N" says what it hides where any of it is worked: the
    /// worked and the waiting apart, the waiting left out where none
    /// waits. Where none of it is worked it is the number alone.
    #[test]
    fn a_cell_s_more_says_what_it_hides_where_any_of_it_is_worked() {
        let hidden = |worked: usize, waiting: usize| -> Vec<String> {
            let beads: Vec<FlowBead> = (0..worked + waiting)
                .map(|n| FlowBead {
                    working: n < worked,
                    ..FlowBead::default()
                })
                .collect();
            more_words(&beads.iter().collect::<Vec<_>>())
        };
        assert_eq!(hidden(0, 1), ["+1"]);
        assert_eq!(hidden(0, 3), ["+3"]);
        assert_eq!(hidden(1, 2), ["+1 working", "2 waiting"]);
        assert_eq!(hidden(2, 0), ["+2 working"]);
        assert_eq!(hidden(1, 0), ["+1 working"]);
        assert_eq!(hidden(3, 1), ["+3 working", "1 waiting"]);
    }

    /// A line's head counts what is worked and what waits on its stages
    /// but the backlog's, and the backlog; its lamp is the worst of those
    /// stages': fault over turn over moving, and none where nothing stands.
    /// The backlog's own lamp burns nowhere, since the panel draws it as a
    /// count.
    #[test]
    fn a_line_s_head_counts_what_is_worked_what_waits_and_the_backlog() {
        let stage = |name: &str, lamp: &str, worked: usize, waiting: usize| FlowStage {
            stage: name.to_string(),
            lamp: lamp.to_string(),
            beads: (0..worked + waiting)
                .map(|n| FlowBead {
                    working: n < worked,
                    ..FlowBead::default()
                })
                .collect(),
            ..FlowStage::default()
        };
        let flow = |stages: Vec<FlowStage>| Flow {
            stages,
            ..Flow::default()
        };
        let moving = flow(vec![
            stage("backlog", "turn", 0, 2),
            stage("new", "none", 2, 2),
            stage("review", "none", 0, 1),
            stage("approved", "none", 0, 0),
        ]);
        assert_eq!(
            line_counts(&moving),
            LineCounts {
                working: 2,
                waiting: 3,
                backlog: 2,
                lamp: "moving"
            }
        );
        // A stage that burns fault or turn outranks one that moves, and
        // fault outranks turn.
        let lamp = |stages: Vec<FlowStage>| line_counts(&flow(stages)).lamp;
        assert_eq!(
            lamp(vec![
                stage("new", "none", 1, 0),
                stage("review", "turn", 0, 1)
            ]),
            "turn"
        );
        assert_eq!(
            lamp(vec![
                stage("new", "none", 1, 0),
                stage("review", "turn", 0, 1),
                stage("approved", "fault", 0, 1),
            ]),
            "fault"
        );
        // Waiting beads alone light nothing, and an empty line says none.
        assert_eq!(lamp(vec![stage("new", "none", 0, 3)]), "none");
        assert_eq!(
            line_counts(&flow(vec![stage("backlog", "turn", 0, 1)])),
            LineCounts {
                working: 0,
                waiting: 0,
                backlog: 1,
                lamp: "none"
            }
        );
        assert_eq!(line_counts(&Flow::default()).lamp, "none");
    }

    /// A headcode reads its marker: working in the text colour,
    /// stalled in red, a held bead in red only where the reader holds
    /// it, a wait on the reader in rust, and a hold by anyone else or
    /// no one known, blocked, late or plain in the text colour.
    /// Working stands first, whatever else the bead carries.
    #[test]
    fn headcodes_mark_working_held_and_waiting() {
        let palette = Palette::of(Look::Dark, WindowAppearance::Dark);
        assert_eq!(
            headcode_color(true, "held by jo", "red", "jo", "jo", palette),
            palette.text
        );
        assert_eq!(
            headcode_color(true, "waits for jo", "amber", "", "jo", palette),
            palette.text
        );
        assert_eq!(
            headcode_color(false, "held by jo", "red", "jo", "jo", palette),
            palette.warn
        );
        assert_eq!(
            headcode_color(false, "held by jo", "none", "jo", "jo", palette),
            palette.warn
        );
        assert_eq!(
            headcode_color(false, "stalled · session failed", "red", "", "jo", palette),
            palette.warn
        );
        assert_eq!(
            headcode_color(false, "held by ada", "red", "ada", "jo", palette),
            palette.text
        );
        assert_eq!(
            headcode_color(false, "held", "red", "", "jo", palette),
            palette.text
        );
        assert_eq!(
            headcode_color(false, "waits for jo", "amber", "", "jo", palette),
            palette.text_accent
        );
        assert_eq!(
            headcode_color(false, "waits for jo", "amber", "", "ada", palette),
            palette.text
        );
        assert_eq!(
            headcode_color(false, "blocked by yd-x", "amber", "", "jo", palette),
            palette.text
        );
        assert_eq!(
            headcode_color(false, "late by 40m", "amber", "", "jo", palette),
            palette.text
        );
        assert_eq!(
            headcode_color(false, "", "none", "", "jo", palette),
            palette.text
        );
    }

    /// The panel's Quiet names its lines, folded or open, with nothing
    /// in transit under them. The bead's back link names where it came
    /// from: the panel or departures, the line, or No line.
    #[test]
    fn the_panel_s_quiet_and_the_bead_s_back_link_name_where() {
        assert_eq!(
            panel_quiet_head(false, &["drafts"]),
            "▸ Quiet · drafts · nothing in transit"
        );
        assert_eq!(
            panel_quiet_head(true, &["drafts", "signalbox"]),
            "▾ Quiet · drafts, signalbox · nothing in transit"
        );
        assert_eq!(bead_back_name(&Selected::Arrivals, false), "panel");
        assert_eq!(bead_back_name(&Selected::Arrivals, true), "departures");
        assert_eq!(
            bead_back_name(&Selected::Line("yardr".into()), false),
            "yardr"
        );
        assert_eq!(bead_back_name(&Selected::NoLine, false), "no line");
    }

    /// The cheatsheet names every key of the open view: the view's own
    /// keys first, then the window's, which answer everywhere. `?`
    /// itself is named where it is bound, and nowhere a line takes it
    /// as text.
    #[test]
    fn the_cheatsheet_names_every_key_of_the_open_view() {
        let rows = |view: KeysView| {
            keys_for(view, false)
                .into_iter()
                .map(|(key, _)| key)
                .collect::<Vec<_>>()
        };
        let window = [
            format!("{SECONDARY}+[ · {SECONDARY}+]"),
            format!("{SECONDARY}+y"),
            format!("{SECONDARY}+1–9"),
            format!("{SECONDARY}+,"),
            format!("{SECONDARY}+= · {SECONDARY}+- · {SECONDARY}+0"),
            format!("{SECONDARY}+shift+l"),
        ];
        for view in [
            KeysView::Switcher,
            KeysView::Settings,
            KeysView::Conversation,
            KeysView::Card,
            KeysView::Waiting,
            KeysView::Moves,
            KeysView::Grants,
            KeysView::Yard,
            KeysView::Timetable,
            KeysView::Away,
        ] {
            let shown = rows(view);
            assert_eq!(&shown[shown.len() - window.len()..], &window, "{view:?}");
        }
        assert!(rows(KeysView::Card).contains(&"d".to_string()));
        assert!(rows(KeysView::Card).contains(&"?".to_string()));
        // A parked bead's card picks moves and types a note, and puts
        // nothing aside, declines nothing and asks nothing.
        for key in ["1–9", "enter", "i", "?"] {
            assert!(rows(KeysView::Waiting).contains(&key.to_string()), "{key}");
        }
        for key in ["x", "d", "a", "e"] {
            assert!(!rows(KeysView::Waiting).contains(&key.to_string()), "{key}");
        }
        // The same keys on the Lines details of a parked bead, which have no
        // decisions' history to filter.
        for key in ["1–9", "enter", "i", "esc", "?"] {
            assert!(rows(KeysView::Moves).contains(&key.to_string()), "{key}");
        }
        for key in ["x", "d", "a", "e", "/"] {
            assert!(!rows(KeysView::Moves).contains(&key.to_string()), "{key}");
        }
        assert!(rows(KeysView::Grants).contains(&"?".to_string()));
        assert!(!rows(KeysView::Grants).contains(&"d".to_string()));
        assert!(!rows(KeysView::Grants).contains(&"enter".to_string()));
        assert!(rows(KeysView::Switcher).contains(&"?".to_string()));
        assert!(rows(KeysView::Switcher).contains(&"+".to_string()));
        assert!(rows(KeysView::Yard).contains(&"shift+x".to_string()));
        assert!(rows(KeysView::Conversation).contains(&"shift+enter".to_string()));
        assert!(rows(KeysView::Card).contains(&"shift+enter".to_string()));
        let oldest_newest = format!("{SECONDARY}+home · {SECONDARY}+end");
        assert!(rows(KeysView::Card).contains(&oldest_newest));
        assert!(rows(KeysView::Yard).contains(&oldest_newest));
        assert!(!rows(KeysView::Conversation).contains(&"?".to_string()));
        assert!(!rows(KeysView::Settings).contains(&"?".to_string()));
    }

    /// `?` opens the cheatsheet of the open card's keys; esc and `?`
    /// again shut it, the hint opens it with a click, and in the
    /// switcher it names the switcher's keys.
    #[gpui::test]
    fn question_opens_the_cheatsheet_and_esc_shuts_it(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_three());
        yard.answer("Bead", &bead_three());
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-a".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-a"));
        // The line starts focused, so esc holds the window's keys
        // first; then `?` opens the card's list, with its hint on
        // the card.
        cx.simulate_keystrokes("escape");
        assert!(drawn(cx, "keys hint card"));
        assert!(!view.read_with(cx, |v, _| v.show_keys));
        cx.simulate_keystrokes("?");
        wait(cx, "the cheatsheet", |cx| {
            drawn(cx, "keys") && view.read_with(cx, |v, _| v.show_keys)
        });
        assert!(drawn(cx, "keys row d"));
        // `?` again shuts it, and so does esc.
        cx.simulate_keystrokes("?");
        wait(cx, "the cheatsheet shut", |cx| {
            !view.read_with(cx, |v, _| v.show_keys)
        });
        cx.simulate_keystrokes("?");
        wait(cx, "the cheatsheet", |cx| {
            view.read_with(cx, |v, _| v.show_keys)
        });
        cx.simulate_keystrokes("escape");
        wait(cx, "the cheatsheet shut", |cx| {
            !view.read_with(cx, |v, _| v.show_keys)
        });
        // The hint opens it with a click.
        click_on(cx, "keys hint card");
        wait(cx, "the cheatsheet", |cx| {
            view.read_with(cx, |v, _| v.show_keys)
        });
        cx.simulate_keystrokes("escape");
        // A click outside shuts it and reaches nothing under it: the
        // rail's chip under the click opens no switcher.
        click_on(cx, "keys hint card");
        wait(cx, "the cheatsheet", |cx| {
            view.read_with(cx, |v, _| v.show_keys)
        });
        click_on(cx, "yard chip");
        assert!(!view.read_with(cx, |v, _| v.show_keys));
        assert_eq!(switching(&view, cx), None);
        // In the switcher it names the switcher's keys.
        cx.simulate_keystrokes("secondary-y");
        wait(cx, "the switcher", |cx| drawn(cx, "switcher"));
        cx.simulate_keystrokes("?");
        wait(cx, "the cheatsheet", |cx| {
            drawn(cx, "keys") && view.read_with(cx, |v, _| v.show_keys)
        });
        assert!(drawn(cx, "keys row +"));
        assert_eq!(view.read_with(cx, |v, _| v.keys_view()), KeysView::Switcher);
        // It stands over the list: a click on it, outside the list, shuts
        // the cheatsheet and not the list, as esc does.
        let keys = bounds_of(cx, "keys");
        cx.simulate_click(
            gpui::point(keys.right() - px(4.), keys.bottom() - px(4.)),
            gpui::Modifiers::default(),
        );
        assert!(!view.read_with(cx, |v, _| v.show_keys));
        assert!(switching(&view, cx).is_some());
        cx.simulate_keystrokes("escape");
        assert_eq!(switching(&view, cx), None);
    }

    /// The About card names this footplate and the yardr on this machine, which
    /// is asked its version each time the card opens, and two doors open
    /// it: the application menu's action, and the row of the settings'
    /// first section. Esc and its button shut it, a click outside shuts it
    /// and goes no further, a click inside leaves it, and the cheatsheet
    /// stands over it, shut first.
    #[cfg(unix)]
    #[gpui::test]
    fn the_about_card_names_both_versions_and_two_doors_open_it(cx: &mut TestAppContext) {
        let home = tempfile::tempdir().unwrap();
        let bin = home.path().join(".local/bin");
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        // What the card holds of the yardr: none while it stands shut,
        // and nothing yet while the program is being asked.
        let kept_of = |view: &Entity<Footplate>, cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| v.about.as_ref().map(|about| about.seen.clone()))
        };
        // The card asks this test's home, not the person's.
        let says = |line: &str| Seen::Says {
            line: line.to_string(),
            path: bin.join("yardr"),
        };
        view.update(cx, |v, _| {
            v.means.machine = Machine {
                home: Some(home.path().to_path_buf()),
                ..Machine::default()
            }
        });
        assert!(!drawn(cx, "about"));

        // The application menu's door, with no yardr there. A second use
        // of it leaves the card as it is.
        cx.dispatch_action(OpenAbout);
        wait(cx, "the card, told that there is none", |cx| {
            kept_of(&view, cx) == Some(Some(Seen::Nothing))
        });
        assert!(drawn(cx, "about card"));
        assert!(drawn(cx, "about footplate"));
        assert!(drawn(cx, "about yardr"));
        cx.dispatch_action(OpenAbout);
        assert!(!drawn(cx, "about yardr path"));
        assert_eq!(kept_of(&view, cx), Some(Some(Seen::Nothing)));
        cx.simulate_keystrokes("escape");
        assert_eq!(kept_of(&view, cx), None);

        // A yardr is there now, and says which it is, each time: it is
        // asked again as the card opens, not once.
        fetch::keep(
            &bin,
            "yardr",
            b"#!/bin/sh\ncat \"$(dirname \"$0\")/says\"\n",
        )
        .unwrap();
        std::fs::write(bin.join("says"), "v0.14.0 (cbceebd22919)\n").unwrap();
        // Start it once and let it end before the card asks it. The system
        // assesses a program the first time it starts: a second or two on
        // a busy Mac, 5 s and more while other programs are being started
        // for the first time too, and the card stops a start at 5 s
        // (`Machine::seen`). Not through `seen` here either: the assessment
        // goes on after a stop, and the first ask would pay what is left
        // of it. The program is not rewritten below, only `says`: a
        // rewritten program is assessed again, a rewritten data file is not.
        // Its answer is dropped: the harness does not catch a child's output.
        let _ = std::process::Command::new(bin.join("yardr"))
            .arg("--version")
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .status();
        cx.dispatch_action(OpenAbout);
        wait(cx, "the card, told which yardr is there", |cx| {
            kept_of(&view, cx) == Some(Some(says("v0.14.0 (cbceebd22919)")))
        });
        assert!(drawn(cx, "about yardr path"));
        cx.simulate_keystrokes("escape");
        std::fs::write(bin.join("says"), "v0.15.0 (0123456789ab)\n").unwrap();
        cx.dispatch_action(OpenAbout);
        wait(cx, "the card, told which yardr is there now", |cx| {
            kept_of(&view, cx) == Some(Some(says("v0.15.0 (0123456789ab)")))
        });

        // A click inside leaves the card. A click outside shuts it, and
        // does not reach the rail's chip under it, which opens the
        // switcher.
        click_on(cx, "about yardr");
        assert!(drawn(cx, "about card"));
        click_on(cx, "yard chip");
        assert_eq!(kept_of(&view, cx), None);
        assert!(
            view.read_with(cx, |v, _| v.switching.is_none()),
            "the click went through the card's overlay"
        );

        // Its button shuts it.
        cx.dispatch_action(OpenAbout);
        assert!(drawn(cx, "about close"));
        click_on(cx, "about close");
        assert_eq!(kept_of(&view, cx), None);

        // The settings' door: the row of their first section, over the
        // sheet. Esc shuts the card first, and the sheet after it.
        cx.simulate_keystrokes("secondary-,");
        assert!(settings_open(&view, cx));
        click_on(cx, "about show");
        assert!(drawn(cx, "about card"));
        assert!(settings_open(&view, cx));
        cx.simulate_keystrokes("escape");
        assert_eq!(kept_of(&view, cx), None);
        assert!(settings_open(&view, cx));
        cx.simulate_keystrokes("escape");
        assert!(!settings_open(&view, cx));

        // The cheatsheet over the card goes first.
        cx.dispatch_action(OpenAbout);
        view.update(cx, |v, cx| v.toggle_keys(cx));
        cx.simulate_keystrokes("escape");
        assert!(!view.read_with(cx, |v, _| v.show_keys));
        assert!(kept_of(&view, cx).is_some());
        cx.simulate_keystrokes("escape");
        assert_eq!(kept_of(&view, cx), None);
    }

    /// The project a test sends feedback to: the stand-in's, with a key and
    /// a survey that are none of the real ones.
    fn feedback_to(posthog: &Posthog) -> Option<crate::feedback::Project> {
        crate::feedback::Project::at(posthog.address(), "phc_test_key", "survey-test")
    }

    /// What the Feedback form holds: the message and the email as typed, and
    /// what it says of the last send.
    fn form_of(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Option<(String, String, Option<String>)> {
        view.read_with(cx, |v, cx| {
            v.feedback.as_ref().map(|form| {
                (
                    form.message.read(cx).text().to_string(),
                    form.email.read(cx).text().to_string(),
                    form.said.clone(),
                )
            })
        })
    }

    /// Which of the form's fields has the keys: the message, the email, or
    /// neither.
    fn form_focus(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> &'static str {
        cx.update(|window, cx| {
            let form = view.read(cx).feedback.as_ref().expect("the form is open");
            match (
                form.message.focus_handle(cx).is_focused(window),
                form.email.focus_handle(cx).is_focused(window),
            ) {
                (true, _) => "message",
                (_, true) => "email",
                _ => "neither",
            }
        })
    }

    /// The Feedback button stands in the rail's foot only where there is a
    /// project to send to, and opens the form over the window, the keys in
    /// its message: the form says plainly what it sends, takes a message and
    /// an email, and Enter sends the one request, with exactly what is
    /// typed. It says thanks in place of its fields, and nothing of it is
    /// kept: esc shuts it, and the next one stands empty, and sends under an
    /// id of its own.
    #[gpui::test]
    fn the_feedback_form_sends_what_is_typed_and_says_thanks(cx: &mut TestAppContext) {
        let posthog = Posthog::start();
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);

        // A test offers none unless it stands one in, as no build does
        // while the survey's id is none: no button, and no form.
        assert!(!drawn(cx, "feedback tile"));
        view.update(cx, |v, _| v.means.feedback = feedback_to(&posthog));
        assert!(drawn(cx, "feedback tile"));

        click_on(cx, "feedback tile");
        for drawn_now in [
            "feedback card",
            "feedback message",
            "feedback email",
            "feedback plain",
            "feedback cancel",
            "feedback send",
        ] {
            assert!(drawn(cx, drawn_now), "{drawn_now}");
        }
        assert!(!drawn(cx, "feedback thanks"));
        assert_eq!(form_focus(&view, cx), "message");

        // Nothing goes while the message is blank: Enter says so.
        cx.simulate_keystrokes("enter");
        assert!(drawn(cx, "feedback said"));
        assert!(posthog.sent().is_empty());

        // Tab and shift+Tab move between the two fields and step nothing
        // behind the form.
        let open_row = view.read_with(cx, |v, _| v.model.as_ref().unwrap().selected().cloned());
        cx.simulate_input("The rail hides my longest depot name.");
        cx.simulate_keystrokes("tab");
        assert_eq!(form_focus(&view, cx), "email");
        cx.simulate_input("ada@example.com");
        cx.simulate_keystrokes("shift-tab");
        assert_eq!(form_focus(&view, cx), "message");
        assert_eq!(
            view.read_with(cx, |v, _| v.model.as_ref().unwrap().selected().cloned()),
            open_row
        );
        assert_eq!(
            form_of(&view, cx),
            Some((
                "The rail hides my longest depot name.".into(),
                "ada@example.com".into(),
                None
            ))
        );

        let form_card = bounds_of(cx, "feedback card");
        cx.simulate_keystrokes("enter");
        wait(cx, "the capture has it", |_| posthog.sent().len() == 1);
        wait(cx, "the thanks", |cx| drawn(cx, "feedback thanks"));
        // Exactly the survey's answer: no other property, and no other call
        // went anywhere.
        let body: Value = serde_json::from_str(&posthog.sent()[0].1).unwrap();
        let id = body["distinct_id"].as_str().unwrap().to_string();
        assert_eq!(
            body,
            json!({
                "api_key": "phc_test_key",
                "event": "survey sent",
                "distinct_id": id,
                "properties": {
                    "$survey_id": "survey-test",
                    "$survey_response": "The rail hides my longest depot name.",
                    "footplate_version": env!("CARGO_PKG_VERSION"),
                    "os": std::env::consts::OS,
                    "email": "ada@example.com",
                },
            })
        );
        // The thanks stand where the fields did, which are no longer
        // drawn: the card is the height of its head, its line and Close.
        // (A frame keeps the bounds of what it drew once, so what is gone
        // is told by the card's height and not by what is drawn.) What was
        // typed is gone from the fields.
        assert!(view.read_with(cx, |v, _| v.feedback.as_ref().is_some_and(|form| form.sent)));
        assert!(drawn(cx, "feedback close"));
        let thanks_card = bounds_of(cx, "feedback card");
        assert!(
            thanks_card.size.height * 2. < form_card.size.height,
            "the fields stand under the thanks: {thanks_card:?} {form_card:?}"
        );
        assert_eq!(
            form_of(&view, cx),
            Some((String::new(), String::new(), None))
        );
        // Esc is the window's with the fields gone, and shuts the form.
        cx.simulate_keystrokes("escape");
        assert_eq!(form_of(&view, cx), None);

        // The next form stands empty, and its message goes under an id of
        // its own, with no email property where none was given.
        click_on(cx, "feedback tile");
        assert_eq!(
            form_of(&view, cx),
            Some((String::new(), String::new(), None))
        );
        cx.simulate_input("Dark mode, please.");
        click_on(cx, "feedback send");
        wait(cx, "the second one", |_| posthog.sent().len() == 2);
        wait(cx, "the second thanks", |cx| drawn(cx, "feedback thanks"));
        let second: Value = serde_json::from_str(&posthog.sent()[1].1).unwrap();
        assert_ne!(second["distinct_id"], body["distinct_id"]);
        assert_eq!(
            second["properties"]["$survey_response"],
            "Dark mode, please."
        );
        assert!(second["properties"].get("email").is_none());
        // Close shuts it.
        click_on(cx, "feedback close");
        assert_eq!(form_of(&view, cx), None);

        // Cancel and a click outside shut a form with its words, which are
        // kept nowhere; a send goes once, however many times Enter is
        // pressed before its answer.
        click_on(cx, "feedback tile");
        cx.simulate_input("Not this.");
        click_on(cx, "feedback cancel");
        assert_eq!(form_of(&view, cx), None);
        click_on(cx, "feedback tile");
        assert_eq!(
            form_of(&view, cx),
            Some((String::new(), String::new(), None))
        );
        let card = bounds_of(cx, "feedback card");
        cx.simulate_click(
            gpui::point(card.left() - px(4.), card.top() - px(4.)),
            gpui::Modifiers::default(),
        );
        assert_eq!(form_of(&view, cx), None);
        click_on(cx, "feedback tile");
        cx.simulate_input("Once.");
        view.update(cx, |v, cx| {
            v.send_feedback(cx);
            v.send_feedback(cx);
        });
        wait(cx, "the third one", |_| posthog.sent().len() == 3);
        wait(cx, "the third thanks", |cx| drawn(cx, "feedback thanks"));
        assert_eq!(posthog.sent().len(), 3);
    }

    /// A message PostHog does not take stays in the form, with the email,
    /// and the form says it could not be sent and to try again; Send is
    /// there again, and the same words go when it is pressed. A send is
    /// never made again by itself.
    #[gpui::test]
    fn a_feedback_that_did_not_go_keeps_what_was_typed_and_says_so(cx: &mut TestAppContext) {
        let posthog = Posthog::start();
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        view.update(cx, |v, _| v.means.feedback = feedback_to(&posthog));
        click_on(cx, "feedback tile");
        cx.simulate_input("Wrap the depot names.");
        cx.simulate_keystrokes("tab");
        cx.simulate_input("ada@example.com");

        posthog.answer(503);
        click_on(cx, "feedback send");
        wait(cx, "what the form says", |cx| drawn(cx, "feedback said"));
        assert_eq!(
            form_of(&view, cx),
            Some((
                "Wrap the depot names.".into(),
                "ada@example.com".into(),
                Some(
                    "It could not be sent: PostHog answered 503. What you wrote is still here; try again."
                        .into()
                )
            ))
        );
        // The form stands as it was: fields, Send, and the keys where they
        // were. Nothing is sent again by itself.
        assert!(drawn(cx, "feedback message") && drawn(cx, "feedback send"));
        assert!(!drawn(cx, "feedback thanks"));
        assert_eq!(form_focus(&view, cx), "email");
        std::thread::sleep(Duration::from_millis(100));
        cx.run_until_parked();
        assert_eq!(posthog.sent().len(), 1);

        // Where nothing answers at all, that is said as well, with the
        // fields as they were.
        let gone = Posthog::start();
        view.update(cx, |v, _| v.means.feedback = feedback_to(&gone));
        gone.stop();
        click_on(cx, "feedback send");
        wait(cx, "what the form says of the lost address", |cx| {
            form_of(&view, cx)
                .and_then(|(_, _, said)| said)
                .is_some_and(|said| {
                    said.starts_with("It could not be sent: PostHog does not answer (")
                })
        });
        assert_eq!(form_of(&view, cx).unwrap().0, "Wrap the depot names.");

        // PostHog takes it the next time, and the words are the same.
        view.update(cx, |v, _| v.means.feedback = feedback_to(&posthog));
        posthog.answer(200);
        click_on(cx, "feedback send");
        wait(cx, "the thanks", |cx| drawn(cx, "feedback thanks"));
        let sent = posthog.sent();
        assert_eq!(sent.len(), 2);
        for (_, body) in &sent {
            let body: Value = serde_json::from_str(body).unwrap();
            assert_eq!(
                body["properties"]["$survey_response"],
                "Wrap the depot names."
            );
            assert_eq!(body["properties"]["email"], "ada@example.com");
        }
    }

    /// While the form stands, what is typed is its field's: a card behind it
    /// keeps its pick and its keys (a number, `d`, `x`, `?`, the arrows are
    /// letters and rows of the message), and Tab steps no row.
    #[gpui::test]
    fn the_feedback_form_takes_every_key_a_card_behind_it_has(cx: &mut TestAppContext) {
        let posthog = Posthog::start();
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("UserAsks", &asks_three());
        yard.answer("Bead", &bead_three());
        yard.answer("AnswerAsk", "{}");
        yard.answer("DeclineAsk", "{}");
        cx.update(|cx| {
            input::bind_keys(cx);
            bind_keys(cx);
        });
        let (view, cx) = cx.add_window_view(|window, cx| {
            let view = Footplate::new(yard.client(), "jo".into(), window, cx);
            window.focus(&view.line.focus_handle(cx));
            view
        });
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-a".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-a"));
        let (ask, chosen) = (current_ask_of(&view, cx), chosen_of(&view, cx, "bead-a", 3));
        view.update(cx, |v, _| v.means.feedback = feedback_to(&posthog));

        click_on(cx, "feedback tile");
        assert_eq!(form_focus(&view, cx), "message");
        cx.simulate_input("2d x? ia/e 1");
        cx.simulate_keystrokes("up down up");
        cx.simulate_keystrokes("tab");
        assert_eq!(form_focus(&view, cx), "email");
        cx.simulate_keystrokes("tab");
        assert_eq!(form_focus(&view, cx), "message");
        assert_eq!(form_of(&view, cx).unwrap().0, "2d x? ia/e 1");
        // The card is as it was: its ask, its pick, its answer unsent, no
        // cheatsheet over it.
        assert_eq!(current_ask_of(&view, cx), ask);
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), chosen);
        assert!(!view.read_with(cx, |v, _| v.show_keys));
        assert_eq!(
            view.read_with(cx, |v, _| v.model.as_ref().unwrap().selected().cloned()),
            Some(Selected::Decision("bead-a".into()))
        );
        assert_eq!(
            yard.asked("AnswerAsk").len() + yard.asked("DeclineAsk").len(),
            0
        );
        assert!(posthog.sent().is_empty());

        // Esc shuts the form, and the card has its keys again: a number
        // picks.
        cx.simulate_keystrokes("escape");
        assert_eq!(form_of(&view, cx), None);
        cx.simulate_keystrokes("2");
        assert_eq!(chosen_of(&view, cx, "bead-a", 3), 2);
    }

    /// With feedback offered, the foot of the rail holds Feedback above the
    /// gear, a label and no glyph, and still fits the narrowest window the
    /// application opens under the traffic lights of a Mac, 360 pixels
    /// high; and with none offered the foot is the gear alone.
    #[gpui::test]
    fn the_rail_s_foot_holds_feedback_above_the_gear_and_fits_the_narrowest_window(
        cx: &mut TestAppContext,
    ) {
        let posthog = Posthog::start();
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        let (strip, _) = strip_stand_in();
        view.update(cx, |v, _| v.means.titlebar = Some(strip));
        cx.simulate_resize(gpui::size(px(WINDOW_MIN), px(360.)));
        assert!(!drawn(cx, "feedback tile"));
        let gear_alone = bounds_of(cx, "settings");

        view.update(cx, |v, _| v.means.feedback = feedback_to(&posthog));
        let (timetable, tile, label, gear) = (
            bounds_of(cx, "rail timetable"),
            bounds_of(cx, "feedback tile"),
            bounds_of(cx, "feedback tile label"),
            bounds_of(cx, "settings"),
        );
        let rail = bounds_of(cx, "rail");
        assert!(
            (tile.size.width - px(52.)).abs() < px(1.),
            "the tile is {tile:?}, not 52 wide like the others"
        );
        assert!(
            timetable.bottom() <= tile.top() && tile.bottom() <= gear.top() + px(1.),
            "the foot is out of order: {timetable:?} {tile:?} {gear:?}"
        );
        assert!(
            tile.left() <= label.left() && label.right() <= tile.right() + px(1.),
            "the label leaves its tile: {label:?} {tile:?}"
        );
        assert!(
            rail.left() <= tile.left() && tile.right() <= rail.right() + px(1.),
            "the tile leaves the rail: {tile:?} {rail:?}"
        );
        // The gear has not moved for the tile above it, and the whole foot
        // is inside the window, which is 360 high.
        assert_eq!(gear.bottom(), gear_alone.bottom());
        assert!(
            gear.bottom() <= px(360.),
            "the gear is {gear:?}: under the window's foot"
        );
    }

    /// The About card's words: this footplate as a release's tag, which a
    /// tag parses as, and the yardr's line as it says itself, or that it is
    /// being asked, not installed, or silent, with where it is.
    #[test]
    fn the_about_card_says_what_it_knows_of_each_version() {
        let tag = footplate_words();
        assert!(tag.starts_with('v'), "{tag}");
        assert_eq!(tag, format!("v{}", env!("CARGO_PKG_VERSION")));
        assert_eq!(yardr_words(None), "reading…");
        assert_eq!(yardr_words(Some(&Seen::Nothing)), "not installed");
        assert_eq!(yardr_place(Some(&Seen::Nothing)), None);
        let path = PathBuf::from("/home/jo/.local/bin/yardr");
        let says = Seen::Says {
            line: "v0.14.0 (cbceebd22919)".into(),
            path: path.clone(),
        };
        assert_eq!(yardr_words(Some(&says)), "v0.14.0 (cbceebd22919)");
        assert_eq!(
            yardr_place(Some(&says)).as_deref(),
            Some("/home/jo/.local/bin/yardr")
        );
        let silent = Seen::Silent {
            why: "ended with status 3".into(),
            path,
        };
        assert_eq!(
            yardr_words(Some(&silent)),
            "could not say its version (ended with status 3)"
        );
        assert!(yardr_place(Some(&silent)).is_some());
    }

    /// A late overrun stands as words in the remark column: `late by
    /// 40m` where the yard prints it, last in the row, and the expected
    /// arrival alone in its own column.
    #[gpui::test]
    fn a_late_overrun_stands_as_words_in_the_remark_column(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_overrun());
        yard.answer("Flows", &flows_board());
        let (_view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&_view, cx);
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        assert!(drawn(cx, "arrival remark yd-zulu"));
        let expected = bounds_of(cx, "arrival expected yd-zulu");
        let remark = bounds_of(cx, "arrival remark yd-zulu");
        assert!(
            expected.right() <= remark.left(),
            "the overrun stands off the remark column: {expected:?} {remark:?}"
        );
        assert!(
            remark.top() <= expected.bottom() && expected.top() <= remark.bottom(),
            "the overrun stands off the row: {expected:?} {remark:?}"
        );
    }

    /// The quiet lines fold under Quiet with their count: folded the
    /// active lines alone stand, unfolded the quiet ones stand under
    /// the fold, and exactly one row of the list ever stands open. A
    /// quiet line opens from under the fold, and folding again takes
    /// its row away: a click where it stood opens nothing.
    #[gpui::test]
    fn the_quiet_lines_fold_under_quiet(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_quiet());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row arrivals"));
        assert!(drawn(cx, "row yardr"));
        assert!(!drawn(cx, "row drafts"));
        assert!(drawn(cx, "quiet"));
        let selected = |view: &Entity<Footplate>, cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| {
                let model = v.model.as_ref().unwrap();
                [model.arrivals_row()]
                    .into_iter()
                    .chain(model.active_line_rows())
                    .chain(model.quiet_rows())
                    .chain(model.no_line_row())
                    .filter(|row| row.selected)
                    .count()
            })
        };
        assert_eq!(selected(&view, cx), 1);
        click_on(cx, "quiet");
        wait(cx, "the quiet lines", |cx| drawn(cx, "row drafts"));
        assert_eq!(selected(&view, cx), 1);
        click_on(cx, "row drafts");
        wait(cx, "the drafts line", |cx| drawn(cx, "flow head drafts"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::Line("drafts".into()))
            );
        });
        assert_eq!(selected(&view, cx), 1);
        // Folded again the row is gone: gpui's test bounds keep what
        // was ever drawn, so the proof is a click where the row stood,
        // which opens nothing.
        let stood = bounds_of(cx, "row drafts").center();
        click_on(cx, "quiet");
        wait(cx, "the fold again", |cx| {
            view.read_with(cx, |v, _| !v.model.as_ref().unwrap().quiet_expanded())
        });
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        cx.simulate_click(stood, gpui::Modifiers::default());
        cx.run_until_parked();
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::Arrivals)
            );
        });
        assert_eq!(selected(&view, cx), 1);
    }

    /// A board row's click opens the bead's details: the title, id,
    /// platform and line, the expected arrival and remark of its row,
    /// the labels, the body, then the notes newest last with their
    /// author and time. Its asks are one line that links nothing, and a
    /// quiet departures link leads back to the board.
    #[gpui::test]
    fn a_board_row_s_click_opens_the_bead_s_details(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_board());
        yard.answer("Bead", &bead_zulu());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        // The bead from the Bead call, through a row's click.
        click_on(cx, "arrival yd-zulu");
        wait(cx, "the bead", |cx| drawn(cx, "bead back"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.selected(), Some(&Selected::Bead("yd-zulu".into())));
            assert!(model.arrivals_row().selected);
            let detail = model.arrival_detail("yd-zulu").unwrap();
            assert_eq!(detail.title, "Zulu's late turn");
            assert_eq!(detail.stage, "draft");
            assert_eq!(detail.line, "yardr");
            assert_eq!(detail.expected, "5h–8h");
            assert_eq!(detail.remark, "late");
            assert_eq!(detail.labels, ["size:medium", "eyes"]);
            assert_eq!(detail.body, "The turn the yard waits on.");
            assert_eq!(
                detail
                    .notes
                    .iter()
                    .map(|n| (n.author.as_str(), n.at.as_str()))
                    .collect::<Vec<_>>(),
                [
                    ("assembly", "2026-10-10T10:30:00Z"),
                    ("yardmaster", "2026-10-10T11:30:00Z"),
                ]
            );
            assert_eq!(detail.open_asks, 2);
        });
        assert!(drawn(cx, "bead title yd-zulu"));
        assert!(drawn(cx, "bead sub yd-zulu"));
        assert!(drawn(cx, "bead remark yd-zulu"));
        assert!(drawn(cx, "bead labels yd-zulu"));
        assert!(drawn(cx, "bead asks yd-zulu"));
        // No session works it, so no worked-by line stands under the id.
        assert!(!drawn(cx, "bead worker yd-zulu"));
        // The asks line links nothing: a click leaves the bead open.
        click_on(cx, "bead asks yd-zulu");
        cx.run_until_parked();
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::Bead("yd-zulu".into()))
            );
        });
        // And back to the board on the arrivals link.
        click_on(cx, "bead back");
        wait(cx, "the board again", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().unwrap().selected() == Some(&Selected::Arrivals)
            })
        });
    }

    /// A bead's details carry its route as a strip under the id line:
    /// one stop per stage of its served flow, with the bead's own among
    /// them. A bead in no served stage carries no strip.
    #[gpui::test]
    fn a_bead_s_details_carry_its_route_as_a_strip(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_board());
        yard.answer("Bead", &bead_zulu());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        click_on(cx, "arrival yd-zulu");
        wait(cx, "the bead", |cx| drawn(cx, "bead back"));
        assert!(drawn(cx, "bead strip yd-zulu"));
        assert!(drawn(cx, "bead stop yd-zulu new"));
        assert!(drawn(cx, "bead stop yd-zulu review"));
        let sub = bounds_of(cx, "bead sub yd-zulu");
        let strip = bounds_of(cx, "bead strip yd-zulu");
        assert!(
            strip.top() >= sub.bottom() - px(1.),
            "the strip stands on the id line's row: {sub:?} {strip:?}"
        );

        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_elsewhere());
        yard.answer("Bead", &bead_shed());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row No line");
        wait(cx, "No line", |cx| drawn(cx, "no line bead yd-shed"));
        click_on(cx, "no line bead yd-shed");
        wait(cx, "the bead", |cx| drawn(cx, "bead back"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::Bead("yd-shed".into()))
            );
            assert_eq!(v.model.as_ref().unwrap().route_for("yd-shed"), None);
        });
        assert!(!drawn(cx, "bead strip yd-shed"));
    }

    /// A worked bead's details carry who works it under the id line:
    /// the session with its group, kind and model, from the bead's
    /// flows row.
    #[gpui::test]
    fn a_worked_bead_s_details_carry_who_works_it(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        let mut flows: Value = serde_json::from_str(&flows_board()).unwrap();
        flows["result"]["depots"][0]["flows"][0]["stages"][0]["beads"][0] = json!(
            {"bead": "yd-zulu", "title": "Zulu's late turn",
             "expected": "5h–8h", "remark": "late", "tone": "amber",
             "working": true, "worker": "herdr yd-zulu-new",
             "group": "muse-builders", "kind": "muse",
             "model": "muse-spark-1.3-contributor"}
        );
        yard.answer("Flows", &flows.to_string());
        yard.answer("Bead", &bead_zulu());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        to_departures(cx);
        wait(cx, "the arrivals", |cx| drawn(cx, "arrival yd-zulu"));
        click_on(cx, "arrival yd-zulu");
        wait(cx, "the bead", |cx| drawn(cx, "bead back"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            let (found, depot) = model.flow_bead("yd-zulu").unwrap();
            assert_eq!(found.worker, "herdr yd-zulu-new");
            assert_eq!(found.group, "muse-builders");
            assert_eq!(found.kind, "muse");
            assert_eq!(found.model, "muse-spark-1.3-contributor");
            assert_eq!(depot, Some("yardr"));
        });
        assert!(drawn(cx, "bead worker yd-zulu"));
        let sub = bounds_of(cx, "bead sub yd-zulu");
        let worked = bounds_of(cx, "bead worker yd-zulu");
        assert!(
            worked.top() >= sub.bottom() - px(1.),
            "the worked-by line stands under the id line: {sub:?} {worked:?}"
        );
    }

