    /// A bead's id line drops the stage where a route strip under it
    /// says where the bead stands, and keeps it where no strip does.
    #[test]
    fn a_bead_s_id_line_drops_the_stage_its_strip_says() {
        let detail = ArrivalDetail {
            bead: "yd-zulu".to_string(),
            title: "Zulu's late turn".to_string(),
            stage: "draft".to_string(),
            line: "yardr".to_string(),
            expected: "5h–8h".to_string(),
            remark: "late".to_string(),
            tone: "amber".to_string(),
            held_by: String::new(),
            labels: Vec::new(),
            body: String::new(),
            notes: Vec::new(),
            open_asks: 0,
        };
        let route = Route {
            stages: vec![
                model::RouteStage {
                    name: "new".to_string(),
                    human: false,
                },
                model::RouteStage {
                    name: "review".to_string(),
                    human: true,
                },
            ],
            current: 0,
        };
        assert_eq!(bead_sub(&detail, Some(&route)), "yd-zulu · yardr");
        assert_eq!(bead_sub(&detail, None), "yd-zulu · draft · yardr");
        let unserved = ArrivalDetail {
            line: String::new(),
            ..detail.clone()
        };
        assert_eq!(bead_sub(&unserved, None), "yd-zulu · draft");
    }

    /// The timetable's list holds the arrivals row with the yard-wide
    /// travelling total, the lines in the served order with their own,
    /// every served line travelling or not, and No line last only while
    /// beads travel with none.
    #[gpui::test]
    fn the_timetable_lists_the_lines_with_their_travelling_totals(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_board());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row arrivals"));
        assert!(drawn(cx, "row yardr"));
        assert!(drawn(cx, "row footplate"));
        assert!(!drawn(cx, "row No line"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.travelling(), 3);
            assert_eq!(model.arrivals_row().line, "3 in transit");
            assert_eq!(
                model
                    .line_rows()
                    .iter()
                    .map(|row| (row.name.clone(), row.line.clone()))
                    .collect::<Vec<_>>(),
                [
                    ("yardr".to_string(), "2 in transit".to_string()),
                    ("footplate".to_string(), "1 in transit".to_string()),
                ]
            );
            assert_eq!(model.no_line_row(), None);
        });
        // The served order from the top: the board, then the lines.
        let arrivals = bounds_of(cx, "row arrivals").top();
        let yardr = bounds_of(cx, "row yardr").top();
        let footplate = bounds_of(cx, "row footplate").top();
        assert!(
            arrivals < yardr && yardr < footplate,
            "the lines stand out of the served order: {arrivals:?} {yardr:?} {footplate:?}"
        );
    }

    /// With beads travelling with no line the No line row stands last,
    /// with how many travel; a click opens its plain list, newest change
    /// first, each row drawn as a flow's bead, with no stages or lamps.
    #[gpui::test]
    fn the_no_line_row_opens_its_plain_list(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_elsewhere());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        cx.run_until_parked();
        assert!(drawn(cx, "row No line"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.travelling(), 4);
            assert_eq!(model.no_line_row().unwrap().line, "2 in transit");
        });
        let yardr = bounds_of(cx, "row yardr").top();
        let no_line = bounds_of(cx, "row No line").top();
        assert!(yardr < no_line, "No line stands above the lines");
        click_on(cx, "row No line");
        wait(cx, "No line", |cx| drawn(cx, "no line head"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::NoLine)
            );
        });
        assert!(drawn(cx, "no line head"));
        // The served order, newest change first, with no stages or lamps.
        for bead in ["yd-bravo", "yd-shed"] {
            assert!(drawn(cx, &format!("no line bead {bead}")), "{bead}");
            assert!(drawn(cx, &format!("no line bead title {bead}")), "{bead}");
            assert!(drawn(cx, &format!("no line bead time {bead}")), "{bead}");
            assert!(drawn(cx, &format!("no line bead sub {bead}")), "{bead}");
        }
        let bravo = bounds_of(cx, "no line bead yd-bravo").top();
        let shed = bounds_of(cx, "no line bead yd-shed").top();
        assert!(bravo < shed, "No line stands out of the served order");
        assert!(!drawn(cx, "column default new"));
        assert!(!drawn(cx, "card yd-bravo"));
    }

    /// A line's click opens its flows: each flow a section with its
    /// stages in travel order as columns, each column its head with the
    /// group words and one card per bead. The backlog column lists its
    /// count, six titles and "+N more"; the terminal column reads
    /// terminal with the buffer stop and lists its landings, newest
    /// first. Tapping one opens the whole bead and back returns to the
    /// line; a flow with none draws no landing rows.
    #[gpui::test]
    fn a_line_s_click_opens_its_stages_as_columns_with_cards(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_landings());
        yard.answer("Bead", &bead_zulu());
        yard.answer_for("Bead", "bead", "yd-r9pn", &bead_landed());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row yardr");
        wait(cx, "the flow", |cx| drawn(cx, "flow head yardr"));
        view.read_with(cx, |v, _| {
            assert_eq!(
                v.model.as_ref().unwrap().selected(),
                Some(&Selected::Line("yardr".into()))
            );
        });
        assert!(drawn(cx, "flow head yardr"));
        assert!(drawn(cx, "flow default"));
        // The stages in travel order as columns, 176 pixels each.
        for stage in ["backlog", "new", "review", "decide", "siding", "merged"] {
            let column = format!("column default {stage}");
            assert!(drawn(cx, &column), "{column}");
            let column = bounds_of(cx, &column);
            assert!(
                (column.size.width - px(176.)).abs() < px(1.),
                "the column is no 176 pixels: {column:?}"
            );
        }
        let backlog = bounds_of(cx, "column default backlog").left();
        let new = bounds_of(cx, "column default new").left();
        let review = bounds_of(cx, "column default review").left();
        let decide = bounds_of(cx, "column default decide").left();
        let siding = bounds_of(cx, "column default siding").left();
        let merged = bounds_of(cx, "column default merged").left();
        assert!(
            backlog < new && new < review && review < decide && decide < siding && siding < merged,
            "the columns stand out of travel order"
        );
        // The heads with their group words: the seats where served, why
        // where a stage cannot take work.
        for stage in ["backlog", "new", "review", "decide", "siding"] {
            assert!(
                drawn(cx, &format!("column default {stage} head")),
                "{stage}"
            );
            assert!(
                drawn(cx, &format!("column default {stage} group")),
                "{stage}"
            );
        }
        for stage in ["backlog", "new", "review"] {
            assert!(
                drawn(cx, &format!("column default {stage} lamp")),
                "{stage}"
            );
        }
        for stage in ["decide", "siding", "merged"] {
            assert!(
                !drawn(cx, &format!("column default {stage} lamp")),
                "{stage}"
            );
        }
        view.read_with(cx, |v, _| {
            let stages = &v.model.as_ref().unwrap().depot("yardr").unwrap().flows[0].stages;
            let words: Vec<String> = stages.iter().map(stage_group_words).collect();
            assert_eq!(
                words,
                [
                    "mckean · waiting on a person",
                    "muse-builders · 2 of 3 seats",
                    "muse-reviewers · 2 of 2 seats",
                    "decisions · waiting on a person · paused",
                    "no route matches",
                    "no route matches",
                ]
            );
        });
        // The backlog column: its count, six titles and "+N more".
        assert!(drawn(cx, "column default backlog count"));
        for n in 1..=6 {
            assert!(drawn(cx, &format!("backlog title yd-b{n}")), "{n}");
        }
        assert!(!drawn(cx, "backlog title yd-b7"));
        assert!(!drawn(cx, "backlog title yd-b8"));
        assert!(drawn(cx, "backlog more default"));
        // One card per bead, with its worker, age, expected arrival
        // and remark each where it holds.
        for bead in ["yd-work", "yd-zulu", "yd-blocked", "yd-plain"] {
            assert!(drawn(cx, &format!("card {bead}")), "{bead}");
            assert!(drawn(cx, &format!("card title {bead}")), "{bead}");
            assert!(drawn(cx, &format!("card expected {bead}")), "{bead}");
        }
        assert!(drawn(cx, "card meta yd-work"));
        assert!(!drawn(cx, "card remark yd-work"));
        assert!(drawn(cx, "card remark yd-zulu"));
        assert!(!drawn(cx, "card meta yd-zulu"));
        assert!(drawn(cx, "card remark yd-blocked"));
        assert!(!drawn(cx, "card meta yd-blocked"));
        assert!(drawn(cx, "card meta yd-plain"));
        assert!(!drawn(cx, "card remark yd-plain"));
        // The terminal column reads terminal with the buffer stop; no
        // other column carries one.
        assert!(drawn(cx, "column default merged stop"));
        assert!(!drawn(cx, "column default merged group"));
        for stage in ["backlog", "new", "review", "decide", "siding"] {
            assert!(
                !drawn(cx, &format!("column default {stage} stop")),
                "{stage}"
            );
        }
        // Landings stand beneath the landed station, newest first.
        for bead in ["yd-r9pn", "yd-q04p"] {
            assert!(drawn(cx, &format!("landing {bead}")), "{bead}");
            assert!(drawn(cx, &format!("landing title {bead}")), "{bead}");
            assert!(drawn(cx, &format!("landing meta {bead}")), "{bead}");
        }
        let first = bounds_of(cx, "landing yd-r9pn");
        let second = bounds_of(cx, "landing yd-q04p");
        assert!(
            first.top() < second.top(),
            "the landings stand out of the served order"
        );
        let rule = bounds_of(cx, "column default merged rule");
        assert!(
            first.top() >= rule.bottom() - px(1.),
            "the landings stand above the landed station: {rule:?} {first:?}"
        );
        // The flow with no landings keeps the empty-stage line and has
        // no landing list.
        assert!(drawn(cx, "column no-landings merged empty"));
        // A landing's tap opens the whole bead, and back returns to
        // the line.
        click_on(cx, "landing yd-r9pn");
        wait(cx, "the landed bead", |cx| drawn(cx, "bead back"));
        assert_eq!(yard.asked("Bead"), [json!({"bead": "yd-r9pn"})]);
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.selected(), Some(&Selected::Bead("yd-r9pn".into())));
            assert_eq!(model.bead_back(), Selected::Line("yardr".into()));
        });
        click_on(cx, "bead back");
        wait(cx, "the line again", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().unwrap().selected() == Some(&Selected::Line("yardr".into()))
            })
        });
        // A card's click opens its bead, and back returns to the line.
        click_on(cx, "card yd-zulu");
        wait(cx, "the bead", |cx| drawn(cx, "bead back"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.selected(), Some(&Selected::Bead("yd-zulu".into())));
            assert_eq!(model.bead_back(), Selected::Line("yardr".into()));
        });
        click_on(cx, "bead back");
        wait(cx, "the line again", |cx| {
            view.read_with(cx, |v, _| {
                v.model.as_ref().unwrap().selected() == Some(&Selected::Line("yardr".into()))
            })
        });
    }

    /// A line's held beads read red only where the reader holds
    /// them: one bead held by jo and one by ada, and only the first
    /// draws warn. A test reads no colours from the frame, so it reads
    /// the rows the window draws and the colours it draws them in.
    #[gpui::test]
    fn a_line_s_held_beads_read_red_only_where_the_reader_holds_them(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_held());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row yardr");
        wait(cx, "the flow", |cx| drawn(cx, "flow head yardr"));
        assert!(drawn(cx, "card remark yd-mine"));
        assert!(drawn(cx, "card remark yd-theirs"));
        let palette = palette(cx);
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.me(), "jo");
            let beads = &model.depot("yardr").unwrap().flows[0].stages[0].beads;
            assert_eq!(beads.len(), 2);
            assert_eq!(
                (beads[0].remark.as_str(), beads[0].held_by.as_str()),
                ("held by jo", "jo")
            );
            assert_eq!(
                (beads[1].remark.as_str(), beads[1].held_by.as_str()),
                ("held by ada", "ada")
            );
            assert_eq!(you_first(&beads[0].remark, model.me()), "held by you");
            assert_eq!(you_first(&beads[1].remark, model.me()), "held by ada");
            for (bead, remark, headcode) in [
                (0, palette.warn, palette.warn),
                (1, palette.faint, palette.text),
            ] {
                let bead = &beads[bead];
                assert_eq!(
                    remark_color(&bead.remark, &bead.tone, &bead.held_by, model.me(), palette),
                    remark,
                    "{}",
                    bead.bead,
                );
                assert_eq!(
                    headcode_color(
                        bead.working,
                        &bead.remark,
                        &bead.tone,
                        &bead.held_by,
                        model.me(),
                        palette
                    ),
                    headcode,
                    "{}",
                    bead.bead,
                );
            }
        });
    }

