    /// The conversation reads as a column: each mail's name stands over
    /// its sender's group alone, a separator breaks over each day, and at
    /// 1920 pixels the mail stands in the 880 column, centred in the pane,
    /// its words in from the gutter, with the composer under it in the
    /// same column.
    #[gpui::test]
    fn the_conversation_reads_as_a_grouped_column_with_day_separators(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "Conversation",
            &json!({"result": [
                {"seq": 12, "at": "2026-10-13T09:30:00Z", "from": "yardmaster", "to": "jo", "text": "one", "read": true},
                {"seq": 13, "at": "2026-10-13T09:33:00Z", "from": "yardmaster", "to": "jo", "text": "two\n\nmore", "read": true},
                {"seq": 14, "at": "2026-10-14T08:05:00Z", "from": "jo", "to": "yardmaster", "text": "three", "read": true},
            ]})
            .to_string(),
        );
        let (view, cx) = opened(&yard, &["one", "two\n\nmore", "three"], cx);
        // The second mail joins the first's group where the two fall on
        // the same day here; the third heads its own, past midnight. Each
        // mail's name stands over it exactly where the model says.
        let entries = view.read_with(cx, |v, _| v.model.as_ref().unwrap().entries());
        assert_eq!(
            entries.iter().map(|entry| entry.head).collect::<Vec<_>>(),
            [true, false, true]
        );
        for (seq, head) in [
            (12, entries[0].head),
            (13, entries[1].head),
            (14, entries[2].head),
        ] {
            assert_eq!(
                drawn(cx, &format!("head {seq}")),
                head,
                "the name over mail {seq}"
            );
        }
        // A separator breaks over each day the model names.
        for (seq, day) in [
            (12, &entries[0].day),
            (13, &entries[1].day),
            (14, &entries[2].day),
        ] {
            if let Some(label) = day {
                assert!(
                    drawn(cx, &format!("day {label}")),
                    "no break over mail {seq}"
                );
            }
        }
        // The second letter's gap past the first is wider than both the
        // blank paragraph gap within it and the line leading.
        let (first, second) = (bounds_of(cx, "text 12"), bounds_of(cx, "text 13"));
        let between = f32::from(second.top() - first.bottom());
        let paragraph = f32::from(second.size.height) - 2. * f32::from(first.size.height);
        assert!(
            paragraph > 0.,
            "the paragraphs stand with no gap: {first:?} {second:?}"
        );
        assert!(
            between > paragraph,
            "the letters stand no further apart than the paragraphs: {between} past {paragraph}"
        );
        let rem = cx.update(|window, _| window.rem_size());
        let leading = f32::from(first.size.height) - f32::from(rem) * 7. / 8.;
        assert!(
            between > leading,
            "the letters stand no further apart than the lines: {between} past {leading}"
        );
        // At 1920 pixels the mail stands in the reading column: capped at
        // 880, off both edges of the pane.
        cx.simulate_resize(gpui::size(px(1920.), px(1080.)));
        let rows = bounds_of(cx, "rows");
        for seq in [12, 13, 14] {
            let text = bounds_of(cx, &format!("text {seq}"));
            assert!(
                text.size.width <= px(880.),
                "mail {seq} runs past the column: {text:?}"
            );
            // The words stand in from the gutter, short of the column's
            // 880: 880 less the 56-pixel gutter.
            assert!(
                text.size.width >= px(800.),
                "mail {seq} stands off the column's width: {text:?}"
            );
            assert!(
                text.origin.x >= rows.right() + px(220.),
                "mail {seq} stands off the column's left: {text:?} in {rows:?}"
            );
            assert!(
                text.right() <= px(1920.) - px(220.),
                "mail {seq} stands off the column's right: {text:?}"
            );
        }
        // The composer stands in the same column: capped at 880 and
        // centred in the pane as the mail is, so its edges meet the
        // column's. (The mail's text keeps a gutter on its left, so its
        // own middle is no measure.)
        let frame = bounds_of(cx, "composer");
        assert!(
            frame.size.width <= px(880.),
            "the composer runs past the column: {frame:?}"
        );
        assert!(
            frame.size.width >= px(850.),
            "the composer stands off the column's width: {frame:?}"
        );
        let middle = frame.origin.x + frame.size.width / 2.;
        let pane = (rows.right() + px(1920.)) / 2.;
        assert!(
            middle >= pane - px(1.),
            "the composer stands off the column's middle: {frame:?} in {rows:?}"
        );
        assert!(
            middle <= pane + px(1.),
            "the composer stands off the column's middle: {frame:?} in {rows:?}"
        );
    }

    /// A head stands under the separator that names its day, so it says
    /// the time alone: the first group of a day, and a later group of the
    /// same day under the same separator. The mails are far enough apart
    /// to fall on two days in any zone.
    #[gpui::test]
    fn the_heads_under_a_day_s_separator_say_the_time_alone(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "Conversation",
            &json!({"result": [
                {"seq": 12, "at": "2026-10-13T09:30:00Z", "from": "yardmaster", "to": "jo", "text": "one", "read": true},
                {"seq": 13, "at": "2026-10-13T09:33:00Z", "from": "yardmaster", "to": "jo", "text": "two", "read": true},
                {"seq": 14, "at": "2026-10-13T09:41:00Z", "from": "jo", "to": "yardmaster", "text": "three", "read": true},
                {"seq": 15, "at": "2026-10-15T08:05:00Z", "from": "yardmaster", "to": "jo", "text": "four", "read": true},
            ]})
            .to_string(),
        );
        let (view, cx) = opened(&yard, &["one", "two", "three", "four"], cx);
        // Two groups on the 13th, the second past the first's five minutes
        // and under the one separator, and one on the 15th under its own.
        let entries = view.read_with(cx, |v, _| v.model.as_ref().unwrap().entries());
        let heads: Vec<bool> = entries.iter().map(|e| e.head).collect();
        let days: Vec<bool> = entries.iter().map(|e| e.day.is_some()).collect();
        assert_eq!(heads, [true, false, true, true]);
        assert_eq!(days, [true, false, false, true]);

        // Each head says the time of its group in the reader's zone, and
        // no date: the separator above names it.
        for (seq, at) in [
            (12, "2026-10-13T09:30:00Z"),
            (14, "2026-10-13T09:41:00Z"),
            (15, "2026-10-15T08:05:00Z"),
        ] {
            let time = local(at, "%H:%M");
            let dated = local(at, "%m-%d %H:%M");
            assert!(drawn(cx, &format!("clock {seq} {time}")), "mail {seq}");
            assert!(!drawn(cx, &format!("clock {seq} {dated}")), "mail {seq}");
        }
        // The mail that reads under the first head has none of its own.
        assert!(!drawn(cx, "head 13"));
    }

    /// A reply says which mail it answers on its head, after the name, as
    /// the yard's inbox, chat and talk page say it: `re 13`. It heads a
    /// group of its own, so that there is a head to say it on, and the
    /// mails under that head answer the same mail. Mail that answers none,
    /// as every mail of a yard from before the field does, says nothing.
    #[gpui::test]
    fn a_reply_s_head_says_which_mail_it_answers(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "Conversation",
            &json!({"result": [
                {"seq": 12, "at": "2026-10-13T09:30:00Z", "from": "yardmaster", "to": "jo", "text": "one", "read": true},
                {"seq": 13, "at": "2026-10-13T09:31:00Z", "from": "yardmaster", "to": "jo", "text": "two", "read": true},
                {"seq": 14, "at": "2026-10-13T09:32:00Z", "from": "jo", "to": "yardmaster", "text": "three", "read": true, "answered": 13},
                {"seq": 15, "at": "2026-10-13T09:33:00Z", "from": "jo", "to": "yardmaster", "text": "four", "read": true, "answered": 13},
                {"seq": 16, "at": "2026-10-13T09:34:00Z", "from": "jo", "to": "yardmaster", "text": "five", "read": true, "answered": 12},
                {"seq": 17, "at": "2026-10-13T09:35:00Z", "from": "jo", "to": "yardmaster", "text": "six", "read": true},
            ]})
            .to_string(),
        );
        let (view, cx) = opened(&yard, &["one", "two", "three", "four", "five", "six"], cx);
        assert_eq!(answered_words(13).as_deref(), Some("re 13"));
        assert_eq!(answered_words(0), None);

        // Mail 13 reads under 12's head: both answer none. Jo's 14 answers
        // 13 and heads a group, 15 answers it too and reads under 14, 16
        // answers another mail and heads its own, and 17 answers none.
        let entries = view.read_with(cx, |v, _| v.model.as_ref().unwrap().entries());
        let heads: Vec<bool> = entries.iter().map(|e| e.head).collect();
        let answered: Vec<u64> = entries.iter().map(|e| e.answered).collect();
        assert_eq!(heads, [true, false, true, false, true, true]);
        assert_eq!(answered, [0, 0, 13, 13, 12, 0]);

        // The mark stands on the head of a mail that answers one, with the
        // yard's words, and on no other: not on the head of mail that
        // answers none, and not on a mail under a head, which says it for
        // that mail too.
        for entry in &entries {
            for n in [12, 13] {
                assert_eq!(
                    drawn(cx, &format!("answers {} re {n}", entry.seq)),
                    entry.head && entry.answered == n,
                    "mail {} re {n}",
                    entry.seq
                );
            }
        }

        // It stands on the head's line, after the time and the name.
        let time = local("2026-10-13T09:32:00Z", "%H:%M");
        let (head, clock, mark) = (
            bounds_of(cx, "head 14"),
            bounds_of(cx, &format!("clock 14 {time}")),
            bounds_of(cx, "answers 14 re 13"),
        );
        assert!(head.contains(&mark.center()), "{mark:?} in {head:?}");
        assert!(mark.left() > clock.right(), "{mark:?} after {clock:?}");
        assert!(
            near(mark.top(), clock.top()),
            "{mark:?} on {clock:?}'s line"
        );
    }

    /// The notice under the mail stands in the reading column, with the
    /// composer under it: its line starts where the composer's frame does,
    /// on a wide window, where the column stands centred in the pane, and
    /// on a narrow one, where the column is the pane less the frame's side
    /// margins. It still wraps, and the composer stands below the last line
    /// of it.
    #[gpui::test]
    fn the_notice_stands_in_the_reading_column_with_the_composer(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        grouped_letters(&yard);
        let (view, cx) = opened(&yard, &["one", "two", "three"], cx);
        view.update(cx, |v, cx| {
            v.notice(
                "the flows could not be read: the yard does not answer (connection timed out)"
                    .into(),
                cx,
            )
        });

        // On a wide window the notice, the letters' heads and the frame
        // stand on one left edge, well in from the pane's, and the notice
        // is the one line.
        let mut line = px(0.);
        for width in [1920., 1280.] {
            cx.simulate_resize(gpui::size(px(width), px(800.)));
            let pane = px(width) - bounds_of(cx, "rows").right();
            assert!(
                pane > px(READING_WIDTH + 24.),
                "{width} is no wide window: the pane is {pane:?}"
            );
            let (notice, frame) = (bounds_of(cx, "notice"), bounds_of(cx, "composer"));
            let head = bounds_of(cx, "head 12");
            assert!(
                near(notice.left(), frame.left()) && near(notice.left(), head.left()),
                "at {width} the notice does not start where the frame and the letters do: {notice:?}, {frame:?}, {head:?}"
            );
            assert!(
                near(notice.right(), frame.right()),
                "at {width} the notice does not end where the frame does: {notice:?}, {frame:?}"
            );
            assert!(
                notice.size.width <= px(READING_WIDTH),
                "at {width} the notice runs past the column: {notice:?}"
            );
            line = notice.size.height;
        }

        // On a narrow one the notice has the frame's margins, wraps over
        // more than the one line, and has the composer below it.
        cx.simulate_resize(gpui::size(px(640.), px(800.)));
        let pane = px(640.) - bounds_of(cx, "rows").right();
        assert!(
            pane < px(READING_WIDTH),
            "640 is no narrow window: the pane is {pane:?}"
        );
        let (notice, frame) = (bounds_of(cx, "notice"), bounds_of(cx, "composer"));
        let head = bounds_of(cx, "head 12");
        assert!(
            near(notice.left(), frame.left()) && near(notice.left(), head.left()),
            "the notice does not start where the frame and the letters do: {notice:?}, {frame:?}, {head:?}"
        );
        assert!(
            near(notice.right(), frame.right()),
            "the notice does not end where the frame does: {notice:?}, {frame:?}"
        );
        assert!(
            near(notice.right(), head.right()),
            "the notice does not end where the letters do: {notice:?}, {head:?}"
        );
        assert!(
            notice.size.height > line * 1.5,
            "the notice does not wrap: {notice:?} against a line of {line:?}"
        );
        assert!(
            notice.bottom() <= frame.top(),
            "the composer stands inside the notice: {frame:?} under {notice:?}"
        );
    }

    /// A conversation of `n` mails from alternating senders, most of
    /// them long enough to wrap in the reading column, each heading
    /// its own group, one with an image. The yard holds it, and
    /// answers it in pages.
    fn wrapping_conversation(yard: &Yard, n: u64) {
        yard.answer(
            "UserInbox",
            r#"{"result": {"mail": [], "unread": 0, "last": 0, "from": []}}"#,
        );
        let long = "New draft is in Gmail on Shai's thread: it says managers cannot change names today, people can edit their own, a manager option is coming with no date promised, and I'll let him know.";
        yard.converse(
            "yardmaster",
            (1..=n)
                .map(|seq| {
                    let from = match seq % 2 == 0 {
                        true => "yardmaster",
                        false => "jo",
                    };
                    let to = match seq % 2 == 0 {
                        true => "jo",
                        false => "yardmaster",
                    };
                    let text = match seq % 3 == 0 {
                        true => "can we get permission to edit?",
                        false => long,
                    };
                    let mut mail = json!({"seq": seq, "at": mailed(seq - 1), "from": from,
                        "to": to, "read": true, "text": text});
                    if seq * 4 == n * 3 {
                        mail["files"] = json!([{"hash": HASH, "type": "image/png", "bytes": 70}]);
                    }
                    mail
                })
                .collect(),
        );
    }

    /// No two of the open conversation's rows overlap: each of the
    /// scroll handle's children stands below the one before, and each
    /// mail's head and text stand below the text before. Within a
    /// pixel, for gpui's rounding to device pixels. Drawn once, and
    /// the bounds read off that frame: a redraw per mail would lay
    /// the whole conversation out again for each.
    fn rows_tile(view: &Entity<Footplate>, cx: &mut VisualTestContext) {
        frames(cx);
        let rows: Vec<Bounds<Pixels>> = view.read_with(cx, |v, _| {
            let mut rows = Vec::new();
            let mut ix = 0;
            while let Some(bounds) = v.conversation.bounds_for_item(ix) {
                rows.push(bounds);
                ix += 1;
            }
            rows
        });
        assert!(!rows.is_empty(), "the conversation shows no rows");
        for (ix, pair) in rows.windows(2).enumerate() {
            assert!(
                pair[1].top() + px(1.) >= pair[0].bottom(),
                "row {} starts inside row {}: {:?} past {:?}",
                ix + 1,
                ix,
                pair[1],
                pair[0],
            );
        }
        let mails: Vec<(u64, bool)> = view.read_with(cx, |v, _| {
            v.model
                .as_ref()
                .map(|m| m.entries().into_iter().map(|e| (e.seq, e.head)).collect())
                .unwrap_or_default()
        });
        let mut below = px(0.);
        let mut first = true;
        for (seq, headed) in mails {
            let text = bounds_now(cx, &format!("text {seq}"));
            if headed {
                let head = bounds_now(cx, &format!("head {seq}"));
                if !first {
                    assert!(
                        head.top() + px(1.) >= below,
                        "mail {seq}'s head starts inside the mail above: {head:?} past {below:?}"
                    );
                }
                assert!(
                    text.top() + px(1.) >= head.bottom(),
                    "mail {seq}'s text starts inside its head: {text:?} past {head:?}"
                );
            } else if !first {
                assert!(
                    text.top() + px(1.) >= below,
                    "mail {seq}'s text starts inside the mail above: {text:?} past {below:?}"
                );
            }
            first = false;
            below = text.bottom();
        }
    }

    /// A long wrapped thread from alternating senders, one mail with
    /// an image: no row stands inside the one above, on first open or
    /// after an older page loads. A row that stood `w_full` with
    /// `max_w` kept the height its text had at full width, and the
    /// mail below started inside it.
    #[gpui::test]
    fn a_wrapped_thread_overlaps_neither_on_open_nor_after_an_older_page(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.blob(HASH, &png());
        wrapping_conversation(&yard, 100);
        let (view, cx) = opened_on(&yard, 50, cx);
        cx.simulate_resize(gpui::size(px(1920.), px(1080.)));
        rows_tile(&view, cx);
        // The rows stand as tall as the lines they wrap to: a column
        // measured at no width made a wrapped paragraph one line tall,
        // and drew the text over the rows below. Mail 99 is the short
        // one, mail 100 the long one that wraps in the column.
        let one = bounds_of(cx, "text 99").size.height;
        let wrapped = bounds_of(cx, "text 100").size.height;
        assert!(
            wrapped > one * 1.9,
            "mail 100 is {wrapped:?}, a line {one:?}"
        );
        scroll_to(&view, cx, 100.);
        wait(cx, "the page before", |cx| texts(&view, cx).len() == 100);
        rows_tile(&view, cx);
    }

    /// The arrivals row opens the panel: one track per travelling
    /// flow — its name above a cell per stage in travel order — with
    /// the lamps lit only where beads stand, two headcodes per cell and
    /// "+N" past that, the Elsewhere stub, No line's own track, and the
    /// quiet tracks folded to one row. The head carries the summary and
    /// the toggle, on the panel.
    #[gpui::test]
    fn the_arrivals_row_opens_the_panel_of_tracks(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_panel());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        wait(cx, "the panel", |cx| drawn(cx, "panel track yardr default"));
        view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            assert_eq!(model.selected(), Some(&Selected::Arrivals));
            assert!(!model.departures());
            assert_eq!(model.working_count(), 1);
            assert_eq!(model.waiting_on_you().len(), 2);
            assert_eq!(model.held_count(), 1);
        });
        // One track per travelling flow, its name above its stages with
        // the backlog's count on the name's line, and no stage cell for
        // the backlog.
        for (depot, flow, first) in [
            ("yardr", "default", "new"),
            ("yardr", "design", "draft"),
            ("footplate", "default", "new"),
        ] {
            let track = format!("panel track {depot} {flow}");
            let name = format!("panel name {depot} {flow}");
            let backlog = format!("panel name {depot} {flow} backlog");
            assert!(drawn(cx, &track), "{track}");
            assert!(drawn(cx, &name), "{name}");
            assert!(drawn(cx, &backlog), "{backlog}");
            let name = bounds_of(cx, &name);
            let stage = bounds_of(cx, &format!("panel stage {depot} {flow} {first}"));
            assert!(
                name.bottom() <= stage.top() + px(1.),
                "the name stands beside its stages, not above: {name:?} {stage:?}"
            );
        }
        assert!(!drawn(cx, "panel stage yardr default backlog"));
        // The stages in travel order, sharing the card's width equally
        // and aligned by place across the tracks.
        for stage in ["new", "review", "approved"] {
            let cell = format!("panel stage yardr default {stage}");
            assert!(drawn(cx, &cell), "{cell}");
        }
        let new = bounds_of(cx, "panel stage yardr default new");
        let review = bounds_of(cx, "panel stage yardr default review");
        let approved = bounds_of(cx, "panel stage yardr default approved");
        assert!(
            new.left() < review.left() && review.left() < approved.left(),
            "the stages stand out of travel order: {new:?} {review:?} {approved:?}"
        );
        for (what, cell) in [("review", &review), ("approved", &approved)] {
            assert!(
                (cell.size.width - new.size.width).abs() < px(1.),
                "the {what} cell shares no width with the new cell: {cell:?} {new:?}"
            );
        }
        let footplate = bounds_of(cx, "panel stage footplate default new");
        assert!(
            (new.left() - footplate.left()).abs() < px(1.),
            "the first stages stand out of column: {new:?} {footplate:?}"
        );
        assert!(
            (new.size.width - footplate.size.width).abs() < px(1.),
            "the tracks share no cell width: {new:?} {footplate:?}"
        );
        // The lamps: fault and turn burn where beads stand, and no lamp
        // where none stands, whatever the stage serves.
        assert!(drawn(cx, "panel lamp yardr default new"));
        assert!(drawn(cx, "panel lamp yardr default review"));
        assert!(!drawn(cx, "panel lamp yardr default approved"));
        assert!(!drawn(cx, "panel lamp yardr design critique"));
        assert!(!drawn(cx, "panel lamp footplate default new"));
        // The terminal stage closes its track with a buffer stop; no
        // other stage carries one.
        assert!(drawn(cx, "panel stop yardr default approved"));
        assert!(!drawn(cx, "panel stop yardr default new"));
        assert!(!drawn(cx, "panel stop yardr default review"));
        // One headcode and "+N" past two beads; two where two
        // stand; every other bead on its stage.
        assert!(drawn(cx, "panel headcode footplate-p512"));
        assert!(!drawn(cx, "panel headcode yd-blocked"));
        assert!(!drawn(cx, "panel headcode yd-extra"));
        assert!(drawn(cx, "panel more yardr default new"));
        for bead in ["yd-zulu", "yd-work", "yd-qskt", "footplate-fc47"] {
            assert!(drawn(cx, &format!("panel headcode {bead}")), "{bead}");
        }
        // Elsewhere hangs under its depot's last track; No line has
        // its own track; the quiet tracks fold to one row.
        assert!(drawn(cx, "panel elsewhere yardr"));
        assert!(drawn(cx, "panel headcode yardr-pinned"));
        let design = bounds_of(cx, "panel track yardr design").top();
        let stub = bounds_of(cx, "panel elsewhere yardr").top();
        let footplate = bounds_of(cx, "panel track footplate default").top();
        assert!(
            design < stub && stub < footplate,
            "Elsewhere hangs off its depot's last track: {design:?} {stub:?} {footplate:?}"
        );
        assert!(drawn(cx, "panel noline"));
        assert!(drawn(cx, "panel headcode yd-shed"));
        assert!(drawn(cx, "panel quiet"));
        assert!(!drawn(cx, "panel track drafts default"));
        // The head: the summary and the toggle, on the panel, with no
        // board beneath them.
        assert!(drawn(cx, "arrivals head"));
        assert!(drawn(cx, "panel summary"));
        assert!(drawn(cx, "panel waits"));
        assert!(drawn(cx, "arrivals panel"));
        assert!(drawn(cx, "arrivals departures"));
        assert!(!drawn(cx, "waits banner"));
        assert!(!drawn(cx, "arrival yd-zulu"));
        // Departures keeps the board under the toggle, and Panel steps
        // back to the panel.
        to_departures(cx);
        wait(cx, "the departures", |cx| drawn(cx, "arrival yd-zulu"));
        assert!(drawn(cx, "waits banner"));
        view.read_with(cx, |v, _| {
            assert!(v.model.as_ref().unwrap().departures());
        });
        click_on(cx, "arrivals panel");
        wait(cx, "the panel again", |cx| {
            drawn(cx, "panel track yardr default")
        });
    }

    /// The panel shows at a glance that a line is moving. A cell draws
    /// its worked beads first, so the one headcode a crowded cell has
    /// room for is a worked bead's though the yard lists it last, and
    /// its "+N" counts what it hides, the worked and the waiting apart;
    /// the worked headcode wears the running dot and a waiting one none;
    /// a stage burns the running lamp where a bead is worked; and the
    /// line's head carries a lamp and what is worked, what waits and the
    /// backlog, where a line that nothing works carries no lamp and no
    /// worked words. The served order stays in the model and in the line
    /// view, whose columns burn the served lamp alone.
    #[gpui::test]
    fn the_panel_shows_a_line_is_moving_with_its_worked_beads_first(cx: &mut TestAppContext) {
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer("Arrivals", &arrivals_board());
        yard.answer("Flows", &flows_moving());
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        to_timetable(&view, cx);
        click_on(cx, "row arrivals");
        wait(cx, "the panel", |cx| drawn(cx, "panel track yardr default"));
        // `new` lists its two waiting beads first and its worked ones
        // last. Its one headcode is the first worked one, with the
        // running dot, and the three others stand in the "+N", which
        // says one of them is worked and two wait.
        assert!(drawn(cx, "panel headcode yd-run1"));
        assert!(drawn(cx, "panel running yd-run1"));
        for hidden in ["yd-wait1", "yd-wait2", "yd-run2"] {
            assert!(!drawn(cx, &format!("panel headcode {hidden}")), "{hidden}");
        }
        assert!(drawn(cx, "panel more yardr default new"));
        assert!(drawn(cx, "panel more yardr default new +1 working"));
        assert!(drawn(cx, "panel more yardr default new 2 waiting"));
        // `review` draws both its beads, the worked one above the
        // waiting one it is listed after, and only that one marked.
        let run = bounds_of(cx, "panel headcode yd-run3");
        let late = bounds_of(cx, "panel headcode yd-late");
        assert!(
            run.bottom() <= late.top() + px(1.),
            "the worked headcode stands under the waiting one: {run:?} {late:?}"
        );
        assert!(drawn(cx, "panel running yd-run3"));
        assert!(!drawn(cx, "panel running yd-late"));
        // Three waiting beads stand in "+2" alone, as before.
        assert!(drawn(cx, "panel headcode footplate-a"));
        assert!(!drawn(cx, "panel running footplate-a"));
        assert!(drawn(cx, "panel more footplate default new +2"));
        assert!(!drawn(cx, "panel more footplate default new 1 waiting"));
        // A stage burns the running lamp where a bead is worked, and
        // none where none is or none stands.
        assert!(drawn(cx, "panel lamp yardr default new"));
        assert!(drawn(cx, "panel lamp yardr default review"));
        assert!(!drawn(cx, "panel lamp yardr default approved"));
        assert!(!drawn(cx, "panel lamp yardr design draft"));
        assert!(!drawn(cx, "panel lamp footplate default new"));
        // The head: the lamp, then what is worked, what waits and the
        // backlog. The line nothing works has no lamp and no worked
        // words, and counts its waiting bead.
        for part in ["lamp", "working", "waiting", "backlog"] {
            let part = format!("panel name yardr default {part}");
            assert!(drawn(cx, &part), "{part}");
        }
        assert!(!drawn(cx, "panel name yardr design lamp"));
        assert!(!drawn(cx, "panel name yardr design working"));
        assert!(drawn(cx, "panel name yardr design waiting"));
        assert!(drawn(cx, "panel name yardr design backlog"));
        assert!(!drawn(cx, "panel name footplate default lamp"));
        assert!(!drawn(cx, "panel name footplate default working"));
        // The model keeps the order the yard served.
        view.read_with(cx, |v, _| {
            let stages = &v.model.as_ref().unwrap().depots()[0].flows[0].stages;
            let new: Vec<&str> = stages[1].beads.iter().map(|b| b.bead.as_str()).collect();
            assert_eq!(new, ["yd-wait1", "yd-wait2", "yd-run1", "yd-run2"]);
        });
        // The line view draws the served lamp alone: no lamp on a stage
        // whose own lamp is none, though a bead is worked there.
        click_on(cx, "panel name yardr default");
        wait(cx, "the line", |cx| drawn(cx, "column default new"));
        assert!(!drawn(cx, "column default new lamp"));
        // The narrowest window, at every text size: the cells stand at
        // their narrowest, and each phrase of the "+N" stands whole on
        // one line inside its cell, as each part of the head does.
        cx.simulate_resize(gpui::size(px(WINDOW_MIN), px(360.)));
        view.update_in(cx, |v, window, cx| v.select(Selected::Arrivals, window, cx));
        wait(cx, "the panel", |cx| drawn(cx, "panel track yardr default"));
        for text in [settings::TEXT_MIN, settings::TEXT, settings::TEXT_MAX] {
            view.update(cx, |v, cx| {
                let set = Settings {
                    text,
                    ..v.settings.clone()
                };
                v.set(set, cx)
            });
            let rem = f32::from(settings_of(&view, cx).rem());
            drawn(cx, "panel");
            let cell = bounds_now(cx, "panel stage yardr default new");
            // At the smallest text the pane has room for wider cells.
            assert!(
                text == settings::TEXT_MIN
                    || (f32::from(cell.size.width) - PANEL_MIN * rem).abs() < 1.,
                "at {text} px the cell is {cell:?}, not its narrowest"
            );
            for phrase in ["+1 working", "2 waiting"] {
                let at = bounds_now(cx, &format!("panel more yardr default new {phrase}"));
                assert!(
                    cell.left() <= at.left() && at.right() <= cell.right(),
                    "at {text} px {phrase} stands off its cell: {cell:?} {at:?}"
                );
                assert!(
                    f32::from(at.size.height) < rem * 1.5,
                    "at {text} px {phrase} wraps inside itself: {at:?}"
                );
            }
            for part in ["depot", "flow", "working", "waiting", "backlog"] {
                let at = bounds_now(cx, &format!("panel name yardr default {part}"));
                assert!(
                    f32::from(at.size.height) < rem * 1.5,
                    "at {text} px the head's {part} is wrapped: {at:?}"
                );
            }
        }
    }

    /// An unreadable quiet depot stays visible on the panel so its
