    /// The one yard the environment names has no other to go to: away, it
    /// keeps the rail with the gear and no tile, its modes dimmed and
    /// inert.
    #[gpui::test]
    fn the_environment_s_yard_away_has_no_switcher(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("mac.token");
        yard::keep_token(&token, crate::fake::TOKEN).unwrap();
        let far = Yard::start_tcp();
        far.stop();
        let env = Env {
            yard: Some(far.address().to_string()),
            token_file: Some(token),
            socket: dir.path().join("yard.sock"),
        };
        let (view, cx) = opened_at(env, &file, cx);
        wait(cx, "that nothing answers", |cx| {
            view.read_with(cx, |v, _| {
                v.down
                    .as_deref()
                    .is_some_and(|why| why.starts_with("No yard: nothing answers"))
            })
        });
        assert!(drawn(cx, "away why") && drawn(cx, "settings"));
        assert!(drawn(cx, "yard chip"));
        // Nor a way to another yard: it is the one there is.
        assert!(!drawn(cx, "way near") && !drawn(cx, "way far") && !drawn(cx, "way hosted"));
        assert!(!drawn(cx, "way here"));
        cx.simulate_keystrokes("secondary-y");
        assert_eq!(switching(&view, cx), None);
        // The rail stands with the chip and the three modes, dimmed
        // and inert: a click and the brackets change nothing.
        assert!(drawn(cx, "yard chip"));
        assert!(drawn(cx, "rail chat") && drawn(cx, "rail decisions"));
        assert!(drawn(cx, "rail timetable"));
        click_on(cx, "rail timetable");
        cx.simulate_keystrokes("secondary-]");
        cx.run_until_parked();
        assert_eq!(rail_mode(&view, cx), Mode::Chat);
        assert!(view.read_with(cx, |v, _| v.model.is_none()));
        // The gear stays alive: the settings open from the rail.
        click_on(cx, "settings");
        assert!(settings_open(&view, cx));
    }

    /// A window with nothing at this run's socket and no settings kept:
    /// the first screen, once it says there is no yard. On Windows there is
    /// no socket to look at, and it says so at once.
    fn no_yard<'a>(
        dir: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        let env = Env {
            socket: dir.join("yard.sock"),
            ..Env::default()
        };
        let (view, cx) = opened_at(env, &dir.join("footplate/settings.json"), cx);
        wait(cx, "that there is no yard", |cx| {
            view.read_with(cx, |v, _| {
                v.down.as_deref().is_some_and(|why| {
                    why.starts_with("No yard: nothing answers")
                        || why.starts_with("This system has no yard of its own")
                })
            })
        });
        (view, cx)
    }

    /// Windows has no yard of this machine: the first screen says so, and
    /// offers the ways to a yard at an address and none to one here. The
    /// entry that is always listed is not tried again, there is no switch
    /// to start it with, and the settings add a yard at an address alone.
    #[cfg(not(unix))]
    #[gpui::test]
    fn on_windows_the_first_screen_offers_only_the_ways_to_a_yard_at_an_address(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let (view, cx) = no_yard(dir.path(), cx);
        assert_eq!(view.read_with(cx, |v, _| v.away), Away::Stopped);
        assert!(!view.read_with(cx, |v, _| v.sets_up_here()));
        assert!(view.read_with(cx, |v, _| matches!(v.switch_for(), SwitchFor::Far)));
        assert!(drawn(cx, "away why") && drawn(cx, "away lead"));
        assert!(drawn(cx, "way far") && drawn(cx, "way hosted"));
        assert!(!drawn(cx, "way here") && !drawn(cx, "way near"));
        assert_eq!(away_why(&view, cx), "this machine · cannot be opened");

        // The settings open on this window: the text size, and no item
        // in a tray, which Windows does not draw.
        cx.simulate_keystrokes("secondary-,");
        assert!(drawn(cx, "text size"));
        assert!(!drawn(cx, "menu bar on") && !drawn(cx, "tray auto"));

        // The About card is opened from the same section, there being no
        // application menu, and names footplate alone: Windows runs no
        // yardr, even if an old file with its names is in this test's folder.
        let bin = dir.path().join("bin");
        std::fs::create_dir_all(&bin).unwrap();
        std::fs::write(bin.join("yardr"), b"not a program").unwrap();
        view.update(cx, |v, _| v.means.machine.own = Some(bin));
        click_on(cx, "about show");
        wait(cx, "the card, told that there is none", |cx| {
            view.read_with(cx, |v, _| {
                v.about
                    .as_ref()
                    .is_some_and(|about| about.seen == Some(Seen::Nothing))
            })
        });
        assert!(drawn(cx, "about card") && drawn(cx, "about footplate"));
        assert!(!drawn(cx, "about yardr"));
        cx.simulate_keystrokes("escape");
        assert!(view.read_with(cx, |v, _| v.about.is_none()));
        assert!(settings_open(&view, cx));

        click_on(cx, "settings section yards");
        assert!(drawn(cx, "add far") && drawn(cx, "add hosted"));
        assert!(!drawn(cx, "add near"));
    }

    /// With no yard the window offers the ways to one, which are the
    /// settings' entries: a yard of this machine by its socket, where this
    /// run's stands to begin with, is added and opened from there, with no
    /// settings shown. Esc leaves the fields.
    // Unix: Windows offers no way to a yard of this machine by its socket; its twin
    // `on_windows_the_first_screen_offers_only_the_ways_to_a_yard_at_an_address` says so.
    #[cfg(unix)]
    #[gpui::test]
    fn no_yard_offers_a_yard_of_this_machine_by_its_socket(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let second = Yard::start();
        a_second_yard_of_jo(&second);
        let (view, cx) = no_yard(dir.path(), cx);
        assert_eq!(view.read_with(cx, |v, _| v.away), Away::Trying);
        assert!(drawn(cx, "away why"));
        // The ways, and nothing asked until one is taken.
        assert!(drawn(cx, "way near") && drawn(cx, "way far") && drawn(cx, "way hosted"));
        assert!(!drawn(cx, "yard name") && !drawn(cx, "yard pair"));
        let adding = |view: &Entity<Footplate>, cx: &mut VisualTestContext| {
            view.read_with(cx, |v, _| v.adding.clone())
        };

        click_on(cx, "way near");
        assert_eq!(adding(&view, cx), Some(Adding::Near));
        assert!(drawn(cx, "yard name") && drawn(cx, "yard socket") && drawn(cx, "yard pair"));
        // The fields have room for a path, under the buttons and inside
        // the window.
        let (field, way) = (bounds_of(cx, "yard socket"), bounds_of(cx, "way near"));
        assert!(field.size.width > px(200.), "{field:?}");
        assert!(field.top() > way.bottom(), "{field:?} {way:?}");
        let window = cx.update(|window, _| window.viewport_size());
        assert!(field.right() < window.width && field.bottom() < window.height);
        // This run's socket stands in the field, and the name is typed:
        // every letter of it, with no card whose keys `e` and `d` are.
        assert_eq!(
            view.read_with(cx, |v, cx| v.socket.read(cx).text().to_string()),
            dir.path().join("yard.sock").to_str().unwrap()
        );
        cx.simulate_input("second home");
        assert_eq!(
            view.read_with(cx, |v, cx| v.yard_name.read(cx).text().to_string()),
            "second home"
        );
        // Esc leaves the fields, and the window is as it was.
        cx.simulate_keystrokes("escape");
        assert_eq!(adding(&view, cx), None);
        assert!(!settings_open(&view, cx));
        assert!(view.read_with(cx, |v, _| v.down.is_some()));

        // No name: said, and nothing changed.
        click_on(cx, "way near");
        cx.simulate_keystrokes("enter");
        assert!(
            yard_said(&view, cx).starts_with("A yard wants a name"),
            "{}",
            yard_said(&view, cx)
        );
        assert!(!file.exists());
        // The second home's socket in place of this run's, and Enter.
        view.update(cx, |v, cx| {
            v.yard_name
                .update(cx, |line, cx| line.set_text("second home", cx));
            let socket = second.socket().to_str().unwrap().to_string();
            v.socket.update(cx, |line, cx| line.set_text(&socket, cx));
        });
        cx.simulate_keystrokes("enter");
        wait(cx, "the second home's yard", |cx| {
            texts(&view, cx) == ["From the second home."]
        });
        assert_eq!(view.read_with(cx, |v, _| v.down.clone()), None);
        assert_eq!(adding(&view, cx), None);
        assert!(!settings_open(&view, cx));
        assert_eq!(open_yard(&view, cx), "second home");
        // It is kept, after this machine's, and is the one to open next.
        let kept = Settings::read(&file);
        assert_eq!(
            kept.yards[1],
            settings::Yard::near("second home", second.socket().to_str().unwrap())
        );
        assert_eq!(kept.open, "second home");
        // The line has the keys, as after a switch.
        cx.simulate_input("hello");
        assert_eq!(typed(&view, cx), "hello");
    }

    /// What the first run of a test reaches out with: a stand-in for
    /// yardr in `dir`, which is found and not installed, a home under
    /// `dir`, and a list in place of the browser. The stand-in's path, and
    /// the pages that were opened.
    #[cfg(unix)]
    fn stand_in_means(
        dir: &std::path::Path,
        apple: bool,
    ) -> (Means, PathBuf, Rc<RefCell<Vec<String>>>) {
        let program = crate::setup::standin::make(&dir.join("fetched"));
        let home = dir.join("home");
        std::fs::create_dir_all(&home).unwrap();
        let opened: Rc<RefCell<Vec<String>>> = Rc::default();
        let (fetched, pages) = (program.clone(), opened.clone());
        let means = Means {
            yardr: Arc::new(move || Ok((fetched.clone(), None))),
            install: Arc::new(|_| Err("nothing is installed in this test".to_string())),
            machine: Machine {
                path: "/usr/bin:/bin".into(),
                home: Some(home),
                own: Some(dir.join("own")),
                ..Machine::default()
            },
            open: Rc::new(move |url, _| pages.borrow_mut().push(url.to_string())),
            apple,
            titlebar: None,
            feedback: None,
            ..Means::real()
        };
        (means, program, opened)
    }

    fn step_of(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<firstrun::Step> {
        view.read_with(cx, |v, cx| v.first_run.as_ref().map(|f| f.read(cx).step))
    }

    fn setup_said(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> String {
        view.read_with(cx, |v, cx| {
            let said = v.first_run.as_ref().and_then(|f| f.read(cx).said.clone());
            said.unwrap_or_default()
        })
    }

    /// Waits until the first run stands at `step` with nothing underway.
    fn at_step(view: &Entity<Footplate>, cx: &mut VisualTestContext, step: firstrun::Step) {
        wait(cx, &format!("the first run at {step:?}"), |cx| {
            view.read_with(cx, |v, cx| {
                v.first_run.as_ref().is_some_and(|f| {
                    let f = f.read(cx);
                    f.step == step && f.busy.is_none()
                })
            })
        });
    }

    fn type_setup(view: &Entity<Footplate>, cx: &mut VisualTestContext, field: &str, text: &str) {
        view.update(cx, |v, cx| {
            let first_run = v.first_run.clone().unwrap();
            first_run.update(cx, |f, cx| f.type_in(field, text, cx));
        });
    }

    fn setup_typed(view: &Entity<Footplate>, cx: &mut VisualTestContext, field: &str) -> String {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().unwrap().read(cx).typed_in(field, cx)
        })
    }

    /// The first run's provider buttons: each installed harness's kind
    /// with its button's text.
    fn setup_providers(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Vec<(String, String)> {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().unwrap().read(cx).provider_buttons()
        })
    }

    /// The first run's model pick: each button's picked id (None is the
    /// harness's own choice) with its text.
    fn setup_models(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Vec<(Option<String>, String)> {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().unwrap().read(cx).model_buttons()
        })
    }

    /// The first run's picked model id: None is the harness's own choice.
    fn setup_picked(view: &Entity<Footplate>, cx: &mut VisualTestContext) -> Option<String> {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().unwrap().read(cx).picked_model()
        })
    }

    /// The first run at its second step, with the stand-in answering
    /// `doctor`: the window with no yard, "way here", and "go on" once
    /// the machine is ready. The stand-in's path, for its answers and
    /// its calls.
    #[cfg(unix)]
    fn at_yard<'a>(
        dir: &tempfile::TempDir,
        doctor: &serde_json::Value,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext, PathBuf) {
        use crate::setup::standin;
        use firstrun::Step;

        let (means, program, _) = stand_in_means(dir.path(), true);
        standin::answers(&program, "doctor", 0, doctor);
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);
        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        (view, cx, program)
    }

    /// The first run on a wide window: its column stands as tall as its
    /// rows wrap, and no row starts inside the one above. A column that
    /// stood `w_full` with `max_w` kept the height its text had at full
    /// width once the max clamped it, so the rows below started inside
    /// wrapped text above. Within a pixel, for gpui's rounding to
    /// device pixels.
    #[cfg(unix)]
    #[gpui::test]
    fn the_first_run_s_rows_tile_on_a_wide_window(cx: &mut TestAppContext) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (view, cx, _) = at_yard(&dir, &standin::doctor_ready(), cx);
        cx.simulate_resize(gpui::size(px(1920.), px(1080.)));
        frames(cx);
        // The max clamps: the column stands well under the window's
        // width, so its prose wraps at the column, not the window.
        let window = cx.update(|window, _| window.viewport_size());
        let column = bounds_of(cx, "setup column");
        assert!(
            column.size.width * 2. < window.width,
            "the column is not clamped: {column:?} in {window:?}"
        );
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        // Each row below the one before: the style note under the
        // style buttons, the yardmaster note under the line about
        // changing it later, and the create button under that note.
        let style = bounds_of(cx, "setup style note");
        for key in ["guide", "show", "work", "report"] {
            let button = bounds_of(cx, &format!("setup style {key}"));
            assert!(
                style.top() + px(1.) >= button.bottom(),
                "the style note starts inside the {key} button: {style:?} past {button:?}"
            );
        }
        let about = bounds_of(cx, "setup about you");
        assert!(
            about.top() + px(1.) >= style.bottom(),
            "the about field starts inside the style note: {about:?} past {style:?}"
        );
        let later = bounds_of(cx, "setup change later");
        let note = bounds_of(cx, "setup yardmaster note");
        assert!(
            note.top() + px(1.) >= later.bottom(),
            "the yardmaster note starts inside the line above: {note:?} past {later:?}"
        );
        let create = bounds_of(cx, "setup create");
        assert!(
            create.top() + px(1.) >= note.bottom(),
            "the create button starts inside the yardmaster note: {create:?} past {note:?}"
        );
        // The column holds its rows: it starts at or above the step
        // line and ends at or below the create button.
        let step = bounds_of(cx, "setup step");
        assert!(
            column.top() <= step.top() + px(1.),
            "the column starts below its first row: {column:?} past {step:?}"
        );
        assert!(
            column.bottom() + px(1.) >= create.bottom(),
            "the column ends above its last row: {column:?} past {create:?}"
        );
    }

    /// A fetch is a Mac road from yardr's data. Even if a doctor answer
    /// includes one on Linux, the row stays a list with the vendor's page.
    #[cfg(unix)]
    #[gpui::test]
    fn linux_keeps_a_doctor_fetch_as_a_page_and_never_offers_install(cx: &mut TestAppContext) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (means, program, _) = stand_in_means(dir.path(), false);
        let home = dir.path().join("home");
        standin::answers(&program, "doctor", 1, &standin::doctor_bare(&home));
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);

        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);

        assert!(!drawn(cx, "setup install herdr"));
        assert!(drawn(cx, "setup page herdr"));
        assert!(drawn(cx, "setup get herdr"));
        assert!(!home.join(".local/bin/herdr").exists());

        // A file at the place a fetch would use is not read there either,
        // since nothing is fetched: the row names the program that answers
        // as claude and says nothing of a fetch that stands. (The pane
        // remembers what it drew, so these two were never drawn above.)
        standin::answers(&program, "doctor", 1, &standin::doctor_other(&home));
        keep_runnable(&home.join(".local/bin/claude"));
        click_on(cx, "setup check");
        wait(cx, "the program that answers as claude", |cx| {
            drawn(cx, "setup other claude")
        });
        assert!(!drawn(cx, "setup install claude") && !drawn(cx, "setup shadow claude"));
    }

    /// A file that runs at `place`, made as a fetch leaves one.
    #[cfg(unix)]
    fn keep_runnable(place: &std::path::Path) {
        use std::os::unix::fs::PermissionsExt;

        std::fs::create_dir_all(place.parent().unwrap()).unwrap();
        std::fs::write(place, b"#!/bin/sh\n").unwrap();
        std::fs::set_permissions(place, std::fs::Permissions::from_mode(0o755)).unwrap();
    }

    /// Doctor's version check of a harness shows on its row. One whose flag
    /// failed or hung is installed, with a warning, and setup goes on; one in
    /// a state setup does not know, from a newer doctor, is installed with
    /// no warning.
    #[cfg(unix)]
    #[gpui::test]
    fn a_harness_whose_version_flag_fails_or_hangs_is_installed_with_a_warning(
        cx: &mut TestAppContext,
    ) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (means, program, _) = stand_in_means(dir.path(), false);
        let mut doctor = standin::doctor_ready();
        doctor["machine"][2]["version"] = json!({"state": "fails", "output": "exit status 1"});
        doctor["machine"][3]["version"] = json!({"state": "hangs"});
        doctor["machine"].as_array_mut().unwrap().push(json!({
            "program": "opencode", "for": "a harness a yard can be created on", "found": true,
            "path": "/opt/stand-in/bin/opencode", "harness": "opencode",
            "version": {"state": "asleep", "output": "zzz"}}));
        standin::answers(&program, "doctor", 0, &doctor);
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);

        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);
        for row in ["claude", "codex", "opencode"] {
            assert!(drawn(cx, &format!("setup row {row}")), "{row}");
            assert!(!drawn(cx, &format!("setup other {row}")), "{row}");
            assert!(!drawn(cx, &format!("setup install {row}")), "{row}");
        }
        assert!(drawn(cx, "setup warns claude") && drawn(cx, "setup warns codex"));
        assert!(!drawn(cx, "setup warns opencode"));
        // Nothing waits on them: all three count, and the step goes on.
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        assert_eq!(
            setup_providers(&view, cx)
                .iter()
                .map(|(kind, _)| kind.as_str())
                .collect::<Vec<_>>(),
            ["claude", "codex", "opencode"]
        );
    }

    /// A program that answers its version flag as another harness is said
    /// not to be it, with what it printed, and is not installed. The real
    /// one is fetched to its place, where it stands behind the other, which
    /// herdr starts first: the row offers nothing, since fetching would
    /// change nothing, and says so. It is read again with every check, so
    /// the offer is back once the file is gone. The pane remembers every
    /// selector it ever drew, so what must not be drawn is asked of a window
    /// that never drew it: the file stands from the start.
    #[cfg(unix)]
    #[gpui::test]
    fn a_program_that_answers_as_another_harness_is_named_and_its_fetch_is_not_offered_again(
        cx: &mut TestAppContext,
    ) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (means, program, _) = stand_in_means(dir.path(), true);
        let home = dir.path().join("home");
        standin::answers(&program, "doctor", 1, &standin::doctor_other(&home));
        let fetched = home.join(".local/bin/claude");
        keep_runnable(&fetched);
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);

        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);
        for row in ["git", "herdr", "claude", "codex"] {
            assert!(drawn(cx, &format!("setup row {row}")), "{row}");
        }
        // The row names the program and what it printed, and what keeps the
        // fetched one from running; it offers no fetch and no page, and no
        // word of how it is installed by hand.
        assert!(drawn(cx, "setup other claude") && drawn(cx, "setup shadow claude"));
        assert!(!drawn(cx, "setup install claude"));
        assert!(!drawn(cx, "setup page claude") && !drawn(cx, "setup get claude"));
        assert!(!drawn(cx, "setup warns claude"));
        // Codex has nothing behind anything: its offer stands.
        assert!(drawn(cx, "setup install codex") && !drawn(cx, "setup shadow codex"));
        // Not a harness a yard can be created on.
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Needs));
        assert_eq!(std::fs::read(&fetched).unwrap(), b"#!/bin/sh\n");

        // The file goes, as it does when it is moved out of the way: the
        // check is made again, and the row offers the fetch as it does for
        // a harness that is missing.
        std::fs::remove_file(&fetched).unwrap();
        click_on(cx, "setup check");
        wait(cx, "the offer of claude again", |cx| {
            drawn(cx, "setup install claude")
        });
        assert!(drawn(cx, "setup other claude"));
    }

    /// The first run's terminal step as it stands: what it offers.
    fn setup_reach(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> Option<crate::setup::Reach> {
        view.read_with(cx, |v, cx| {
            v.first_run.as_ref().and_then(|f| f.read(cx).reach())
        })
    }

    /// Every file under `dir` with what is in it: a folder of a test as a
    /// list, to be compared with itself later.
    #[cfg(unix)]
    fn files_under(dir: &std::path::Path) -> Vec<(PathBuf, Vec<u8>)> {
        let mut files = Vec::new();
        let mut dirs = vec![dir.to_path_buf()];
        while let Some(dir) = dirs.pop() {
            for entry in std::fs::read_dir(dir).into_iter().flatten() {
                let path = entry.unwrap().path();
                match path.is_dir() {
                    true => dirs.push(path),
                    false => files.push((path.clone(), std::fs::read(path).unwrap())),
                }
            }
        }
        files.sort();
        files
    }

    /// The first run on a Mac where herdr and claude were fetched to
    /// `~/.local/bin` and the person's shell is `shell`, whose PATH does not
    /// name it: the window with no yard and the means to set one up, herdr
    /// and claude found where fetching puts them.
    #[cfg(unix)]
    fn at_terminal<'a>(
        dir: &tempfile::TempDir,
        shell: &str,
        apple: bool,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        use crate::setup::standin;

        let (mut means, program, _) = stand_in_means(dir.path(), apple);
        let bin = dir.path().join("home/.local/bin");
        let mut doctor = standin::doctor_ready();
        doctor["machine"][0]["path"] = json!(bin.join("herdr"));
        doctor["machine"][2]["path"] = json!(bin.join("claude"));
        standin::answers(&program, "doctor", 0, &doctor);
        // A login shell that is asked for its PATH, which has no
        // `.local/bin` in it.
        means.machine.shell = Some(
            crate::fetch::keep(
                &dir.path().join("shell"),
                shell,
                b"#!/bin/sh\necho /usr/bin:/bin\n",
            )
            .unwrap(),
        );
        means.machine.within = std::time::Duration::from_secs(60);
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);
        (view, cx)
    }

    /// Goes through the first run's first screen to its "go on".
    #[cfg(unix)]
    fn go_on_from_needs(view: &Entity<Footplate>, cx: &mut VisualTestContext) {
        click_on(cx, "way here");
        at_step(view, cx, firstrun::Step::Needs);
        click_on(cx, "setup go on");
    }

    /// The programs fetched to `~/.local/bin` and a terminal that does not
    /// look there: after the programs, a step shows the line and the file
    /// it goes to, and yes adds the line once and goes on to the yard's
    /// form. A second run of setup has no step, though the login shell
    /// answers as it did: a zsh asked with `-l -c` does not read `.zshrc`.
    #[cfg(unix)]
    #[gpui::test]
    fn a_terminal_is_made_to_find_the_programs_on_the_person_s_yes(cx: &mut TestAppContext) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let home = dir.path().join("home");
        let (view, cx) = at_terminal(&dir, "zsh", true, cx);
        go_on_from_needs(&view, cx);
        assert_eq!(step_of(&view, cx), Some(Step::Terminal));
        // Which programs, the line to the letter, and the file by its name.
        let reach = setup_reach(&view, cx).unwrap();
        assert_eq!(reach.named(), "herdr and claude");
        assert_eq!(reach.line, r#"export PATH="$HOME/.local/bin:$PATH""#);
        assert_eq!(reach.shown().as_deref(), Some("~/.zshrc"));
        assert!(drawn(cx, "setup path line"));
        assert!(drawn(cx, "setup path add") && drawn(cx, "setup path later"));
        // A shell whose file is known has a yes and a no, not a go on.
        assert!(!drawn(cx, "setup path go on"));
        // The rows stand as tall as the lines they wrap to, and the buttons
        // as one: a column measured at no width made a paragraph one line
        // and a row of buttons two, and drew the text over the rows below.
        let one = bounds_of(cx, "setup step").size.height;
        for selector in ["setup path why", "setup path where", "setup path note"] {
            let height = bounds_of(cx, selector).size.height;
            assert!(
                height > one * 1.9,
                "{selector} is {height:?}, a line {one:?}"
            );
        }
        let buttons = bounds_of(cx, "setup path add").size.height;
        assert!(
            buttons < one * 1.5,
            "the buttons are {buttons:?}, a line {one:?}"
        );
        // Nothing is written until the person says.
        assert!(!home.join(".zshrc").exists());

        // Yes: the line is the file, once, and the yard's form follows.
        click_on(cx, "setup path add");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        assert_eq!(
            std::fs::read_to_string(home.join(".zshrc")).unwrap(),
            "export PATH=\"$HOME/.local/bin:$PATH\"\n"
        );
        assert_eq!(
            setup_said(&view, cx),
            "Added to ~/.zshrc. A terminal opened from now on finds herdr and claude."
        );
        assert_eq!(setup_reach(&view, cx), None);

        // The second run: the same machine, and no step.
        click_on(cx, "setup leave");
        go_on_from_needs(&view, cx);
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        assert_eq!(
            std::fs::read_to_string(home.join(".zshrc")).unwrap(),
            "export PATH=\"$HOME/.local/bin:$PATH\"\n"
        );

        // A home that has a yard already, which is not running: the step
        // is still first, and what follows it says its own words too.
        std::fs::remove_file(home.join(".zshrc")).unwrap();
        let mut doctor = standin::doctor_ready();
        doctor["yard"] = json!(true);
        doctor["machine"][0]["path"] = json!(home.join(".local/bin/herdr"));
        standin::answers(&dir.path().join("fetched/yardr"), "doctor", 0, &doctor);
        click_on(cx, "setup leave");
        go_on_from_needs(&view, cx);
        assert_eq!(step_of(&view, cx), Some(Step::Terminal));
        click_on(cx, "setup path add");
        assert_eq!(step_of(&view, cx), Some(Step::Start));
        assert_eq!(
            setup_said(&view, cx),
            "Added to ~/.zshrc. A terminal opened from now on finds herdr.\nThis machine has a yard already, which is not running."
        );
    }

    /// Only a Mac has programs fetched to `~/.local/bin`: the same machine
    /// on Linux goes from what it needs to the yard's form, and the login
    /// shell is not asked.
    #[cfg(unix)]
    #[gpui::test]
    fn linux_is_given_no_terminal_step(cx: &mut TestAppContext) {
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (view, cx) = at_terminal(&dir, "zsh", false, cx);
        go_on_from_needs(&view, cx);
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        assert!(!dir.path().join("shell/zsh.asked").exists());
    }

    /// Everything the person has and the settings keep, as files with what
    /// is in them: a step that is declined leaves it as it was.
    #[cfg(unix)]
    fn kept_under(dir: &std::path::Path) -> Vec<(PathBuf, Vec<u8>)> {
        let mut kept = files_under(&dir.join("home"));
        kept.extend(files_under(&dir.join("footplate")));
        kept
    }

    /// No at the step writes, makes and marks nothing, and setup goes on;
    /// the step comes again in the next run. A file that cannot be read is
    /// said so on the step, which stays.
    #[cfg(unix)]
    #[gpui::test]
    fn the_terminal_s_step_can_be_declined_and_writes_nothing_it_may_not(cx: &mut TestAppContext) {
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let home = dir.path().join("home");
        let (view, cx) = at_terminal(&dir, "zsh", true, cx);
        std::fs::write(home.join(".zshrc"), "alias ll='ls -l'").unwrap();
        let before = kept_under(dir.path());

        go_on_from_needs(&view, cx);
        assert_eq!(step_of(&view, cx), Some(Step::Terminal));
        click_on(cx, "setup path later");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        assert_eq!(setup_said(&view, cx), "");
        assert_eq!(kept_under(dir.path()), before);

        // The step comes again, as nothing was marked.
        click_on(cx, "setup leave");
        go_on_from_needs(&view, cx);
        assert_eq!(step_of(&view, cx), Some(Step::Terminal));

        // A file that cannot be read: said so on the step, which stays,
        // and nothing is added; not now goes on, as before.
        std::fs::remove_file(home.join(".zshrc")).unwrap();
        std::fs::create_dir(home.join(".zshrc")).unwrap();
        click_on(cx, "setup path add");
        assert_eq!(step_of(&view, cx), Some(Step::Terminal));
        assert!(
            setup_said(&view, cx).starts_with("~/.zshrc could not be read ("),
            "{}",
            setup_said(&view, cx)
        );
        assert_eq!(std::fs::read_dir(home.join(".zshrc")).unwrap().count(), 0);
        click_on(cx, "setup path later");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
    }

    /// A shell that is not known has the line shown and no yes offered, and
    /// going on leaves every file as it was.
    #[cfg(unix)]
    #[gpui::test]
    fn a_shell_that_is_not_known_is_shown_the_line_and_offered_no_yes(cx: &mut TestAppContext) {
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (view, cx) = at_terminal(&dir, "tcsh", true, cx);
        let before = kept_under(dir.path());
        go_on_from_needs(&view, cx);
        assert_eq!(step_of(&view, cx), Some(Step::Terminal));
        let reach = setup_reach(&view, cx).unwrap();
        assert_eq!((reach.file, reach.shell.as_deref()), (None, Some("tcsh")));
        assert_eq!(reach.line, r#"export PATH="$HOME/.local/bin:$PATH""#);
        assert!(drawn(cx, "setup path line") && drawn(cx, "setup path go on"));
        assert!(!drawn(cx, "setup path add") && !drawn(cx, "setup path later"));
        click_on(cx, "setup path go on");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));
        assert_eq!(kept_under(dir.path()), before);
    }

    /// The third way, from no yard to talking with the yardmaster: yardr
    /// is had, what the machine lacks is listed from doctor's JSON with
    /// how each comes, the yard is created without being started, the
    /// harness's login is led by what yardr asks for, the yard is started,
    /// a folder becomes its depot with a first bead, and the yardmaster's
    /// conversation is open. Every step is a command of the stand-in for
    /// yardr, with a PATH made from doctor's data.
    #[cfg(unix)]
    #[gpui::test]
    fn no_yard_offers_to_set_one_up_here_and_ends_talking_with_the_yardmaster(
        cx: &mut TestAppContext,
    ) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (means, program, opened) = stand_in_means(dir.path(), true);
        let home = dir.path().join("home");
        standin::answers(&program, "doctor", 1, &standin::doctor_bare(&home));
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);
        assert!(
            drawn(cx, "way here")
                && drawn(cx, "way near")
                && drawn(cx, "way far")
                && drawn(cx, "way hosted")
        );
        assert!(!drawn(cx, "setup step"));

        // What this needs: doctor's rows, each with how it comes.
        click_on(cx, "way here");
        at_step(&view, cx, Step::Needs);
        assert!(drawn(cx, "setup step"));
        for row in ["git", "herdr", "claude", "opencode"] {
            assert!(drawn(cx, &format!("setup row {row}")), "{row}");
        }
        // herdr has a way yardr names; the harnesses here have a page, and
        // yardr's words for installing them by hand.
        assert!(drawn(cx, "setup install herdr") && !drawn(cx, "setup install claude"));
        assert!(drawn(cx, "setup get claude") && !drawn(cx, "setup get herdr"));
        assert!(!drawn(cx, "setup install git") && !drawn(cx, "setup page git"));
        click_on(cx, "setup page claude");
        assert_eq!(*opened.borrow(), ["https://claude.com/claude-code"]);
        // Nothing goes on while herdr and a harness are missing.
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Needs));
        // What is started finds what doctor found: the login shell's
        // directory and the one a program is fetched to.
        let wide = format!(
            "/usr/bin:/bin:{}:/opt/stand-in/bin",
            home.join(".local/bin").display()
        );
        let path = view.read_with(cx, |v, cx| v.first_run.as_ref().unwrap().read(cx).path());
        assert_eq!(path, Some(wide.clone().into()));

        // They are installed: checked again, a herdr whose server is down
        // waits and keeps nothing back.
        standin::answers(&program, "doctor", 0, &standin::doctor_ready());
        click_on(cx, "setup check");
        wait(cx, "herdr's server waiting", |cx| {
            drawn(cx, "setup server waits")
        });
        click_on(cx, "setup go on");
        assert_eq!(step_of(&view, cx), Some(Step::Yard));

        // Your yard: the login name stands in the field, the first
        // provider is chosen, and one with no login recipe says so.
        assert_eq!(setup_typed(&view, cx, "your name"), "jo");
        assert!(drawn(cx, "setup provider claude") && drawn(cx, "setup provider codex"));
        assert!(drawn(cx, "setup style guide") && drawn(cx, "setup style report"));
        // The row is the scale it is: the question, the four numbered in
        // order, and the line that they change later.
        assert!(drawn(cx, "setup savvy") && drawn(cx, "setup change later"));
        let left = |key: &str| bounds_of(cx, &format!("setup style {key}")).origin.x;
        let places: Vec<_> = ["guide", "show", "work", "report"]
            .into_iter()
            .map(left)
            .collect();
        assert!(places.windows(2).all(|pair| pair[0] < pair[1]));
        // The name is typed where the focus is: every letter of it.
        cx.simulate_keystrokes("secondary-a");
        cx.simulate_input("Jo Deed");
        assert_eq!(setup_typed(&view, cx, "your name"), "Jo Deed");
        type_setup(&view, cx, "about you", "I teach history");
        standin::answers(&program, "init", 0, &json!({"harness": "claude"}));
        cx.simulate_keystrokes("enter");
        at_step(&view, cx, Step::Login);
        let calls = standin::calls(&program);
        let yard = dir.path().display();
        assert_eq!(
            calls.last().unwrap(),
            &format!(
                "[init] [--harness=claude] [--operator=Jo Deed] [--yardmaster=yardmaster] [--style=guide] [--about=I teach history] [--json] [--home] [{yard}] [--actor=Jo Deed]"
            )
        );

        // The login: the ways yardr names as buttons, the page as a
        // button, the code in a field that keeps nothing, and the
        // question before the one real call.
        click_on(cx, "setup log in");
        wait(cx, "the ways to log in", |cx| drawn(cx, "setup method 1"));
        click_on(cx, "setup method 0");
        wait(cx, "the page and the code's field", |cx| {
            drawn(cx, "setup page") && drawn(cx, "setup code")
        });
        click_on(cx, "setup page");
        assert_eq!(
            opened.borrow()[1],
            "https://claude.com/cai/oauth/authorize?code=true"
        );
        // The field has the keys, and shows none of what is typed.
        cx.simulate_input("good#code");
        assert_eq!(setup_typed(&view, cx, "code"), "good#code");
        cx.simulate_keystrokes("enter");
        assert_eq!(setup_typed(&view, cx, "code"), "");
        wait(cx, "the question before the real call", |cx| {
            drawn(cx, "setup prove")
        });
        click_on(cx, "setup prove");
        at_step(&view, cx, Step::Start);
        assert_eq!(setup_said(&view, cx), "Logged in, and the harness answers.");
        assert_eq!(
            standin::answered(&program),
            [
                r#"{"choose":"Claude subscription"}"#,
                r#"{"input":"good#code"}"#,
                r#"{"confirm":true}"#
            ]
        );

        // Start: what yardr could not start is said in its words, and the
        // yard that then runs is followed by itself, under the first run.
        standin::answers(
            &program,
            "up.1",
            1,
            &json!({"up": false, "parts": [
                {"part": "herdr", "running": false, "error": "its server did not come up.", "do": "Look at herdr-server.log."}]}),
        );
        standin::answers(&program, "up", 0, &json!({"up": true, "parts": []}));
        click_on(cx, "setup start");
        wait(cx, "what could not be started", |cx| {
            setup_said(&view, cx) == "herdr: its server did not come up. Look at herdr-server.log."
        });
        assert_eq!(step_of(&view, cx), Some(Step::Start));
        let near = Yard::start_at(&dir.path().join("yard.sock"));
        a_yard_of_jo(&near);
        click_on(cx, "setup start");
        at_step(&view, cx, Step::Depot);
        wait(cx, "the yard that was started", |cx| {
            view.read_with(cx, |v, _| v.down.is_none() && v.model.is_some())
        });
        assert!(view.read_with(cx, |v, _| v.first_run.is_some()));

        // The folder: its name is offered, and a folder that is no git
        // checkout has no branch. The import's questions are answered.
        let folder = dir.path().join("My Essays");
        std::fs::create_dir(&folder).unwrap();
        view.update(cx, |v, cx| {
            let first_run = v.first_run.clone().unwrap();
            first_run.update(cx, |f, cx| f.chose(&folder, cx));
        });
        assert_eq!(setup_typed(&view, cx, "name"), "my-essays");
        assert_eq!(setup_typed(&view, cx, "base branch"), "");
        standin::answers(
            &program,
            "depot-add",
            0,
            &json!({"name": "my-essays", "kind": "dir"}),
        );
        standin::answers(
            &program,
            "depot-init.1",
            2,
            &json!({"error": "depot init cannot ask without a terminal",
                    "missing": ["--bind builders=<kind>[:<model>]", "--members decisions=<users>"]}),
        );
        standin::answers(
            &program,
            "depot-init",
            0,
            &json!({"result": {"created": 9}}),
        );
        click_on(cx, "setup set up");
        at_step(&view, cx, Step::Bead);

        // The first bead, and the yardmaster's conversation.
        type_setup(&view, cx, "title", "A first draft");
        type_setup(&view, cx, "done when", "It reads well aloud.");
        standin::answers(&program, "bead-create", 0, &json!({"id": "my-essays-1a2b"}));
        standin::answers(
            &program,
            "bead-advance",
            0,
            &json!({"id": "my-essays-1a2b"}),
        );
        standin::answers(&program, "subscribe", 0, &json!([]));
        click_on(cx, "setup hand on");
        wait(cx, "the yardmaster's conversation", |cx| {
            open_row(&view, cx) == Some(Selected::Conversation("yardmaster".into()))
        });
        assert!(view.read_with(cx, |v, _| v.first_run.is_none()));
        let tail = format!("[--json] [--home] [{yard}] [--actor=Jo Deed]");
        let calls = standin::calls(&program);
        let after_init: Vec<&str> = calls
            .iter()
            .skip_while(|call| !call.starts_with("[harness]"))
            .map(String::as_str)
            .collect();
        assert_eq!(
            after_init,
            [
                format!("[harness] [login] {tail} [--] [claude]"),
                format!("[up] {tail}"),
                format!("[up] {tail}"),
                format!(
                    "[depot] [add] {tail} [--] [my-essays] [{}]",
                    folder.display()
                ),
                format!("[depot] [init] [--yes] {tail} [--] [my-essays]"),
                format!(
                    "[depot] [init] [--yes] [--bind] [builders=claude] [--members] [decisions=Jo Deed] {tail} [--] [my-essays]"
                ),
                format!(
                    "[bead] [create] [--depot=my-essays] [-b] [It reads well aloud.] {tail} [--] [A first draft]"
                ),
                format!("[bead] [advance] [--to=new] {tail} [--] [my-essays-1a2b]"),
                format!(
                    "[subscribe] [--done] [--where=depot=my-essays] {tail} [--] [Jo Deed] [yardr]"
                ),
                // The first run over, the switch reads what it made:
                // doctor widening its PATH, then status. This run's yard
                // takes no home flag.
                "[doctor] [--json]".to_string(),
                "[status] [--json]".to_string(),
            ]
        );
        // Every one of the first run's with the PATH doctor's data made;
        // the switch's two read with its own, unwidened here.
        let paths = standin::paths(&program);
        assert!(
            paths[1..paths.len() - 2].iter().all(|path| *path == wide),
            "{paths:?}"
        );
        assert_eq!(
            &paths[paths.len() - 2..],
            ["/usr/bin:/bin", "/usr/bin:/bin"]
        );
        // The line has the keys, in the yardmaster's conversation.
        cx.simulate_input("hello");
        assert_eq!(typed(&view, cx), "hello");
    }

    /// The second step names the providers and picks the yardmaster's
    /// model from the chosen one's offers: the recommended one stands
    /// picked, and creating the yard sends its id.
    #[cfg(unix)]
    #[gpui::test]
    fn the_second_step_picks_the_yardmaster_s_model_from_the_provider_s_offers(
        cx: &mut TestAppContext,
    ) {
        use crate::setup::standin;
        use firstrun::Step;

        let dir = tempfile::tempdir().unwrap();
        let (view, cx, program) = at_yard(&dir, &standin::doctor_ready_with_offers(), cx);

        // The providers by their labels, the one with no login recipe
        // saying it needs a terminal once.
        assert!(drawn(cx, "setup provider claude") && drawn(cx, "setup provider codex"));
        assert_eq!(
            setup_providers(&view, cx),
            [
                ("claude".to_string(), "Anthropic · Claude Code".to_string()),
                (
                    "codex".to_string(),
                    "OpenAI · Codex (needs a terminal once to log in)".to_string()
                ),
            ]
        );
        // The model pick: the recommended offer stands picked and marked,
        // beside the harness's own choice.
        assert!(
            drawn(cx, "setup model opus")
                && drawn(cx, "setup model fable")
                && drawn(cx, "setup model sonnet")
                && drawn(cx, "setup model own")
        );
        assert_eq!(
            setup_models(&view, cx),
            [
                (
                    Some("opus".to_string()),
                    "Opus 5.5 (recommended)".to_string()
                ),
                (Some("fable".to_string()), "Fable 5.1".to_string()),
                (Some("sonnet".to_string()), "Sonnet 5".to_string()),
                (None, "the harness's own choice".to_string()),
            ]
        );
        assert_eq!(setup_picked(&view, cx), Some("opus".to_string()));

        // Creating the yard sends the picked id.
        standin::answers(&program, "init", 0, &json!({"harness": "claude"}));
        click_on(cx, "setup create");
        at_step(&view, cx, Step::Login);
        let yard = dir.path().display().to_string();
        assert_eq!(
            standin::calls(&program).last().unwrap(),
            &format!(
                "[init] [--harness=claude] [--operator=jo] [--yardmaster=yardmaster] [--style=guide] [--model=opus] [--json] [--home] [{yard}] [--actor=jo]"
            )
        );
    }

