    /// Stop with no agent stops at once and asks nothing: down without
    /// the flag, and no second call with it.
    #[cfg(unix)]
    #[gpui::test]
    fn stop_with_no_agent_stops_at_once_and_asks_nothing(cx: &mut TestAppContext) {
        use crate::setup::standin;

        let dir = tempfile::tempdir().unwrap();
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        let (means, program, _) = stand_in_means(dir.path(), true);
        standin::answers(&program, "doctor", 0, &standin::doctor_ready());
        standin::answers(&program, "status", 0, &standin::status(true, false));
        standin::answers(&program, "down.1", 0, &standin::down_done());
        view.update(cx, |v, _| v.means = means);
        view.update(cx, |v, cx| v.refresh_switch(cx));
        wait(cx, "the running yard read", |cx| {
            settled(&view, cx) && view.read_with(cx, |v, _| v.switch_status.is_some())
        });
        click_on(cx, "switch stop");
        wait(cx, "down run", |cx| {
            settled(&view, cx)
                && standin::calls(&program)
                    .iter()
                    .any(|call| call.starts_with("[down]"))
        });
        assert!(!drawn(cx, "stop question"));
        view.read_with(cx, |v, _| assert!(v.switch_question.is_none()));
        let downs: Vec<String> = standin::calls(&program)
            .into_iter()
            .filter(|call| call.starts_with("[down]"))
            .collect();
        assert_eq!(downs, ["[down] [--json]".to_string()]);

        standin::answers(&program, "status", 0, &standin::status(false, false));
        yard.stop();
        wait(cx, "the yard stopped", |cx| {
            settled(&view, cx) && view.read_with(cx, |v, _| v.down.is_some())
        });
        assert!(drawn(cx, "switch start"));
    }

    /// Switching "start at login" off where the yard runs starts the
    /// daemon again, which removing its service stopped: the yard runs on.
    #[cfg(unix)]
    #[gpui::test]
    fn unchecking_start_at_login_starts_the_daemon_again_where_the_yard_runs(
        cx: &mut TestAppContext,
    ) {
        use crate::setup::standin;

        let dir = tempfile::tempdir().unwrap();
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        let (view, cx) = opened(&yard, &["Shall I land it?"], cx);
        let (means, program, _) = stand_in_means(dir.path(), true);
        standin::answers(&program, "doctor", 0, &standin::doctor_ready());
        standin::answers(&program, "status", 0, &standin::status(true, true));
        standin::answers(
            &program,
            "daemon-uninstall",
            0,
            &json!({"kind": "daemon", "name": "d", "file": "/tmp/d",
                    "removed": true, "unloaded": true}),
        );
        standin::answers(&program, "up.1", 0, &json!({"up": true, "parts": []}));
        view.update(cx, |v, _| v.means = means);
        view.update(cx, |v, cx| v.refresh_switch(cx));
        wait(cx, "the login read on", |cx| {
            settled(&view, cx)
                && view.read_with(cx, |v, _| {
                    v.switch_status.as_ref().unwrap().starts_at_login()
                })
        });
        click_on(cx, "settings");
        click_on(cx, "settings section yards");
        click_on(cx, "login off");
        wait(cx, "the daemon started again", |cx| {
            settled(&view, cx)
                && standin::calls(&program)
                    .iter()
                    .any(|call| call.starts_with("[up]"))
        });
        // The uninstall first, then up starting the daemon again.
        let calls = standin::calls(&program);
        let uninstall = calls
            .iter()
            .position(|call| call.starts_with("[daemon]"))
            .unwrap();
        let up = calls
            .iter()
            .position(|call| call.starts_with("[up]"))
            .unwrap();
        assert!(uninstall < up, "{calls:?}");
        // The yard runs on throughout.
        view.read_with(cx, |v, _| assert!(v.down.is_none() && v.model.is_some()));

        standin::answers(&program, "status", 0, &standin::status(true, false));
        view.update(cx, |v, cx| v.refresh_switch(cx));
        wait(cx, "the login read off", |cx| {
            settled(&view, cx)
                && view.read_with(cx, |v, _| {
                    !v.switch_status.as_ref().unwrap().starts_at_login()
                })
        });
    }

    /// Where there is no yardr the first run says so and offers its
    /// installer, which runs on the person's word alone, shows what it
    /// prints, and where it fails says what it said and can be tried again.
    /// A program that cannot be fetched is said so, and Esc leaves the first
    /// run for the first screen.
    #[cfg(unix)]
    #[gpui::test]
    fn a_missing_yardr_is_installed_on_the_person_s_word(cx: &mut TestAppContext) {
        use crate::setup::standin;
        use firstrun::Step;
        use std::sync::atomic::{AtomicUsize, Ordering};

        let dir = tempfile::tempdir().unwrap();
        let (mut means, program, _) = stand_in_means(dir.path(), true);
        means.yardr = Arc::new(|| Err(fetch::NOT_THERE.to_string()));
        let tries = Arc::new(AtomicUsize::new(0));
        let (installed, tried) = (program.clone(), tries.clone());
        means.install = Arc::new(move |_| match tried.fetch_add(1, Ordering::SeqCst) {
            0 => Err("The installer of yardr failed. It said: no curl".to_string()),
            _ => Ok(installed.clone()),
        });
        let mut doctor = standin::doctor_bare(&dir.path().join("home"));
        // Nothing listens there: the fetch fails without leaving this
        // machine.
        doctor["machine"][0]["fetch"]["url"] = json!("http://127.0.0.1:1/herdr");
        standin::answers(&program, "doctor", 1, &doctor);
        let (view, cx) = no_yard(dir.path(), cx);
        view.update(cx, |v, _| v.means = means);

        click_on(cx, "way here");
        wait(cx, "that there is no yardr", |cx| {
            setup_said(&view, cx) == fetch::NOT_THERE
        });
        assert_eq!(step_of(&view, cx), Some(Step::Yardr));
        assert!(drawn(cx, "setup again") && !drawn(cx, "setup check"));
        assert_eq!(tries.load(Ordering::SeqCst), 0);
        assert_eq!(standin::calls(&program), Vec::<String>::new());

        click_on(cx, "setup again");
        wait(cx, "the installer's words", |cx| {
            setup_said(&view, cx).ends_with("It said: no curl")
        });
        assert_eq!(step_of(&view, cx), Some(Step::Yardr));
        assert!(drawn(cx, "setup again"));
        assert_eq!(standin::calls(&program), Vec::<String>::new());

        click_on(cx, "setup again");
        at_step(&view, cx, Step::Needs);
        assert_eq!(standin::calls(&program).len(), 2);

        click_on(cx, "setup install herdr");
        wait(cx, "that herdr was not fetched", |cx| {
            setup_said(&view, cx)
                .starts_with("herdr was not fetched from 127.0.0.1:1: it does not answer")
        });
        assert!(!dir.path().join("home/.local/bin/herdr").exists());

        // Esc leaves it: the first screen, with its ways, and the yard
        // still asked for.
        cx.simulate_keystrokes("escape");
        assert!(view.read_with(cx, |v, _| v.first_run.is_none()));
        assert!(drawn(cx, "way here") && drawn(cx, "away why"));
        assert_eq!(view.read_with(cx, |v, _| v.away), Away::Trying);
    }

    /// The other way: a yard at an address, by a device pairing's code,
    /// from where there is no yard and with no settings shown.
    #[gpui::test]
    fn no_yard_offers_a_pairing_with_a_yard_at_an_address(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let (view, cx) = no_yard(dir.path(), cx);
        click_on(cx, "way far");
        assert!(drawn(cx, "yard name") && drawn(cx, "yard address") && drawn(cx, "yard code"));
        assert!(!drawn(cx, "yard socket"));
        // No pairing is open at the yard: said under the fields.
        type_in(&view, cx, "far", far.address(), "K7QM-2XPD");
        click_on(cx, "yard pair");
        wait(cx, "that no pairing is open", |cx| {
            yard_said(&view, cx).starts_with("No pairing is open at this yard")
        });
        assert!(drawn(cx, "yard said"));
        assert!(!file.exists());
        // The operator opens one: the code pairs this device, and the
        // yard is opened as that device.
        far.pair("K7QM-2XPD");
        click_on(cx, "yard pair");
        wait(cx, "the yard that was paired", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert_eq!(view.read_with(cx, |v, _| v.down.clone()), None);
        assert!(!settings_open(&view, cx));
        assert_eq!(open_yard(&view, cx), "far");
        // Its calls are plain, and neither the message nor the list's row
        // says otherwise.
        assert_sealed_alike(&view, cx, "far", false);
        let kept = Settings::read(&file);
        assert_eq!(
            kept.yards[1],
            settings::Yard::far("far", far.address(), "yard-far.token")
        );
        assert_eq!(kept.open, "far");
        assert_eq!(
            yard::read_token(&dir.path().join("footplate/yard-far.token")).unwrap(),
            "yardr-dev-paired-1"
        );
        assert_eq!(far.devices(), [crate::fake::TOKEN, "yardr-dev-paired-1"]);
        // A yard reached direct keeps its code-only pairing: no run of the
        // PAKE, so no key of the device's is pinned at the yard and none
        // is kept here beside the token.
        assert_eq!(far.pinned_key("yardr-dev-paired-1"), None);
        assert!(!yard::key_path(&dir.path().join("footplate/yard-far.token")).exists());
    }

    /// A yard at an address paired by the QR's four fields, key and all: the
    /// code is redeemed sealed and the key kept beside the token, but a yard
    /// reached direct is called plain, so the message says nothing of sealed
    /// calls, as the list's row says nothing of them. The pairings of a
    /// hosted yard, which is called sealed, say both.
    #[gpui::test]
    fn no_yard_pairing_a_yard_at_an_address_by_its_key_says_nothing_of_sealed_calls(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let token = dir.path().join("footplate/yard-far.token");
        let far = Yard::start_tcp();
        a_far_yard_of_jo(&far);
        let (view, cx) = no_yard(dir.path(), cx);
        click_on(cx, "way far");
        far.pair("K7QM-2XPD");
        // The QR's text whole, with its third field empty: a yard reached
        // direct has no edge to name one of an account's yards.
        let qr = format!("{}#K7QM-2XPD##{}", far.address(), far.channel_public());
        type_in(&view, cx, "far", &qr, "");
        click_on(cx, "yard pair");
        wait(cx, "the pairing", |cx| {
            yard_said(&view, cx).starts_with("Paired:")
        });
        assert_sealed_alike(&view, cx, "far", false);
        // The pairing was sealed all the same: the yard pinned this device's
        // key, and the yard's is kept beside the token.
        let kept = yard::read_token(&token).unwrap();
        assert!(far.pinned_key(&kept).is_some());
        let channel = yard::channel_for(&token, &api::Address::parse(far.address()).unwrap())
            .unwrap()
            .unwrap();
        assert_eq!(
            channel.yard_public,
            crate::e2e::parse_channel_public(&far.channel_public()).unwrap()
        );
        // The yard is opened with the device's token in the clear, as a
        // yard reached direct is.
        wait(cx, "the yard that was paired", |cx| {
            texts(&view, cx) == ["From afar."]
        });
        assert!(
            far.last_request()
                .contains(&format!("Authorization: Bearer {kept}\r\n")),
            "{}",
            far.last_request()
        );
    }

    /// From where there is no yard, a pairing's http address off this
    /// machine is refused under the fields, in docs/yards.md's words, the
    /// moment pair is pressed: the button is never silent, nothing is
    /// sent, and the fields stay filled for the fix.
    #[gpui::test]
    fn no_yard_refuses_a_pairing_s_http_address_off_this_machine(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let (view, cx) = no_yard(dir.path(), cx);
        click_on(cx, "way far");
        type_in(
            &view,
            cx,
            "",
            "http://droplet-yard.tail5cf2e8.ts.net:8790",
            "K7QM-2XPD",
        );
        click_on(cx, "yard pair");
        let said = yard_said(&view, cx);
        assert!(
            said.contains("plain http is for a yard on this machine alone")
                && said.contains("Give the https:// address"),
            "{said}"
        );
        assert!(drawn(cx, "yard said"));
        // The line stands directly under the button, above the help: where
        // a person looks the moment pair is pressed.
        let pair = bounds_of(cx, "yard pair").origin.y;
        let said = bounds_of(cx, "yard said").origin.y;
        let help = bounds_of(cx, "yard help").origin.y;
        assert!(said > pair && help > said);
        // Nothing was sent: no pairing is in flight, no yard was kept.
        view.read_with(cx, |v, _| assert!(!v.pairing));
        assert!(!file.exists());
        // The fields stay filled, so the address can be fixed where it is.
        view.read_with(cx, |v, cx| {
            assert_eq!(
                v.address.read(cx).text().to_string(),
                "http://droplet-yard.tail5cf2e8.ts.net:8790"
            );
            assert_eq!(v.code.read(cx).text().to_string(), "K7QM-2XPD");
        });
    }

    /// From where there is no yard, a pairing with a yard that answers
