    /// The window goes on asking for the yard that is away while a way's
    /// fields are open: started, it answers under them. The fields and
    /// the screen stand until esc leaves them, and the screen says the
    /// yard answers again. What is typed stays in the field; esc opens
    /// the yard, and the line has the keys.
    #[cfg(unix)]
    #[gpui::test]
    fn no_yard_is_tried_again_while_a_way_is_open(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let (view, cx) = no_yard(dir.path(), cx);
        // The switch last read a stopped yard. Once the socket answers,
        // its status is up even though the away screen stays for the form.
        view.update(cx, |v, cx| {
            v.switch_status =
                Some(serde_json::from_value(crate::setup::standin::status(false, false)).unwrap());
            cx.notify();
        });
        assert!(view.read_with(cx, |v, _| v.yard_is_stopped()));
        click_on(cx, "way near");
        cx.simulate_input("second home");
        let near = Yard::start_at(&dir.path().join("yard.sock"));
        a_yard_of_jo(&near);
        wait(cx, "that the yard answers again", |cx| {
            drawn(cx, "away answers")
        });
        // The fields and the screen stand: the yard is not opened by
        // itself under the fingers.
        assert_eq!(
            view.read_with(cx, |v, _| v.adding.clone()),
            Some(Adding::Near)
        );
        assert!(view.read_with(cx, |v, _| v.down.is_some()));
        assert!(drawn(cx, "yard name"));
        assert!(!drawn(cx, "rows"));
        assert!(view.read_with(cx, |v, _| !v.yard_is_stopped() && !v.sets_up_here()));
        // What is typed now is the field's, not the line's, and the
        // yard that came back has no mail.
        cx.simulate_input("hello");
        view.read_with(cx, |v, cx| {
            assert_eq!(v.yard_name.read(cx).text().to_string(), "second homehello");
        });
        assert_eq!(typed(&view, cx), "");
        assert_eq!(near.asked("Mail"), Vec::<Value>::new());
        // Esc leaves the fields, and the yard that answered opens: the
        // line has the keys.
        cx.simulate_keystrokes("escape");
        assert_eq!(view.read_with(cx, |v, _| v.down.clone()), None);
        assert_eq!(open_yard(&view, cx), "this machine");
        assert_eq!(texts(&view, cx), ["Shall I land it?"]);
        cx.simulate_input("hello");
        assert_eq!(typed(&view, cx), "hello");
        assert_eq!(near.asked("Mail"), Vec::<Value>::new());
    }

    /// If the yard goes away again under the still-open form, the answer
    /// notice clears and retrying returns. A later answer still preserves
    /// the form and its focus.
    #[cfg(unix)]
    #[gpui::test]
    fn no_yard_keeps_its_fields_through_a_flap(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let (view, cx) = no_yard(dir.path(), cx);
        click_on(cx, "way near");
        cx.simulate_input("second home");
        let near = Yard::start_at(&dir.path().join("yard.sock"));
        a_yard_of_jo(&near);
        wait(cx, "that the yard answers again", |cx| {
            drawn(cx, "away answers")
        });
        assert!(view.read_with(cx, |v, _| v.answers_under_adding()));
        assert!(view.read_with(cx, |v, _| { !v.unreached.contains_key(&v.yard) }));

        near.stop();
        wait(cx, "that the yard is away again", |cx| {
            view.read_with(cx, |v, _| {
                v.unreached.contains_key(&v.yard) && !v.answers_under_adding()
            })
        });
        assert!(view.read_with(cx, |v, _| {
            v.unreached.contains_key(&v.yard) && !v.answers_under_adding()
        }));
        assert!(view.read_with(cx, |v, _| {
            v.adding == Some(Adding::Near) && v.down.is_some()
        }));

        let near = Yard::start_at(&dir.path().join("yard.sock"));
        a_yard_of_jo(&near);
        wait(cx, "that the yard answers after the flap", |cx| {
            view.read_with(cx, |v, _| v.answers_under_adding())
        });
        assert!(view.read_with(cx, |v, _| v.answers_under_adding()));
        cx.simulate_input("hello");
        view.read_with(cx, |v, cx| {
            assert_eq!(v.yard_name.read(cx).text().to_string(), "second homehello");
        });
        assert_eq!(typed(&view, cx), "");
        assert_eq!(near.asked("Mail"), Vec::<Value>::new());
    }

    /// A pairing's code typed while the yard is away stays the field's
    /// when the yard answers: its tail lands in no line, and the enter
    /// meant for pair sends no mail. The fields stay filled for the fix.
    #[cfg(unix)]
    #[gpui::test]
    fn no_yard_keeps_a_pairing_s_code_while_the_yard_answers(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        // A loopback address nothing answers at: plain http is allowed on
        // this machine, so the code goes, and the connection says no.
        let far = Yard::start_tcp();
        let address = far.address().to_string();
        far.stop();
        let (view, cx) = no_yard(dir.path(), cx);
        click_on(cx, "way far");
        type_in(&view, cx, "droplet", &address, "");
        click_on(cx, "yard code");
        cx.simulate_input("K7QM-");
        let near = Yard::start_at(&dir.path().join("yard.sock"));
        a_yard_of_jo(&near);
        wait(cx, "that the yard answers again", |cx| {
            drawn(cx, "away answers")
        });
        // The tail of the code is the field's, and enter is the field's:
        // the code goes to the yard at the address, which says no, and
        // the yard that came back has neither mail nor an answer.
        cx.simulate_input("2XPD");
        view.read_with(cx, |v, cx| {
            assert_eq!(v.code.read(cx).text().to_string(), "K7QM-2XPD");
        });
        assert_eq!(typed(&view, cx), "");
        cx.simulate_keystrokes("enter");
        wait(cx, "that the yard does not answer", |cx| {
            yard_said(&view, cx).starts_with("the yard does not answer")
        });
        assert!(drawn(cx, "yard said"));
        view.read_with(cx, |v, cx| {
            assert_eq!(v.code.read(cx).text().to_string(), "K7QM-2XPD");
        });
        assert_eq!(typed(&view, cx), "");
        assert_eq!(near.asked("Mail"), Vec::<Value>::new());
        assert_eq!(near.asked("AnswerAsk"), Vec::<Value>::new());
        assert_eq!(near.asked("AddNote"), Vec::<Value>::new());
    }

    /// What the yard says a secret ask asks for.
    const BOOKS_LINE: &str =
        "a secret: BOOKS_TOKEN, for the source books (https://books.example.com)";

    /// A value as a person has it on the clipboard.
    const VALUE: &str = "bk-live-3f9a-7Qx";

    fn secret_of(env: &[&str]) -> Value {
        json!({"source": "books", "env": env, "line": BOOKS_LINE})
    }

    /// The secret ask 7 on bead-s as the queue lists it, open or in `state`.
    fn queued_secret(env: &[&str], ask: u64, state: &str, given: &[&str]) -> Value {
        let mut queued = json!({
            "bead": "bead-s", "bead_title": "The books", "topic": "", "ask": ask,
            "question": "The token for the books", "asker": "yardmaster",
            "since": "2026-10-10T10:00:00Z", "secret": secret_of(env)
        });
        if !state.is_empty() {
            queued["state"] = json!(state);
            queued["given"] = json!(given);
        }
        queued
    }

    fn bead_secret(env: &[&str], asks: &[u64]) -> String {
        let asks: Vec<Value> = asks
            .iter()
            .map(|ask| {
                json!({"ask": ask, "to": "jo", "asker": "yardmaster",
                       "since": "2026-10-10T10:00:00Z",
                       "question": "The token for the books",
                       "context": ["Create one in the books' settings."],
                       "options": [], "state": "open", "secret": secret_of(env)})
            })
            .collect();
        json!({"result": {"id": "bead-s", "title": "The books", "body": "The body.",
                          "stage": "new", "labels": [], "notes": [], "asks": asks}})
        .to_string()
    }

    /// The window on a yard whose one open ask is the secret ask 7 on
    /// bead-s for `env`, its card open and read, the settings kept in
    /// `file`.
    fn opened_on_a_secret_ask<'a>(
        yard: &Yard,
        env: &[&str],
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [queued_secret(env, 7, "", &[])], "decided": []}})
                .to_string(),
        );
        yard.answer("Bead", &bead_secret(env, &[7]));
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// The window on a yard whose one open ask is the secret ask 7 on
    /// bead-s for `env`, marked no secret, its card open and read, the
    /// settings kept in `file`.
    fn opened_on_an_unconcealed_secret_ask<'a>(
        yard: &Yard,
        env: &[&str],
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        let mut open = queued_secret(env, 7, "", &[]);
        open["concealed"] = json!(false);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [open], "decided": []}}).to_string(),
        );
        yard.answer("Bead", &bead_secret(env, &[7]));
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// The window at `at`, a yard whose one open ask is on bead-s, with
    /// that ask's card open and read.
    fn opened_on_the_ask<'a>(
        at: Env,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        let (view, cx) = opened_at(at, file, cx);
        wait(cx, "the decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-s".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-s"));
        cx.run_until_parked();
        (view, cx)
    }

    /// What is typed in the field of a secret, what the field draws of it,
    /// and what it says while empty.
    fn secret_field(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
    ) -> (String, String, String) {
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        view.read_with(cx, |v, cx| {
            let field = v.secret.read(cx);
            let (drawn, says) = field.drawn();
            (field.text().to_string(), drawn, says)
        })
    }

    /// Everything the window keeps or says that is not the field of a
    /// secret: the line, the drafts, the words of the asks, the notice,
    /// the cards' refusals, the settings and every file beside them.
    fn kept_outside_the_field(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        dir: &std::path::Path,
    ) -> String {
        fn files(dir: &std::path::Path, all: &mut String) {
            for entry in std::fs::read_dir(dir).into_iter().flatten().flatten() {
                let path = entry.path();
                if path.is_dir() {
                    files(&path, all);
                } else {
                    all.push_str(&String::from_utf8_lossy(&std::fs::read(&path).unwrap()));
                }
            }
        }
        let mut kept = view.read_with(cx, |v, cx| {
            format!(
                "{:?} {:?} {:?} {:?} {:?} {:?} {:?} {:?} {:?} {:?}",
                v.line.read(cx).text(),
                v.line.read(cx).drawn(),
                v.drafts,
                v.ask_words,
                v.model.as_ref().map(|m| m.notice.clone()),
                v.refused,
                v.settings,
                v.yard_said,
                v.down,
                v.secret.read(cx).drawn(),
            )
        });
        files(dir, &mut kept);
        kept
    }

    /// A secret ask's card: the yard's line and a field that shows marks
    /// in place of the words line. Paste works and nothing copies out;
    /// Enter calls `GiveSecret` and the field is emptied whatever is
    /// answered; what the yard did not take is said on the card, and a
    /// call that ends without an answer says the value may be written; a
    /// yard without the call sends the person to a terminal. The value is
    /// in no draft, no setting, no notice and no refusal at any point.
    #[gpui::test]
    fn a_secret_is_typed_as_marks_given_in_its_call_and_kept_nowhere(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_secret_ask(&yard, &["BOOKS_TOKEN"], &file, cx);
        let nowhere = |view: &Entity<Footplate>, cx: &mut VisualTestContext, when: &str| {
            let kept = kept_outside_the_field(view, cx, dir.path());
            assert!(!kept.contains(VALUE), "{when}: {kept}");
        };
        let marks = |n: usize| "\u{2022}".repeat(n);

        // The window opened with the focus in the line, which this card
        // does not draw: the window's keys have it, not a line out of
        // sight.
        let in_line = view.update_in(cx, |v, window, cx| {
            v.line.focus_handle(cx).is_focused(window)
        });
        assert!(!in_line);

        // The yard's line as it is, and the field where another card has
        // its line for words.
        assert!(drawn(cx, BOOKS_LINE));
        assert!(drawn(cx, "secret bead-s 7"));
        assert!(!drawn(cx, "words bead-s 7"));
        assert_eq!(
            secret_field(&view, cx),
            (
                String::new(),
                String::new(),
                "BOOKS_TOKEN for the source books".to_string()
            )
        );

        // Typed, it is marks, and the line for words has none of it.
        cx.simulate_keystrokes("i");
        cx.simulate_input(VALUE);
        let (typed_in, shown, _) = secret_field(&view, cx);
        assert_eq!((typed_in.as_str(), shown), (VALUE, marks(VALUE.len())));
        assert_eq!(typed(&view, cx), "");
        nowhere(&view, cx, "typed");
        // Nothing copies out, by copy or by cut.
        cx.write_to_clipboard(ClipboardItem::new_string("before".to_string()));
        cx.simulate_keystrokes("secondary-a secondary-c secondary-x");
        assert_eq!(
            cx.read_from_clipboard().and_then(|item| item.text()),
            Some("before".to_string())
        );
        assert_eq!(secret_field(&view, cx).0, VALUE);
        // A setting kept while it is typed keeps none of it.
        cx.simulate_keystrokes("secondary-=");
        cx.run_until_parked();
        assert!(file.exists());
        nowhere(&view, cx, "a setting kept");
        // Leaving the card forgets it: it is in no draft of the
        // conversation that opens, and is not back with the card. Tab
        // stays in the mode's list, and this yard's decisions hold one
        // row alone, so leaving steps to chat and back.
        cx.simulate_keystrokes("secondary-[");
        cx.run_until_parked();
        assert_eq!(secret_field(&view, cx).0, "");
        assert_eq!(typed(&view, cx), "");
        nowhere(&view, cx, "the card left");
        cx.simulate_keystrokes("secondary-]");
        wait(cx, "the card again", |cx| drawn(cx, "secret bead-s 7"));
        assert_eq!(secret_field(&view, cx).0, "");
        nowhere(&view, cx, "the card again");

        // Pasted, with the line break a copy often ends in. This yard does
        // not have the call: the field is empty at once, the value went in
        // the call without the break, and the card says where to answer.
        cx.write_to_clipboard(ClipboardItem::new_string(format!("{VALUE}\n")));
        cx.simulate_keystrokes("i");
        cx.simulate_keystrokes("secondary-v");
        assert_eq!(secret_field(&view, cx).1, marks(VALUE.len() + 1));
        cx.simulate_keystrokes("enter");
        assert_eq!(secret_field(&view, cx).0, "");
        wait(cx, "the yard without the call", |cx| {
            refused_of(&view, cx, "bead-s", 7)
                == "this yard takes no secret from footplate. Answer in a terminal on the yard's machine: yardr bead answer bead-s 7 --secret"
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        assert_eq!(
            yard.asked("GiveSecret"),
            [json!({"bead": "bead-s", "ask": 7, "values": {"BOOKS_TOKEN": VALUE}, "actor": "jo"})]
        );
        assert_eq!(yard.asked("AnswerAsk"), Vec::<Value>::new());
        nowhere(&view, cx, "no such call");

        // The yard goes away over the call: never "sent", and not "not
        // sent" either.
        yard.answer_nothing("GiveSecret");
        cx.simulate_input(VALUE);
        cx.simulate_keystrokes("enter");
        assert_eq!(secret_field(&view, cx).0, "");
        wait(cx, "no answer", |cx| {
            refused_of(&view, cx, "bead-s", 7)
                == "the yard did not answer. The value may be written. Give it again."
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        assert_eq!(yard.asked("GiveSecret").len(), 2);
        nowhere(&view, cx, "no answer");

        // The yard says no, in its words.
        yard.answer(
            "GiveSecret",
            r#"{"error": {"code": "error", "message": "GiveSecret is the operator's to give"}}"#,
        );
        cx.simulate_input(VALUE);
        cx.simulate_keystrokes("enter");
        assert_eq!(secret_field(&view, cx).0, "");
        wait(cx, "refused", |cx| {
            refused_of(&view, cx, "bead-s", 7) == "not given: GiveSecret is the operator's to give"
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        nowhere(&view, cx, "refused");

        // A refusal that repeated the value, which the yard's never does,
        // is not shown.
        yard.answer(
            "GiveSecret",
            &json!({"error": {"code": "error", "message": format!("cannot take {VALUE}")}})
                .to_string(),
        );
        cx.simulate_input(VALUE);
        cx.simulate_keystrokes("enter");
        wait(cx, "a refusal with the value", |cx| {
            refused_of(&view, cx, "bead-s", 7) == "not given: the yard refused it"
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        nowhere(&view, cx, "a refusal with the value");

        // Given: the yard's words for where it is set, and the ask among
        // the decided as one that gave the name.
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [
                queued_secret(&["BOOKS_TOKEN"], 7, "answered", &["BOOKS_TOKEN"])
            ]}})
            .to_string(),
        );
        yard.answer(
            "GiveSecret",
            r#"{"result": {"given": ["BOOKS_TOKEN"], "file": "/home/jo/.yardr/sources/books.env",
                "credential": "BOOKS_TOKEN is set in /home/jo/.yardr/sources/books.env"}}"#,
        );
        cx.simulate_input(VALUE);
        cx.simulate_keystrokes("enter");
        assert_eq!(secret_field(&view, cx).0, "");
        wait(cx, "given", |cx| {
            notice(&view, cx)
                == "gave BOOKS_TOKEN · BOOKS_TOKEN is set in /home/jo/.yardr/sources/books.env"
        });
        // The new answer cleared the refusal the last one left.
        assert_eq!(refused_of(&view, cx, "bead-s", 7), "");
        assert_eq!(yard.asked("GiveSecret").len(), 5);
        let detail = decided_detail_of(&view, cx, "bead-s", 7);
        assert_eq!(detail.state_line, "you gave BOOKS_TOKEN");
        cx.run_until_parked();
        assert_eq!(secret_field(&view, cx).0, "");
        nowhere(&view, cx, "given");
        // Nothing of the value went to the yard but in that call.
        for call in yard.calls() {
            if call != "GiveSecret" {
                let asked = format!("{:?}", yard.asked(&call));
                assert!(!asked.contains(VALUE), "{call}: {asked}");
            }
        }
    }

    /// A refused answer says why on its card, in place: the yard's
    /// refusal of a secret giving, answered with a status, is the card's
    /// line under its field, and the field is empty after, the value
    /// kept nowhere.
    #[gpui::test]
    fn a_refused_answer_says_why_on_its_card_and_keeps_no_secret(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_secret_ask(&yard, &["BOOKS_TOKEN"], &file, cx);
        // The yard refuses the giving: fewer names than the ask asks for.
        yard.answer_status(
            "GiveSecret",
            409,
            r#"{"error": {"code": "error", "message": "ask 7 asks for BOOKS_TOKEN: BOOKS_TOKEN was not given"}}"#,
        );
        cx.simulate_keystrokes("i");
        cx.simulate_input(VALUE);
        cx.simulate_keystrokes("enter");
        assert_eq!(secret_field(&view, cx).0, "");
        wait(cx, "the refusal on the card", |cx| {
            refused_of(&view, cx, "bead-s", 7)
                == "not given: ask 7 asks for BOOKS_TOKEN: BOOKS_TOKEN was not given"
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        assert_eq!(secret_field(&view, cx).0, "");
        let kept = kept_outside_the_field(&view, cx, dir.path());
        assert!(!kept.contains(VALUE), "{kept}");
    }

    /// The command of the run ask in these tests: longer than the window
    /// is wide.
    fn long_command() -> String {
        let crew: Vec<String> = (1..=40).map(|n| format!("--crew builder-{n}")).collect();
        format!("yardr source grant crm read {}", crew.join(" "))
    }

    const RUN_DOES: &str = "the link with airy (it calls itself yardr, key 6lHks9_z…) takes 300 mails and asks an hour from it. It takes 30 now.";
    const RUN_BACK: &str = "yardr peer allow airy --mail-limit 30";
    const RUN_RESULT: &str = "peer airy: takes 300 mails and asks an hour, and 2400 files";
    const WEIGHTY_RUN_LINE: &str = "lets the yard change something outside it: crew members builder-1 through builder-40 may call send of crm (an update)";
    const WEIGHTY_RUN_RESULT: &str = "source crm: send granted to builder-1 through builder-40";

    fn run_of() -> Value {
        let command = long_command();
        let argv: Vec<&str> = command.split(' ').skip(1).collect();
        json!({"argv": argv, "command": command, "does": [RUN_DOES], "back": RUN_BACK})
    }

    /// A long update grant for the weighty run card, to keep its proposal
    /// and the yard's outside line about the same change.
    fn weighty_long_command() -> String {
        let crew: Vec<String> = (1..=40).map(|n| format!("--crew builder-{n}")).collect();
        format!("yardr source grant crm send {}", crew.join(" "))
    }

    fn weighty_run_of() -> Value {
        let command = weighty_long_command();
        let argv: Vec<&str> = command.split(' ').skip(1).collect();
        let does = WEIGHTY_RUN_LINE;
        let crew: Vec<String> = (1..=40).map(|n| format!("--crew builder-{n}")).collect();
        let back = format!("yardr source revoke crm send {}", crew.join(" "));
        json!({"argv": argv, "command": command, "does": [does], "back": back})
    }

    /// The run ask 7 on bead-s as the queue lists it, open or in `state`,
    /// approved when `ran`.
    fn queued_run(state: &str, ran: bool) -> Value {
        queued_run_about("Take more mail from airy?", state, ran)
    }

    /// The same, asking `question`.
    fn queued_run_about(question: &str, state: &str, ran: bool) -> Value {
        let mut queued = json!({
            "bead": "bead-s", "bead_title": "The link with airy", "topic": "", "ask": 7,
            "question": question, "asker": "yardmaster",
            "since": "2026-10-10T10:00:00Z", "run": run_of()
        });
        if !state.is_empty() {
            queued["state"] = json!(state);
        }
        if ran {
            queued["ran"] = json!({"argv": run_of()["argv"], "result": RUN_RESULT});
        }
        queued
    }

    const PAIR_DOES: [&str; 5] = [
        "opens a pairing for the device watch of jo, reached at https://mac.example.net.",
        "jo has 1 device: phone (never used).",
        "Approval opens the pairing for that device alone: its code is good for ten minutes and for one device, and whoever has the code within those minutes is answered with that device's token.",
        "Nothing in the yard keeps the code after it is used or runs out.",
        "The new device then calls as jo until yardr user device rm jo watch, and jo will then have 2 devices.",
    ];
    const PAIR_BACK: &str = "yardr user device pair --end ends it while it stands; once the code is used, yardr user device rm jo watch removes the device";
    const PAIR_WEIGHT: &str = "a new device watch of jo speaks as them: whoever holds its token calls as jo until the device is removed";
    const PAIR_RESULT: &str = "a pairing was opened for the device watch of jo, good until 09:30:00: the code was shown to the approver alone and is kept nowhere";
    const PAIR_CODE: &str = "K7QM-2XPD";
    const PAIR_QR: &str = "https://mac.example.net#K7QM-2XPD";

    /// The pairing ask 7 on bead-s: the watch of jo, reached at the
    /// yard's address, in the yard's words.
    fn pair_run_of() -> Value {
        json!({"argv": ["user", "device", "pair", "jo", "watch"],
            "command": "yardr user device pair jo watch",
            "does": PAIR_DOES, "back": PAIR_BACK})
    }

    /// That ask as the queue lists it, open or in `state`, approved
    /// when `ran`.
    fn queued_pair(state: &str, ran: bool) -> Value {
        let mut queued = json!({
            "bead": "bead-s", "bead_title": "A second device", "topic": "", "ask": 7,
            "question": "Pair the watch?", "asker": "yardmaster",
            "since": "2026-10-10T10:00:00Z", "run": pair_run_of(),
            "weight": weighed("trust", PAIR_WEIGHT)
        });
        if !state.is_empty() {
            queued["state"] = json!(state);
        }
        if ran {
            queued["ran"] = json!({"argv": pair_run_of()["argv"], "result": PAIR_RESULT});
        }
        queued
    }

    /// The bead of that ask.
    fn bead_pair() -> String {
        json!({"result": {"id": "bead-s", "title": "A second device", "body": "The body.",
            "stage": "new", "labels": [], "notes": [], "asks": [
                {"ask": 7, "to": "jo", "asker": "yardmaster",
                 "since": "2026-10-10T10:00:00Z",
                 "question": "Pair the watch?",
                 "context": ["jo's watch arrived, and wants the yard."],
                 "options": [], "state": "open", "run": pair_run_of(),
                 "weight": weighed("trust", PAIR_WEIGHT)}]}})
        .to_string()
    }

    /// The window on a yard whose one open ask is that pairing ask, its
