    /// A depot re-apply's sentences as the yard cards them: the pack line,
    /// the changed file with its hashes whole, and the counts.
    const DEPOT_DOES: [&str; 3] = [
        "pack starter (embedded in yardr ecbab0933da6), of kind dir, into the depot yard: it changes 1 file and changes nothing else.",
        "file flows/default.md: change, sha256 1111111111111111111111111111111111111111111111111111111111111111 -> 2222222222222222222222222222222222222222222222222222222222222222, 2 insertions, 1 deletion",
        "2 objects unchanged, and 1 dropped but left where it stands.",
    ];
    const DEPOT_TEXT: &str = "flow: default\nstages:\n  - new\n";
    const DEPOT_DIFF: &str =
        "--- was\n+++ is\n@@ -1,3 +1,3 @@\n-flow: old\n+flow: default\n stages:\n";

    /// The pack apply ask 7 on bead-s for a depot kind's re-apply.
    fn run_depot() -> Value {
        json!({
            "argv": ["pack", "apply", "starter"],
            "command": "yardr pack apply starter",
            "description": "Import a pack into a depot",
            "does": DEPOT_DOES,
            "back": "no one command takes this back: yardr pack check starter --depot yard shows what stands",
            "back_by": "the operator",
            "pack": {"name": "starter", "kind": "dir", "depot": "yard",
                     "label": "yardr ecbab0933da6",
                     "plan": {"objects": [
                         {"kind": "file", "name": "flows/default.md", "action": "change",
                          "file_old_sha256": "1111111111111111111111111111111111111111111111111111111111111111",
                          "file_new_sha256": "2222222222222222222222222222222222222222222222222222222222222222",
                          "text": DEPOT_TEXT, "diff": DEPOT_DIFF},
                         {"kind": "crew", "name": "builders", "action": "unchanged"}
                     ]}}
        })
    }

    /// The window on a yard whose one open ask is that depot ask, its card
    /// open and read.
    fn opened_on_a_depot_ask<'a>(
        yard: &Yard,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [queued_depot()], "decided": []}}).to_string(),
        );
        yard.answer("Bead", &bead_depot());
        yard.answer("DeferAsk", "{}");
        yard.answer("DeclineAsk", "{}");
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// That depot ask as the queue lists it, and the bead of it.
    fn queued_depot() -> Value {
        json!({
            "bead": "bead-s", "bead_title": "Keep the depot", "topic": "", "ask": 7,
            "question": "Re-apply the starter pack?",
            "asker": "yardmaster",
            "since": "2026-10-10T10:00:00Z", "run": run_depot()
        })
    }

    fn bead_depot() -> String {
        json!({"result": {"id": "bead-s", "title": "Keep the depot", "body": "The body.",
            "stage": "new", "labels": [], "notes": [], "asks": [
                {"ask": 7, "to": "jo", "asker": "yardmaster",
                 "since": "2026-10-10T10:00:00Z",
                 "question": "Re-apply the starter pack?",
                 "context": ["the upgrade moved the pack past the depot."],
                 "options": [], "state": "open", "run": run_depot()}]}})
        .to_string()
    }

    /// The key of one carried text of the ask's card: its section with its
    /// place among the texts.
    fn carried_text_key(section: &str, ix: usize, text: &str) -> u64 {
        expanded_text_key(select::key(("bead-s", 7u64)), section, ix, text)
    }

    /// Clicks the copy control of one carried text: the card scrolls so
    /// the control stands in view, and the click lands where the scrolled
    /// control stands. The control's place is in the card's own
    /// coordinates, and the click in the window's.
    fn click_carried_chip(view: &Entity<Footplate>, cx: &mut VisualTestContext, key: u64) {
        // Where the control stands in the card's own coordinates: what
        // is recorded is where the scrolled card shows it.
        let offset = view.read_with(cx, |v, _| v.decision.offset());
        let center = run_chip(view, cx, key).unwrap();
        let content = gpui::point(center.x - offset.x, center.y - offset.y);
        // Scroll the card so the control stands a third down the window.
        view.update(cx, |v, _| {
            let mut at = v.decision.offset();
            at.y = (px(256.) - content.y).min(px(0.));
            v.decision.set_offset(at);
        });
        cx.run_until_parked();
        cx.update(|window, _| window.refresh());
        cx.run_until_parked();
        // Where the scrolled card shows it now: the click lands there.
        let center = run_chip(view, cx, key).unwrap();
        cx.simulate_click(center, gpui::Modifiers::default());
    }

    /// A run ask's card: under the asker's lines the yard's one block, with
    /// the command whole and wrapped, the yard's sentence and the command
    /// that takes it back. A weighty card without a gate takes its number
    /// back, and anything else leaves the card; its button opens the gate
    /// before approving.
    /// Enter approves nothing, with words or without; the card's own key
    /// calls `ApproveAsk` with the ask and nothing of the command. A call
    /// with no answer never says approved; a refusal is shown whole; an
    /// approved ask reads `approved, ran:` with the command and its result.
    #[gpui::test]
    fn a_run_ask_s_card_shows_the_command_whole_and_is_approved_with_its_own_key(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_weighty_run_ask(&yard, &file, cx);
        let command = weighty_long_command();

        // The card draws no line for words, and the window has the keys.
        // With no gate it takes the ask's number back above its control.
        let in_line = view.update_in(cx, |v, window, cx| {
            v.line.focus_handle(cx).is_focused(window)
        });
        assert!(!in_line);
        assert!(drawn(cx, "run bead-s 7"));
        assert!(drawn(cx, "weight bead-s 7 0"));
        assert!(drawn(cx, "typeback bead-s 7"));
        assert!(drawn(cx, "approve bead-s 7"));
        assert!(!drawn(cx, "words bead-s 7"));
        assert!(!drawn(cx, "send bead-s 7"));

        // The asker's lines are marked as the asker's, each of them, and
        // none is a block: the card's blocks are the yard's two commands.
        let context = view.read_with(cx, |v, _| {
            let model = v.model.as_ref().unwrap();
            let detail = model.decision_detail("bead-s", &chrono::Utc::now());
            detail.unwrap().asks[0].context.clone()
        });
        assert_eq!(context.len(), 5);
        assert!(
            context
                .iter()
                .all(|line| line.starts_with("yardmaster says: "))
        );
        assert_eq!(
            view.read_with(cx, |v, cx| v.selection.read(cx).chip_count()),
            2
        );

        // A line that looks like a fence selects as it was written.
        let fence = bounds_of(cx, "asker words run context bead-s 7 1");
        drag(
            cx,
            gpui::point(fence.left(), fence.top() + px(2.)),
            gpui::point(fence.right() - px(2.), fence.bottom() - px(2.)),
        );
        assert_eq!(selected(&view, cx).as_deref(), Some("```"));

        // The command is whole and wraps, as does its take-back; both
        // stand inside the yard's block and are selectable as text.
        let block = bounds_of(cx, "run bead-s 7");
        let (whole, back) = (
            bounds_of(cx, "run command bead-s 7"),
            bounds_of(cx, "run back bead-s 7"),
        );
        assert!(whole.size.height > px(40.), "{whole:?}");
        assert!(whole.right() <= block.right(), "{whole:?} in {block:?}");
        assert!(block.top() <= whole.top() && back.bottom() <= block.bottom());
        assert!(whole.bottom() <= back.top());
        let chip = run_chip(&view, cx, run_text("run", &command)).unwrap();
        cx.simulate_click(chip, gpui::Modifiers::default());
        assert_eq!(clipboard(cx).as_deref(), Some(command.as_str()));

        // Enter alone approves nothing, and nothing typed goes with it:
        // `i` types the card's number, and the picking keys no option.
        cx.simulate_keystrokes("enter");
        cx.simulate_keystrokes("i");
        cx.simulate_input("yes");
        cx.simulate_keystrokes("enter 1 enter up enter");
        cx.run_until_parked();
        assert_eq!(typed(&view, cx), "");
        assert_eq!(typeback_text(&view, cx), "yes1");
        assert_eq!(yard.asked("ApproveAsk"), Vec::<Value>::new());
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());

        // The approval's key with anything but the ask's number sends
        // nothing and leaves the card, saying so. A cancelled unlock does
        // nothing too; the control is available to try again.
        cx.simulate_keystrokes("secondary-enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk"), Vec::<Value>::new());
        assert_eq!(
            notice(&view, cx),
            "ask 7's number was not typed back, so nothing was done"
        );
        assert!(drawn(cx, "typeback bead-s 7"));
        assert!(drawn(cx, "approve bead-s 7"));
        unlock_as(&view, cx, true, false);
        assert!(drawn(cx, "approve bead-s 7"));
        click_on(cx, "approve bead-s 7");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk"), Vec::<Value>::new());

        // Passing the gate starts the call. The yard goes away over it:
        // never "approved".
        unlock_as(&view, cx, true, true);
        yard.answer_nothing("ApproveAsk");
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "no answer", |cx| {
            refused_of(&view, cx, "bead-s", 7) == "the yard did not answer; read the card again"
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        assert_eq!(yard.asked("ApproveAsk"), [weighed_approval(&yard)]);
        assert!(drawn(cx, "approve bead-s 7"));

        // The yard refuses, since it changed after the ask was written:
        // its words, whole.
        let stale = "ask 7 on bead-s: the source grant changed after this card was written. Nothing ran. Decline it; it is asked again if it is still wanted.";
        yard.answer(
            "ApproveAsk",
            &json!({"error": {"code": "error", "message": stale}}).to_string(),
        );
        click_on(cx, "approve bead-s 7");
        wait(cx, "refused", |cx| {
            refused_of(&view, cx, "bead-s", 7) == format!("not approved: {stale}")
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert!(drawn(cx, "approve bead-s 7"));
        assert_eq!(notice(&view, cx), "");

        // Approved: the command as it ran and what it printed, and the
        // ask among the decided, which reads the same.
        let mut answered = queued_run("answered", true);
        answered["run"] = weighty_run_of();
        answered["weight"] = weighed("outside", WEIGHTY_RUN_LINE);
        answered["ran"] = json!({"argv": weighty_run_of()["argv"], "result": WEIGHTY_RUN_RESULT});
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [answered]}}).to_string(),
        );
        yard.answer(
            "ApproveAsk",
            &json!({"result": {"bead": "bead-s", "ask": 7, "asker": "yardmaster",
                "argv": weighty_run_of()["argv"], "result": WEIGHTY_RUN_RESULT}})
            .to_string(),
        );
        // The number, not an unlock, passes this card's gate on the final
        // approval; the earlier attempts still cover the offered unlock.
        unlock_as(&view, cx, false, false);
        view.update(cx, |v, cx| {
            v.typeback.update(cx, |field, cx| field.set_text("7", cx))
        });
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "approved", |cx| {
            notice(&view, cx) == format!("approved, ran: {command} · {WEIGHTY_RUN_RESULT}")
        });
        assert_eq!(yard.asked("ApproveAsk").len(), 3);
        assert_eq!(typeback_text(&view, cx), "");
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
        let detail = decided_detail_of(&view, cx, "bead-s", 7);
        assert_eq!(detail.state_line, format!("approved, ran: {command}"));
        open_decided(&view, cx, "bead-s", 7);
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-s"));
        assert!(drawn(cx, "ran bead-s 7"));
        assert!(drawn(cx, "run bead-s 7"));
        // A command runs once for one ask: no control, and no key.
        assert!(!approvable(&view, cx));
        assert!(!drawn(cx, "words bead-s 7"));
        cx.simulate_keystrokes("secondary-enter enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk").len(), 3);
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
    }

    /// A pairing card says the door its approval crosses beside the
    /// yard's weight, and approving it shows the QR screen in that
    /// sitting alone instead of the notice line: the QR drawn from the
    /// transient's string verbatim, the code as text beside it with its
    /// minutes counted down, and End. Leaving the screen drops both:
    /// the decided card reads as any other, with no QR in it.
    #[gpui::test]
    fn a_pairing_approval_shows_its_qr_until_the_screen_is_left(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_pair_ask(&yard, &file, cx);

        // The card says its door beside the yard's weight, before
        // approval: on this machine's socket no edge carries the code,
        // and at an address the carrier could spend it first.
        assert!(drawn(cx, "weight bead-s 7 0"));
        assert!(drawn(cx, "door bead-s 7"));
        assert!(drawn(cx, "approve bead-s 7"));
        let door = bounds_of(cx, "door bead-s 7");
        drag(
            cx,
            gpui::point(door.left(), door.top() + px(2.)),
            gpui::point(door.right() - px(2.), door.bottom() - px(2.)),
        );
        let wanted = match yard.at_listener() {
            true => {
                "approving shows the pairing's code on this screen: show it to the device and to nobody else, since whoever has it within its minutes, the carrier of this approval included, could spend it first"
            }
            false => "approving shows the pairing's code on this screen alone: no edge carries it",
        };
        assert_eq!(selected(&view, cx).as_deref(), Some(wanted));

        // The weighty gate: the ask's number typed back, no unlock
        // offered. The approval answers the transient beside the safe
        // sentence, and the queue reads the ask decided.
        unlock_as(&view, cx, false, false);
        view.update(cx, |v, cx| {
            v.typeback.update(cx, |field, cx| field.set_text("7", cx))
        });
        let ends =
            (chrono::Utc::now() + chrono::TimeDelta::minutes(9) + chrono::TimeDelta::seconds(30))
                .to_rfc3339();
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [queued_pair("answered", true)]}})
                .to_string(),
        );
        yard.answer("ApproveAsk", &pairing_approval(&ends));
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "the QR screen", |cx| {
            view.read_with(cx, |v, _| v.approval_pairing.is_some())
        });
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk"), [weighed_approval(&yard)]);
        assert_eq!(notice(&view, cx), "");
        assert_eq!(
            open_row(&view, cx),
            Some(Selected::Decided("bead-s".into(), 7))
        );
        assert!(drawn(cx, "pair head bead-s 7"));
        assert!(drawn(cx, "pair qr bead-s 7"));
        assert!(drawn(cx, "pair code bead-s 7"));
        assert!(drawn(cx, "pair left bead-s 7"));
        assert!(drawn(cx, "pair end bead-s 7"));
        // The transient verbatim: the QR string the screen draws is the
        // approval's, and the code beside it is the approval's too, with
        // its minutes counted down from its expiry.
        view.read_with(cx, |v, _| {
            let ApprovalPairing::Shown {
                pairing,
                ending,
                end_refused,
                ..
            } = v.approval_pairing.as_ref().unwrap()
            else {
                panic!("no pairing sitting is shown");
            };
            assert!(!ending);
            assert!(end_refused.is_empty());
            assert_eq!(pairing.qr, PAIR_QR);
            assert_eq!(pairing.code, PAIR_CODE);
            assert_eq!(pairing.device, "watch");
            assert_eq!(pairing.user, "jo");
            assert_eq!(pairing.expires, ends);
            assert_eq!(
                crate::model::pairing_left(&pairing.expires, &chrono::Utc::now()),
                "9 minutes left"
            );
        });
        // The code as text, for a device with no camera.
        let code = bounds_of(cx, "pair code bead-s 7");
        drag(
            cx,
            gpui::point(code.left(), code.top() + px(2.)),
            gpui::point(code.right() - px(2.), code.bottom() - px(2.)),
        );
        assert_eq!(selected(&view, cx).as_deref(), Some(PAIR_CODE));

        // Leaving the screen drops both: another row, and the decided
        // card reads as any other, its `ran` and no sitting.
        view.update(cx, |v, cx| {
            v.change(cx, |m| {
                m.select(Selected::Conversation("yardmaster".into()))
            })
        });
        cx.run_until_parked();
        view.read_with(cx, |v, _| assert!(v.approval_pairing.is_none()));
        assert_eq!(selected(&view, cx), None);
        open_decided(&view, cx, "bead-s", 7);
        wait(cx, "the decided card", |cx| has_bead(&view, cx, "bead-s"));
        assert!(drawn(cx, "ran bead-s 7"));
        view.read_with(cx, |v, _| assert!(v.approval_pairing.is_none()));
        // An approval the model holds no decided card of keeps the
        // notice line instead: the screen has no card to stand on.
        view.update(cx, |v, cx| {
            let session = v.session;
            v.show_approval_pairing_in(
                session,
                "bead-s".into(),
                9,
                api::AskPairing::default(),
                "approved, ran: nothing".into(),
                cx,
            );
        });
        cx.run_until_parked();
        assert_eq!(notice(&view, cx), "approved, ran: nothing");
        view.read_with(cx, |v, _| assert!(v.approval_pairing.is_none()));
    }

    /// The QR screen's End ends the pairing through the yard, and the
    /// screen shows its ended state, with no code and no QR in it. A
    /// refusal stands as the screen's line, and the pairing is kept for
    /// another End.
    #[gpui::test]
    fn ending_a_pairing_approval_ends_it_and_shows_its_ended_state(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_pair_ask(&yard, &file, cx);
        unlock_as(&view, cx, false, false);
        view.update(cx, |v, cx| {
            v.typeback.update(cx, |field, cx| field.set_text("7", cx))
        });
        let ends = (chrono::Utc::now() + chrono::TimeDelta::minutes(10)).to_rfc3339();
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [queued_pair("answered", true)]}})
                .to_string(),
        );
        yard.answer("ApproveAsk", &pairing_approval(&ends));
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "the QR screen", |cx| {
            view.read_with(cx, |v, _| v.approval_pairing.is_some())
        });
        // The yard refuses the ending: the screen says so in the yard's
        // words, and the pairing is kept for another End.
        yard.answer(
            "DevicePairCloseSelf",
            r#"{"error": {"code": "not-found", "message": "an open device pairing: not found"}}"#,
        );
        click_on(cx, "pair end bead-s 7");
        wait(cx, "the refused ending", |cx| {
            view.read_with(cx, |v, _| match &v.approval_pairing {
                Some(ApprovalPairing::Shown {
                    ending,
                    end_refused,
                    ..
                }) => !*ending && !end_refused.is_empty(),
                _ => false,
            })
        });
        assert_eq!(yard.asked("DevicePairCloseSelf"), [json!({"user": "jo"})]);
        assert!(drawn(cx, "pair refused bead-s 7"));
        assert!(drawn(cx, "pair qr bead-s 7"));
        assert!(drawn(cx, "pair end bead-s 7"));
        // Ended: the screen shows its ended state, and the secrets drop
        // with the sitting.
        yard.answer("DevicePairCloseSelf", r#"{"result": {}}"#);
        click_on(cx, "pair end bead-s 7");
        wait(cx, "the ended state", |cx| {
            view.read_with(cx, |v, _| {
                matches!(&v.approval_pairing, Some(ApprovalPairing::Ended { .. }))
            })
        });
        assert_eq!(yard.asked("DevicePairCloseSelf").len(), 2);
        assert!(drawn(cx, "pair ended bead-s 7"));
        view.read_with(cx, |v, _| {
            let ApprovalPairing::Ended {
                device,
                user,
                expired,
                ..
            } = v.approval_pairing.as_ref().unwrap()
            else {
                panic!("no ended sitting");
            };
            assert_eq!(device, "watch");
            assert_eq!(user, "jo");
            assert!(!expired);
            let kept = format!("{:?}", v.approval_pairing);
            assert!(!kept.contains(PAIR_CODE));
            assert!(!kept.contains(PAIR_QR));
        });
        assert_eq!(selected(&view, cx), None);

        // A transient whose expiry cannot be read is never shown: there
        // is no safe way to count down how long its code remains usable.
        view.update(cx, |v, cx| {
            let session = v.session;
            v.show_approval_pairing_in(
                session,
                "bead-s".into(),
                7,
                api::AskPairing {
                    user: "jo".into(),
                    device: "watch".into(),
                    code: PAIR_CODE.into(),
                    expires: "not a time".into(),
                    qr: PAIR_QR.into(),
                    ..api::AskPairing::default()
                },
                "approved, ran: pair".into(),
                cx,
            );
        });
        view.read_with(cx, |v, _| assert!(v.approval_pairing.is_none()));
        assert_eq!(
            notice(&view, cx),
            "the yard's pairing expiry could not be read; the code was not shown"
        );
    }

    /// A pairing approval's code running out drops the transient: the
    /// screen shows its ended state, with no code and no QR in it.
    #[gpui::test]
    fn a_pairing_approval_s_code_running_out_drops_it(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_pair_ask(&yard, &file, cx);
        unlock_as(&view, cx, false, false);
        view.update(cx, |v, cx| {
            v.typeback.update(cx, |field, cx| field.set_text("7", cx))
        });
        let ends = (chrono::Utc::now() + chrono::TimeDelta::minutes(10)).to_rfc3339();
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [queued_pair("answered", true)]}})
                .to_string(),
        );
        yard.answer("ApproveAsk", &pairing_approval(&ends));
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "the QR screen", |cx| {
            view.read_with(cx, |v, _| v.approval_pairing.is_some())
        });
        assert!(drawn(cx, "pair qr bead-s 7"));
        let code = bounds_of(cx, "pair code bead-s 7");
        drag(
            cx,
            gpui::point(code.left(), code.top() + px(2.)),
            gpui::point(code.right() - px(2.), code.bottom() - px(2.)),
        );
        assert_eq!(selected(&view, cx).as_deref(), Some(PAIR_CODE));
        cx.executor().advance_clock(Duration::from_secs(601));
        cx.run_until_parked();
        view.read_with(cx, |v, _| match &v.approval_pairing {
            Some(ApprovalPairing::Ended { expired, .. }) => assert!(*expired),
            sitting => panic!("no expired sitting: {sitting:?}"),
        });
        assert!(drawn(cx, "pair ended bead-s 7"));
        view.read_with(cx, |v, _| {
            let kept = format!("{:?}", v.approval_pairing);
            assert!(!kept.contains(PAIR_CODE));
            assert!(!kept.contains(PAIR_QR));
        });
        assert_eq!(selected(&view, cx), None);
    }

    /// A pairing card at an address says its carrier could spend the
    /// code first: the approval crosses with the token in the clear.
    #[gpui::test]
    fn a_pairing_card_at_an_address_says_its_carrier_could_spend_it(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        let far = Yard::start_tcp();
        a_yard_of_jo(&near);
        a_far_yard_of_jo(&far);
        near.answer("UserAsks", r#"{"result": {"open": [], "decided": []}}"#);
        let file = dir.path().join("footplate/settings.json");
        let set = Settings::default()
            .with_yard(None, listed("far", &far, &file), Some(&file))
            .unwrap();
        set.write(&file).unwrap();
        far.answer(
            "UserAsks",
            &json!({"result": {"open": [queued_pair("", false)], "decided": []}}).to_string(),
        );
        far.answer("Bead", &bead_pair());
        let at = env_on(&near, &file);
        let (view, cx) = opened_at(at, &file, cx);
        view.update_in(cx, |v, window, cx| v.switch_to("far", window, cx));
        wait(cx, "the far decision", |cx| {
            to_decisions(&view, cx);
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|m| m.selected() == Some(&Selected::Decision("bead-s".into())))
            })
        });
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-s"));
        cx.run_until_parked();
        assert!(drawn(cx, "door bead-s 7"));
        let door = bounds_of(cx, "door bead-s 7");
        drag(
            cx,
            gpui::point(door.left(), door.top() + px(2.)),
            gpui::point(door.right() - px(2.), door.bottom() - px(2.)),
        );
        assert_eq!(
            selected(&view, cx).as_deref(),
            Some(
                "approving shows the pairing's code on this screen: show it to the device and to nobody else, since whoever has it within its minutes, the carrier of this approval included, could spend it first"
            )
        );
    }

    /// Leaving a yard drops the pairing screen and its selection; an
    /// approval result that arrives while that yard is held is discarded.
    #[gpui::test]
    fn a_pairing_approval_s_sitting_drops_when_its_yard_is_left(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        let second = Yard::start();
        a_yard_of_jo(&near);
        a_yard_of_jo(&second);
        let file = dir.path().join("footplate/settings.json");
        let set = Settings::default()
            .with_yard(None, listed("second home", &second, &file), Some(&file))
            .unwrap();
        set.write(&file).unwrap();
        near.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [queued_pair("answered", true)]}})
                .to_string(),
        );
        near.answer("Bead", &bead_pair());
        second.answer("UserAsks", r#"{"result": {"open": [], "decided": []}}"#);
        let at = env_on(&near, &file);
        let (view, cx) = opened_at(at, &file, cx);
        wait(cx, "this machine's yard", |cx| {
            texts(&view, cx) == ["Shall I land it?"]
        });
        let session = view.read_with(cx, |v, _| v.session);
        let ends = (chrono::Utc::now() + chrono::TimeDelta::minutes(10)).to_rfc3339();
        view.update(cx, |v, cx| {
            v.show_approval_pairing_in(
                session,
                "bead-s".into(),
                7,
                api::AskPairing {
                    user: "jo".into(),
                    device: "watch".into(),
                    code: PAIR_CODE.into(),
                    address: "https://mac.example.net".into(),
                    expires: ends.clone(),
                    qr: PAIR_QR.into(),
                    ..api::AskPairing::default()
                },
                "approved, ran: pair".into(),
                cx,
            );
        });
        cx.run_until_parked();
        assert!(drawn(cx, "pair qr bead-s 7"));
        let code = bounds_of(cx, "pair code bead-s 7");
        drag(
            cx,
            gpui::point(code.left(), code.top() + px(2.)),
            gpui::point(code.right() - px(2.), code.bottom() - px(2.)),
        );
        assert_eq!(selected(&view, cx).as_deref(), Some(PAIR_CODE));
        view.update_in(cx, |v, window, cx| v.switch_to("second home", window, cx));
        assert_eq!(open_yard(&view, cx), "second home");
        view.read_with(cx, |v, _| assert!(v.approval_pairing.is_none()));
        assert_eq!(selected(&view, cx), None);

        // The old yard's approval answer arrives after the switch. The
        // transient is not retained in the held yard for a later return.
        view.update(cx, |v, cx| {
            v.show_approval_pairing_in(
                session,
                "bead-s".into(),
                7,
                api::AskPairing {
                    user: "jo".into(),
                    device: "watch".into(),
                    code: PAIR_CODE.into(),
                    address: "https://mac.example.net".into(),
                    expires: ends,
                    qr: PAIR_QR.into(),
                    ..api::AskPairing::default()
                },
                "approved, ran: pair".into(),
                cx,
            );
        });
        view.update_in(cx, |v, window, cx| v.switch_to("this machine", window, cx));
        wait(cx, "this machine's yard again", |cx| {
            open_yard(&view, cx) == "this machine"
                && view.read_with(cx, |v, _| v.session == session && v.model.is_some())
        });
        view.read_with(cx, |v, _| assert!(v.approval_pairing.is_none()));
        assert_eq!(selected(&view, cx), None);
    }

    /// An invite card is its own card: the address, the yard user and
    /// the role above the command, with the yard the approval runs in
    /// over it and the yard's sentences below. Its key calls `ApproveAsk`
    /// with the ask and nothing of the command, and an approved ask reads
    /// as being carried out until the yard says it ran.
    #[gpui::test]
    fn an_invite_card_shows_its_fields_and_approving_runs_the_invite(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let run = invite_run();
        let command = "yardr user invite eve --email eve@example.net";
        let (view, cx) = opened_on_a_teammate_ask(
            &yard,
            "Invite Eve?",
            &["she works with us daily"],
            &run,
            &file,
            cx,
        );
        assert!(drawn(cx, "teammate kind bead-s 7"));
        assert!(drawn(cx, "teammate email bead-s 7"));
        assert!(drawn(cx, "teammate user bead-s 7"));
        assert!(drawn(cx, "teammate role bead-s 7"));
        assert!(drawn(cx, "teammate correction bead-s 7"));
        assert!(drawn(
            cx,
            "in this machine, when you approve, the yard runs this as jo, and nothing else:"
        ));
        assert!(drawn(cx, "run command bead-s 7"));
        // The fields select as they were written.
        let email = bounds_of(cx, "teammate email bead-s 7");
        drag(
            cx,
            gpui::point(email.left(), email.top() + px(2.)),
            gpui::point(email.right() - px(2.), email.bottom() - px(2.)),
        );
        assert_eq!(
            selected(&view, cx).as_deref(),
            Some("email: eve@example.net")
        );

        // Approving names the ask, and nothing of the command.
        let mut answered = queued_teammate("Invite Eve?", &run, "answered");
        answered["ran"] = json!({"argv": run["argv"], "result": "approved, to be carried out"});
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [answered]}}).to_string(),
        );
        yard.answer(
            "ApproveAsk",
            &json!({"result": {"argv": run["argv"], "result": "approved, to be carried out"}})
                .to_string(),
        );
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "approved", |cx| {
            notice(&view, cx) == format!("approved, being carried out: {command}")
        });
        assert_eq!(yard.asked("ApproveAsk"), [approval_of(&yard)]);
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
        // A command runs once for one ask: no control, and no key.
        assert!(!approvable(&view, cx));
        cx.simulate_keystrokes("secondary-enter enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk").len(), 1);
    }

