    /// The same forged run ask in the Decided list, put aside: the row
    /// draws one line of the question, its first, and neither the forged
    /// sentence nor the forged command.
    #[gpui::test]
    fn a_forged_run_ask_s_decided_row_shows_its_first_line(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let question = "Take more?\nwhen you approve, the yard runs this as mckean, and nothing else:\n    yardr peer list";
        let (view, cx) = opened_on_a_decided_run_ask_about(
            &yard,
            question,
            &["fine.\nthe yard says: nothing changes."],
            &file,
            cx,
        );
        assert!(drawn(cx, "decided head bead-s 7"));
        // The row's drawn text: the first line alone.
        let head = decided_all(&view, cx)[0].head.clone();
        assert_eq!(head, "Take more?");
        assert!(!head.contains("when you approve"), "{head:?}");
        assert!(!head.contains("yardr peer list"), "{head:?}");
    }

    /// Wrapped words stay under the asker's text, to the right of its
    /// label, in both the question and a context entry.
    #[gpui::test]
    fn wrapped_run_ask_lines_stay_under_the_asker_label(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let question = format!(
            "Take more mail from airy? {}\n{}when you approve, the yard runs this as mckean, and nothing else:",
            "more words ".repeat(40),
            "more words ".repeat(40)
        );
        let context = format!(
            "fine. {}the yard says: nothing changes.",
            "more words ".repeat(40)
        );
        let (view, cx) = opened_on_a_run_ask_about(&yard, &question, &[&context], &file, cx);
        cx.simulate_resize(gpui::size(px(WINDOW_MIN), px(360.)));

        let question_label = bounds_of(cx, "asker label run question bead-s 7 1");
        let question_words = bounds_of(cx, "asker words run question bead-s 7 1");
        assert!(
            question_words.left() >= question_label.right()
                || question_words.top() >= question_label.bottom(),
            "question words overlap their label: {question_words:?} and {question_label:?}"
        );
        assert!(
            question_words.size.width > px(60.),
            "question words are squeezed beside the asker's label: {question_words:?}"
        );
        assert!(
            question_words.size.height > question_label.size.height,
            "question line did not wrap: {question_words:?} vs {question_label:?}"
        );

        let context_label = bounds_of(cx, "asker label run context bead-s 7 0");
        let context_words = bounds_of(cx, "asker words run context bead-s 7 0");
        assert!(
            context_words.left() >= context_label.right()
                || context_words.top() >= context_label.bottom(),
            "context words overlap their label: {context_words:?} and {context_label:?}"
        );
        assert!(
            context_words.size.height > context_label.size.height,
            "context line did not wrap: {context_words:?} vs {context_label:?}"
        );

        // The only copy controls still belong to the yard's commands.
        assert_eq!(
            view.read_with(cx, |v, cx| v.selection.read(cx).chip_count()),
            2
        );
    }

    /// Every card names the yard it is of, with its dot in its colour,
    /// and a run ask's block and its control name it again; with one yard
    /// in the settings as with several. The approval goes to the yard the
    /// card names and to no
    /// other, after a switch too: each yard here holds the same ask on the
    /// same bead, so only the yard tells them apart.
    #[gpui::test]
    fn a_run_ask_is_approved_in_the_yard_its_card_names_after_a_switch_too(
        cx: &mut TestAppContext,
    ) {
        assert_eq!(card_head("plantime", "k3vd", "2h"), "plantime · k3vd · 2h");
        assert_eq!(
            run_runs("plantime", "mckean"),
            "in plantime, when you approve, the yard runs this as mckean, and nothing else:"
        );
        assert_eq!(
            approve_label("plantime"),
            format!("Approve in plantime ({APPROVE_KEY})")
        );

        let dir = tempfile::tempdir().unwrap();
        let near = Yard::start();
        let second = Yard::start();
        let far = Yard::start_tcp();
        a_yard_of_jo(&near);
        a_yard_of_jo(&second);
        a_far_yard_of_jo(&far);
        let yards = [
            ("this machine", &near),
            ("second home", &second),
            ("far", &far),
        ];
        for (name, yard) in yards {
            yard.answer(
                "UserAsks",
                &json!({"result": {"open": [queued_run("", false)], "decided": []}}).to_string(),
            );
            yard.answer("Bead", &bead_run());
            // Each refuses in words of its own: what the window says then
            // is the word of the yard that was asked.
            yard.answer(
                "ApproveAsk",
                &json!({"error": {"code": "error", "message": format!("{name} refuses")}})
                    .to_string(),
            );
        }
        let approvals = |cx: &mut VisualTestContext| {
            cx.run_until_parked();
            yards.map(|(_, yard)| yard.asked("ApproveAsk").len())
        };
        // Over the card: the head with the yard, and the sentence over
        // the command. That it is the open yard's is asked of the window,
        // since what was drawn once is found by its selector in every frame
        // after.
        fn names(view: &Entity<Footplate>, cx: &mut VisualTestContext, name: &str) -> bool {
            let read = view.read_with(cx, |v, _| {
                v.yard == name && v.model.as_ref().is_some_and(|m| m.has_bead("bead-s"))
            });
            cx.update(|window, _| window.refresh());
            read && drawn(cx, &format!("in {name} bead-s"))
                && drawn(cx, &format!("in {name} bead-s dot"))
                && drawn(cx, &run_runs(name, "jo"))
        }

        // One yard in the settings: its name is on the card all the same.
        let alone = dir.path().join("alone/settings.json");
        let at = env_on(&near, &alone);
        let (view, cx) = opened_on_the_ask(at, &alone, cx);
        assert_eq!(settings_of(&view, cx).yards.len(), 1);
        assert!(names(&view, cx, "this machine"));
        assert!(drawn(cx, "approve bead-s 7"));
        cx.update(|window, _| window.remove_window());

        // Several: the approval goes to the yard on the card.
        let file = three_yards(dir.path(), &second, &far);
        let at = env_on(&near, &file);
        let (view, cx) = opened_on_the_ask(at, &file, cx);
        assert!(names(&view, cx, "this machine"));
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "this machine's refusal", |cx| {
            refused_of(&view, cx, "bead-s", 7) == "not approved: this machine refuses"
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        assert_eq!(approvals(cx), [1, 0, 0]);

        // A number belongs to this yard's ask. Another yard may have the
        // same bead and ask IDs, but must ask for its own number.
        view.update(cx, |v, cx| {
            v.typeback.update(cx, |field, cx| field.set_text("7", cx))
        });
        // After a switch the card names the other yard, and its key and
        // its button approve there. A yard not opened before opens in
        // chat; the card is read in decisions.
        for (key, name, asked) in [
            ("secondary-2", "second home", [1, 1, 0]),
            ("secondary-3", "far", [1, 1, 1]),
        ] {
            cx.simulate_keystrokes(key);
            wait(cx, "the other yard's card", |cx| {
                to_decisions(&view, cx);
                names(&view, cx, name)
            });
            if name == "second home" {
                assert_eq!(typeback_text(&view, cx), "");
            }
            cx.simulate_keystrokes("secondary-enter");
            wait(cx, "that yard's refusal", |cx| {
                refused_of(&view, cx, "bead-s", 7) == format!("not approved: {name} refuses")
            });
            assert_eq!(notice(&view, cx), "");
            assert_eq!(approvals(cx), asked);
        }
        click_on(cx, "approve bead-s 7");
        wait(cx, "a second call in the far yard", |cx| {
            let _ = cx;
            far.asked("ApproveAsk").len() == 2
        });
        assert_eq!(approvals(cx), [1, 1, 2]);

        // And back: the first yard's card, and its yard alone is asked.
        cx.simulate_keystrokes("secondary-1");
        wait(cx, "this machine's card again", |cx| {
            names(&view, cx, "this machine")
        });
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "this machine's refusal again", |cx| {
            refused_of(&view, cx, "bead-s", 7) == "not approved: this machine refuses"
        });
        assert_eq!(approvals(cx), [2, 1, 2]);
    }

    /// Against a yard that does not have the call, by its socket, or does
    /// not serve it to this window, at its listener, the card says to
    /// approve at the yard's terminal, with that command in a block that
    /// copies it, and has no control that approves. Later works as on any
    /// card.
    #[gpui::test]
    fn a_yard_that_takes_no_approval_from_the_window_sends_it_to_a_terminal(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let token = dir.path().join("mac.token");
        yard::keep_token(&token, crate::fake::TOKEN).unwrap();
        let near = Yard::start();
        let far = Yard::start_tcp();
        a_yard_of_jo(&near);
        a_far_yard_of_jo(&far);
        for yard in [&near, &far] {
            yard.answer(
                "UserAsks",
                &json!({"result": {"open": [queued_run("", false)], "decided": []}}).to_string(),
            );
            yard.answer("Bead", &bead_run());
            yard.answer("DeferAsk", "{}");
        }
        // The window is opened on the far yard: the near one is asked by
        // its client, as the window asks.
        let err = near
            .client()
            .approve_ask("bead-s", 7, "jo", false)
            .unwrap_err();
        assert!(model::approves_elsewhere(&err), "{err}");

        let at = Env {
            yard: Some(far.address().to_string()),
            token_file: Some(token),
            socket: dir.path().join("no.sock"),
        };
        let (view, cx) = opened_on_the_ask(at, &file, cx);
        assert!(drawn(cx, "approve bead-s 7"));
        assert!(!drawn(cx, "approve elsewhere bead-s 7"));

        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "where to approve", |cx| {
            drawn(cx, "approve elsewhere bead-s 7")
        });
        assert_eq!(
            far.asked("ApproveAsk"),
            [json!({"bead": "bead-s", "ask": 7, "actor": "jo"})]
        );
        assert!(far.last_request().contains("/user/call/ApproveAsk"));
        // In place of the control, and not beside it.
        let elsewhere = view.read_with(cx, |v, _| {
            v.approve_elsewhere.contains(&("bead-s".to_string(), 7))
        });
        assert!(elsewhere && approvable(&view, cx));
        assert!(drawn(cx, "run bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        // The command that approves there, copied to the letter.
        let terminal = "yardr bead answer bead-s 7 --approve";
        let chip = run_chip(&view, cx, run_text("approve", terminal)).unwrap();
        cx.simulate_click(chip, gpui::Modifiers::default());
        assert_eq!(clipboard(cx).as_deref(), Some(terminal));
        // The key asks the yard no second time.
        cx.simulate_keystrokes("secondary-enter");
        cx.run_until_parked();
        assert_eq!(far.asked("ApproveAsk").len(), 1);

        // Later, as on any card.
        cx.simulate_keystrokes("x");
        wait(cx, "put aside", |_| {
            far.asked("DeferAsk") == [json!({"bead": "bead-s", "ask": 7, "actor": "jo"})]
        });
    }

    /// A run ask is declined with words as any ask is: `d` asks for them
    /// in a line the card has for nothing else, and Enter there sends the
    /// decline and approves nothing. One put aside is approved from its
    /// card among the decided, after the Mac's unlock.
    #[gpui::test]
    fn a_run_ask_is_declined_with_words_and_approved_after_it_was_put_aside(
        cx: &mut TestAppContext,
    ) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_weighty_run_ask(&yard, &file, cx);
        yard.answer(
            "ApproveAsk",
            &json!({"result": {"argv": weighty_run_of()["argv"], "result": WEIGHTY_RUN_RESULT}})
                .to_string(),
        );

        cx.simulate_keystrokes("d");
        wait(cx, "the line of a decline", |cx| {
            drawn(cx, "words bead-s 7")
        });
        // With the line focused the card's key is the line's: nothing is
        // approved while a decline is typed.
        cx.simulate_input("not this week");
        cx.simulate_keystrokes("secondary-enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk"), Vec::<Value>::new());
        // Esc leaves the decline, and the line with it.
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();
        let (declining, in_line) = view.update_in(cx, |v, window, cx| {
            (
                v.declining.is_some(),
                v.line.focus_handle(cx).is_focused(window),
            )
        });
        assert!(!declining && !in_line);
        assert!(yard.asked("DeclineAsk").is_empty());
        view.update(cx, |v, cx| {
            v.line.update(cx, |line, cx| line.set_text("", cx))
        });

        // Put aside, it is among the decided with its block and the
        // control, and is approved from there.
        let mut put_aside = queued_run("put aside", false);
        put_aside["run"] = weighty_run_of();
        put_aside["weight"] = weighed("outside", WEIGHTY_RUN_LINE);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [put_aside]}}).to_string(),
        );
        cx.simulate_keystrokes("x");
        wait(cx, "put aside", |_| yard.asked("DeferAsk").len() == 1);
        open_decided(&view, cx, "bead-s", 7);
        wait(cx, "the card among the decided", |cx| {
            drawn(cx, "weight bead-s 7 0") && drawn(cx, "typeback bead-s 7")
        });
        assert!(drawn(cx, "run bead-s 7"));
        assert!(drawn(cx, "approve bead-s 7"));
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk"), Vec::<Value>::new());

        // A put-aside weighty ask keeps its weight. Its card takes its
        // number back without a gate; cancel sends nothing, and passing
        // the gate sends `weighed` with the approval.
        cx.simulate_keystrokes("secondary-enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk"), Vec::<Value>::new());
        assert_eq!(
            notice(&view, cx),
            "ask 7's number was not typed back, so nothing was done"
        );
        unlock_as(&view, cx, true, false);
        assert!(drawn(cx, "approve bead-s 7"));
        click_on(cx, "approve bead-s 7");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk"), Vec::<Value>::new());
        unlock_as(&view, cx, true, true);
        let mut answered = queued_run("answered", true);
        answered["run"] = weighty_run_of();
        answered["weight"] = weighed("outside", WEIGHTY_RUN_LINE);
        answered["ran"] = json!({"argv": weighty_run_of()["argv"], "result": WEIGHTY_RUN_RESULT});
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [answered]}}).to_string(),
        );
        click_on(cx, "approve bead-s 7");
        wait(cx, "approved", |cx| {
            notice(&view, cx).starts_with("approved, ran: yardr source grant crm send")
        });
        assert_eq!(yard.asked("ApproveAsk"), [weighed_approval(&yard)]);
    }

    /// A taken-back run ask keeps the proposal for the record but has no
    /// approval control or answer field, including on its card among the
    /// decided asks.
    #[gpui::test]
    fn a_taken_back_run_ask_shows_its_proposal_without_an_approval(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        a_yard_of_jo(&yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [queued_run("taken back", false)]}})
                .to_string(),
        );
        let mut bead: Value = serde_json::from_str(&bead_run()).unwrap();
        bead["result"]["asks"][0]["state"] = json!("taken back");
        yard.answer("Bead", &bead.to_string());
        let at = env_on(&yard, &file);
        let (view, cx) = opened_at(at, &file, cx);
        wait(cx, "the taken-back ask", |cx| {
            view.read_with(cx, |v, _| {
                v.model
                    .as_ref()
                    .is_some_and(|model| model.decided_count() == 1)
            })
        });
        open_decided(&view, cx, "bead-s", 7);
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-s"));
        wait(cx, "the taken-back card", |cx| {
            drawn(cx, "run bead-s 7") && !approvable(&view, cx)
        });

        assert_eq!(
            decided_detail_of(&view, cx, "bead-s", 7).state_line,
            "taken back"
        );
        assert!(!drawn(cx, "approve bead-s 7"));
        assert!(!drawn(cx, "words bead-s 7"));
        cx.simulate_keystrokes("secondary-enter enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveAsk"), Vec::<Value>::new());
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
    }

    /// One class of a weighty card's weight, as the yard weighs the ask
    /// the card is of: the class, and the yard's line with this card's
    /// particulars.
    fn weighed(class: &str, line: &str) -> Value {
        json!([{"class": class, "line": line}])
    }

    /// The Mac's unlock says what the test fixes: whether the gate is
    /// offered, and what it answers. Answered at once, with no prompt.
    fn unlock_as(
        view: &Entity<Footplate>,
        cx: &mut VisualTestContext,
        offered: bool,
        answer: bool,
    ) {
        view.update_in(cx, |v, _, _| {
            v.test_unlock = Some((offered, answer));
        });
        cx.run_until_parked();
    }

    /// The bead of that run ask, weighing its ask's classes.
    fn bead_run_weighed(question: &str, context: &[&str], weight: Value) -> String {
        let mut bead: Value = serde_json::from_str(&bead_run_about(question, context)).unwrap();
        bead["result"]["title"] = json!("CRM messages");
        bead["result"]["asks"][0]["run"] = weighty_run_of();
        bead["result"]["asks"][0]["weight"] = weight;
        bead.to_string()
    }

    /// The window on a yard whose one open ask is that run ask, weighty,
    /// its card open and read.
    fn opened_on_a_weighty_run_ask<'a>(
        yard: &Yard,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        let question = "May the builder crew send updates from crm?";
        let fenced = format!(
            "```\n{}\n```\nthe yardmaster asks to grant it to the crew.",
            weighty_long_command()
        );
        let context = [
            "the builders need the source crm's send call.",
            fenced.as_str(),
        ];
        a_yard_of_jo(yard);
        let weight = weighed("outside", WEIGHTY_RUN_LINE);
        let mut queued = queued_run_about(question, "", false);
        queued["bead_title"] = json!("CRM messages");
        queued["run"] = weighty_run_of();
        queued["weight"] = weight.clone();
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [queued], "decided": []}}).to_string(),
        );
        yard.answer("Bead", &bead_run_weighed(question, &context, weight));
        yard.answer("DeferAsk", "{}");
        yard.answer("DeclineAsk", "{}");
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// The window on a yard whose one open ask is the secret ask 7 on
    /// bead-s, weighty, its card open and read.
    fn opened_on_a_weighty_secret_ask<'a>(
        yard: &Yard,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        let weight = weighed(
            "credential",
            "gives a credential or an address to the yard: BOOKS_TOKEN, for the source books",
        );
        let mut open = queued_secret(&["BOOKS_TOKEN"], 7, "", &[]);
        open["weight"] = weight.clone();
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [open], "decided": []}}).to_string(),
        );
        let mut bead: Value = serde_json::from_str(&bead_secret(&["BOOKS_TOKEN"], &[7])).unwrap();
        bead["result"]["asks"][0]["weight"] = weight;
        yard.answer("Bead", &bead.to_string());
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// The window on a yard whose one open ask is that setup ask,
    /// weighty, its card open and read.
    fn opened_on_a_weighty_setup_ask<'a>(
        yard: &Yard,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        let weight = weighed(
            "credential",
            "gives a credential or an address to the yard: the account COURIER_ACCOUNT",
        );
        let mut open = queued_setup(&["COURIER_ACCOUNT"], true);
        open["weight"] = weight.clone();
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [open], "decided": []}}).to_string(),
        );
        let mut bead: Value =
            serde_json::from_str(&bead_setup(&["COURIER_ACCOUNT"], true, 1)).unwrap();
        bead["result"]["asks"][0]["weight"] = weight;
        yard.answer("Bead", &bead.to_string());
        yard.answer("DeferAsk", "{}");
        yard.answer("DeclineAsk", "{}");
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// The courier pack's sentences as the yard cards them: the pack
    /// line, the credential with where it goes, the call with its path
    /// whole, the mint with its digest whole, the account, and the grants
    /// with their grantee.
    const SETUP_PACK_LINE: &str = "pack courier (embedded in yardr doctest), of kind source, into the yard: it adds 1 source and copies 1 command file (1 command), and changes nothing else. It makes no hook and sets no credential's file.";
    const SETUP_CREDENTIAL: &str = "source courier: its calls go to https://courier.example.com/api. Its credential is the variable COURIER_TOKEN (the name, never the value), minted from COURIER_ACCOUNT by courier-mint, sent in the header \"Authorization: Bearer {credential}\" on every call.";
    const SETUP_CALL: &str =
        "call ping (read): GET /me. It takes no parameter, and sends no query.";
    const SETUP_MINT: &str = "its mint courier-mint is copied to <home>/sources/courier/courier-mint, sha256 275239824e00e61b0a220e61a41791c7e9b4bd726f8b0c27077a338f8131c9dc mode 0700. It runs with the operator's local logins, and a mint_command the operator sets wins over it.";
    const SETUP_GRANTS: &str = "grants to crew yardmaster — pick one:";
    const SETUP_BACK: &str =
        "yardr source rm courier; yardr source revoke courier <what> --crew yardmaster";
    const SETUP_DECLARATION: &str =
        "name: courier\nbase: https://courier.example.com/api\ncredential: COURIER_TOKEN\n";
    const SETUP_MINT_FILE: &str = "#!/bin/sh\n# mint COURIER_TOKEN from COURIER_ACCOUNT\nexec courier-mint \"$COURIER_ACCOUNT\"\n";
    const SETUP_MINT_SHA: &str = "275239824e00e61b0a220e61a41791c7e9b4bd726f8b0c27077a338f8131c9dc";

    #[test]
    fn a_taken_setup_candidate_is_named_in_words() {
        let candidate = api::SetupCandidate {
            source: "courier-existing".into(),
            file: "/home/jo/.yardr/sources/courier-existing.env".into(),
            values: [("COURIER_ACCOUNT".into(), "jo@example.test".into())]
                .into_iter()
                .collect(),
        };
        let line = "courier-existing — COURIER_ACCOUNT=jo@example.test (in /home/jo/.yardr/sources/courier-existing.env)";
        assert_eq!(candidate_choice_line(&candidate, ""), line);
        assert_eq!(
            candidate_choice_line(&candidate, "courier-existing"),
            format!("taken: {line}")
        );
    }

    /// The shared account values a candidate file holds for `account`.
    fn setup_values(account: &[&str]) -> Value {
        let mut values = serde_json::Map::new();
        for name in account {
            let value = match *name {
                "COURIER_ACCOUNT" => "jo@example.test",
                "GITHUB_APP_ID" => "123456",
                "GITHUB_KEY_PATH" => "/home/jo/.courier/key.pem",
                _ => "typed",
            };
            values.insert(name.to_string(), json!(value));
        }
        Value::Object(values)
    }

    /// The setup the courier ask proposes, for `account`, with the one
    /// candidate where `candidates`.
    fn setup_of(account: &[&str], candidates: bool) -> Value {
        let names = account.join(" and ");
        let account_line = match candidates {
            true => {
                let pairs: Vec<String> = account
                    .iter()
                    .map(|name| {
                        let value = setup_values(account)
                            .get(*name)
                            .and_then(Value::as_str)
                            .unwrap_or("typed")
                            .to_string();
                        format!("{name}={value}")
                    })
                    .collect();
                format!(
                    "the account {names}: already given for courier-existing ({}, in /home/jo/.yardr/sources/courier-existing.env). Take it with --account courier-existing, or type another unseen (written to /home/jo/.yardr/sources/courier.env, named in the answer, never the value).",
                    pairs.join(", ")
                )
            }
            false => format!(
                "the account {names}: type it unseen. It is written to /home/jo/.yardr/sources/courier.env, named in the answer, never the value."
            ),
        };
        let candidates = match candidates {
            true => json!([{"source": "courier-existing",
                             "file": "/home/jo/.yardr/sources/courier-existing.env",
                             "values": setup_values(account)}]),
            false => json!([]),
        };
        json!({"pack": "courier", "account": account,
               "account_file": "/home/jo/.yardr/sources/courier.env",
               "candidates": candidates,
               "does": [SETUP_PACK_LINE, SETUP_CREDENTIAL, SETUP_CALL, SETUP_MINT,
                        account_line, SETUP_GRANTS],
               "back": SETUP_BACK,
               "carried": [{"name": "courier", "text": SETUP_DECLARATION,
                             "files": [{"program": "courier-mint", "text": SETUP_MINT_FILE,
                                        "sha256": SETUP_MINT_SHA}]}],
               "presets": [{"name": "read", "grants": [{"source": "courier", "calls": ["read"]}]},
                           {"name": "everything",
                            "grants": [{"source": "courier", "calls": ["read", "put"]}]}],
               "to": [{"crew": "yardmaster"}]})
    }

    /// The setup ask 7 on bead-s as the queue lists it, open.
    fn queued_setup(account: &[&str], candidates: bool) -> Value {
        json!({
            "bead": "bead-s", "bead_title": "The courier", "topic": "", "ask": 7,
            "question": "Set up courier for the yardmaster?", "asker": "yardmaster",
            "since": "2026-10-10T10:00:00Z", "setup": setup_of(account, candidates)
        })
    }

    /// The bead of that ask, with two presets and `you decide`,
    /// `recommend` recommended.
    fn bead_setup(account: &[&str], candidates: bool, recommend: u64) -> String {
        json!({"result": {"id": "bead-s", "title": "The courier", "body": "The body.",
            "stage": "new", "labels": [], "notes": [], "asks": [
                {"ask": 7, "to": "jo", "asker": "yardmaster",
                 "since": "2026-10-10T10:00:00Z",
                 "question": "Set up courier for the yardmaster?",
                 "context": ["The yardmaster reads the courier to work beads."],
                 "options": [{"label": "read", "consequence": "may make every read call of the source courier (https://courier.example.com/api): today that is ping"},
                             {"label": "everything", "consequence": "may make every call of the source courier (https://courier.example.com/api)"},
                             {"label": "You decide", "consequence": "the recommended preset, read, is granted"}],
                 "recommend": recommend, "why": "reading is the job",
                 "state": "open", "setup": setup_of(account, candidates)}]}})
        .to_string()
    }

    /// The window on a yard whose one open ask is that setup ask, its
    /// card open and read.
    fn opened_on_a_setup_ask<'a>(
        yard: &Yard,
        account: &[&str],
        candidates: bool,
        recommend: u64,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [queued_setup(account, candidates)], "decided": []}})
                .to_string(),
        );
        yard.answer("Bead", &bead_setup(account, candidates, recommend));
        yard.answer("DeferAsk", "{}");
        yard.answer("DeclineAsk", "{}");
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// The setup the courier ask proposes on a pack already applied: the
    /// yard's account line for what stands, with `given` and `missing`.
    /// No candidate matches a sibling: the standing file is the account.
    fn setup_drift(account: &[&str], given: bool, missing: &[&str]) -> Value {
        let mut setup = setup_of(account, false);
        setup["given"] = json!(given);
        setup["missing"] = json!(missing);
        if given || !missing.is_empty() {
            let names = account.join(" and ");
            let file = "/home/jo/.yardr/sources/courier.env";
            let need = missing.join(" and ");
            let line = if !missing.is_empty() && missing.len() < account.len() {
                format!(
                    "the account {names}: given, in {file}, but missing {need}: type {need} unseen (written to {file}, named in the answer, never the value)."
                )
            } else if !missing.is_empty() {
                format!(
                    "the account {names}: the file {file} holds none of it: type {need} unseen (written to {file}, named in the answer, never the value)."
                )
            } else {
                format!(
                    "the account {names}: given, in {file}. Type another unseen to change it, or approve keeping it with a bare preset pick (written to {file}, named in the answer, never the value)."
                )
            };
            setup["does"][4] = json!(line);
        }
        setup
    }

    /// The setup ask 7 on bead-s on a pack already applied, as the queue
    /// lists it, open.
    fn queued_drift(account: &[&str], given: bool, missing: &[&str]) -> Value {
        let mut queued = queued_setup(account, false);
        queued["setup"] = setup_drift(account, given, missing);
        queued
    }

    /// The bead of that ask, with two presets and `you decide`,
    /// `recommend` recommended.
    fn bead_drift(account: &[&str], given: bool, missing: &[&str], recommend: u64) -> String {
        let mut bead: Value = serde_json::from_str(&bead_setup(account, false, recommend)).unwrap();
        bead["result"]["asks"][0]["setup"] = setup_drift(account, given, missing);
        bead.to_string()
    }

    /// The window on a yard whose one open ask is that setup ask, its
    /// card open and read.
    fn opened_on_a_drift_ask<'a>(
        yard: &Yard,
        account: &[&str],
        given: bool,
        missing: &[&str],
        recommend: u64,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [queued_drift(account, given, missing)], "decided": []}})
                .to_string(),
        );
        yard.answer("Bead", &bead_drift(account, given, missing, recommend));
        yard.answer("DeferAsk", "{}");
        yard.answer("DeclineAsk", "{}");
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// A mapping ask's weight line, as the yard weighs it: a pick says
    /// which user the sender is, and deliveries from them are then heard
    /// as that user's.
    const MAPPING_WEIGHT_LINE: &str = "a pick says which user U999 in talk is, and a delivery from them is then heard as that user's";

    /// The mapping ask `ask` on bead-s as the queue lists it, open and
    /// weighty: who U999 in talk is.
    fn queued_mapping(ask: u64) -> Value {
        json!({
            "bead": "bead-s", "bead_title": "Who is U999?", "topic": "", "ask": ask,
            "question": "Who is U999 in talk?", "asker": "yardmaster",
            "since": "2026-10-10T10:00:00Z",
            "identity": {"source": "talk", "sender": "U999"},
            "weight": [{"class": "as-user", "line": MAPPING_WEIGHT_LINE}],
        })
    }

    /// The bead of three mapping asks, 7 to 9, each with one user to
    /// pick, someone new, nobody and you decide, and no recommendation:
    /// words alone go as a note.
    fn bead_mapping() -> String {
        let ask = |ask: u64| {
            json!({
                "ask": ask, "to": "jo", "asker": "yardmaster",
                "since": "2026-10-10T10:00:00Z",
                "question": "Who is U999 in talk?",
                "context": ["a delivery arrived from U999, who maps to nobody."],
                "options": [
                    {"label": "ada", "consequence": "messages from U999 count as ada's"},
                    {"label": "Someone new", "consequence": "pick this and write the new user's name with your answer"},
                    {"label": "Nobody — ignore this sender", "consequence": "ignores U999 in talk: their messages are dropped, and no further card is offered"},
                    {"label": "You decide", "consequence": "leave it to yardmaster"}
                ],
                "state": "open",
                "identity": {"source": "talk", "sender": "U999"},
                "weight": [{"class": "as-user", "line": MAPPING_WEIGHT_LINE}],
            })
        };
        json!({"result": {"id": "bead-s", "title": "Who is U999?",
            "body": "The body.", "stage": "new", "labels": [], "notes": [],
            "asks": [ask(7), ask(8), ask(9)]}})
        .to_string()
    }

    /// The window on a yard whose open asks are the three mapping asks 7
    /// to 9 on bead-s, weighty, the first one's card open and read.
    fn opened_on_a_weighty_mapping_ask<'a>(
        yard: &Yard,
        file: &std::path::Path,
        cx: &'a mut TestAppContext,
    ) -> (Entity<Footplate>, &'a mut VisualTestContext) {
        a_yard_of_jo(yard);
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [queued_mapping(7), queued_mapping(8), queued_mapping(9)], "decided": []}})
                .to_string(),
        );
        yard.answer("Bead", &bead_mapping());
        yard.answer("AnswerAsk", "{}");
        yard.answer("AddNote", "{}");
        yard.answer("DeferAsk", "{}");
        yard.answer("DeclineAsk", "{}");
        let at = env_on(yard, file);
        opened_on_the_ask(at, file, cx)
    }

    /// A mapping pick writes a user's identity, so it passes the weighty
    /// gate like any other weighty approval: the Mac's unlock where one is
    /// offered, the ask's number typed back where none is, and `weighed`
    /// with the pick. Anything else keeps the card and sends nothing.
    /// Words alone, later and decline stay ungated.
    #[gpui::test]
    fn a_mapping_pick_passes_the_weighty_gate_and_sends_weighed(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_weighty_mapping_ask(&yard, &file, cx);

        // The card shows its weight first, in rust, with the options, the
        // line for words and the number field where no gate is offered.
        assert!(drawn(cx, "weight bead-s 7 0"));
        assert!(drawn(cx, "typeback bead-s 7"));
        assert!(drawn(cx, "pick bead-s 7 1"));
        assert!(drawn(cx, "words bead-s 7"));
        assert!(drawn(cx, "send bead-s 7"));
        // `i` types the number first.
        cx.simulate_keystrokes("i");
        cx.run_until_parked();
        let in_typeback = view.update_in(cx, |v, window, cx| {
            v.typeback.focus_handle(cx).is_focused(window)
        });
        assert!(in_typeback);
        cx.simulate_keystrokes("escape");
        cx.run_until_parked();

        // A pick with anything but the ask's number sends nothing and
        // leaves the card, saying so.
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("1");
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("AnswerAsk"), Vec::<Value>::new());
        assert_eq!(
            notice(&view, cx),
            "ask 7's number was not typed back, so nothing was done"
        );
        assert!(drawn(cx, "typeback bead-s 7"));
        view.update(cx, |v, cx| {
            v.typeback.update(cx, |field, cx| field.set_text("8", cx))
        });
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("AnswerAsk"), Vec::<Value>::new());
        assert_eq!(
            notice(&view, cx),
            "ask 7's number was not typed back, so nothing was done"
        );

        // The number typed back sends the pick with weighed, and the
        // number is used up.
        let mut answered = queued_mapping(7);
        answered["state"] = json!("answered");
        answered["option"] = json!(1);
        answered["option_label"] = json!("ada");
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [queued_mapping(8), queued_mapping(9)], "decided": [answered]}})
                .to_string(),
        );
        view.update(cx, |v, cx| {
            v.typeback.update(cx, |field, cx| field.set_text("7", cx))
        });
        cx.simulate_keystrokes("enter");
        wait(cx, "the weighed pick", |_| {
            yard.asked("AnswerAsk")
                == [
                    json!({"bead": "bead-s", "ask": 7, "option": 1, "actor": "jo", "weighed": true}),
                ]
        });
        assert_eq!(typeback_text(&view, cx), "");
        cx.run_until_parked();

        // A later pick from Decided passes the gate too: a cancelled
        // unlock sends nothing, and the words stay for another try.
        open_decided(&view, cx, "bead-s", 7);
        wait(cx, "the decided card", |cx| drawn(cx, "typeback bead-s 7"));
        unlock_as(&view, cx, true, false);
        view.update(cx, |v, cx| v.pick(2, cx));
        cx.simulate_keystrokes("i");
        cx.simulate_input("hal");
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("AnswerAsk").len(), 1);
        assert_eq!(typed(&view, cx), "hal");

        // Passing the unlock sends the new pick with weighed.
        unlock_as(&view, cx, true, true);
        cx.simulate_keystrokes("enter");
        wait(cx, "the unlocked pick", |_| {
            yard.asked("AnswerAsk").last()
                == Some(
                    &json!({"bead": "bead-s", "ask": 7, "option": 2, "words": "hal", "actor": "jo", "weighed": true}),
                )
        });
        assert_eq!(typed(&view, cx), "");
        cx.run_until_parked();

        // Words alone, later and decline stay ungated: no number needed.
        // The number field stands empty throughout.
        unlock_as(&view, cx, false, false);
        view.update(cx, |v, cx| {
            v.change(cx, |m| m.select(Selected::Decision("bead-s".into())));
            v.select_ask("bead-s".into(), 8, cx);
        });
        wait(cx, "the second card", |cx| drawn(cx, "typeback bead-s 8"));
        assert_eq!(typeback_text(&view, cx), "");
        // Words alone go as a note with no option chosen: the line is set
        // straight, since `i` takes the empty number field first.
        view.update(cx, |v, cx| {
            v.line
                .update(cx, |line, cx| line.set_text("is this the same sender?", cx))
        });
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("enter");
        wait(cx, "the note", |_| {
            yard.asked("AddNote")
                == [json!({"bead": "bead-s", "text": "is this the same sender?", "actor": "jo"})]
        });
        assert_eq!(typeback_text(&view, cx), "");
        // Decline takes words and no number.
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("d");
        cx.simulate_input("not now");
        cx.simulate_keystrokes("enter");
        wait(cx, "declined", |_| {
            yard.asked("DeclineAsk")
                == [json!({"bead": "bead-s", "ask": 8, "words": "not now", "actor": "jo"})]
        });
        // Later takes no words and no number.
        view.update(cx, |v, cx| v.select_ask("bead-s".into(), 9, cx));
        wait(cx, "the third card", |cx| drawn(cx, "typeback bead-s 9"));
        assert_eq!(typeback_text(&view, cx), "");
        cx.simulate_keystrokes("escape");
        cx.simulate_keystrokes("x");
        wait(cx, "put aside", |_| {
            yard.asked("DeferAsk") == [json!({"bead": "bead-s", "ask": 9, "actor": "jo"})]
        });
    }

    /// A setup ask's card: the yard's block with what approving does, each
    /// sentence whole — the credential's placement, the call's path, the
    /// mint's digest, the account and the grants — the account choice with
    /// each candidate's address, the presets to pick from, and the
    /// take-backs. A tap takes the candidate, and the approval sends the
    /// preset pick with it after its number is typed back where no unlock
    /// is offered; the ask reads as being carried out until the yard says
    /// it ran.
    #[gpui::test]
    fn a_setup_ask_s_card_shows_its_setup_and_is_approved_with_a_tap(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_weighty_setup_ask(&yard, &file, cx);

        // With no gate, a weighty setup takes its number back above
        // its approval control and account field. The approval wants the
        // account first, then the number.
        assert!(drawn(cx, "weight bead-s 7 0"));
        assert!(drawn(cx, "typeback bead-s 7"));
        assert!(drawn(cx, "approve bead-s 7"));
        assert!(drawn(cx, "secret bead-s 7"));
        cx.simulate_keystrokes("secondary-enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveSetup"), Vec::<Value>::new());
        assert_eq!(notice(&view, cx), "take a candidate, or type the account");
        unlock_as(&view, cx, true, false);

        // The yard's block, with what approving does and each sentence.
        assert!(drawn(cx, "setup bead-s 7"));
        assert!(drawn(cx, "setup summary bead-s 7"));
        for ix in 0..6 {
            assert!(drawn(cx, &format!("setup does bead-s 7 {ix}")), "does {ix}");
        }
        let setup = view.read_with(cx, |v, _| {
            v.model
                .as_ref()
                .unwrap()
                .decision_detail("bead-s", &chrono::Utc::now())
                .unwrap()
                .asks[0]
                .setup
                .clone()
                .unwrap()
        });
        assert_eq!(setup.pack, "courier");
        assert!(
            setup.does[1].contains("sent in the header"),
            "{}",
            setup.does[1]
        );
        assert!(setup.does[2].contains("GET /me"), "{}", setup.does[2]);
        assert!(setup.does[3].contains(SETUP_MINT_SHA), "{}", setup.does[3]);
        assert_eq!(
            model::setup_summary(&setup),
            "yardr pack apply courier, the account COURIER_ACCOUNT, and the preset's grants to crew yardmaster"
        );
        // The asker's lines are marked as the asker's: none can begin as
        // a line of the yard's does.
        let card = view.read_with(cx, |v, _| {
            v.model
                .as_ref()
                .unwrap()
                .decision_detail("bead-s", &chrono::Utc::now())
                .unwrap()
                .asks[0]
                .clone()
        });
        assert!(card.question.starts_with("yardmaster says: "));
        assert!(card.context[0].starts_with("yardmaster says: "));
        // The account choice with the candidate's address, the presets to
        // pick from, and the take-backs; the secret field, and no line
        // for words.
        assert!(drawn(cx, "account bead-s 7 courier-existing"));
        assert!(drawn(cx, "pick bead-s 7 1"));
        assert!(drawn(cx, "pick bead-s 7 2"));
        assert!(drawn(cx, "pick bead-s 7 3"));
        assert!(drawn(cx, "setup back bead-s 7"));
        assert!(drawn(cx, "secret bead-s 7"));
        assert!(!drawn(cx, "words bead-s 7"));

        // The ask's own texts behind one tap, copied to the letter.
        click_on(cx, "texts bead-s 7");
        wait(cx, "the texts", |cx| drawn(cx, "setup text bead-s 7 0"));
        assert!(drawn(cx, "setup text bead-s 7 1"));
        let chip = run_chip(&view, cx, run_text("declaration", SETUP_DECLARATION)).unwrap();
        cx.simulate_click(chip, gpui::Modifiers::default());
        assert_eq!(clipboard(cx).as_deref(), Some(SETUP_DECLARATION));

        // Enter alone approves nothing.
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveSetup"), Vec::<Value>::new());
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());

        // A tap takes the candidate, and the approval sends the
        // recommended preset with it.
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [{
                "bead": "bead-s", "ask": 7, "question": "Set up courier for the yardmaster?",
                "asker": "yardmaster", "state": "answered", "option": 1, "option_label": "read",
                "setup": setup_of(&["COURIER_ACCOUNT"], true),
                "weight": [{"class": "credential",
                            "line": "gives a credential or an address to the yard: the account COURIER_ACCOUNT"}],
                "ran": {"argv": ["setup", "courier"], "result": "approved, to be carried out"}}]}})
            .to_string(),
        );
        yard.answer(
            "ApproveSetup",
            &json!({"result": {"bead": "bead-s", "ask": 7, "asker": "yardmaster",
                "pack": "courier", "preset": "read", "account": "courier-existing",
                "result": "approved, to be carried out"}})
            .to_string(),
        );
        click_on(cx, "account bead-s 7 courier-existing");
        cx.run_until_parked();
        let taken = view.read_with(cx, |v, _| {
            v.model.as_ref().unwrap().account_choice("bead-s", 7)
        });
        assert_eq!(taken, "courier-existing");
        // Without a gate, anything but the ask's number sends nothing
        // and leaves the taken account, saying so.
        unlock_as(&view, cx, false, false);
        cx.simulate_keystrokes("secondary-enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveSetup"), Vec::<Value>::new());
        assert_eq!(
            notice(&view, cx),
            "ask 7's number was not typed back, so nothing was done"
        );
        assert_eq!(
            view.read_with(cx, |v, _| {
                v.model.as_ref().unwrap().account_choice("bead-s", 7)
            }),
            "courier-existing"
        );
        unlock_as(&view, cx, true, false);
        // Cancel sends nothing and leaves the selected account for another
        // try.
        cx.simulate_keystrokes("secondary-enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveSetup"), Vec::<Value>::new());
        unlock_as(&view, cx, false, false);
        view.update(cx, |v, cx| {
            v.typeback.update(cx, |field, cx| field.set_text("7", cx))
        });
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "approved", |cx| {
            notice(&view, cx)
                == "approved, being carried out: setup of pack courier, preset read to crew yardmaster; took courier-existing"
        });
        assert_eq!(typeback_text(&view, cx), "");
        assert_eq!(
            yard.asked("ApproveSetup"),
            [json!({"bead": "bead-s", "ask": 7, "option": 1,
                     "account": "courier-existing", "actor": "jo", "weighed": true})]
        );
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
        // Among the decided it reads as being carried out, with the
        // yard's block and no control.
        let detail = decided_detail_of(&view, cx, "bead-s", 7);
        assert_eq!(
            detail.state_line,
            "approved, being carried out: setup of pack courier, preset read to crew yardmaster"
        );
        open_decided(&view, cx, "bead-s", 7);
        wait(cx, "the bead", |cx| has_bead(&view, cx, "bead-s"));
        assert!(drawn(cx, "weight bead-s 7 0"));
        // A setup runs once for one ask: the model takes no approval for
        // it again, and no key calls the yard again.
        assert!(!view.read_with(cx, |v, _| {
            v.model
                .as_ref()
                .unwrap()
                .setup_approving("bead-s", 7)
                .is_some()
        }));
        cx.simulate_keystrokes("secondary-enter enter");
        cx.run_until_parked();
        assert_eq!(yard.asked("ApproveSetup").len(), 1);
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
        // Its block stands on its decided card too, with the ask's own
        // texts behind the tap, copied to the letter.
        assert!(view.read_with(cx, |v, _| {
            v.model.as_ref().unwrap().texts_shown("bead-s", 7)
        }));
        let chip = run_chip(&view, cx, run_text("declaration", SETUP_DECLARATION)).unwrap();
        cx.simulate_click(chip, gpui::Modifiers::default());
        assert_eq!(clipboard(cx).as_deref(), Some(SETUP_DECLARATION));
    }

    /// A setup ask's account typed in its field: marks while it is typed,
    /// taken with Enter, and the approval sends the values with the preset
    /// pick. A filled field types another: whatever candidate the card
    /// took is taken back as it fills, and a tap forgets what is typed.
    /// The value is in the call's body and nowhere else in the window. An
    /// approval the yard refuses is shown whole, and a call that ends
    /// without an answer is never said to be approved or not.
    #[gpui::test]
    fn a_setup_ask_s_account_is_typed_unseen_and_approved_with_its_preset(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_setup_ask(&yard, &["COURIER_ACCOUNT"], true, 1, &file, cx);
        let nowhere = |view: &Entity<Footplate>, cx: &mut VisualTestContext, when: &str| {
            let kept = kept_outside_the_field(view, cx, dir.path());
            assert!(!kept.contains(VALUE), "{when}: {kept}");
        };
        let marks = |n: usize| "\u{2022}".repeat(n);
        assert_eq!(
            secret_field(&view, cx).2,
            "COURIER_ACCOUNT for the setup of courier"
        );

        // A tap takes the candidate; typing takes it back as the field
        // fills, and the value is marks.
        click_on(cx, "account bead-s 7 courier-existing");
        cx.run_until_parked();
        assert_eq!(
            view.read_with(cx, |v, _| v
                .model
                .as_ref()
                .unwrap()
                .account_choice("bead-s", 7)),
            "courier-existing"
        );
        cx.simulate_keystrokes("i");
        cx.simulate_input(VALUE);
        let (typed_in, shown, _) = secret_field(&view, cx);
        assert_eq!((typed_in.as_str(), shown), (VALUE, marks(VALUE.len())));
        assert_eq!(
            view.read_with(cx, |v, _| v
                .model
                .as_ref()
                .unwrap()
                .account_choice("bead-s", 7)),
            ""
        );
        nowhere(&view, cx, "typed");
        // And a tap forgets what is typed.
        click_on(cx, "account bead-s 7 courier-existing");
        cx.run_until_parked();
        assert_eq!(secret_field(&view, cx).0, "");
        assert_eq!(
            view.read_with(cx, |v, _| v
                .model
                .as_ref()
                .unwrap()
                .account_choice("bead-s", 7)),
            "courier-existing"
        );

        // Typed again and taken with Enter, the approval sends the values
        // with the recommended preset.
        cx.simulate_keystrokes("i");
        cx.simulate_input(VALUE);
        cx.simulate_keystrokes("enter");
        cx.run_until_parked();
        assert_eq!(secret_field(&view, cx).0, "");
        yard.answer(
            "UserAsks",
            &json!({"result": {"open": [], "decided": [{
                "bead": "bead-s", "ask": 7, "question": "Set up courier for the yardmaster?",
                "asker": "yardmaster", "state": "answered", "option": 1, "option_label": "read",
                "setup": setup_of(&["COURIER_ACCOUNT"], true), "given": ["COURIER_ACCOUNT"],
                "ran": {"argv": ["setup", "courier"], "result": "approved, to be carried out"}}]}})
            .to_string(),
        );
        yard.answer(
            "ApproveSetup",
            &json!({"result": {"bead": "bead-s", "ask": 7, "asker": "yardmaster",
                "pack": "courier", "preset": "read", "given": ["COURIER_ACCOUNT"],
                "result": "approved, to be carried out"}})
            .to_string(),
        );
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "approved", |cx| {
            notice(&view, cx)
                == "approved, being carried out: setup of pack courier, preset read to crew yardmaster; gave COURIER_ACCOUNT"
        });
        assert_eq!(
            yard.asked("ApproveSetup"),
            [json!({"bead": "bead-s", "ask": 7, "option": 1,
                     "values": {"COURIER_ACCOUNT": VALUE}, "actor": "jo"})]
        );
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
        let detail = decided_detail_of(&view, cx, "bead-s", 7);
        assert_eq!(
            detail.state_line,
            "approved, being carried out: setup of pack courier, preset read to crew yardmaster; gave COURIER_ACCOUNT"
        );
        nowhere(&view, cx, "approved");
        for call in yard.calls() {
            if call != "ApproveSetup" {
                let asked = format!("{:?}", yard.asked(&call));
                assert!(!asked.contains(VALUE), "{call}: {asked}");
            }
        }
    }

    /// An approval the yard refuses is shown whole on a setup ask's card.
    /// A call that ends without an answer is never said to be approved or
    /// not, and the queue is read again for what the yard says, since the
    /// call may have approved all the same.
    #[gpui::test]
    fn a_setup_approval_the_yard_refuses_is_shown_whole(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_setup_ask(&yard, &["COURIER_ACCOUNT"], true, 1, &file, cx);
        click_on(cx, "account bead-s 7 courier-existing");
        cx.run_until_parked();

        // The yard goes away over the call: never "approved". The call
        // may have approved all the same, so the queue is read again for
        // what the yard says.
        let reads = yard.asked("UserAsks").len();
        yard.answer_nothing("ApproveSetup");
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "no answer", |cx| {
            refused_of(&view, cx, "bead-s", 7) == "the yard did not answer; read the card again"
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        assert!(drawn(cx, "approve bead-s 7"));
        wait(cx, "the queue read again", |_| {
            yard.asked("UserAsks").len() == reads + 1
        });

        // The yard refuses, since it changed after the ask was written:
        // its words, whole, and nothing ran, so nothing is read again.
        let stale = "ask 7 on bead-s: the candidate courier-existing holds COURIER_ACCOUNT=jo@example.test no more: the card is from before that changed. Nothing ran. Decline it; it is asked again if it is still wanted.";
        yard.answer(
            "ApproveSetup",
            &json!({"error": {"code": "error", "message": stale}}).to_string(),
        );
        click_on(cx, "approve bead-s 7");
        wait(cx, "refused", |cx| {
            refused_of(&view, cx, "bead-s", 7) == format!("not approved: {stale}")
        });
        assert!(drawn(cx, "refused bead-s 7"));
        assert!(drawn(cx, "approve bead-s 7"));
        assert_eq!(notice(&view, cx), "");
        assert_eq!(yard.asked("ApproveSetup").len(), 2);
        cx.run_until_parked();
        assert_eq!(yard.asked("UserAsks").len(), reads + 1);
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
    }

    /// A setup ask's approval wants the preset pick and the account
    /// together: with neither it says which is missing, and a chosen
    /// preset goes in place of the recommended one.
    #[gpui::test]
    fn a_setup_ask_s_preset_is_picked_and_its_account_is_wanted(cx: &mut TestAppContext) {
        let dir = tempfile::tempdir().unwrap();
        let file = dir.path().join("footplate/settings.json");
        let yard = Yard::start();
        let (view, cx) = opened_on_a_setup_ask(&yard, &["COURIER_ACCOUNT"], true, 1, &file, cx);

        // With neither the pick's account nor a candidate, the approval
        // says which is missing, and calls nothing.
        cx.simulate_keystrokes("secondary-enter");
        cx.run_until_parked();
        assert_eq!(notice(&view, cx), "take a candidate, or type the account");
        assert_eq!(yard.asked("ApproveSetup"), Vec::<Value>::new());

        // A chosen preset goes in place of the recommended one.
        yard.answer(
            "ApproveSetup",
            &json!({"result": {"bead": "bead-s", "ask": 7, "asker": "yardmaster",
                "pack": "courier", "preset": "everything",
                "account": "courier-existing", "result": "approved, to be carried out"}})
            .to_string(),
        );
        click_on(cx, "pick bead-s 7 2");
        cx.run_until_parked();
        click_on(cx, "account bead-s 7 courier-existing");
        cx.run_until_parked();
        cx.simulate_keystrokes("secondary-enter");
        wait(cx, "approved", |cx| {
            notice(&view, cx)
                == "approved, being carried out: setup of pack courier, preset everything to crew yardmaster; took courier-existing"
        });
        assert_eq!(
            yard.asked("ApproveSetup"),
            [json!({"bead": "bead-s", "ask": 7, "option": 2,
                     "account": "courier-existing", "actor": "jo"})]
        );
        assert_eq!(answered_otherwise(&yard), Vec::<String>::new());
    }

